insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', '1SA', 30, 22, 'Nĩvo ĩndĩ andũ athũku o na ala athe onthe, katĩ wa asu maendie na Ndaviti, masũngĩie, na masya, Nĩkwĩthĩwa matyaaenda naitũ, tũtikamenenga kĩndũ o na kĩmwe kya mũtavo ũla tũtũngĩte, ate o kĩla mũndũ kĩveti kyake na syana syake, nĩ kana amatongoesye, mathi.'),
('kam', '1SA', 30, 23, 'Nĩvo ĩndĩ Ndaviti waisye, Mũtitonya kwĩka ũu, ana‐a‐asa makwa, na kĩla Yeova ũtũnengete, ũla ũtũsũvĩĩte, na kũnengane kw’okonĩ kwitũ nguthu ĩla yatũvithũkĩe.'),
('kam', '1SA', 30, 24, 'Na nũũ ũla wĩmwĩthukĩĩsya ũndũnĩ ũũ? Nũndũ o tondũ kĩanda kya ũla ũkatheeaa kaũnĩ kĩkethĩawa, now’o kĩanda kya ũla ũkekalaa na mĩio kĩkethĩawa: makaaĩawa ũndũ ũmwe.'),
('kam', '1SA', 30, 25, 'Na kweethĩwa kuma mũthenya ũsu na kũendeea, atw’a ũndũ ũsu mwamũlo na ũtw’ĩo kwondũ wa Isilaeli kũvika ũmũnthĩ.'),
('kam', '1SA', 30, 26, 'Na yĩla Ndaviti wavikie Nzikilaki, atwaĩa atumĩa ma Yuta sya mũtavo, o anyanyae make, akĩmea, Sisya, nĩ mũthĩnzĩo ũndũ wenyu wa mũtavo wa amaitha ma Yeova:'),
('kam', '1SA', 30, 27, 'kwa ala maĩ Mbethi‐eli, na kwa ala maĩ Lamothi ya ngalĩ ya Ĩtheo, na kwa ala maĩ Yatili,'),
('kam', '1SA', 30, 28, 'na kwa ala maĩ Aloeli, na kwa ala maĩ Sivimothi, na kwa ala maĩ Esitemoa,'),
('kam', '1SA', 30, 29, 'na kwa ala maĩ Lakali, na kwa ala maĩ ndũanĩ sya Ayelameeli, na kwa ala maĩ ndũanĩ sya Akeni,'),
('kam', '1SA', 30, 30, 'na kwa ala maĩ Olima, na kwa ala maĩ Mboli‐asani, na kwa ala maĩ Athaki,'),
('kam', '1SA', 30, 31, 'na kwa ala maĩ Eviloni, na kũndũ kw’onthe kũla Ndaviti o na andũ make makothaa kwanganga.'),
('kam', '1SA', 31, 1, 'Na ĩndĩ Avilisiti nĩmokitie na Isilaeli: na andũ ma Isilaeli makũka makĩĩte Avilisiti, na mavalũkw’a me oae kĩĩmanĩ kya Ngilivoa.'),
('kam', '1SA', 31, 2, 'Na Avilisiti mamaatĩĩa Saulo na ana make na vinya; na Avilisiti mooaa Yonathani, na Avinatavu, na Malikisua, ana ma Saulo.'),
('kam', '1SA', 31, 3, 'Na kaũ weethĩwa mwai kũla kwĩ Saulo, na andũ ma mata mamũwĩla; na aũũya mũno, ũndũ wa andũ ma mata.'),
('kam', '1SA', 31, 4, 'Nĩvo ĩndĩ Saulo wamwĩie mũkui wa mĩio yake ya kaũ, Kũa ũvyũ waku, ũndonye mũkuthũ naw’o, aa ala mate aĩke matikese kũka na kũndonya mũkuthũ, na kũnthĩn’ya. Ĩndĩ mũkui wa mĩio yake ya kaũ ndaaĩtĩkĩla; nũndũ akĩaa mũno. Kwondũ wa ũu Saulo oosa ũvyũ wake, na eevalũkya ĩũlũ waw’o eetonyethya.'),
('kam', '1SA', 31, 5, 'Na yĩla mũkui wa mĩio yake ya kaũ wonie atĩ Saulo nĩwakw’a, eevalũkya ĩũlũ wa ũvyũ wake eetonyethya nake, na akw’a vamwe nake.'),
('kam', '1SA', 31, 6, 'Ũu nĩw’o Saulo wakwie, na ana make atatũ, na mũkui wa mĩio yake ya kaũ, na andũ make onthe, mũthenya o ũsu me vamwe.'),
('kam', '1SA', 31, 7, 'Na yĩla andũ ma Isilaeli ala maĩ mũingo ũla ũngĩ wa mwanda, na ala maĩ mũingo ũya wa Yolotani, moonie kana andũ ma Isilaeli nĩmakũka makĩa, na kana Saulo na ana make nĩmakw’a, matia ndũa, na makũka makĩa; na Avilisiti mooka na maitũa.'),
('kam', '1SA', 31, 8, 'Na kweethĩwa ũnĩ ũsu, yĩla Avilisiti mookie kũmatusa ala moaĩtwe, moona Saulo na ana make atatũ mavalũkĩte kĩĩmanĩ kya Ngilivoa.'),
('kam', '1SA', 31, 9, 'Na matila mũtwe wake, na matusa mĩio yake ya kaũ, na matũmana nthĩ ya Avilisiti kw’onthe, matwaĩe nyũmba ya mĩvw’anano yoo, o na andũ, ũvoo.'),
('kam', '1SA', 31, 10, 'Na maia mĩio yake ya kaũ nyũmbanĩ ya Asetalothi; na maathĩĩa kimba kyake ũvainĩ wa Mbethi‐sani.'),
('kam', '1SA', 31, 11, 'Na yĩla ala matwĩe Yavesi‐ngileati meewie ũvoo wake ũndũ Avilisiti mamwĩkie Saulo,'),
('kam', '1SA', 31, 12, 'andũ ngũmbaũ onthe mookĩla, na maenda ũtukũ w’onthe, na maumya kimba kya Saulo na simba sya ana make ũvainĩ wa Mbethi‐sani; na mavika Yavesi, na maivĩvĩsya vo.'),
('kam', '1SA', 31, 13, 'Na moosa mavĩndĩ moo, na mamenzĩa nthĩ ĩtina wa mũtĩ wa mweseli ku Yavesi, na matĩĩa ũya mĩthenya mũonza.'),
('kam', '2SA', 1, 1, 'Na kweethĩwa ĩtina wa kĩkw’ũ kya Saulo, yĩla Ndaviti waĩ anasyoka kuma kũmoaa Aamaleki, na Ndaviti aĩ anekala mĩthenya ĩlĩ Nzikilaki;'),
('kam', '2SA', 1, 2, 'kweethĩwa mũthenya wa katatũ, sisya, mũndũ auma mwakonĩ wa maeema kwa Saulo, atembũangĩte ngũa syake, na e na mũthanga mũtwe wake: na kweethĩwa, yĩla wavikie vala ve Ndaviti, eevalũkya nthĩ, na eekunamya vyũ.'),
('kam', '2SA', 1, 3, 'Na Ndaviti amũkũlya, Wauma va? Na amwĩa, Nĩnavonoka kuma mwakonĩ wa maeema wa Isilaeli.'),
('kam', '2SA', 1, 4, 'Na Ndaviti amũkũlya, Ũvoo ũnaendie ata? Nĩngũkwĩsũva, ndavya. Na asũngĩa, Andũ nĩmanakĩie manauma kaũnĩ, o na andũ aingĩ nĩ avalũkye na nĩ akw’ũ; na Saulo na Yonathani mwana wake nao nĩ akw’ũ.'),
('kam', '2SA', 1, 5, 'Na Ndaviti akũlya mwanake ũla wamũtavya, Wĩsĩ ata Saulo na Yonathani mwana wake nĩ akw’ũ?'),
('kam', '2SA', 1, 6, 'Na mwanake ũla wamũtavya asya, Yĩla nĩnesie kwĩthĩwa kĩĩmanĩ kya Ngilivoa, sisya, Saulo aneetw’ĩĩkĩte na ĩtumo yake; na, sisya, makasya ma kaũ na andũ matũlĩte mbalasi mamũatĩĩa vakuvi.'),
('kam', '2SA', 1, 7, 'Na yĩla ũnasyaisye ĩtina, ambona, na ambĩta. Nakwa nasũngĩa, Ninyioo.'),
('kam', '2SA', 1, 8, 'Na angũlya, Nue ũũ? Na namũsũngĩa, Nyie nĩ Mũamaleki.'),
('kam', '2SA', 1, 9, 'Na ambĩa, Nĩngũkwĩsũva, ũngama vakuvĩ nakwa, ũmbũaĩĩe; nũndũ nthikũ nĩngwatĩte, nũndũ thayũ wakwa no ũtiele nthĩnĩ wakwa kũvika yu.'),
('kam', '2SA', 1, 10, 'Na ĩndĩ naũngama vakuvĩ nake, na namũaa, nũndũ nĩnĩneesĩ ndatonya kwĩkala thayũ ĩtina wa avalũka: na naumya ngovia ya ũsumbĩ ĩla ĩnaĩ mũtwe wake, na kĩtang’a kĩla kĩnaĩ kw’okonĩ kwake, na nĩnaiete vaa kwa mwĩaĩi wakwa.'),
('kam', '2SA', 1, 11, 'Nĩvo ĩndĩ Ndaviti wakwatie ngũa syake, na aitembũanga; na andũ onthe ala maĩ nake o ta ũu:'),
('kam', '2SA', 1, 12, 'na mameta, na kũĩa, na kũtĩĩa ũya kũvika wĩoo, kwondũ wa Saulo, na kwondũ wa Yonathani mwana wake, na kwondũ wa andũ ma Yeova, na kwondũ wa nyũmba ya Isilaeli; nũndũ nĩmavalũkilw’e na ũvyũ.'),
('kam', '2SA', 1, 13, 'Na Ndaviti amũkũlya mwanake ũla wamũtavisye, Wĩ wa va? Na amũsũngĩa, Nĩ mwana wa mwĩkali wa ũenini, Mũamaleki.'),
('kam', '2SA', 1, 14, 'Na Ndaviti amũkũlya, Nũndũ wa ki ndwaakĩa kũtambũũkya kw’oko kwaku wanange mwĩtĩkĩw’a mauta wa Yeova?'),
('kam', '2SA', 1, 15, 'Na Ndaviti eeta mwanake ũmwe, na asya, Thengeea ũmũthũũmũkĩe. Na amũkũna akw’a.'),
('kam', '2SA', 1, 16, 'Na Ndaviti amwĩa, Nthakame yaku yĩthĩwe ĩũlũ wa mũtwe waku; nũndũ kanyw’a waku nũkũkũsĩĩe, ũkyasya, Nĩnũaĩte mwĩtĩkĩw’a mauta wa Yeova.'),
('kam', '2SA', 1, 17, 'Na Ndaviti aĩa kĩĩo kĩĩ kwondũ wa Saulo na kwondũ wa Yonathani mwana wake'),
('kam', '2SA', 1, 18, '(na ameaĩa mamanyĩsye ana ma yuta wathi wa ũta: sisya, nĩkũandĩkĩtwe ĩvukunĩ ya Yasali):'),
('kam', '2SA', 1, 19, 'Ũnene waku, we Isilaeli, nĩwũaĩwe ĩũlũ wa kũndũ kwaku kũtũlu! Kaĩ! Ala me ũtonyi nĩ avalũku!'),
('kam', '2SA', 1, 20, 'Ũu ndũkatavanw’e ku Ngathi, Ndũkanyaĩĩkw’e nzĩanĩ nene sya Asikeloni: Eĩtu ma Avilisiti matikese kũtana, Eĩtu ma ala mate aĩke maikese kũkĩlya vinya.'),
('kam', '2SA', 1, 21, 'Inyw’ĩ iĩma sya Ngilivoa, Kũtikethĩwe ĩmwe kana mbua ĩũlũ wenyu, o na mĩũnda ya nthembo: Nũndũ nĩvo ngao ya ũla wĩ ũtonyi yekiw’e ĩkĩvũthw’a, Ngao ya Saulo ta ũtetĩkĩw’e mauta.'),
('kam', '2SA', 1, 22, 'Vala ve nthakame ya ala oae, vale ve ũnou wa ala me ũtonyi, Ũta wa Yonathani ndwaasyoka ĩtina, Na ũvyũ wa Saulo ũtyaasyoka mana.'),
('kam', '2SA', 1, 23, 'Saulo na Yonathani maĩ aseo na ma kwendeesya mathayũnĩ moo, O na kĩkw’ũnĩ kyoo matyaatanw’a: Maĩ mĩtũkĩ kwĩ ndiũ, Maĩ na vinya kwĩ mĩnyambũ.'),
('kam', '2SA', 1, 24, 'Inyw’ĩ eĩtu ma Isilaeli, ĩĩai Saulo, Ũla wamwĩkĩie ngũa ndune mũno sya kwendeesya, Ũla wekĩie wanake wa thaavu ngũanĩ syenyu.'),
('kam', '2SA', 1, 25, 'Kaĩ! Ala me ũtonyi nĩ avalũku kaũnĩ katĩ! Yonathani nĩwũaĩwe ĩũlũ wa kũndũ kwaku kũtũlu.'),
('kam', '2SA', 1, 26, 'Nĩngũũũya kwondũ waku, mwana‐a‐ia Yonathani: Wambendeeasya mũno: Wendo waku kwakwa waĩ wa ũseng’ya, Ũvĩtũkĩte wendo wa aka.'),
('kam', '2SA', 1, 27, 'Kaĩ! Ala me ũtonyi nĩ avalũku, Na mĩio ya kaũ nĩ myanangĩku!'),
('kam', '2SA', 2, 1, 'Na kweethĩwa ĩtina wa ũu, Ndaviti akũlya Yeova, akyasya, Nambate ndũanĩ o na yĩva ya Yuta? Na Yeova amwĩa, Ambata. Na Ndaviti akũlya, Nambate va? Na asũngĩa, Eviloni.'),
('kam', '2SA', 2, 2, 'Na ĩndĩ Ndaviti ambata kw’o, o na aka make eli, Ainoamu Mũyesileeli, na Avikaili ũla waĩ kĩveti kya Navali Mũkalimeli.'),
('kam', '2SA', 2, 3, 'Na Ndaviti ambatya andũ make ala maĩ nake, kĩla mũndũ na andũ ma nyũmba yake: na matũa ndũanĩ sya Eviloni.'),
('kam', '2SA', 2, 4, 'Na andũ ma Yuta mooka, na mamwĩtĩkĩĩsya Ndaviti mauta kw’o ethĩwe mũsumbĩ wa nyũmba ya Yuta. Na matavya Ndaviti, makyasya, Andũ ma Yavesi‐ngileati nĩmo ala mamwĩnzĩie Saulo nthĩ.'),
('kam', '2SA', 2, 5, 'Na Ndaviti atũma atũmwa kwa andũ ma Yavesi‐ngileati, na amea, Athimwai nĩ Yeova, nũndũ nĩmwĩkĩte mwĩaĩĩ wenyu, o Saulo, ũseo ũũ, wa kũmwĩnzĩa nthĩ.'),
('kam', '2SA', 2, 6, 'Na yu Yeova namwon’ye ũseo wĩ wendo na w’o: nakwa ngamwĩka nesa ũndũ wa ũseo ũsu, nũndũ nĩmwĩkĩte ũndũ ũsu.'),
('kam', '2SA', 2, 7, 'Yu kwondũ wa ũu moko menyu methĩwe na vinya, nenyu mwĩthĩwe na ũkũmbaũ; nũndũ Saulo mwĩaĩi wenyu nĩ mũkw’ũ, na ĩngĩ nyũmba ya Yuta nĩmbĩtĩkĩsye mauta nĩthĩwe mũsumbĩ wayo.'),
('kam', '2SA', 2, 8, 'Na yu Avineli mwana wa Neli, kavuteni wa nguthu ya Saulo, aĩ anamwosa Isi‐vosethi mwana wa Saulo, na kũmũtwaa ku Maanaimu;'),
('kam', '2SA', 2, 9, 'na amũtw’ĩkĩthya mũsumbĩ wa Ngileati, na Aasuli, na Yesileeli, na Evalaimu, na Mbenyamini, na Isilaeli onthe.'),
('kam', '2SA', 2, 10, 'Isi‐vosethi, mwana wa Saulo, aĩ wa myaka mĩongo ĩna yĩla wambĩlĩlye kũsumbĩka Isilaeli, na asumbĩka myaka ĩlĩ. Ĩndĩ nyũmba ya Yuta yaatĩĩa Ndaviti.'),
('kam', '2SA', 2, 11, 'Na ĩvinda yĩla Ndaviti wasumbĩkie nyũmba ya Yuta ku Eviloni nĩ myaka mũonza na myei thanthatũ.'),
('kam', '2SA', 2, 12, 'Na Avineli mwana wa Neli, na athũkũmi ma Isi‐vosethi mwana wa Saulo, mauma Maanaimu mathi Ngiveoni.'),
('kam', '2SA', 2, 13, 'Na Yoavu mwana wa Nzeluia, na athũkũmi ma Ndaviti maumaala, na makomana nao vakuvĩ na ndia ya Ngiveoni; na mekala nthĩ, amwe ngalĩ ĩmwe ya ndia, na ala angĩ ngalĩ ĩla ĩngĩ ya ndia.'),
('kam', '2SA', 2, 14, 'Na Avineli amwĩa Yoavu, Nĩngũkwĩsũva, anake mokĩle mathaũke twene. Na Yoavu asya, Mokĩle.'),
('kam', '2SA', 2, 15, 'Na ĩndĩ mookĩla na mainga me atale: ĩkũmi na elĩ ma Mbenyamini, o ma Isi‐vosethi mwana wa Saulo, na athũkũmi ĩkũmi na elĩ ma Ndaviti.'),
('kam', '2SA', 2, 16, 'Na makwatana mĩtwe kĩla ũmwe na ũla ũngĩ, na matonyanĩla mbaunĩ kĩla mũndũ na ũla ũngĩ: na ĩndĩ mavalũkanĩla vamwe: kwondũ wa ũu vandũ vau vetwa Elikathi‐asulimu, na vo ve Ngiveoni.'),
('kam', '2SA', 2, 17, 'Na kaũ waĩ vinya mũno mũthenya ũsu; na Avineli akĩlw’a vinya, o na andũ ma Isilaeli, nĩ athũkũmi ma Ndaviti.'),
('kam', '2SA', 2, 18, 'Na ana atatũ ma Nzeluia maĩ kw’o, Yoavu, na Avisai, na Asaeli: na Asaeli aĩ maũũ ta nthwaia nga.'),
('kam', '2SA', 2, 19, 'Na Asaeli akũa Avineli; na amũkũĩte ndaathũka ngali ya kw’oko kwa aũme kana kwa aka aeke kũmũkũa Avineli.'),
('kam', '2SA', 2, 20, 'Nĩvo ĩndĩ Avineli wasiisye ĩtina wake, na asya, Nue, Asaeli? Na asũngĩa, Ninyie.'),
('kam', '2SA', 2, 21, 'Na Avineli amwĩa, Athũka ngalĩ ya kw’oko kwa aũme kwaku kana kwa aka, ũkwate mwanake ũmwe, nokyosa mĩio yake ya kaũ. Ĩndĩ Asaeli ndaaĩtĩkĩla kwathũka aeke ũmũkũa.'),
('kam', '2SA', 2, 22, 'Na Avineli amwĩa Asaeli ĩngĩ, Athũka ũeke kũngũa: nĩkĩ ngũkũne ũvalũke nthĩ? Ngatonya ata ĩndĩ kũkĩlya ũthyũ wakwa vala ve Yoavu mwana‐a‐mwenyu?'),
('kam', '2SA', 2, 23, 'Ĩndĩ alea kwathũka: kwondũ wa ũu Avineli amũtonya na mũla wa ĩtumo ĩvunĩ, na ĩtumo yaumĩlĩla mũongo; na avalũka vo, na akw’ĩa o vo: na kweethĩwa, o ala mavikĩe vandũ vala Asaeli wavalũkile akĩkw’a maũngama.'),
('kam', '2SA', 2, 24, 'Ĩndĩ Yoavu na Avisai maatĩĩa Avineli: na syũa yathũa yĩla mavikie kĩĩmanĩ kya Ama, kĩla kĩ mbee wa Ngia nzĩanĩ ĩla ĩelete weũnĩ wa Ngiveoni.'),
('kam', '2SA', 2, 25, 'Na ana ma Mbenyamini meeyũmbanĩsya vala ve Avineli, na matw’ĩka nguthu ĩmwe, na maũngama mũtumbĩnĩ wa kĩĩma.'),
('kam', '2SA', 2, 26, 'Nĩvo ĩndĩ Avineli wamwĩtie Yoavu, na amũkũlya, Ũvyũ ũkamina matukũ onthe? Ndũũmanya kũkeethĩwa ũũ mũminũkĩlyonĩ? Kũkeethĩwa kũvika ĩndĩĩ ũkĩsa kũtavya andũ masyoke maeke kũatĩĩa ana‐a‐ĩthe moo?'),
('kam', '2SA', 2, 27, 'Na Yoavu asya, O tondũ Ngai wĩ thayũ, o na kethĩwa ndũnaneena, vate ndĩi andũ meĩ yĩnũka kĩoko, na makĩeka kũatĩĩa kĩla ũmwe mwana‐a‐ĩthe wake.'),
('kam', '2SA', 2, 28, 'Kwondũ wa ũu Yoavu avuva soo; na andũ onthe maũngama, na matyaaatĩĩa Isilaeli ĩngĩ, kana kũkita namo ĩngĩ.'),
('kam', '2SA', 2, 29, 'Na Avineli na andũ make maenda ũtukũ ũsu w’onthe mavĩtĩla Alava; na mainga Yolotani, na mavĩtĩla Vithiloni yonthe, na mavika Maanaimu.'),
('kam', '2SA', 2, 30, 'Na Yoavu asyoka aeka kũatĩĩa Avineli: na yĩla waminie kũmban’ya andũ onthe, athũkũmi ma Ndaviti maolekete andũ ĩkũmi na kenda, na Asaeli.'),
('kam', '2SA', 2, 31, 'Ĩndĩ athũkũmi ma Ndaviti nĩmakũnĩte andũ ma Mbenyamini, o andũ ma Avineli, makakw’a andũ maana atatũ na mĩongo thanthatũ.'),
('kam', '2SA', 2, 32, 'Na mamwosa Asaeli na mamũthika ngunganĩ ya ĩthe wake vala vathikawa akw’ũ, ĩla yaĩ Mbethi‐leemu. Na Yoavu na andũ make maenda ũtukũ w’onthe, na makeewe ku Eviloni.'),
('kam', '2SA', 3, 1, 'Na kwaĩ kaũ ĩvinda ĩasa wa nyũmba ya Saulo na nyũmba ya Ndaviti: na Ndaviti aendeea kũneneva mũno, ĩndĩ nyũmba ya Saulo yaendeea na kwaa vinya mũno.'),
('kam', '2SA', 3, 2, 'Na Ndaviti asyaĩa ana ku Eviloni: ĩkithathi yake nĩ Aminoni, wa Ainoamu Mũyesileeli;'),
('kam', '2SA', 3, 3, 'na mwana wake wa kelĩ nĩ Kileavu, wa Avikaili ũla waĩ kĩveti kya Navali Mũkalimeli; na wa katatũ nĩ Avisalomu mwana wa Maaka mwĩĩtu wa Talimai mũsumbĩ wa Ngesuli;'),
('kam', '2SA', 3, 4, 'na wa kana nĩ Atoniya mwana wa Akithi; na wa katano nĩ Sevatia mwana wa Avitali;'),
('kam', '2SA', 3, 5, 'na wa thanthatũ nĩ Ithileamu wa Ekila, kĩvetĩ kya Ndaviti. Asu Ndaviti amasyaĩe ku Eviloni.'),
('kam', '2SA', 3, 6, 'Na kweethĩwa, yĩla kwaĩ kaũ wa nyũmba ya Saulo na nyũmba ya Ndaviti, Avineli eeyongeleela vinya nyũmbanĩ ya Saulo.'),
('kam', '2SA', 3, 7, 'Na Saulo aĩ na mũka ngombo, ũla syĩtwa yake eetawa Lisiva, mwĩĩtu wa Aia: na Isi‐vosethi akũlya Avineli, Nũndũ wa kĩ ũlikĩte kwa mũka ngombo wa ĩthe wakwa?'),
('kam', '2SA', 3, 8, 'Nĩvo ĩndĩ Avineli wathilĩkile mũno nũndũ wa ndeto sya Isi‐vosethi, na akũlya, Nyie nĩ mũtwe wa ngitĩ ĩsu Yuta? Ũmũnthĩ nĩnĩkaa nyũmba ya Saulo ĩthe waku nesa, na ana‐a‐ĩthe make, na anyanyae make, na ndyaakũnengane kw’okonĩ kwa Ndaviti; ĩndĩ ũmũnthĩ nũũmbilĩĩla ĩvĩtyo ũndũ wa mũndũ mũka ũsu.'),
('kam', '2SA', 3, 9, 'Ngai namwĩke Avineli ũu, o na mbee, ethĩwa ndimwĩka Ndaviti o w’o, o tondũ Yeova wamwĩvĩtĩe Ndaviti;'),
('kam', '2SA', 3, 10, 'aumye ũsumbĩ nyũmbanĩ ya Saulo, na kũũngamya kĩvĩla kya ũsumbĩ kya Ndaviti asumbĩke Isilaeli na Yuta, kuma Ndani o na kũvika Mbeeli‐sieva.'),
('kam', '2SA', 3, 11, 'Na ndaatonya kũsũngĩa Avineli ndeto ĩngĩ, nũndũ nĩwamũkĩie.'),
('kam', '2SA', 3, 12, 'Na Avineli atũma atũmwa kwa Ndaviti ngalĩ ĩ yake, akĩmũkũlya, Nthĩ nĩ vau? Na ĩngĩ akĩmwĩa, Seũvya wĩw’ano waku nakwa, na, sisya, kw’oko kwakwa kũkeethĩwa vamwe naku, nĩalyũle Isilaeli onthe methĩwe ngalĩ yaku.'),
('kam', '2SA', 3, 13, 'Na asũngĩa. Nĩ ũseo; ngaseũvya wĩw’ano naku; ĩndĩ ũndũ ũmwe ngũandũa kwaku: nĩ atĩĩ, ndũkona ũthyũ wakwa, ũtaetete Mikali, mwĩĩtu wa Saulo, yĩla wĩũka kwona ũthyũ wakwa.'),
('kam', '2SA', 3, 14, 'Na Ndaviti atũma atũmwa kwa Isi‐vosethi, mwana wa Saulo, akĩmwĩa, Nenga mũka wakwa Mikali, ũla neeasĩsye na ikonde sya mbinũ ĩana sya Avilisiti.'),
('kam', '2SA', 3, 15, 'Na Isi‐vosethi atũmana, na amumya kwa mũũme, o kuma kwa Valitieli mwana wa Laisa.'),
('kam', '2SA', 3, 16, 'Na mũũme aendan’ya nake, akĩĩa aendete, na amũatĩĩa kũvika Mbaulimu. Nĩvo ĩndĩ Avineli wamwĩie, Enda, ũsyoke: na asyoka.'),
('kam', '2SA', 3, 17, 'Na Avineli aneena na atumĩa ma Isilaeli, Mavinda ala mavitu nĩmwamanthie Ndaviti ethĩwe mũsumbĩ wenyu:'),
('kam', '2SA', 3, 18, 'na yu ĩndĩ ĩkai ũu; nũndũ Yeova nũneenete ũndũ wa Ndaviti, akyasya, Ngatangĩĩa andũ makwa Isilaeli na kw’oko kwa mũthũkũmi wakwa Ndaviti kũmaumya kw’okonĩ kwa Avilisiti, na kuma kw’okonĩ kwa amaitha moo onthe.'),
('kam', '2SA', 3, 19, 'O na Avineli aneena matũnĩ ma Mbenyamini: na ĩngĩ Avineli athi aneene matũnĩ ma Ndaviti ku Eviloni ũvoo w’onthe ũla Isilaeli moonie wĩ ũseo, o na nyũmba yonthe ya Mbenyamini.'),
('kam', '2SA', 3, 20, 'Na ĩndĩ Avineli ooka vala ve Ndaviti Eviloni, e na andũ mĩongo ĩlĩ. Na Ndaviti amavokea Avineli na andũ ala maĩ nake mboka.'),
('kam', '2SA', 3, 21, 'Na Avineli amwĩa Ndaviti, Nĩngũkĩla nĩthi, ngamũmbanĩsye mwĩaĩi wakwa mũsumbĩ Isilaeli onthe, nĩ kana matianĩe ũtianĩo naku, na nĩ kana ũsumbĩke w’onthe ũla ngoo yaku yendete. Na Ndaviti amũeka Avineli athi; na aenda na mũuo.'),
('kam', '2SA', 3, 22, 'Na, sisya, athũkũmi ma Ndaviti mooka me na Yoavu maumĩte kaũnĩ, na maete mũtavo mũnene: ĩndĩ Avineli ndaĩ na Ndaviti ku Eviloni; nũndũ nĩwamũekete na akathi, na aĩ anaenda na mũuo.'),
('kam', '2SA', 3, 23, 'Na yĩla Yoavu na ngũthu yonthe ĩla yaĩ nake mavikie, andũ matavya Yoavu, makĩmwĩa, Avineli mwana wa Neli okie kwa mũsumbĩ, na nũmũekie athi, na nũendie na mũuo.'),
('kam', '2SA', 3, 24, 'Nĩvo ĩndĩ Yoavu waendie kwa mũsumbĩ, na amũkũlya, Wĩkie ata? Sisya, Avineli nĩwũkie kwaku; nũndũ wa kĩ ũmũekie athi, na nũendie vyũ?'),
('kam', '2SA', 3, 25, 'Nũmwĩsĩ Avineli mwana wa Neli, kana okie akũkenge, na kũthiana kumaala kwaku na kũlika kwaku, na kũmanya w’onthe ũla wĩkaa.'),
('kam', '2SA', 3, 26, 'Na yĩla Yoavu waumie vala ve Ndaviti, atũma atũmwa maatĩĩe Avineli, na mamũtũngĩthĩsya kĩthimanĩ kya Silaa: ĩndĩ Ndaviti ndaamanya ũu.'),
('kam', '2SA', 3, 27, 'Na yĩla Avineli watũngiwe Eviloni, Yoavu amũtwaa ũtee mbingĩlonĩ katĩ aneene nake mbola, na amũtonyea ĩvu vo, na akw’a, nũndũ wa nthakame ya mwana‐a‐ĩthe Asaeli.'),
('kam', '2SA', 3, 28, 'Na ĩtina, yĩla Ndaviti wewie ũu, asya, Nyie na ũsumbĩ wakwa tũti na ĩtĩtyo kwa Yeova tene na tene ũndũ wa nthakame ya Avineli mwana wa Neli:'),
('kam', '2SA', 3, 29, 'nĩyĩthĩwe ĩũlũ wa mũtwe wa Yoavu, na nyũmba ya ĩthe wake; na nyũmba ya Yoavu ndĩkaaĩthĩwe o na ĩndĩĩ ĩte na ũmwe wĩ na mũluo, kana wĩ na mangũ, kana ũla wĩlumĩlaa na ndata, kana ũla ũvalũkawa na ũvyũ, kana ũla ũte na lĩu.'),
('kam', '2SA', 3, 30, 'Na ĩndĩ Yoavu na Avisai mwana‐a‐inyia mooaie Avineli, nĩkwĩthĩwa nĩwoaĩe mwana‐a‐inyia woo Asaeli ku kaũnĩ Ngiveoni.'),
('kam', '2SA', 3, 31, 'Na Ndaviti amwĩa Yoavu, na andũ onthe ala maĩ nake, Tembũangai ngũa syenyu, na mũyĩvotoa makunia, mũmũmetee Avineli. Na mũsumbĩ Ndaviti aatĩĩa mũsekeseke.'),
('kam', '2SA', 3, 32, 'Na mamũthika Avineli ku Eviloni: na mũsumbĩ ookĩlya wasya wake, na aĩĩa mbũanĩ ya Avineli; na andũ onthe maĩa.'),
('kam', '2SA', 3, 33, 'Na mũsumbĩ amũĩĩa Avineli, na akũlya, Avineli aĩle kũkw’a tondũ ndia ĩkusaa?'),
('kam', '2SA', 3, 34, 'Moko maku matyĩĩ move, kana maũũ maku matyĩĩkĩwe mbĩngũ: O tondũ mũndũ ũvalũkaa mbee wa ana ma ũthũku, now’o wavalũka. Na andũ onthe mamũĩĩa ĩngĩ.'),
('kam', '2SA', 3, 35, 'Na andũ onthe mooka mamũingĩĩsye Ndaviti aye lĩu kwĩ mũthenya; ĩndĩ Ndaviti eevita, akyasya, Ngai nambĩke ũu, o na mbee, ethĩwa ngasama kĩmũtũ, kana kĩndũ kĩngĩ syũa yĩte ĩthũu.'),
('kam', '2SA', 3, 36, 'Na andũ onthe moona ũndũ ũsu, na mendeew’a; nũndũ o ũndũ mũsumbĩ wekaa andũ onthe mendeeaw’a nĩw’o.'),
('kam', '2SA', 3, 37, 'Kwondũ wa ũu andũ onthe ma Isilaeli onthe mamanya mũthenya ũsu kana ti ũvoo wa mũsumbĩ kũaa Avineli mwana wa Neli.'),
('kam', '2SA', 3, 38, 'Na mũsumbĩ akũlya athũkũmi make, Mũtyĩsĩ kana mũnene wĩ mbee ũsumbĩnĩ, mũndũ wĩ nguma, nũvalũkile ũmũnthĩ kwa Isilaeli?'),
('kam', '2SA', 3, 39, 'Na ũmũnthĩ nĩ mwonzu, o na kau nĩnetĩkĩw’e mauta nĩthĩwe mũsumbĩ; na andũ aa ana ma Nzeluia nĩmanemie nyie: Yeova naĩvanĩsye mwĩki wa ũthũku kwĩanana na ũthũku wake.'),
('kam', '2SA', 4, 1, 'Na yĩla Isi‐vosethi, mwana wa Saulo, wewie Avineli nũnakw’ĩĩe Eviloni, moko make maleela, na Aisilaeli onthe maũũya.'),
('kam', '2SA', 4, 2, 'Na Isi‐vosethi, mwana wa Saulo, aĩ na andũ elĩ makavuteni ma nguthu: syĩtwa ya ũmwe eetawa Mbaana, na syĩtwa ya ũla ũngĩ eetawa Lekavi, ana ma Limoni Mũmbeelothi, wa ana ma Mbenyamini (nũndũ o na Mbeelothi ĩtalawa ya Mbenyamini:'),
('kam', '2SA', 4, 3, 'na Ambeelothi maindũkĩĩa Ngitaimu, na nĩ ekali ma ũeninĩ kw’o kũvika ũmũnthĩ).'),
('kam', '2SA', 4, 4, 'Na Yonathani, mwana wa Saulo, aĩ na mwana waĩte maũũ. Aĩ wa myaka ĩtano yĩla ũvoo wa Saulo na Yonathani waumie Yesileeli; na mũei wake amũvulya, na akĩa: na kweethĩwa, ekalaatĩte akĩe, mwana avalũka na ĩndĩ aaa maũũ. Na syĩtwa yake eetawa Mevivosethi.'),
('kam', '2SA', 4, 5, 'Na ana ma Limoni Mũmbeelothi, Lekavi na Mbaana, mathi, na mavika nyũmbanĩ ya Isi‐vosethi mũthenya kwavyũva, o yĩla wathũmũĩte mũthenya katĩ.'),
('kam', '2SA', 4, 6, 'Na malika nyũmbanĩ nthĩnĩ, ta mekwenda kwosa nganũ; na mamũtonya ĩvu: na Lekavi na Mbaana mwana‐a‐inyia makũka.'),
('kam', '2SA', 4, 7, 'Na ĩndĩ yĩla malikile nyũmbanĩ, akomete ũkomoni wake kasũmbanĩ kake ka ũkoma, mamũtonya, na mamũaa, na matila mũtwe wake, na moosa mũtwe wake, na mathi ũtukũ w’onthe na nzĩa ĩla ĩelete nthĩ ya Alava.'),
('kam', '2SA', 4, 8, 'Na mamũtwaĩa Ndaviti mũtwe wa Isi‐vosethi ku Eviloni, na mamwĩa mũsumbĩ, Sisya mũtwe wa Isi‐vosethi, mwana wa Saulo, mũmaitha waku, ũla wamanthaa thayũ waku; na Yeova nũĩvanĩsye mwĩaĩĩ wakwa mũsumbĩ ũmũnthĩ ũndũ wa Saulo na, ũsyao wake.'),
('kam', '2SA', 4, 9, 'Na Ndaviti asũngĩa Lekavi na Mbaana mwana‐a‐inyia, ana ma Limoni Mũmbeelothi, na amea, O tondũ Yeova wĩ thayũ, ũla wovoisye thayũ wakwa kuma thĩnanĩ w’onthe,'),
('kam', '2SA', 4, 10, 'yĩla ũmwe wandavisye, akyasya, Sisya, Saulo nĩ mũkw’ũ, akĩsũanĩa nũetete ũvoo mũseo, nĩnamũkwatie, na namũaĩa Nzikilaki, nĩw’o waĩ ĩtuvi yake namũnengie ũndũ wa ũvoo wake.'),
('kam', '2SA', 4, 11, 'Nĩ mbee veana ata, ngaandũa nthakame yake mokonĩ menyu, na kũmũveta kũũ nthĩ, yĩla andũ athũku mooaĩe mũndũ mũlũngalu nyũmbanĩ yake mwene e ũkomonĩ wake?'),
('kam', '2SA', 4, 12, 'Na Ndaviti eeaĩa anake make, namo mamoaa, na matila moko moo, na maũũ moo, na kũmasũsya vakuvĩ na ndia yĩ Eviloni. Ĩndĩ moosa mũtwe wa Isi‐vosethi, na mawĩnzĩa nthĩ mbũanĩ ya Avineli kũ Eviloni.'),
('kam', '2SA', 5, 1, 'Nĩvo ĩndĩ mbaĩ syonthe sya Isilaeli syookie Eviloni kwa Ndaviti, na syaneena, ikĩmwĩa, Sisya, twĩ ĩvĩndĩ yaku na mwĩĩ waku.'),
('kam', '2SA', 5, 2, 'Mavinda mavĩtu yĩla Saulo waĩ mũsumbĩ waitũ, nue watongoesye Isilaeli kũmaumaalasyaa na kũmatũngaa: na Yeova akwĩa, Nue ũkethĩwa mũĩthi wa andũ makwa Isilaeli, na ũkethĩwa mũnene wĩ mbee ũsumbĩnĩ wa Isilaeli.'),
('kam', '2SA', 5, 3, 'Kwondũ wa ũu atumĩa onthe ma Isilaeli mooka kwa mũsumbĩ ku Eviloni; na mũsumbĩ Ndavitĩ atianĩĩa ũtianĩo nao ku Eviloni mbee wa Yeova: na mamwĩtĩkĩsya Ndaviti mauta ethĩwe mũsumbĩ wa Isilaeli.'),
('kam', '2SA', 5, 4, 'Ndaviti aĩ wa myaka mĩongo ĩtatũ yĩla wambĩlilye kũsumbĩka, na asumbĩka myaka mĩongo ĩna.'),
('kam', '2SA', 5, 5, 'Ku Eviloni asumbĩka Yuta myaka mũonza na myei thanthatũ; na Yelusaleme asumbĩka Isilaeli onthe na Yuta myaka mĩongo ĩtatũ na ĩtatũ.'),
('kam', '2SA', 5, 6, 'Na mũsumbĩ na andũ make maenda Yelusaleme mokite na Ayevusi, ala matwĩe ĩ nthĩ, ala maneenie na Ndaviti, makĩmwĩa, Ũtavetete ililinda na ala mathuaa, ndũkalika vaa; makĩsũanĩa, Ndaviti ndatonya kũlika vaa.'),
('kam', '2SA', 5, 7, 'Ĩndĩ Ndaviti oosa ngome yĩ vinya ya Saioni; nayo nĩ ndũa ya Ndaviti.'),
('kam', '2SA', 5, 8, 'Na Ndaviti aneena mũthenya ũsu, O ũla wĩthi kũkũna Ayevusi, nĩambate na mũtaũ wa manzĩ, na aikũna ala mathuaa na ililinda, ala mamenetwe nĩ ngoo ya Ndaviti. Kwondũ wa ũu measya, Ve ala mathuaa na ililinda; ndatonya kũlika ĩ nyũmba.'),
('kam', '2SA', 5, 9, 'Na Ndaviti nĩwekalaa ngomenĩ ĩsu yĩ vinya, na amĩta ndũa ya Ndaviti. Na Ndaviti aaka athyũlũlũkĩtye, kuma Milo na kũendeea nthĩnĩ.'),
('kam', '2SA', 5, 10, 'Na Ndaviti ongeleka kũneneva; nũndũ Yeova, Ngai wa nguthu, aĩ vamwe nake.'),
('kam', '2SA', 5, 11, 'Na Ilamu mũsumbĩ wa Tile atũma atũmwa kwa Ndaviti, na mĩtĩ ya mĩkũũ, na aseũvya ma mbwaũ, na aki ma mavia; na mamwakĩa Ndaviti nyũmba.'),
('kam', '2SA', 5, 12, 'Na Ndaviti amanya kana Yeova nũmũlũlũmĩlye ethĩwe mũsumbĩ wa Isilaeli, na nĩwũkĩlĩtye ũsumbĩ wake kwondũ wa andũ make Isilaeli.'),
('kam', '2SA', 5, 13, 'Na Ndaviti atwaa aka angĩ ngombo na iveti ku Yelusaleme, ĩtina wa auma Eviloni; na ana na eĩtu angĩ masyawa nĩ Ndaviti.'),
('kam', '2SA', 5, 14, 'Na aa nĩo masyĩtwa ma ala masyaĩwe Yelusaleme: Samua, na Sovavu, na Nathani, na Solomoni,'),
('kam', '2SA', 5, 15, 'na Iviali, na Elisua, na Neveki, na Yavia,'),
('kam', '2SA', 5, 16, 'na Elisama, na Eliata, na Eliveleti.'),
('kam', '2SA', 5, 17, 'Na yĩla Avilisiti meewie kana nĩmamwĩtĩkĩsye Ndaviti mauta ethĩwe mũsumbĩ wa Isilaeli onthe, Avilisiti onthe mambata mamanthe Ndaviti; na Ndaviti eew’a ũu, na atheea vala ve ngome yĩ vinya.'),
('kam', '2SA', 5, 18, 'Na Avilisiti maĩ manooka na makenyasya mwandanĩ wa Alevai.'),
('kam', '2SA', 5, 19, 'Na Ndaviti akũlya Yeova, akyasya, Nambate kũkita na Avilisiti? Ũkamanengane kw’okonĩ kwakwa? Na Yeove amwĩa Ndaviti, Ambata; nũndũ vate ndĩi nganengane Avilisiti kw’okonĩ kwaku.'),
('kam', '2SA', 5, 20, 'Na Ndaviti avika Mbaali‐velasimu, na Ndaviti amakũnĩa kw’o; na asya, Yeova nũtũlĩte amaitha makwa nene, ta vandũ vavũthũĩtwe nĩ manzĩ. Kwondũ wa ũu eeta syĩtwa ya vandũ vau Mbaali‐velasimu.'),
('kam', '2SA', 5, 21, 'Na matia mĩvw’anano yoo kw’o; na Ndaviti na andũ make mamĩtwaa.'),
('kam', '2SA', 5, 22, 'Na Avilisiti mambata o ĩngĩ, na meenyasya mwandanĩ wa Alevai.'),
('kam', '2SA', 5, 23, 'Na yĩla Ndaviti wakũlilye Yeova, amwĩa, Ndũkambate: melingĩle ĩtina woo, noimavithũkĩa welekele mĩtĩnĩ ya mĩvolosati.'),
('kam', '2SA', 5, 24, 'Na kũkeethĩwa, yĩla wĩĩw’a matuu ta ma andũ maendele mĩthyanĩ ya mĩvolosatĩ, nĩvo ĩndĩ wĩkuthũka; nũndũ nĩvo Yeova wumaalĩte mbee waku akũne nguthu ya Avilisiti.'),
('kam', '2SA', 5, 25, 'Na Ndaviti eeka ũu, o tondũ Yeova wamwĩaĩe, na akũna Avilisiti kuma Ngeva kũvika Ngeseli.'),
('kam', '2SA', 6, 1, 'Na Ndaviti oomban’ya ĩngĩ andũ onthe anyuve ma Isilaeli, ngili mĩongo ĩtatũ.'),
('kam', '2SA', 6, 2, 'Na Ndaviti ookĩla, na aenda na andũ onthe ala maĩ nake, kuma Mbaaleyuta, makaete kuma kw’o ĩsandũkũ ya Ngai, yĩla yĩtanĩaw’a na yĩla Syĩtwa, nayo nĩ syĩtwa ya Yeova wa nguthu ũla wĩkalaa ĩũlũ wa akeluvi.'),
('kam', '2SA', 6, 3, 'Na mailĩĩla ĩsandũkũ ya Ngai ĩkasyanĩ yeũ, na mayumya nyũmbanĩ ya Avinatavu ĩla yaĩ kĩĩmanĩ: na Usa na Aio, ana ma Avinatavu mainga yĩla ĩkasya yeũ.'),
('kam', '2SA', 6, 4, 'Na mayumya nyũmbanĩ ya Avinatavu, ĩla yaĩ kĩĩmanĩ, vamwe na ĩsandũkũ ya Ngai: na Aio atongoesya yĩla ĩsandũkũ.'),
('kam', '2SA', 6, 5, 'Na Ndaviti na nyũmba yonthe ya Isilaeli mainga me mbee wa Yeova mĩthemba yonthe ya syĩndũ sya kũinga iseũvĩtw’e na mĩtĩ ya mĩsonovali, na mbeve, na inanda, na tũthembe, na tũmĩtĩ twa ũkunangan’ya, na tũmasaya.'),
('kam', '2SA', 6, 6, 'Na yĩla mavikie kĩvũĩonĩ kya Nakoni Usa atambũũkya kw’oko kwake vala ve ĩsandũkũ ya Ngai, na ayĩtw’ĩĩka; nũndũ ng’ombe mĩsyatiũũkie.'),
('kam', '2SA', 6, 7, 'Na ũthatu wa Yeova wakanĩa Usa; na Ngai amũkũnĩa vo nũndũ wa ĩvĩtyo yake; na akw’ĩa vo vakuvĩ na ĩsandũkũ ya Ngai.'),
('kam', '2SA', 6, 8, 'Na Ndaviti eew’a woo, nũndũ Yeova nĩwakũna Usa; na eeta vandũ vau Velesi‐ũsa, kũvika ũmũnthĩ.'),
('kam', '2SA', 6, 9, 'Na Ndaviti akĩa Ngai mũthenya ũsu; na asya, Ĩsandũkũ ya Yeova yĩkaetwe kwakwa ata?'),
('kam', '2SA', 6, 10, 'Kwondũ wa ũu Ndaviti ndaaĩtĩkĩla kũthamĩsya ĩsandũkũ ya Yeova kwake ndũanĩ ya Ndaviti; ĩndĩ Ndaviti ayelelũkĩĩlya nyũmbanĩ ya Oveti‐etomu Mũngiti.'),
('kam', '2SA', 6, 11, 'Na ĩsandũkũ ya Yeova yekala nyũmbanĩ ya Oveti‐etomu Mũngiti myei ĩtatũ: na Yeova aathima Oveti‐etomu, na nyũmba yake yonthe.'),
('kam', '2SA', 6, 12, 'Na mũsumbĩ Ndaviti wataviw’e, kũkyaw’a, Yeova nũathimĩte nyũmba ya Oveti‐etomu, na syĩndũ syake syonthe, nũndũ wa ĩsandũkũ ya Ngai. Na Ndaviti aenda na aete ĩsandũkũ ya Ngai ndũanĩ ya Ndaviti kuma nyũmbanĩ ya Oveti‐etomu ayĩlikya ndũanĩ ya Ndaviti e na ũtanu.'),
('kam', '2SA', 6, 13, 'Na kweethĩwa, yĩla ala makuĩte ĩsandũkũ ya Yeova maĩ manaenda matambya thanthatũ, athemba ng’ombe na kĩla kĩnou.'),
('kam', '2SA', 6, 14, 'Na Ndaviti asũnga e mbee wa Yeova na vinya wake w’onthe; na Ndaviti evotoete evoti ya katane.'),
('kam', '2SA', 6, 15, 'Uu nĩw’o Ndaviti na nyũmba yonthe ya Isilaeli maetie ĩsandũkũ ya Yeova makyũkĩlya mawasya manene, na wasya wa soo.'),
('kam', '2SA', 6, 16, 'Na kweethĩwa, yĩla ĩsandũkũ ya Yeova yalikile ndũanĩ ya Ndaviti, Mĩkalĩ mwĩĩtu wa Saulo asyaĩlya mbũthinĩ, na oona mũsumbĩ Ndaviti akĩtũlĩlanga na kũsũnga e mbee wa Yeova; na amũvũthya ngoonĩ yake.'),
('kam', '2SA', 6, 17, 'Na maete ĩsandũkũ ya Yeova nthĩnĩ, na mayia vandũ vayo, ĩeemanĩ nthĩnĩ yĩla Ndaviti wambĩte kwondũ wayo; na Ndaviti amũthembea Yeova nthembo sya kũvĩvw’a na nthembo sya mũuo.'),
('kam', '2SA', 6, 18, 'Na yĩla Ndaviti waminie kũthemba nthembo ya kũvĩvw’a na nthembo sya mũuo, aathima andũ syĩtwanĩ ya Yeova wa nguthu.'),
('kam', '2SA', 6, 19, 'Na amaaĩa andũ onthe, o ĩkomano yonthe ya Isilaeli, aũme o na aka, kĩla ũmwe kĩlungu kya kĩmũtũ, na kĩlungu kya nyama, na kakũmbwa ka nzavivũ mbovu. Na ĩndĩ andũ onthe maenda kĩla ũmwe nyũmbanĩ kwake.'),
('kam', '2SA', 6, 20, 'Na ĩndĩ Ndaviti asyoka aathime andũ ma nyũmba yake. Na Mikali mwĩĩtu, wa Saulo aumaala amũthaũe Ndaviti, na asya, A! Kaĩ, mũsumbĩ wa Isilaeli nĩwĩnenevisye ũmũnthĩ, ũla wĩvũie ũmũnthĩ athũkũmi eĩtu ma athũkũmi make mamwene, o tondũ ũmwe wa ala mate kĩĩĩ wĩvuaa vate nthoni!'),
('kam', '2SA', 6, 21, 'Na Ndaviti amwĩa Mikali, Ũu wĩĩ mbee wa Yeova, ũla wanyuvie kũte au, na kũte nyũmba yake yonthe, kũmbia nĩthĩwe mũnene wĩ mbee ũsumbĩnĩ andũnĩ ma Yeova, o Isilaeli; kwondũ wa ũu ngasũnga Yeova ene.'),
('kam', '2SA', 6, 22, 'O na ngeethĩwa nĩ mũthũku kũvĩta ũu, na ngeethĩwa nĩ ĩtheo methonĩ makwa mwene: ĩndĩ ngataĩwa nĩ athũkũmi eĩtu, asu ala waweta.'),
('kam', '2SA', 6, 23, 'Na Mikali mwĩĩtu wa Saulo ndaaĩthĩwa na kana kũvika mũthenya wa kĩkw’ũ kyake.'),
('kam', '2SA', 7, 1, 'Na kweethĩwa, yĩla mũsumbĩ wekalaa nyũmbanĩ yake, na Yeova wamũnengete kũthũmũa kuma amaithanĩ make onthe ala mathyũlũlũkĩte,'),
('kam', '2SA', 7, 2, 'mũsumbĩ amwĩa mwathani Nathani, Sisya yu, nĩkalaa nyũmbanĩ ya mĩtĩ ya mĩkũũ, ĩndĩ ĩsandũkũ ya Ngai nĩyĩkalaa nthĩnĩ wa motũtũ ma ngũa.'),
('kam', '2SA', 7, 3, 'Na Nathani amwĩa mũsumbĩ, Enda na ũkĩka w’onthe ũla wĩ ngoonĩ yaku; nũndũ Yeova e vamwe naku.'),
('kam', '2SA', 7, 4, 'Na kweethĩwa ũtukũ ũsu, ndeto ya Yeova yamũkĩa Nathani, ikimwĩa,'),
('kam', '2SA', 7, 5, 'Enda, ũmũtavye mũthũkũmi wakwa Ndaviti, Ũũ nĩw’o Yeova ũnũũkũlya, Ũkambakĩa nyũmba ya kwĩkala?'),
('kam', '2SA', 7, 6, 'Nũndũ ndyaaĩkala nyũmbanĩ kuma mũthenya ũla nambatisye ana ma Isilaeli kuma Misili, o kũvika ũmũnthĩ, ĩndĩ nĩnĩendaa ĩeemanĩ na wĩkalonĩ.'),
('kam', '2SA', 7, 7, 'Kũndũ kw’onthe kũla naatambũka na ana onthe ma Isilaeli, naaneena ndeto na mbaĩ o na yĩva ya Isilaeli, ĩla neeaĩe ĩĩthye andũ makwa Isilaeli, ngakũlya, Nũndũ wa kĩ mũtyaambakĩa nyũmba ya mĩtĩ ya mĩkũũ?'),
('kam', '2SA', 7, 8, 'Na yu kwondũ wa ũu ũkamwĩe mũthũkũmi wakwa Ndaviti atĩĩ, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Nĩnakumisye kyengonĩ kya malondu, yĩla waatĩĩaa malondu, nĩ kana wĩthĩwe mũnene wĩ mbee ũsumbĩnĩ andũnĩ makwa, o Isilaeli;'),
('kam', '2SA', 7, 9, 'na naĩ vamwe naku o vala waendaa, na naveta amaitha maku onthe maume mbee waku; na ngakwonea syĩtwa ĩnene, ta syĩtwa ya ala anene ala me kũũ nthĩ.'),
('kam', '2SA', 7, 10, 'Na ngatw’a vandũ kwondũ wa andũ makwa Isilaeli, na ngamavanda, nĩ kana matũae vandũ voo ene, na matikathamw’a ĩngĩ; o na ana ma ũthũku matikamathĩn’ya ĩngĩ, ta ĩvinda ya mbee,'),
('kam', '2SA', 7, 11, 'na kuma mũthenya ũla neeaĩe asili methĩwe ĩũlũ wa andũ makwa Isilaeli; na ngakũthũmũsya kuma amaithanĩ maku onthe. Na ĩngĩ Yeova nũnũũkũtavya kana Yeova akakwakĩa nyũmba.'),
('kam', '2SA', 7, 12, 'Yĩla matukũ maku meĩanĩa, na wĩkoma na aaĩthe maku, ngookĩlya ũsyao waku ĩtina waku, ũla ũkauma kĩnyunyũnĩ kyaku, na ngalũlũmĩlya ũsumbĩ wake.'),
('kam', '2SA', 7, 13, 'Akaaka nyũmba kwondũ wa syĩtwa yakwa, na ngalũlũmĩlya kĩvĩla kya ũsumbĩ kya ũsumbĩko wake tene na tene.'),
('kam', '2SA', 7, 14, 'Ngeethĩwa ĩthe wake, nake akeethĩwa mwana wakwa: ethĩwa akeeka ũthũku, ngamũsilĩla na ndata ya andũ, na makũna ma ana ma andũ;'),
('kam', '2SA', 7, 15, 'ĩndĩ ũseo wakwa wĩ wendo ndũkauma kwake, o tondũ nawumisye kwa Saũlo, ũla navetie aume mbee waku.'),
('kam', '2SA', 7, 16, 'Na nyũmba yaku na ũsumbĩ waku ĩkalũlũmĩlw’a kwaku tene na tene: kĩvĩla kyaku kya ũsumbĩ kĩkalũlũmĩlw’a tene na tene.'),
('kam', '2SA', 7, 17, 'Kwĩanana na ndeto ii syonthe, na kwĩanana na woni ũũ w’onthe, now’o Nathani wamũtavĩsye Ndaviti.'),
('kam', '2SA', 7, 18, 'Na ĩndĩ mũsumbĩ Ndaviti alika nthĩnĩ, na ekala mbee wa Yeova; na akũlya, Nyie nĩ ũũ, ame Mwĩaĩi Yeova, na nyũmba yakwa yĩ kyaũ, ũndũ ũndetete kũvika vaa nĩĩ?'),
('kam', '2SA', 7, 19, 'Na ũndũ ũsu nĩwonaa ta ũnini, ame Mwĩaĩi Yeova; ĩndĩ nũneenete ũvoo wa nyũmba ya mũthũkũmi waku kũvika ĩvinda yĩ vaasa mũno yĩla yĩkoka; na kaĩ ũu nĩwĩkawa nĩ andũ, ame Mwĩaĩi Yeova!'),
('kam', '2SA', 7, 20, 'Na Ndaviti atonya ũkũtavya ũndũ ũngĩ mwaũ mbee wa ũu? Nũndũ nĩwĩsĩ mũthũkũmi waku, ame Mwĩaĩi Yeova.'),
('kam', '2SA', 7, 21, 'Kwondũ wa ndeto yaku, na kwĩanana na ngoo yaku mwene, nĩwĩkĩte ũnene ũũ w’onthe, ũmanyĩthye mũthũkũmi wakũ ũndũ ũsu.'),
('kam', '2SA', 7, 22, 'Kwondũ wa ũu wi mũnene, ame Yeova Ngai: nũndũ vati ũngĩ ũilyĩ taku, o na vati Ngai ũngĩ ate o we, kwĩanana na w’onthe ũla twĩw’ĩte na matũ maitũ.'),
('kam', '2SA', 7, 23, 'Na nĩ yĩva mbaĩ ĩmwe kũũ nthĩ ĩilyĩ andũ maku, o Isilaeli, ala Ngai waendie kwĩyovoesya mwene methĩwe ũko wa andũ, na kwĩyonea syĩtwa, na ũkwĩka maũndũ manene, na maũndũ ma kũtĩsya kwondũ wa nthĩ yaku, kwa andũ maku, ala weeyovoesye kũmaumya Misili, kuma mbaĩnĩ na ngainĩ syasyo.'),
('kam', '2SA', 7, 24, 'Na weelũlũmĩlĩĩsya andũ maku Isilaeli methĩwe ũko wa andũ kwaku tene na tene; naku, Yeova, watw’ĩka Ngai woo.'),
('kam', '2SA', 7, 25, 'Na yu, ame Yeova Ngai, Ndeto ĩla ũneenete ũndũ wa mũthũkũmi waku, na ũndũ wa nyũmba yake, mĩlũlũmĩlye tene na tene, na ũkĩka o tondũ ũneenete.'),
('kam', '2SA', 7, 26, 'Na syĩtwa yaku nĩyĩnenevw’e tene ne tene, kũkyaw’a, Yeova wa nguthu nĩ Ngai wa Isilaeli; na nyũmba ya mũthũkũmi waku Ndaviti ĩkalũlũmĩlw’a mbee waku.'),
('kam', '2SA', 7, 27, 'Nũndũ we, ame Yeova wa nguthu, Ngai wa Isilaeli, nũmũvuanĩsye mũthũkũmi waku, ũkyasya, Ngakwakĩa nyũmba: kwondũ wa ũu mũthũkũmi waku nĩwonete ngoonĩ yake kũvoya mboya ĩno.'),
('kam', '2SA', 7, 28, 'Na yu, ame Mwĩaĩi Yeova, nue Ngai, na ndeto syaku nĩ w’o, na nũmwathĩte mũthũkũmi waku ũndũ ũũ ũseo;'),
('kam', '2SA', 7, 29, 'yu kwondũ wa ũu endeew’a nĩ kũathima nyũmba ya mũthũkũmi waku, nĩ kana yĩkalae tene na tene ĩ mbee waku; nũndũ we, ame Mwiaĩĩ Yeova, nũneenete ũu: na nyũmba ya mũthũkũmi waku nĩathimwe na ũathimo waku tene na tene.'),
('kam', '2SA', 8, 1, 'Na kweethĩwa ĩtina wa ũu, Ndaviti akũna Avilisiti, na amakĩlya vinya: na Ndaviti oosa mũkwa o ndũa nyinyia kuma mokonĩ ma Avilisiti.'),
('kam', '2SA', 8, 2, 'Na akũna Moavi, na amathima na ũlii wa kũthima, amakomethetye nthĩ; na athima na ũlii mĩta ĩlĩ ya kũawa, na mwĩta ũmwe wa ũlii wa kũekwa wĩ thayũ. Na Amoavi matw’ĩke athũkũmi ma Ndaviti, na kumasya koti.'),
('kam', '2SA', 8, 3, 'O na Ndaviti amũkũna Atateseli mwana wa Leovu, mũsumbĩ wa Sova, aendete kũtũnga ũsumbĩko wake ĩngĩ ũla waĩ ũla Ũsĩnĩ.'),
('kam', '2SA', 8, 4, 'Na Ndaviti amũvena andũ ma ũtũlaa mbalasi ngili na maana mũonza, na andũ ala maendaa na maũũ ngili mĩongo ĩlĩ: na Ndaviti atilanga mbalasi syonthe sya makasya mĩlangũ, ate o atialilye sya makasya ĩana.'),
('kam', '2SA', 8, 5, 'Na yĩla Asilia ma Ndamasiku mookie kũmũtethya Atateseli mũsumbĩ wa Sova, Ndaviti akũna Asilia andũ ngili mĩongo ĩlĩ na ilĩ.'),
('kam', '2SA', 8, 6, 'Nĩvo ĩndĩ Ndaviti waiie ngome sya asikalĩ ku Silia ya Ndamasiku; na Asilia matw’ĩka athũkũmi ma Ndaviti, na kumasya koti. Na Yeova anenga Ndaviti kũkĩlya vinya o vala waendaa.'),
('kam', '2SA', 8, 7, 'Na Ndaviti oosa ngao sya thaavu ila syaĩ na athũkũmi ma Atateseli, na aiete Yelusaleme.'),
('kam', '2SA', 8, 8, 'Na mũsumbĩ Ndaviti oosa ũthuku mwingĩ mũno kuma Mbeta na Mbelothai, ndũa sya Atateseli.'),
('kam', '2SA', 8, 9, 'Na yĩla Toi mũsumbĩ wa Amathi wewie kana Ndaviti nũkũnĩte nguthu yonthe ya Atateseli,'),
('kam', '2SA', 8, 10, 'nĩvo ĩndĩ Toi watũmie Yolamu mwana wake kwa mũsumbĩ Ndaviti, akamũkethye, na kũmũathima, nĩkwĩthĩwa aĩ anokita na Atateseli na kũmũkũna: nũndũ Atateseli eethĩawa na makaũ na Toi. Na Yolamu atwaa mĩio ya vetha, na mĩio ya thaavu, na mĩio ya ũthuku:'),
('kam', '2SA', 8, 11, 'na ĩsu nayo mũsumbĩ Ndaviti amĩvathie yĩthĩwe mĩtheu kwa Yeova, vamwe na vetha na thaavu ila wavathie syĩthĩwe ntheu, ila sya mbaĩ syonthe ila waikĩlĩtye vinya;'),
('kam', '2SA', 8, 12, 'sya Silia, na sya Moavi, na sya ana ma Amimoni, na sya Avilisiti, na sya Amalekĩ, na sya mũtavo wa Atateseli, mwana wa Leovu, mũsumbĩ wa Sova.'),
('kam', '2SA', 8, 13, 'Na Ndaviti eeyonea syĩtwa yĩla wasyokie kuma kũmakũnĩa Asilia Kyandanĩ kya Mũnyũ, o andũ ngili ĩkũmi na nyanya.'),
('kam', '2SA', 8, 14, 'Na aia ngome sya asikalĩ ku Etomu; Etomu kw’onthe aia ngome syĩ asikalĩ, na Aetomu onthe matw’ĩka athũkũmi ma Ndaviti. Na Yeova amũnenga Ndaviti kũkĩlya vinya o kũla waendaa.'),
('kam', '2SA', 8, 15, 'Na Ndaviti asumbĩka Isilaeli onthe; na Ndaviti asilanasya andũ make onthe na sila wa katĩ na mũlũngalu.'),
('kam', '2SA', 8, 16, 'Na Yoavu mwana wa Nzeluia aĩ mũnene wa nguthu; na Yeosavati mwana wa Ailuti aĩ mũandĩki wa maũndũ;'),
('kam', '2SA', 8, 17, 'na Nzatoki mwana wa Aituvu, na Aimeleki mwana wa Aviathali, maĩ athembi; na Selaia aĩ mũandĩki;'),
('kam', '2SA', 8, 18, 'na Mbenaia mwana wa Yeoiata aĩ mũnene wa Akelethi na Avelethi; na ana ma Ndaviti maĩ anene ũsumbĩkinĩ.'),
('kam', '2SA', 9, 1, 'Na Ndaviti akũlya, Nĩvethĩwa ũmwe watialile nyũmbanĩ ya Saulo nĩmwĩke nesa kwondũ wa Yonathani?'),
('kam', '2SA', 9, 2, 'Na kwaĩ mũthũkũmi wa nyũmba ya Saulo ũla wetawa syĩtwa yake Nziva, na mamwĩta aende kwa Ndaviti; na mũsumbĩ amũkũlya, Nue Nziva? Na asũngĩa, Mũthũkũmi waku nĩwe.'),
('kam', '2SA', 9, 3, 'Na mũsumbĩ akũlya, Vatyĩthĩwa ũmwe wa nyũmba ya Saulo, nĩ kana nĩmwĩke ũseo wa Ngaĩ? Na Nziva amwĩa mũsumbĩ, Yonathani e na mwana, waie maũũ.'),
('kam', '2SA', 9, 4, 'Na mũsumbĩ amũkũlya, Aĩva? Na Nziva amwĩa mũsumbĩ, Sisya, e nyũmbanĩ ya Makili mwana wa Amieli ku Lo‐ndevali.'),
('kam', '2SA', 9, 5, 'Nĩvo ĩndĩ mũsumbĩ Ndaviti watũmanie alatw’e kumw’a nyũmbanĩ ya Makili mwana wa Amieli, ku Lo‐ndevali.'),
('kam', '2SA', 9, 6, 'Na Mevivosethi mwana wa Yonathani, mwana wa Saulo, ooka kwa Ndaviti, na avalũka na ũthyũ wake, na eekunamya vyũ. Na Ndaviti asya, Mevivosethi. Na asũngĩa, Sisya, mũthũkũmi waku!'),
('kam', '2SA', 9, 7, 'Na Ndaviti amwĩa, Ndũkakĩe; nũndũ ndi ndĩi ya kũlea ũkwĩka nesa kwondũ wa ĩthe waku Yonathani, na ngakũtũngĩa nthĩ yonthe ya ĩthe waku Saulo; na ũkaĩsaa lĩu mesanĩ yakwa mavinda onthe.'),
('kam', '2SA', 9, 8, 'Na eekunamya vyũ, na asya, Mũthũkũmi waku nĩ mwaũ, ũndũ ũũsisya ngitĩ ngw’ũ takwa?'),
('kam', '2SA', 9, 9, 'Nĩvo ĩndĩ mũsumbĩ wamwĩtie Nziva, mũthũkũmi wa Saulo, na amwĩa, Kyonthe kya Saulo na kya nyũmba yake yonthe nĩnĩnengete mwana wa vwana waku.'),
('kam', '2SA', 9, 10, 'Na ũkamũĩmĩaa mĩũnda, we, na ana maku, na athũkũmi maku; na ũkaetae mosyao, nĩ kana mwana wa vwana waku ethĩawe na lĩu wa ũya: ĩndĩ Mevivosethi mwana wa vwana waku akaĩsaa lĩu ĩndĩ yonthe mesanĩ yakwa. Na ĩndĩ Nzĩva aĩ na ana ĩkũmi na atano na athũkũmi mĩongo ĩlĩ.'),
('kam', '2SA', 9, 11, 'Nĩvo ĩndĩ Nziva wamwĩie mũsumbĩ, O kwĩanana na w’onthe ũla mwĩaĩi wakwa mũsumbĩ ũnũũmwĩaĩa mũthũkũmi wake, now’o mũthũkũmi wakũ ũkekaa. Ĩndĩ ũndũ wa Mevivosethi, mũsumbi asya, akaĩsaa mesanĩ yakwa ta ũmwe wa ana ma mũsumbĩ.'),
('kam', '2SA', 9, 12, 'Na Mevivosethi aĩ na kamwana kala keetawa syĩtwa yako Mika. Na onthe ala mekalaa nyũmbanĩ ya Nziva maĩ athũkũmi ma Mevivosethi.'),
('kam', '2SA', 9, 13, 'Na ĩndĩ Mevivosethi atũa Yelusaleme; nũndũ aĩsaa mavinda onthe mesanĩ ya mũsumbĩ. Na nĩwaĩte maũũ make elĩ.'),
('kam', '2SA', 10, 1, 'Na kweethĩwa ĩtina wa ũu, mũsumbĩ wa ana ma Amimoni akw’a, na Anuni mwana wake asumbĩka vandũ vake.'),
('kam', '2SA', 10, 2, 'Na Ndaviti asya, Ngamwĩka Anuni mwana wa Naasu nesa, o tondũ ĩthe wake wambĩkie nesa. Kwondũ wa ũu Ndaviti atũma athũkũmi make makamũkiakisye ũndũ wa ĩthe wake. Na athũkũmi ma Ndaviti mavika nthĩ ya ana ma Amimoni.'),
('kam', '2SA', 10, 3, 'Ĩndĩ anene me mbee ũsumbĩnĩ ma Amimoni mamũkũlya Anuni mwĩaĩi woo, Nũũsũanĩa kana Ndaviti nũnũũtaĩa au, nũndũ nũkũtũmĩe akũkiakĩsya? Ndaviti ndatũmĩte athũkũmi make kwaku mekuũe ndũa, na kũmĩthĩana, na kũmĩng’uthũlanga?'),
('kam', '2SA', 10, 4, 'Na ĩndĩ Anunĩ akwata athũkũmi ma Ndaviti, na amenza nyunzu ya ĩng’ew’a, na aatũanĩlya ngũa syoo katĩ o kũvika itimbanĩ syoo, na amaeka mathi.'),
('kam', '2SA', 10, 5, 'Yĩla andũ mamũtavisye Ndaviti ũndũ ũsu, atũmana mathaũwe; nũndũ andũ asu nĩmasonokaa mũno. Na mũsumbĩ amea, Ĩkalai Yeliko kũvika ing’ew’a syenyu syamea, na ĩndĩ mũkĩsyoka.'),
('kam', '2SA', 10, 6, 'Na yĩla ana ma Amimoni moonie kana nĩmenyungĩthĩtye naĩ kwa Ndaviti, ana ma Amimoni matũma andũ makamatuve Asilia ma Mbethi‐leovu, na Asilia ma Sova, andũ ngili mĩongo ĩlĩ ala maendaa na maũũ, na mũsumbĩ wa Maaka e na andũ ngili, na andũ ma Tovu ngili ĩkũmi na ilĩ.'),
('kam', '2SA', 10, 7, 'Na yĩla Ndaviti wewie ũu, atũma Yoavu, na nguthu yonthe ya ngũmbaũ.'),
('kam', '2SA', 10, 8, 'Na ana ma Amimoni maumaala, na mataũsya ita mokitĩe ũlikĩlonĩ mbingĩlonĩ: na Asilia ma Sova na ma Leovu, na andũ ma Tovu na Maaka, maĩ kĩsesinĩ me oka.'),
('kam', '2SA', 10, 9, 'Na yĩla Yoavu wonie kana nĩmetaũĩtye mokite nake mbee na ĩtina, anyuva amwe ma andũ onthe anyuve ma Isilaeli, na amataũsya mokite na Asilia:'),
('kam', '2SA', 10, 10, 'na andũ ala angĩ amaia kw’okonĩ kwa Avisai mwana‐a‐inyia: na amataũsya mokite na ana ma Amimoni.'),
('kam', '2SA', 10, 11, 'Na asya, Ethĩwa Asilia me vinya kwĩ nyie, nĩvo wĩndethya; ĩndĩ ethĩwa ana ma Amimoni me vinya kwĩ we, nĩvo nĩũka na ngĩũtethya.'),
('kam', '2SA', 10, 12, 'Ĩthĩwa na ũkũmbaũ mũnene, na twĩthĩwe aũme kwondũ wa andũ maitũ, na kwondũ wa ndũa sya Ngai waitũ: na Yeova nĩeke ũndũ ũnũkwona wĩ ũseo.'),
('kam', '2SA', 10, 13, 'Na ĩndĩ Yoavu na andũ ala maĩ nake mathengeea mokite na Asilia kaũnĩ: nao makũka mamũkĩa.'),
('kam', '2SA', 10, 14, 'Na yĩla ana ma Amimoni moonie kana Asilia nĩmakĩa, nao o ta ũu makĩa Avisai, na malĩka ndũanĩ. Na ĩndĩ Yoavu asyoka kuma vala ve ana ma Amimoni, na ooka Yelusaleme.'),
('kam', '2SA', 10, 15, 'Na yĩla Asilia moonie kana nĩmakũiwe nĩ Isilaeli, moombana vamwe.'),
('kam', '2SA', 10, 16, 'Na Ataleseli atũmana, kũetwe Asilia ala maĩ mũingo wa ũla Ũsĩ: na mooka Eelamu, me na Sovaki kavuteni wa nguthu ya Ataleseli amatongoesye.'),
('kam', '2SA', 10, 17, 'Na Ndaviti atavw’a; na oomban’ya Isilaeli onthe vamwe, na mainga Yolotani, na mavika Eelamu. Na Asilia meetaũsya mokite na Ndaviti, na mokita nake.'),
('kam', '2SA', 10, 18, 'Na Asilia makũka makĩa Isilaeli; na Ndaviti ooaa Asilia andũ ma makasya ngili mũonza, na andũ ala matũlaa mbalasi ngili mĩongo ĩna, na amũkũna Sovaki kavuteni wa nguthu yoo, na akw’ĩa kw’o.'),
('kam', '2SA', 10, 19, 'Na yĩla asumbĩ onthe ala maĩ athũkũmi ma Ataleseli moonie kana nĩmakũwa nĩ Isilaeli, maseũvya mũuo na Isilaeli, na mamathũkũma. Na ĩndĩ Asilia makĩa kũtethya ana ma Amimoni ĩngĩ.'),
('kam', '2SA', 11, 1, 'Na kweethĩwa mwaka ũkyambĩlĩlya, ĩvinda yĩla asumbĩ maendaa kaũnĩ, Ndaviti atũma Yoavu, e na athũkũmi make, na Isilaeli onthe; na maananga ana ma Amimoni, na mathyũlũlũka Lava mamĩtw’ĩkanĩsye. Ĩndĩ Ndaviti ekala Yelusaleme.'),
('kam', '2SA', 11, 2, 'Na kweethĩwa ĩ ya wĩoo, Ndaviti ookĩla kuma ũkomonĩ wake, na atambũka ĩũlũ wa kĩala kya nyũmba ya mũsumbĩ: na e kĩalanĩ oona mũndũ mũka akĩthamba; na mũndũ mũka ũsu aĩ mwanake kwa kũsiw’a.'),
('kam', '2SA', 11, 3, 'Na Ndaviti atũmana akũlye ũndũ wa ũ mũndũ mũka. Na ũmwe asya, Ũũ ti Mbethi‐sieva, mwĩĩtu wa Eliamu, mũka wa Ulia Mũititi?'),
('kam', '2SA', 11, 4, 'Na Ndaviti atũma atũmwa, mamũlatye; nake ooka kwake, na akoma nake (nũndũ nĩwatheetw’e ũvuku wake); na asyoka nyũmbanĩ yake.'),
('kam', '2SA', 11, 5, 'Na mũndũ mũka aitava; na atũmana na amũtavya Ndaviti, na asya, Nĩ ĩvu.'),
('kam', '2SA', 11, 6, 'Na Ndaviti atũmana kwa Yoavu, akĩmwĩa, Ndũmĩa Ulia Mũititi. Na Yoavu atũma Ulia kwa Ndaviti.'),
('kam', '2SA', 11, 7, 'Na yĩla Ulia wavikie, Ndaviti amũkũlya ũndũ Yoavu ũilyĩ, na ũndũ andũ mailyĩ, na ũndũ kaũ ũendeee.'),
('kam', '2SA', 11, 8, 'Na Ndaviti eea Ulia, Theea nyũmbanĩ yaku, noithambya maũũ maku. Na Ulia aumaala kuma nyũmbanĩ ya mũsumbĩ, na aatĩĩwa lĩu kuma kwa mũsumbĩ.'),
('kam', '2SA', 11, 9, 'Ĩndĩ Ulia akoma ũtee wa mũomo wa nyũmba ya mũsumbĩ vamwe na athũkũmi onthe ma mwĩaĩi wake, na ndaatheea nyũmbanĩ yake.'),
('kam', '2SA', 11, 10, 'Na yĩla mamũtavisye Ndaviti, makĩmwĩa, Ulia ndaneetheea nyũmbanĩ yake, Ndaviti amũkũlya Ulia, Ndumĩte kyalonĩ? Nũndũ wa kĩ ũtaneetheea nyũmbanĩ yaku?'),
('kam', '2SA', 11, 11, 'Na Ulia amwĩa Ndaviti, Yĩla ĩsandũkũ, na Isilaeli, na Yuta, mekalaa malwandanĩ; na mwĩaĩĩ wakwa Yoavu, na athũkũmi ma mwĩaĩi wakwa, me mwakonĩ wa maeema weũnĩ; nakwa ngalika nyũmbanĩ yakwa, nĩye na kũnyw’a, na kũkoma na kĩveti kyakwa? O tondũ wĩ thayũ, no tondũ kyuu kyaku kĩ thayũ, ndikeka undũ ũsu.'),
('kam', '2SA', 11, 12, 'Na Ndaviti amwĩa Ulia, Ĩkalanga vaa ũmũnthĩ naw’o, na ũnĩ ngakũeka ũthi. Na indĩ Ulia ekala Yelusaleme mũthenya ũsu, na ũni ũsu.'),
('kam', '2SA', 11, 13, 'Na yĩla Ndaviti wamwĩtie, aya na anyw’a e mbee wake; atuma amilwa: na wĩoo aumaala kũkoma ũkomonĩ wake vamwe na athũkũmi ma mwĩaĩi wake, ĩndĩ ndaatheea nyũmbanĩ yake.'),
('kam', '2SA', 11, 14, 'Na kweethĩwa kĩoko, Ndaviti amũandĩkĩa Yoavu valũa, na ootwaa na kw’oko kwa Ulia.'),
('kam', '2SA', 11, 15, 'Na aandĩka valũanĩ, akyasya, Iai Ulia mbee vala ve kaũ mũvyũ, na mũimũkĩĩa, nĩ kana akũnwe, akw’e.'),
('kam', '2SA', 11, 16, 'Na kweethĩwa, yĩla Yoavu wasyaĩĩsye ndũa, aia Ulia vandũ vala wĩsĩ ve andũ ngũmbaũ.'),
('kam', '2SA', 11, 17, 'Na andũ ma ndũa maumaala, na mokita na Yoavu: na amwe ma andũ mavalũka, o ma athũkũmi ma Ndaviti; o na Ulĩa ũla Mũititi akw’a.'),
('kam', '2SA', 11, 18, 'Nĩvo ĩndĩ Yoavu watũmanie na amũtavya Ndaviti maũndũ onthe ma kaũ;'),
('kam', '2SA', 11, 19, 'na eeaĩa mũtũmwa, akĩmwĩa, Wamina kũtavya mũsumbĩ maũndũ onthe ma kaũ,'),
('kam', '2SA', 11, 20, 'kũkeethĩwa ethĩwa ũthatu wa mũsumbĩ ũkookĩla, nake akwĩa, Nũndũ wa kĩ mũthengeeie ndũa ta ũu mũkite? Mũtyaamanya kana makekya me ũvainĩ?'),
('kam', '2SA', 11, 21, 'Nũũ wakũnie Avimeleki mwana wa Yeluvesethi? Mũndũ mũka ndaamũlekelya nthio ya ĩvia e ũvainĩ, na akw’ĩa Thevesi? Nĩkĩ mũthengeeie ũvai ta ũu? Nĩvo ĩndĩ wĩasya, Mũthũkũmi waku Ulia Mũititi nake no mũkw’ũ.'),
('kam', '2SA', 11, 22, 'Na ĩndĩ mũtũmwa athi, na avika na amwon’ya Ndaviti w’onthe ũla Yoavu wamũtũmĩe.'),
('kam', '2SA', 11, 23, 'Na mũtũmwa amwĩa Ndaviti, Andũ nĩmatũkĩlilye vinya, na matũtindĩka kũvika weũnĩ, naitũ twamatũngĩthya o kũvika ũlikĩlonĩ mbingĩlonĩ.'),
('kam', '2SA', 11, 24, 'Na aathi me ũvainĩ maatha athũkũmi maku; na amwe ma athũkũmi ma mũsumbĩ nĩ akw’ũ, na mũthũkũmi waku Ulia ũla Mũititi nake no mũkw’ũ.'),
('kam', '2SA', 11, 25, 'Na ĩndĩ Ndaviti amwĩa mũtũmwa, Ũũ nĩw’o wĩmwĩa Yoavu, Ũndũ ũũ ndũkakwĩw’ĩthye woo, nũndũ ũvyũ nũminaa ũmwe o ta ũla ũngĩ; ongeleela kaũ waku vinya mbee ĩ ndũanĩ, noimĩng’uthũla: naku mwĩkĩe vinya.'),
('kam', '2SA', 11, 26, 'Na yĩla kĩveti kya Ulia kyeewie Ulia mũũme wakyo nũkwie, kyamũĩĩa mũũme.'),
('kam', '2SA', 11, 27, 'Na yĩla kũmeta kwathelile, Ndaviti atũmana na kyaetwe nyũmbanĩ yake, na kyatw’ĩka kĩveti kyake, na kyamũsyaĩa mwana. Ĩndĩ ũndũ ũsu ũla Ndaviti wekie nĩwamwĩw’ĩthisye Yeova woo.'),
('kam', '2SA', 12, 1, 'Na Yeova atũma Nathani kwa Ndaviti. Na avika vala ũĩ, na amwĩa, Kwai andũ elĩ ndũanĩ ĩmwe; ũmwe mũthwĩĩ, na ũla ũngĩ ngya.'),
('kam', '2SA', 12, 2, 'Ũ mũthwii aĩ na ndĩthya nyingĩ mũno sya mbũi na malondu na sya ng’ombe;'),
('kam', '2SA', 12, 3, 'ĩndĩ ĩ ngya ndĩaĩ na kĩndũ, ate o kamwatĩ kamwe, kala wathooie na kũkaĩthasya: nako keanĩa kwake, na vamwe na syana syake; nĩkaĩsaa kalĩu kake mwene, na kanyusaa kĩkombe kyake mwene, na kakomaa kĩthũinĩ kyake, na kailyĩ kwake ta mwĩĩtu.'),
('kam', '2SA', 12, 4, 'Na kwathokie mũendi wa kyalo kwa ũ mũthwii, nake alea kwosa ndĩthyanĩ yake mwene ya mbũi na malondu na ndĩthyanĩ yake ya ng’ombe, akulĩle ũ mũendi wa kyalo ũla wamũthokee, ĩndĩ oosa katena ka ĩlondu ka mũndũ ũsu ngya, na akaseũvĩsya mũndũ ũsu ũla wamũthokeie.'),
('kam', '2SA', 12, 5, 'Na ũthatu wa Ndaviti wakanĩa mũndũ ũsu mũno; na amwĩa Nathani, O tondũ Yeova wĩ thayũ, mũndũ ũla wekie ũu nĩwaĩle kũkw’a:'),
('kam', '2SA', 12, 6, 'na akatũnga vandũ va kala katena kũndũ kũna, nũndũ nĩwekie ũndũ ũsu, na nũndũ ndaĩ na tei.'),
('kam', '2SA', 12, 7, 'Na Nathani amwĩa Ndaviti, Nue mũndũ ũsu. Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Nĩnakwĩtĩkĩsye mauta wĩthĩwe mũsumbĩ wa Isilaeli, na nĩnakũvonokisye kuma kw’okonĩ kwa Saulo;'),
('kam', '2SA', 12, 8, 'na nĩnakũnengie nyũmba ya vwana waku, na iveti sya vwana waku kĩthũinĩ kyaku, na nakũnenga nyũmba ya Isilaeli na ya Yuta; na kethĩwa ũu waĩ ũnini, nĩthĩwa nakwongeleele kĩna na kĩna.'),
('kam', '2SA', 12, 9, 'Nũndũ wa kĩ ũvũthĩtye ndeto ya Yeova, wĩke ũthũku ene? Nũkũnĩthĩtye Ulia ũla Mũititi na ũvyũ, na nĩwosete kĩveti kyake kĩthĩwe kĩveti kyaku, na nũmũaĩte na ũvyũ wa ana ma Amimoni.'),
('kam', '2SA', 12, 10, 'Kwondũ wa ũu ĩndĩ ũvyũ ndũkauma nyũmbanĩ yaku o na ĩndĩĩ, nũndũ nũmbũthĩtye, na nũtwaĩte kĩveti kya Ulia ũla Mũititi kĩthĩwe kĩveti kyaku.'),
('kam', '2SA', 12, 11, 'Ũũ nĩw’o Yeova ũnũkwasya, Sisya, ngakũkĩlĩlya ũthũku ũla wĩuma nyũmbanĩ yaku mwene; na ngoosa iveti syaku wene na metho maku, na kwinenga mũtũi waku, na akakoma na iveti syaku syũa yĩĩ yene.'),
('kam', '2SA', 12, 12, 'Nũndũ nĩweekie ũu kĩmbĩthĩ: ĩndĩ nyie ngeeka ũndũ ũũ Isilaeli onthe mene, o na syũa.'),
('kam', '2SA', 12, 13, 'Na Ndaviti amwĩa Nathani, Nĩnĩmũvĩtanĩsye Yeova. Na Nathani amwĩa Ndaviti, O na Yeova nũvetete naĩ yaku; ndũkakw’a.'),
('kam', '2SA', 12, 14, 'Ĩndĩ, nĩkwĩthĩwa nũnengete amaitha ma Yeova mwanya mũnene wa kũmũuma kwondũ wa wĩko ũsu, o na kana kala wasyaĩwa kaitĩa kũkw’a.'),
('kam', '2SA', 12, 15, 'Na Nathani aenda nyũmbanĩ kwake. Na Yeova akũna kana kala kĩveti kya Ulia kyamũsyaĩe Ndaviti, na kawaa mũno.'),
('kam', '2SA', 12, 16, 'Kwondũ wa ũu Ndaviti avoya Ngai kwondũ wa kana; na Ndaviti atĩĩa ũya na avota nthĩnĩ, na akoma nthĩ ũtukũ mũima.'),
('kam', '2SA', 12, 17, 'Na atumĩa ma nyũmba yake mookĩla, na maũngama vakuvĩ nake, mamũkĩlye nthĩ; ĩndĩ alea, o na ndaaya lĩu nao.'),
('kam', '2SA', 12, 18, 'Na kweethĩwa mũthenya wa mũonza, kala kana kakw’a. Na athũkũmi ma Ndaviti makĩa kũmũtavya atĩ kana nĩkakwie; nũndũ masya, Sisya, yĩla kana keĩ thayũ, tũneenie nake, na ndanethũkĩĩsya wasya witũ: ai! Akeeyĩw’ĩthya woo wĩana ata, ethĩwa twĩnmũtavya atĩ kana nĩkakwie!'),
('kam', '2SA', 12, 19, 'Ĩndĩ yĩla Ndaviti wonie athũkũmi make makĩneenan’ya na kĩwe, Ndaviti amanya atĩ kana nĩkakwie; na Ndaviti amakũlya athũkũmi make, Kana nĩkakwie? Na masya, Nĩkakwie.'),
('kam', '2SA', 12, 20, 'Nĩvo ĩndĩ Ndaviti wokĩlile nthĩ, na athamba, na eevaka mauta, na akũan’ya ngũa syake; na alika nyũmbanĩ ya Yeova, na athaitha: na ĩndĩ asyoka nyũmbanĩ yake mwene; na yĩla wetisye, maia lĩu mbee wake, nake aya.'),
('kam', '2SA', 12, 21, 'Nĩvo ĩndĩ athũkũmi make mamũkũlilye, Ũndũ ũũ nĩ mwaũ ũla wĩkĩte? Nĩwatĩĩie ũya na waĩa kwondũ wa kana, ke thayũ; ĩndĩ kana kakw’a, wookĩla na waya lĩu.'),
('kam', '2SA', 12, 22, 'Na asya, Yĩla kana keĩ thayũ, natĩĩa ũya na kũĩa: nũndũ nĩnaisye, Nũũ wĩsĩ ethĩwa Yeova ndembĩka nesa, kana kekalae thayũ?'),
('kam', '2SA', 12, 23, 'Ĩndĩ yu nĩkakwie, nĩtĩĩa ũya nĩkĩ? Nĩndonya kũkatũnga ĩngĩ? Ngathi vala kaĩ, ĩndĩ katikanzyokea.'),
('kam', '2SA', 12, 24, 'Na Ndaviti akiakisya Mbathi‐sieva mũka wake, na alika vala ũĩ, na akoma nake: na asyaa mwana, na amwĩta syĩtwa yake Solomoni. Na Yeova amwenda;'),
('kam', '2SA', 12, 25, 'na atũmana na kw’oko kwa mwathani Nathani; nake amwĩta syĩtwa yake Yetitia, kwondũ wa Yeova.'),
('kam', '2SA', 12, 26, 'Na ĩndĩ Yoavu nĩwokitaa na Lava, ndũa ĩmwe ya ana ma Amimoni, na oosa ndũa ya kĩũsumbĩ.'),
('kam', '2SA', 12, 27, 'Na Yoavu atũma atũmwa kwa Ndaviti, na asya, Nĩnũkitĩte na Lava; ĩĩ, nĩnosete ndũa yĩ manzĩ.'),
('kam', '2SA', 12, 28, 'Yu kwondũ wa ũu ũmban’ya andũ ala matiele, na amba maeema ũtaũĩĩe ndũa, noimĩkwata; ndikese kwosa ĩ ndũa, na ĩkĩtanĩaw’a na syĩtwa yakwa.'),
('kam', '2SA', 12, 29, 'Na Ndaviti oomban’ya andũ onthe, na athi Lava, na okita nayo, na amĩkwata.'),
('kam', '2SA', 12, 30, 'Na aumya ngovia ya ũsumbĩ ya mũsumbĩ woo mũtwe kwake; na ũito wayo waĩ talendi wa thaavu, na yaĩ na tũvila twĩ thooa mũnene; na yeekĩwa mũtwe kwa Ndaviti. Na aumaalya mũtavo wa ĩ ndũa, mwingĩ mũno.'),
('kam', '2SA', 12, 31, 'Na aumaalya andũ ala maĩ nthĩnĩ wayo, na amatilanga na mang’weli, na syĩndũ mbũĩ sya iaa sya kũvukũlya mavali, na mathoka ma iaa, na amavĩtĩlya kĩvĩvĩsyonĩ kya mavali: na ndũa syonthe sya Amimoni asyĩka ũu. Na Ndaviti na andũ onthe masyoka Yelusaleme.'),
('kam', '2SA', 13, 1, 'Na kweethĩwa ĩtina wa ũu, Avisalomu mwana wa Ndaviti aĩ na mwĩĩtu‐a‐inyia mwanake, ũla wetawa syĩtwa yake Tamali; na Aminoni mwana wa Ndaviti amwenda.'),
('kam', '2SA', 13, 2, 'Na Aminoni eethĩn’ya kũvika awaa nũndũ wa mwĩĩtua‐ĩthe Tamali; nĩkwĩthĩwa aĩ mwĩĩtu mũtheu; na Aminoni oona kwĩthĩwa ta vinya kũmwĩka ũndũ.'),
('kam', '2SA', 13, 3, 'Ĩndĩ Aminoni aĩ na mũnyanyae ũla wetawa syĩtwa yake Yonatavu, mwana wa Simea, mwana‐a‐inyia wa Ndaviti: na Yonatavu aĩ mũndũ nzeleke mũno.'),
('kam', '2SA', 13, 4, 'Na amũkũlya, Nũndũ wa kĩ, we mwana wa mũsumbĩ, ũũmosa ta ũu o kĩla mũthenya? Ndũndavya? Na Aminoni amwĩa, Nĩmwendaa Tamali, mwĩĩtu‐a‐inyia wa mwana‐a‐asa Avisalomu.'),
('kam', '2SA', 13, 5, 'Na Yonatavu amwĩa, Koma ũkomonĩ waku wĩwaĩthye: na yĩla au wĩũka ũkũsisya, mwĩe, Nĩngũkwĩsũva, mwĩĩtu‐a‐asa Tamali nioke, anenge lĩu wa ũya, na akĩseũvya lĩu nene, nĩ kana nĩwone, na kũya kuma kw’okonĩ kwake.'),
('kam', '2SA', 13, 6, 'Na ĩndĩ Aminoni akoma, na eewaĩthya: na yĩla mũsumbĩ wokie kũmũsisya, Aminoni amwĩa mũsumbĩ, Nĩngũkwĩsũva, mwĩĩtu‐a‐asa Tamali nĩoke na kũnzeũvisya tũmũtũ twĩlĩ nene, nĩye kuma kw’okonĩ kwake.'),
('kam', '2SA', 13, 7, 'Na ĩndĩ Ndaviti atũmana nyũmba vala ve Tamali, akĩmwĩa, Enda yu nyũmbanĩ ya mwana‐a‐au Aminoni, noimũseũvĩsya lĩu.'),
('kam', '2SA', 13, 8, 'Na ĩndĩ Tamali aenda nyũmbanĩ ya mwana‐a‐ĩthe Aminoni; na aĩ anakoma. Na oosa ngũmbwa, na amyũmba, na aseũvya tũmũtũ ene, na atũua.'),
('kam', '2SA', 13, 9, 'Na oosa kĩkaangi, na atũtulũla ene; ĩndĩ alea kũya. Na Aminoni asya, Andũ onthe nĩmaume vaa nĩĩ. Na kĩla mũndũ auma vala ũĩ.'),
('kam', '2SA', 13, 10, 'Na Aminoni amwĩa Tamali, Ete lĩu kasũmbanĩ nĩye kuma kw’okonĩ kwaku. Na Tamali oosa tũmũtũ tũla waseũvĩtye, na amũtwaĩa Aminoni mwana‐a‐ĩthe vu kasũmbanĩ.'),
('kam', '2SA', 13, 11, 'Na yĩla watũthengeeisye vala ũĩ aye, amũkwata na amwĩa, Ũka, ũkome nakwa, mwĩĩtu‐a‐asa.'),
('kam', '2SA', 13, 12, 'Na amũsũngĩa, Aiee, mwana‐a‐asa, ndũkanginde; nũndũ ũndũ ta ũsu ndwaĩle kwĩkwa nthĩnĩ wa Isilaeli; ndũkeke ũtumanũ ũũ.'),
('kam', '2SA', 13, 13, 'Nakwa, ngaenda na nthoni syakwa nakũ? Naku ngalĩ ĩ yaku, ũkeethĩwa ta ũmwe wa ndia sya Isilaeli. Kwondũ wa ũu nĩngũkwĩsũva, neena na mũsumbĩ; nũndũ ndakakũvata ũindwaa.'),
('kam', '2SA', 13, 14, 'Ĩndĩ ndaaĩtĩkĩla kwĩthukĩĩsya wasya wake; ĩndĩ nũndũ aĩ vinya kwĩ we, amũkĩlya vinya na amũkinda.'),
('kam', '2SA', 13, 15, 'Nĩvo ĩndĩ Aminoni wamũmenie na kĩmena kĩnene mũno; nũndũ kĩmena kĩla wamũmenie kyaĩ kĩnene kwĩ wendo ũla wamwendaa naw’o. Na Aminoni amwĩa, Ũkĩla, thi.'),
('kam', '2SA', 13, 16, 'Nake amwĩa, Ti w’o, nũndũ ĩvĩtyo yĩĩ ĩnene ya kũngũa nĩ ĩthũku kwĩ yĩla yĩngĩ wambĩka. Ĩndĩ ndaaĩtĩkĩla kũmwĩthukĩĩsya.'),
('kam', '2SA', 13, 17, 'Na ĩndĩ eeta mũthũkũmi wake ũla wamũthũkũmaa, na amwĩa, Umaalya mũndũ mũka ũũ aume vaa nĩĩ, noivinga mũomo ki aumaala.'),
('kam', '2SA', 13, 18, 'Nake eekĩte ngũa yĩ langi wa mĩthemba mingĩ; nũndũ eĩtu atheu ma mũsumbĩ meekĩaa ngũa ta isu. Na ĩndĩ mũthũkũmi wake amumaalya, na avinga mũomo ki amumaalya.'),
('kam', '2SA', 13, 19, 'Na Tamali eekĩa mũu mũtwe wake, na atembũanga ngũa yake yĩ langi wa mĩthemba mingĩ, ĩla wekĩĩte; na ailĩĩla kw’oko kwake mũtwe kwake, na eeendea, akĩĩa na wasya aendete.'),
('kam', '2SA', 13, 20, 'Na Avisalomu mwana‐a‐inyia amũkũlya, Aminoni mwana‐a‐asa waku eĩ naku? Yu ĩndĩ vindya mwĩĩtu‐a‐ia: we nĩ mwana‐a‐au; ndũkaie ũndũ ũũ ngoonĩ. Kwondũ wa ũu Tamali ekala nyũmbanĩ ya mwana‐a‐inyia Avisalomu e na ĩvou.'),
('kam', '2SA', 13, 21, 'Ĩndĩ yĩla mũsumbĩ Ndaviti wewie maũndũ asu onthe, athilĩka mũno.'),
('kam', '2SA', 13, 22, 'Na Avisalomu ndaaneena na Aminoni ũseo kana ũthũku; nũndũ Avisalomu nĩwamenie Aminoni, nĩkwĩthĩwa nĩwakindie mwĩĩtu‐a‐inyia Tamali.'),
('kam', '2SA', 13, 23, 'Na kweethĩwa ĩtina wa myaka ĩlĩ mĩima, Avisalomu aĩ na atili ma w’ĩa wa malondu ku Mbaali‐asoli, ĩla yĩ ũtee wa Evalaimu: na Avisalomu eeta ana onthe ma mũsumbĩ.'),
('kam', '2SA', 13, 24, 'Na Avisalomu amũendea mũsumbĩ na amwĩa, Sisya yu, mũthũkũmi waku e na atili ma w’ĩa wa malondu; nĩngũkwĩsũva, mũsumbĩ na athũkũmi make maendan’ye na mũthũkũmi waku.'),
('kam', '2SA', 13, 25, 'Na mũsumbĩ amwĩa Avisalomu, Aiee, mwana wakwa, tũtikoke ithyonthe, tũtikese ũkũtw’ĩkĩa mũio. Na amũthing’ĩĩsya: ĩndĩ nĩwaleile kũthi, ĩndĩ amũathima.'),
('kam', '2SA', 13, 26, 'Na ĩndĩ Avisalomu amwĩa, Ethĩwa tĩ ũu, nĩngũkwĩsũva, mwana‐a‐asa Aminoni aendan’ye naitũ. Na mũsumbĩ akũlya, Aendan’ye naku nĩkĩ?'),
('kam', '2SA', 13, 27, 'Ĩndĩ Avisalomu amũthing’ĩĩsya na aeka Aminoni na ana onthe ma mũsumbĩ maendan’ye nake.'),
('kam', '2SA', 13, 28, 'Na Avisalomu eeaĩa athũkũmi make, akĩmea, Sisyai yu, yĩla ngoo ya Aminoni ĩnĩũtanw’a nĩ mbinyu; na yĩla nĩĩmwĩa, Kũnai Aminoni, mũaei ĩndĩ; mũtikakĩe; ndimwĩaĩe nyie? Ĩthĩwai na ũnyiau, na ũkũmbaũ.'),
('kam', '2SA', 13, 29, 'Na athũkũmi ma Avisalomu mamwĩka Aminoni o tondũ Avisalomu weaie. Nĩvo ĩndĩ ana onthe ma mũsumbĩ mookĩlile, na kĩla mũndũ atũla nyũmbũ yake, na akĩa.'),
('kam', '2SA', 13, 30, 'Na kweethĩwa, yĩla maĩ nzĩanĩ, ũvoo wamũvikĩa Ndaviti, kũkyaw’a, Avisalomu nĩwũaĩte ana onthe ma mũsumbĩ, na vati ũmwe ũtiele.'),
('kam', '2SA', 13, 31, 'Nivo ĩndĩ mũsumbĩ wokĩlile, na atembũanga ngũa syake, na akoma nthĩ; na athũkũmi make onthe maũngama vakuvĩ matembũangĩte ngũa syoo.'),
('kam', '2SA', 13, 32, 'Na Yonatavu, mwana wa Simea, mwana‐a‐inyia wa Ndaviti, asũngĩa na amwĩa, Mwĩaĩĩ wakwa ndakasũanĩe kana nĩmoaĩte anake onthe ana ma mũsumbĩ; nũndũ no Aminoni wũaiwe: nĩkwĩthĩwa ũndũ wa ũtw’ĩo wa Avisalomu ũndũ ũũ nĩwatwiwe kuma mũthenya ũla wakindie mwĩĩtu‐a‐inyia wake Tamali.'),
('kam', '2SA', 13, 33, 'Yu kwondũ wa ũu mwĩaĩi wakwa mũsumbĩ ndakaie ũndũ ũsu ngoonĩ yake, asũanĩe ana onthe ma mũsumbĩ nĩ akw’ũ; nũndũ no Aminoni e weka mũkw’ũ.'),
('kam', '2SA', 13, 34, 'Ĩndĩ Avisalomu akĩa. Na mwanake ũla wasyaĩĩasya aũngalalya metho make, na aketeea, na, sisya, andũ aingĩ nĩmokĩte na nzĩa yĩ mũongonĩ wake yĩ nguumo ya kĩĩma.'),
('kam', '2SA', 13, 35, 'Na Yonatavu amwĩa mũsumbĩ, Sisya, ana ma mũsumbĩ nĩmokĩte: o tondũ mũthũkũmi waku waisye, now’o kũilyĩ.'),
('kam', '2SA', 13, 36, 'Na kweethĩwa, amina kũneena, sisya, ana ma mũsumbĩ mooka, na mookĩlya mawasya moo na maĩa: na mũsumbĩ nake na athũkũmi make onthe maĩa mũno.'),
('kam', '2SA', 13, 37, 'Ĩndĩ Avisalomu akĩa, na athi kwa Talimai mwana wa Amiuli mũsumbĩ wa Ngesuli. Na Ndaviti ametea mwana wake kĩla mũthenya.'),
('kam', '2SA', 13, 38, 'Na ĩndĩ Avisalomu akĩa na athi Ngesuli, na ekala kw’o myaka ĩtatũ.'),
('kam', '2SA', 13, 39, 'Na ngoo ya mũsumbĩ Ndaviti yaĩ na mea ma kũthi vala ve Avisalomu: nũndũ nĩwakiakiiw’e ũndũ wa Aminoni, nũndũ aĩ mũkw’ũ.'),
('kam', '2SA', 14, 1, 'Na Yoavu mwana wa Nzeluia oona atĩ ngoo ya mũsumbĩ yelekele Avisalomu.'),
('kam', '2SA', 14, 2, 'Na Yoavu atũmana Tekoa, na aete kuma kw’o mũndũ mũka mũĩ, na amwĩa, Nĩngũkwĩsũva, wĩtw’ĩkĩthye ta wĩ mũndũ ũnũũmeta, na ũkĩkĩa ngũa ila syĩkĩawa nĩ ũla ũnũũmeta, nĩngũkwĩsũva, na ndũkevake mauta, ĩndĩ ĩthĩwa ta mũndũ mũka ũla ũmetee mũndũ mũkw’ũ ĩvinda ĩasa:'),
('kam', '2SA', 14, 3, 'na lika vala ve mũsumbĩ, noineena nake ta ũũ. Na ĩndĩ Yoavu eekĩa ndeto kanyw’anĩ wake.'),
('kam', '2SA', 14, 4, 'Na yĩla ũla mũndũ mũka wa Tekoa waneenie na mũsumbĩ, avalũka nthĩ na ũthyũ wake, na eekunamya vyũ, na amwĩa, Ndethya, ame mũsumbĩ.'),
('kam', '2SA', 14, 5, 'Na mũsumbĩ amũkũlya, Wĩ na ũndũ mwaũ? Nake asũngĩa, Nĩ ndiwa w’o, na mũemewa nĩ mũkw’ũ.'),
('kam', '2SA', 14, 6, 'Na mũthũkũmi waku mwĩĩtu, aĩ na ana elĩ, na asu elĩ mokita ene kwa ene kĩsesinĩ, na vatyaĩ mũndũ wa kũmatan’ya, ĩndĩ ũmwe akũna ũla ũngĩ, na amũaa.'),
('kam', '2SA', 14, 7, 'Na, sisya, mũvĩa w’onthe nũmũkĩlĩle mũthũkũmi waku mwĩĩtu, na measya, Nengane ũla wakũnie mwana‐a‐inyia, nĩ kana tũmũae vandũ va thayũ wa mwana‐a‐inyia ũla woaie, na ĩndĩ twanange mũtiĩwa nake. O ta ũu makavosya ĩkaa yakwa yĩla yĩtiele, na matikatiĩa mũemewa syĩtwa kana ũtialo ĩũlũ wa nthĩ.'),
('kam', '2SA', 14, 8, 'Na mũsumbĩ amwĩa ũ mũndũ mũka, Enda nyũmbanĩ kwaku, na ngeeaa ũndũ waku.'),
('kam', '2SA', 14, 9, 'Na ũla mũndũ mũka wa Tekoa amwĩa mũsumbĩ, Mwĩaĩi wakwa, ame mũsumbĩ, ũthũku ũsu wĩthĩwe ĩũlũ wakwa, na ĩũlũ wa nyũmba ya nau; na mũsumbĩ ethĩwe ate na ĩvĩtyo, o na kĩvĩla kyake kya ũsumbĩ.'),
('kam', '2SA', 14, 10, 'Na mũsumbĩ amwĩa, O ũla ũkaneena naku, ũkamũete kwakwa, na ndakakũkiita ĩngĩ.'),
('kam', '2SA', 14, 11, 'Nĩvo ĩndĩ waisye, Nĩngũkwĩsũva, mũsumbĩ nalilikane Yeova Ngai waku, nĩ kana mũĩvanĩsya wa nthakame ndakanange ĩngĩ, matikese kwananga mwana wakwa. Na asya, O tondũ Yeova wĩ thayũ, ũsw’ĩĩ ũmwe wa mwana waku ndũkavalũka nthĩ.'),
('kam', '2SA', 14, 12, 'Nĩvo ĩndĩ ũ mũndũ mũka waisye, Nĩngũkwĩsũva, mũthũkũmi waku mwĩĩtu naneene ndeto na mwĩaĩi wakwa mũsumbĩ. Na amwĩa, Neenanga.'),
('kam', '2SA', 14, 13, 'Na mũndũ mũka akũlya, Nũndũ wa kĩ ĩndĩ ũmasũanĩĩe andũ ma Ngai ũndũ ta ũsu? Nũndũ akĩneena ndeto ĩsu mũsumbĩ ailyĩ ta ũmwe mũvĩtan’ya, nũndũ mũsumbĩ ndaatũnga ũla wake walũngilw’e'),
('kam', '2SA', 14, 14, 'Nũndũ mũvaka tũkw’e, na tũilyĩ manzĩ metĩku nthĩ, ala matatonya kũkolanw’a ĩngĩ; o na Ngai ndavetaa thayũ, ĩndĩ nũsũanĩaa maũndũ, nĩ kana ũla walũngilw’e ndakethĩwe mũlũngw’a kwake.'),
('kam', '2SA', 14, 15, 'Yu ĩndĩ nũndũ nĩnũkie kũneena ndeto ĩno na mwĩaĩĩ wakwa mũsumbĩ, nĩ kwa kwĩthĩwa andũ nĩmatumie nĩkĩa: na mũthũkũmi waku mwĩĩtu aisye, Yu nganeena na mũsumbĩ; nokwĩthĩwa mũsumbĩ akeanĩsya ũndũ mũthũkũmi wake ũnũũmũkũlya.'),
('kam', '2SA', 14, 16, 'Nũndũ mũsumbĩ akeew’a, avonokye mũthũkũmi wake kuma kw’okonĩ kwa mũndũ ũla ũnũkwenda kũmbananga nyie na mwana wakwa vamwe tume ũtiĩwanĩ wa Ngai.'),
('kam', '2SA', 14, 17, 'Nĩvo ĩndĩ mũthũkũmi waku mwĩĩtu waisye, Nĩngũkwĩsũva, ndeto ya mwĩaĩi wakwa mũsumbĩ nĩĩthĩwe ya kũkiakisya; nũndũ ta mũlaĩka wa Ngai, now’o ũilyĩ mwĩaĩi wakwa mũsumbĩ kũvathũkan’ya ũseo na ũthũku: na Yeova Ngai waku nĩethĩwe naku.'),
('kam', '2SA', 14, 18, 'Nĩvo ĩndĩ mũsumbĩ wasũngĩie na amwĩa mũndũ mũka, Nĩngũkwĩsũva, ndũkambithe ũndũ o na wĩva ũla ngũũkũlya. Na mũndũ mũka amwĩa, Mwĩaĩi wakwa mũsumbĩ naneene yu.'),
('kam', '2SA', 14, 19, 'Na mũsumbĩ amũkũlya, Kw’oko kwa Yoavu kwĩ naku ũndũnĩ ũũ w’onthe? Na mũndũ mũka asũngĩa na asya, O tondũ kyuu kyaku kĩ thayũ, mwĩaĩi wakwa mũsumbĩ, vati ũla ũtonya kwĩthyũũa kw’okonĩ kwa aũme kana kwa aka kũtia ũndũ o na wĩva ũla mũsumbĩ ũneenete; nũndũ mũthũkũmi waku Yoavu, we nũmbĩaĩe, na eekĩa ndeto isu syonthe kanyw’anĩ wa mũthũkũmi waku mwĩĩtu;'),
('kam', '2SA', 14, 20, 'mũthũkũmi waku Yoavu nĩwĩkĩte ũu nĩ kana aalyũle ũvoo ũndũ ũilyĩ: na mwĩaĩi wakwa nĩ mũĩ kwĩanana na ũĩ wa mũlaĩka wa Ngai, kũmanya maũndũ onthe ala me kũũ nthĩ.'),
('kam', '2SA', 14, 21, 'Na mũsumbĩ amwĩa Yoavu, Sisya yu, nĩnĩkĩte ũndũ ũsu: kwondũ wa ũu enda, ũlatye ũ mwanake Avisalomu.'),
('kam', '2SA', 14, 22, 'Na Yoavu avalũka nthĩ na ũthyũ wake, na eekunamya vyũ, na amũathima mũsumbĩ; na Yoavu asya, Ũmũnthĩ mũthũkũmi waku nĩwĩsĩ nĩnonete ũseo methonĩ maku, mwĩaĩi wakwa, ame mũsumbĩ, nũndũ mũsumbĩ nĩwĩanĩsye ũndũ mũthũkũmi wake ũkũlĩtye.'),
('kam', '2SA', 14, 23, 'Na ĩndĩ Yoavu ookĩla na athi Ngesuli, na aete Avisalomu Yelusaleme.'),
('kam', '2SA', 14, 24, 'Na mũsumbĩ asya, Naende nyũmba kwake, ĩndĩ ndakone ũthyũ wakwa. Na ĩndĩ Avisalomu aenda nyũmbanĩ kwake, na ndaaona ũthyũ wa mũsumbĩ.'),
('kam', '2SA', 14, 25, 'Na ĩndĩ kwa Isilaeli onthe kũtyaĩ ũmwe wa kũtaĩwa mũno ta Avisalomu ũndũ wa mũmbĩlwe wake: kuma ũnyaĩĩ o na kũvika lolotya vatyaĩ kĩema nthĩnĩ wake.'),
('kam', '2SA', 14, 26, 'Na yĩla wenzaa nzw’ĩĩ sya mũtwe wake (aitilaa mũminũkĩlyo wa kĩla mwaka; nĩkwĩthĩwa syaĩ ngito kwake, kwondũ wa ũu nĩwaitilaa); nĩwathimaa nzw’ĩĩ sya mũtwe wake sekeli maana elĩ, kwĩanana na kĩthimi kya mũsumbĩ.'),
('kam', '2SA', 14, 27, 'Na Avisalomu asyaa ana atatũ, na mwĩĩtu ũmwe, ũla wetawa syĩtwa yake Tamali: nake aĩ mũndũ mũka wĩ ũthyũ mũseo.'),
('kam', '2SA', 14, 28, 'Na Avisalomu ekala Yelusaleme myaka ĩlĩ mĩima; na ndaaona ũthyũ wa mũsumbĩ.'),
('kam', '2SA', 14, 29, 'Na ĩndĩ Avisalomu atũmana Yoavu, amũtũme kwa mũsumbĩ; ĩndĩ ndaaĩtĩkĩla kũka vala ũĩ: na atũmana ĩngĩ ya kelĩ, ĩndĩ ndaaĩtĩkĩla kũka.'),
('kam', '2SA', 14, 30, 'Kwondũ wa ũu amea athũkũmi make, Sisyai, mũũnda wa Yoavu wĩ vakuvĩ na wakwa, na e na mbaale vo; endai mũkovĩvye. Na athũkũmi ma Avisalomu mavĩvya mũũnda.'),
('kam', '2SA', 14, 31, 'Nĩvo ĩndĩ Yoavu wokĩlile, na athi kwa Avisalomu nyũmbanĩ kwake, na amũkũlya, Nũndũ wa kĩ athũkũmi maku mavĩvĩtye mũũnda wakwa?'),
('kam', '2SA', 14, 32, 'Na Avisalomu asũngĩa Yoavu, Sisya, nĩnatũmanie kwaku, ngĩkwĩa, Ũka vaa, nĩkũtũme kwa mũsumbĩ, ũkamũkũlye, Nũndũ wa kĩ nookie kuma Ngesuli? Nĩ kavaa kwakwa kwĩthĩwa kw’o kũvika yu. Yu kwondũ wa ũu ndeka ngone ũthyũ wa mũsumbĩ; na ethĩwa ve ũthũku nthĩnĩ wakwa, nambũae'),
('kam', '2SA', 14, 33, 'Na ĩndĩ Yoavu aenda vala ve mũsumbĩ, na amũtavya; na yĩla wamwĩtie Avisalomu, ooka vala ve mũsumbĩ, na eekũnamya nthĩ na ũthyũ wake mbee wa mũsumbĩ: na mũsumbĩ amũmunya Avisalomu.'),
('kam', '2SA', 15, 1, 'Na kweethĩwa ĩtĩna wa ũu, Avisalomu eeyũmbanĩsya ĩkasya na mbalasi na andũ mĩongo ĩtano ma kũsembaa mbee wake.'),
('kam', '2SA', 15, 2, 'Na Avisalomu ookĩla kĩoko tene, na aũngama ũtee wa nzĩa ĩla ĩelete mbingĩlonĩ: na kweethĩwa, yĩla mũndũ o na wĩva wethĩawa na ĩkoani yĩla yaaĩle kũetwe kwa mũsumbĩ yĩsilwe, nĩvo Avisalomu wamwĩtaa na kũkũlya, Wĩ wa ndũa yĩva? Na akyasya, Mũthũkũmi waku nĩ wa mbaĩ ĩmwe ya Isilaeli.'),
('kam', '2SA', 15, 3, 'Na Avisalomu aimwĩa, Sisya, maũndũ maku nĩ maseo na ma w’o; ĩndĩ vati mũndũ wiĩtwe nĩ mũsumbĩ wa ũkwĩthukĩĩsya.'),
('kam', '2SA', 15, 4, 'Na ĩngĩ Avisalomu akyasya, A! Kethĩwa nĩndw’ĩkĩthw’a mũsili ĩ nthĩ, nĩ kana kĩla mũndũ ũla wĩ na ĩkoani kana ũndũ o na wĩva akokaa kwakwa, na ngĩmũsilĩla sila wa katĩ!'),
('kam', '2SA', 15, 5, 'Na kweethĩwa atĩ yĩla mũndũ o na wĩva wathengeea kũmwĩkunamĩsya, aĩtambũũkya kw’oko kwake, na aimũkwata, na kũmũmumunya.'),
('kam', '2SA', 15, 6, 'Ũu nĩw’o Avisalomu wekaa Isilaeli onthe ala mamũkĩe mũsumbĩ ũndũ wa kũsilanw’a: na ĩndĩ Avisalomu ooya ngoo sya andũ ma Isilaeli.'),
('kam', '2SA', 15, 7, 'Na kweethĩwa myaka mĩongo ĩna yathela, Avisalomu amwĩa mũsumbĩ, Nĩngũkwĩsũva, ndeka nĩende na kwĩanĩsya wĩvĩto wakwa, ũla namwĩvĩtĩe Yeova, ku Eviloni.'),
('kam', '2SA', 15, 8, 'Nũndũ mũthũkũmi waku nĩwevĩtie wĩvĩto yĩla natwĩe Ngesuli nthĩ ya Silia, ngyasya, Ethĩwa Yeova akandũnga ĩngĩ Yelusaleme w’o, nĩvo ĩndĩ ngamũthũkũma Yeova.'),
('kam', '2SA', 15, 9, 'Na mũsumbĩ amwĩa, Enda na mũuo. Na ĩndĩ ookĩla na athi Eviloni.'),
('kam', '2SA', 15, 10, 'Ĩndĩ Avisalomu atũma athiani mbaĩnĩ syonthe sya Isilaeli, akyasya, O yĩla mwĩĩw’a wasya wa soo, nĩvo ĩndĩ mwĩasya, Avisalomu nĩ mũsumbĩ ku Eviloni.'),
('kam', '2SA', 15, 11, 'Na vamwe na Avisalomu kwaendie andũ maana elĩ kuma Yelusaleme, ala meetĩtwe, na mathi kwondũ wa kũtamanya kwoo; na matyeesĩ ũndũ.'),
('kam', '2SA', 15, 12, 'Na Avisalomu atũmana Aithoveli Mũngilo, mũtai wa Ndaviti, oke kuma ndũanĩ yake, o ku Ngilo, yĩla wathembaa nthembo. Na wĩw’ano ũsu mũthũku waĩ vinya; nũndũ andũ nĩmaingĩvĩĩe mavinda onthe ngalĩ ya Avisalomu.'),
('kam', '2SA', 15, 13, 'Na kwookie mũtũmwa kwa Ndaviti, akĩmwĩa, Ngoo sya andũ ma Isilaeli niatĩĩe Avisalomu.'),
('kam', '2SA', 15, 14, 'Na Ndaviti amea athũkũmi make onthe ala maĩ Yelusaleme Ũkĩlai, tũindũke; ethĩwa tĩ ũu vatikethĩwa ũmwe waitũ ũkavonoka aume kw’okonĩ kwa Avisalomu; ĩkalaatei tũende ndakese kũtũkwata mĩtũkĩ, na kũtũetee ũthũku, na kũkũna ndũa kwa kũmitemanga na ũvyũ.'),
('kam', '2SA', 15, 15, 'Na athũkũmi ma mũsumbĩ mamwĩa mũsumbĩ, Sisya, athũkũmi maku nĩmeyũmbanĩtye kwĩka o ũndũ mwĩaĩĩ wakwa mũsumbĩ wĩnyuva.'),
('kam', '2SA', 15, 16, 'Na mũsumbĩ aumaala aenda, na andũ onthe ma nyũmba yake mamũvikĩla. Na mũsumbĩ atia aka ĩkũmi, ala maĩ aka ngombo, masũvĩae nyũmba.'),
('kam', '2SA', 15, 17, 'Na mũsũmbĩ aumaala aenda, na andũ onthe mamũatĩĩa; na mekalanga Mbethimelaka.'),
('kam', '2SA', 15, 18, 'Na athũkũmi make onthe mavĩta vakuvĩ nake; na Akelethi onthe, na Avelethi onthe, na Angiti onthe, andũ maana thanthatũ ala mookie mamũatĩĩe kuma Ngathi, mavĩta maenda mbee wa mũsumbĩ.'),
('kam', '2SA', 15, 19, 'Nĩvo ĩndĩ mũsumbĩ wamũkũlilye Itai Mũngiti, Nũndũ wa kĩ ũũendan’ya naitũ? Syoka, wĩkale na mũsumbĩ: nũndũ we wĩ mũndũ wa nthĩ ĩngĩ, na ĩngĩ ũla walũngilw’e kwoo; syoka vandũ vaku mwene.'),
('kam', '2SA', 15, 20, 'Ũndũ ũnookie o ĩoo yĩ ĩthei, ũmũnthĩ nĩnaĩle ũkũtwaa ũende naitũ kũũ na kũũ, nakwa nĩthi o kũla ndonya? Syoka we, noitũnga ana‐a‐ĩthe maku; tei na w’o syĩthĩwe naku.'),
('kam', '2SA', 15, 21, 'Na Itai asũngĩa mũsumbĩ, na amwĩa, O tondũ Yeova wĩ thayũ, na o tondũ mwĩaĩĩ wakwa mũsumbĩ wĩ thayũ, vate ndĩi o vala mwĩaĩi wakwa mũsumbĩ ũkethĩwa, ethĩwa nĩ kĩkw’ũnĩ kana thayũnĩ, o vo nĩvo mũthũkũmi waku ũkethĩwa.'),
('kam', '2SA', 15, 22, 'Na Ndaviti amwĩa Itai, Enda ũinge. Na Itai Mũngiti ainga, na andũ make onthe, na twana tw’onthe tũnini tũla twaĩ nake.'),
('kam', '2SA', 15, 23, 'Na nthĩ yonthe yaĩa na wasya mũnene, na andũ onthe mainga: o na mũsumbĩ mwene ainga kalũsĩ ka Kitiloni, na andũ onthe maingaa, melekele nzĩa ĩelete weũnĩ.'),
('kam', '2SA', 15, 24, 'Na, sisya, Nzatoki nake ooka, na Alivai onthe vamwe nake, makuĩte ĩsandũkũ ya ũtianĩo ya Ngai; na maia ĩsandũkũ ya Ngai nthĩ: na Aviathali ambata, kũvika andũ onthe mamina kuma ndũanĩ.'),
('kam', '2SA', 15, 25, 'Na mũsumbĩ amwĩa Nzatoki, Tũnga ĩsandũkũ ya Ngai ndũanĩ: ethĩwa ngoona ũseo methonĩ ma Yeova, akandũnga ĩngĩ, na kũmbon’ya yo, o na ũtũo wake:'),
('kam', '2SA', 15, 26, 'ĩndĩ ethĩwa akasya atĩĩ, Ndikũtanĩa; sisya, ninyioo, nambĩke o ũndũ ũkwona wĩ ũseo.'),
('kam', '2SA', 15, 27, 'Na ĩngĩ mũsumbĩ akũlya mũthembi Nzatokĩ, Ndwĩ mwoni? Syoka ndũanĩ na mũuo, na ana maku elĩ vamwe naku, Aimaasi mwana waku, na Yonathani mwana wa Aviathali.'),
('kam', '2SA', 15, 28, 'Sisya, ngekala masyũkonĩ me weũnĩ, kũvika ndeto yooka kuma kwaku ya kũmanyĩthya.'),
('kam', '2SA', 15, 29, 'Kwondũ wa ũu Nzatoki na Aviathali makua ĩsandũkũ ya Ngaĩ matũnga Yelusaleme: na mekala kw’o.'),
('kam', '2SA', 15, 30, 'Na Ndaviti ambata kyambato kya kĩĩma kya Mĩthata, na aĩa ambatĩte; na eevw’ĩkĩte mũtwe, na athi maũũ me mathei: na andũ onthe ala maĩ nake kĩla mũndũ eevw’ĩka mũtwe, na mambata, makĩĩa mambatĩte.'),
('kam', '2SA', 15, 31, 'Na ũmwe atavya Ndaviti, akĩmwĩa, Aithoveli nĩ ũmwe wa asamĩĩi vamwe na Avisalomu. Na Ndaviti asya, Ame Yeova, nĩngũũvoya, alyũla ũtao wa Aithoveli wĩthĩwe ũtumanu.'),
('kam', '2SA', 15, 32, 'Na kweethĩwa, yĩla Ndaviti wavikie mũthyanĩ wa kyambato, vala Ngai wathaithĩawa, sisya, Usiai Mũaliiki amũthaũa atembũangĩte kanzũ wake, na e na mũthanga mũtwe.'),
('kam', '2SA', 15, 33, 'Na Ndaviti amwĩa, Ethĩwa ũkaendan’ya nakwa, ũkeethĩwa mũio kwakwa ĩndĩ:'),
('kam', '2SA', 15, 34, 'ĩndĩ ethĩwa ũkasyoka ndũanĩ, na kũmũtavya Avisalomu, Ngeethĩwa mũthũkũmi waku, we mũsumbĩ; o ũndũ nĩnaĩ mũthũkũmi wa au ĩvinda ĩvĩtu, now’o ngwĩthĩwa mũthũkũmi waku; nĩvo ĩndĩ wĩmbanangĩa ũtao wa Aithoveli.'),
('kam', '2SA', 15, 35, 'Na ndwĩ na athembi Nzatoki na Aviathali vamwe naku kw’o? Kwondũ wa ũu kũkeethĩwa, ũvoo o na wĩva ũla ũkew’a kuma nyũmbanĩ ya mũsumbĩ, ũkatavya athembi Nzatoki na Aviathali.'),
('kam', '2SA', 15, 36, 'Sisya, me na ana moo elĩ, Aimaasi, mwana wa Nzatoki, na Yonathani, mwana wa Aviathali, kw’o vamwe nao; na kwondũ woo mũkaetae kwakwa kĩla ũvoo ũla mũkew’aa.'),
('kam', '2SA', 15, 37, 'Na ĩndĩ Usiai, mũnyanyae wa Ndaviti, alika ndũanĩ; na Avisalomu alika Yelusaleme.'),
('kam', '2SA', 16, 1, 'Na yĩla Ndaviti wavĩtũkĩte vanini mũthya wa kyambato, sisya, Nziva mũthũkũmi wa Mevivosethi akomana nake, e na mang’oi elĩ matandĩke, makuĩte imũtũ maana elĩ, na ĩtũngo ĩana sya nzavivũ mbovu, na ĩana sya mosyao ma ĩvinda ya syũa, na kathatwa ke mbinyu.'),
('kam', '2SA', 16, 2, 'Na mũsumbĩ akũlya Nziva, Wĩasya ata na isu? Na Nziva asũngĩa, Mang’oi nĩ ma andũ ma nyũmba ya mũsumbĩ makuwe nĩmo; na imũtũ na ũsyao wa ĩvinda ya syũa nĩ ma anake maye; na mbinyu, nĩ kana ala menyalĩla weũnĩ manyw’e.'),
('kam', '2SA', 16, 3, 'Na mũsumbĩ amũkũlya, Na mwana wa vwana waku aĩva? Na Nziva amwĩa mũsumbĩ, Sisya, ekalaa Yelusaleme; nũndũ asya, Ũmũnthĩ nyũmba ya Isilaeli ĩkandũngĩa ũsumbĩ wa ĩthe wakwa.'),
('kam', '2SA', 16, 4, 'Nĩvo ĩndĩ mũsumbĩ wamwĩie Nziva, Sisya, kyonthe kya Mevivosethi nĩ kyaku. Na Nziva asya, Nĩngwĩkunamya vyũ; none ũseo methonĩ maku, mwĩaĩi wakwa, we mũsumbĩ.'),
('kam', '2SA', 16, 5, 'Na yĩla mũsumbĩ Ndaviti wavikie Mbaulimu, sisya, kwaumĩla kw’o mũndũ wa mũvĩa wa nyũmba ya Saulo, ũla wetawa syĩtwa yake Simei, mwana wa Ngela; aumaala, na akĩumangana okĩte.'),
('kam', '2SA', 16, 6, 'Na amwĩkya Ndaviti mavia, na athũkũmi onthe ma mũsumbĩ Ndaviti; na andũ onthe, na ngũmbaũ syonthe syaĩ ngalĩ ya kw’oko kwa aũme kwake na kw’oko kwa aka.'),
('kam', '2SA', 16, 7, 'Na ũũ nĩw’o ũla Simei waneenie akĩũmangana, Thi, thi, we mũndũ wa nthakame, na mũndũ mwathe:'),
('kam', '2SA', 16, 8, 'Yeova nũtũngĩte ĩũlũ waku nthakame yonthe ya nyũmba ya Saulo, ũla wasumbĩkie vandũ vake; na Yeova nũnenganĩte ũsumbĩ kw’okonĩ kwa Avisalomu mwana waku; na, sisya, nũkwatĩtw’e ũthũkunĩ waku mwene, nĩkwĩthĩwa wĩ mũndũ wa nthakame.'),
('kam', '2SA', 16, 9, 'Nĩvo ĩndĩ Avisai mwana wa Nzeluia wakũlilye mũsumbĩ, Nũndũ wa kĩ ngitĩ ĩno ngw’ũ ĩkũumanga mwĩaĩi wakwa mũsumbĩ? Ndeka nĩinge, nĩngũkwĩsũva, na ngĩtila mũtwe wake.'),
('kam', '2SA', 16, 10, 'Na mũsumbĩ akũlya, Nĩ ũndũ mwaũ nenyu, inyw’ĩ ana ma Nzeluia? Nĩkwĩthĩwa nũnũkũumangana, na nĩkwĩthĩwa Yeova nũmũtavĩtye, Umanga Ndaviti; nũũ ũla ũkasya, Weka ũu nĩkĩ?'),
('kam', '2SA', 16, 11, 'Na Ndaviti amwĩa Avisai, na athũkũmi make onthe, Sisyai, mwana wakwa, ũla waumie kĩnyunyunĩ kyakwa, nũnũũmantha thayũ wakwa: Mũmbenyamini ũũ atonya kwĩka ũu mbee veana ata? Ekanai nake, na ekai aumangane; nũndũ Yeova nũmwĩaĩe.'),
('kam', '2SA', 16, 12, 'Nokwĩthĩwa Yeova akasisya ũthũku ũla nĩkĩtwe, na Yeova akandĩva ũseo kwondũ wa kũumangwa nĩwe ũmũnthĩ.'),
('kam', '2SA', 16, 13, 'Na ĩndĩ Ndaviti na andũ make maendeea nzĩanĩ; na Simei akyamĩĩa kĩĩmanĩ amwĩkuumĩĩsye, na akĩumangana aendete, na amwĩkya mavia na kũvulya kĩtoo.'),
('kam', '2SA', 16, 14, 'Na mũsumbĩ, na andũ onthe ala maĩ nake mavika me anou; na anookea kw’o.'),
('kam', '2SA', 16, 15, 'Na Avisalomu, na andũ onthe, andũ ma Isilaeli, mooka Yelusaleme, na Aithoveli aĩ nake.'),
('kam', '2SA', 16, 16, 'Na kweethĩwa yĩla Usiai Mũaliiki, mũnyanyae wa Ndaviti, wavikie kwa Avisalomu, Usiai amwĩa Avisalomu, Mũsumbĩ nĩethĩwe thayũ ĩvinda ĩasa, mũsumbĩ nĩethĩwe thayũ ĩvinda ĩasa.'),
('kam', '2SA', 16, 17, 'Na Avisalomu akũlya Usiai, Ũũ nĩ ũseo waku kwa mũnyanyau? Nĩkĩ ũtaneethi na mũnyanyau?'),
('kam', '2SA', 16, 18, 'Na Usiai amwĩa Avisalomu, Aiee; ĩndĩ ũla Yeova, na andũ aa, na andũ onthe ma Isilaeli manyuvĩte, ngeethĩwa wake, na ngekala nake.'),
('kam', '2SA', 16, 19, 'Na ĩngĩ, naĩle kũthũkũma ũũ? Ndyaĩle kũthũkũma vala ve mwana wake? O tondũ nathũkũmie vala ve ĩthe waku, now’o ngethĩwa vala ũĩ.'),
('kam', '2SA', 16, 20, 'Nĩvo ĩndĩ Avisalomu wamwĩie Aithoveli, Ete ũtao waku ũndũ twĩĩka.'),
('kam', '2SA', 16, 21, 'Na Aithoveli amwĩa Avisalomu, Lika kwa aka ngombo ma au, ala watiie masũvĩae nyũmba; na Isilaeli onthe makeew’a nũthĩthĩtwe mũno nĩ ĩthe waku: na ĩndĩ moko ma onthe ala me naku makeethĩwa na vinya.'),
('kam', '2SA', 16, 22, 'Na ĩndĩ mamũũngamĩsya Avisalomu ĩeema nyũmbanĩ ĩũlũ; na Avisalomu alika vala ve aka ngombo ma ĩthe wake Isilaeli onthe mene.'),
('kam', '2SA', 16, 23, 'Na ũtao wa Aithoveli, ũla wanenganie mĩthenya ĩsu, wailyĩ ta wa mũndũ ũla wakũlilye ndetonĩ ya Ngai; now’o wailyĩ ũtao w’onthe wa Aithoveli kwa Ndaviti o na kwa Avisalomu.'),
('kam', '2SA', 17, 1, 'Na ĩngĩ Aithoveli amwĩa Avisalomu, Ndeka nĩnyuve yu andũ ngili ĩkũmi na ilĩ, na ngookĩla na kũmũatĩĩa Ndaviti ũtukũ ũũ:'),
('kam', '2SA', 17, 2, 'na ngamũkwata yĩla wĩ na mĩnoo na moko make mate vinya, na ngamũtelemya; na andũ onthe ala me nake makakũka; na ngakũna mũsumbĩ e weka;'),
('kam', '2SA', 17, 3, 'na ngatũnga andũ onthe kwaku: mũndũ ũsu ũla ũũmũmantha ailyĩ ta kethĩwa onthe nĩmasyoka: na ĩndĩ andũ onthe makeethĩwa na mũuo.'),
('kam', '2SA', 17, 4, 'Na kũneena kũu kwamwendeesya Avisalomu mũno, na atumĩa onthe ma Isilaeli.'),
('kam', '2SA', 17, 5, 'Nĩvo ĩndĩ Avisalomu waisye, Yu mwĩtei Usiai Mũaliiki nake, twĩw’e naw’o ũndũ ũkwasya.'),
('kam', '2SA', 17, 6, 'Na yĩla Usiai wokie kwa Avisalomu, Avisalomu aneena nake, akĩmwĩa, Aithoveli nũneenete ũũ na ũũ: nĩtũkwĩka ta ndeto syake? Ethĩwa tĩ ũu, neena.'),
('kam', '2SA', 17, 7, 'Na Usiai amwĩa Avisalomũ, Ũtao ũla Aithoveli wanengane ĩvinda yĩĩ ti mũseo.'),
('kam', '2SA', 17, 8, 'Na Usiai aendeea kwasya, Nĩwĩsĩ ĩthe waku na andũ make, atĩ nĩ ngũmbaũ, na me na woo ililikanonĩ syoo, ta nduva yĩ kĩthekanĩ ĩvenetwe tũswii twayo; na ĩthe waku nĩ mũndũ wa kaũ, na ndeĩtĩkĩla kũkoma vamwe na andũ.'),
('kam', '2SA', 17, 9, 'Sisya, nũvithĩtwe yu ĩimanĩ, kana vandũ vangĩ: na kũkeethĩwa, yĩla amwe moo meamba kũvalũka, o ũla wĩĩw’a ũndũ ũsu akasya, Ve ũaanĩ katĩ wa andũ ala maatĩĩaa Avisalomu.'),
('kam', '2SA', 17, 10, 'O na ũla wĩ na ũkũmbaũ, ũla ngoo yake ĩilyĩ ngoo ya mũnyambũ, akatweka vyũ; nũndũ Isilaeli onthe nĩmesĩ ĩthe waku nĩ ngũmbaũ, na ala me nake me na ũkũmbaũ.'),
('kam', '2SA', 17, 11, 'Ĩndĩ nĩngũtaa atĩ Isilaeli onthe mombanw’e vamwe vala ũĩ, kuma Ndani kũvika Mbeeli‐sieva, ta kĩthangathĩ kĩ ũtee wa ũkanga ũndũ wa kwingĩva; naku mwene ũkĩenda kaũnĩ.'),
('kam', '2SA', 17, 12, 'Na ĩndĩ tũkamũwĩla vandũ o va wĩoneka, na tũkamũvalũkĩla o tondũ ĩmwe yĩvalũkaa nthĩ; nake na andũ onthe ala me nake tũtikatialya o na ũmwe.'),
('kam', '2SA', 17, 13, 'Na ũndũ ũngĩ, ethĩwa akalĩka ndũanĩ, nĩvo Isilaeli onthe meete makanda ndũanĩ ĩsu, na tũkamĩkusĩĩsya ũsĩnĩ, mũvaka kũtikoneka vo kavila kamwe kanini.'),
('kam', '2SA', 17, 14, 'Na Avisalomu na andũ onthe ma Isilaeli masya, Ũtao wa Usiai Mũaliiki nĩ mũseo kwĩ ũtao wa Aithoveli. Nũndũ Yeova nũtw’ĩte kwananga ũtao mũseo wa Aithovelĩ, nĩ kana Yeova aete ũthũku ĩũlũ wa Avisalomu.'),
('kam', '2SA', 17, 15, 'Nĩvo ĩndĩ Usiai wameie athembi Nzatoki na Aviathali, Aithoveli amũtaa Avisalomu na atumĩa ma Isilaeli ũna na ũna; nakwa nataa ũna na ũna.'),
('kam', '2SA', 17, 16, 'Yu kwondũ wa ũu tũmana mĩtũkĩ, noitavya Ndaviti, ũkĩmwĩa, Ndũkakome ũtukũ ũũ masyũkonĩ me weũnĩ, ĩndĩ ndũkatĩe kũinga; mũsumbĩ ndakese kũminwa, na andũ onthe ala me nake.'),
('kam', '2SA', 17, 17, 'Na ĩndĩ Yonathani na Aimaasi mekalĩte vakuvĩ na Eni‐lokeli; na mũthũkũmi mwĩĩtu, akothaa kũthi na kũmatavya; namo maithi na makĩtavya mũsumbĩ Ndaviti: nũndũ no mũvaka matikoneke makĩlika ndũanĩ.'),
('kam', '2SA', 17, 18, 'Ĩndĩ kĩmwana kyamona, na kyatavya Avisalomu: na me elĩ maenda mĩtũkĩ, na mavika nyũmba ya mũndũ ku Mbaulimu, ũla waĩ na kĩthima nza kwake; na malika nthĩnĩ wakyo.'),
('kam', '2SA', 17, 19, 'Na mũndũ mũka oosa na alan’ya kya kũkunĩka kanyw’a wa kĩthima, na anyaĩĩkya nganũ mbũe ĩũlũ wakyo; na vati ũndũ waamanyĩka.'),
('kam', '2SA', 17, 20, 'Na athũkũmi ma Avisalomu mamũkĩa ũ mũndũ mũka nyũmbanĩ; na makũlya, Aimaasĩ na Yonathani maĩva? Na mũndũ mũka amea, Nĩmaingie kalũsĩ ke manzĩ. Na yĩla mamamanthie na malea kũmona, masyoka Yelusaleme.'),
('kam', '2SA', 17, 21, 'Na kweethĩwa, ĩtina wa mathi, asu mauma kĩthimanĩ, na maenda na matavya mũsumbĩ Ndaviti; na mamwĩa Ndaviti, Ũkĩlai, mũinge manzĩ mĩtũkĩ; nũndũ Aithoveli nũtaanĩte ũu ĩũlũ wenyu.'),
('kam', '2SA', 17, 22, 'Na ĩndĩ Ndaviti ookĩla, na andũ onthe ala maĩ nake, na mainga Yolotani: kĩoko kũikya kũtyatialĩte o na ũmwe wa asu ũtaingĩte Yolotani.'),
('kam', '2SA', 17, 23, 'Na yĩla Aithoveli wonie ũtao wake ndwaaatĩĩwa, atandĩka ĩng’oi yake, na ookĩla, na enũka ndũanĩ yoo, na eeaa maũndũ ma nyũmba yake, na eesũsya mwene; na akw’a, na athikwa ngunganĩ ya ĩthe wake vala vathikawa akw’ũ.'),
('kam', '2SA', 17, 24, 'Na ĩndĩ Ndaviti avika Maanaimu. Na Avisalomu ainga Yolotani, we na andũ onthe ma Isilaeli vamwe nake.'),
('kam', '2SA', 17, 25, 'Na Avisalomu aia Amasa ethĩwe mũnene wa ĩ nguthu vandũ va Yoavu. Na ĩndĩ Amasa aĩ mwana wa mũndũ, ũla wetawa syĩtwa yake Ithala Mũisilaeli, ũla walikile kwa Avikaili mwĩĩtu wa Naasu, mwĩĩtu‐a‐inyia wa Nzeluia, inyia wa Yoavu.'),
('kam', '2SA', 17, 26, 'Na Isilaeli na Avisalomu mamba maeema moo nthĩ ya Ngileati.'),
('kam', '2SA', 17, 27, 'Na kweethĩwa, yĩla Ndaviti wavikie Maanaimu, Sovi mwana wa Naasu wa Lava wa ana ma Amimoni, na Makili mwana wa Amieli wa Londevali, na Mbalisilai Mũngileati wa Lokelimu,'),
('kam', '2SA', 17, 28, 'maete mokomo, na masaani manene, na mĩio ya yũmba, na nganũ, na mbaale, na mũtu, na lĩu wa mbaa ngetha mũkaange, na mbooso, na ndengũ, na isyo ngaange,'),
('kam', '2SA', 17, 29, 'na ũkĩ wa nzũkĩ, na mauta, na malondu, na ngũmbwa sya matulu ma ĩia ya ng’ombe, kwondũ wa Ndaviti, na kwondũ wa andũ ala maĩ nake, maye: nũndũ maasya, Andũ me na nzaa, na mĩnoo, na waũni, ku weũnĩ.'),
('kam', '2SA', 18, 1, 'Na Ndaviti atala andũ ala maĩ nake, na amaiĩa makavuteni ma ngili ngili na makavuteni ma maana.'),
('kam', '2SA', 18, 2, 'Na Ndaviti atilangan’ya andũ mathi me nguthu itatũ, kĩlungu kĩmwe kw’okonĩ kwa Yoavu, na kĩlungu kĩngĩ kw’okonĩ kwa Avisai mwana wa Nzeluia, mwana‐a‐ĩthe wa Yoavu, na kĩlungu kĩngĩ kw’okonĩ kwa Itai Mũngiti. Na mũsumbĩ amea andũ, Nditĩa kũthi nenyu nyie mwene.'),
('kam', '2SA', 18, 3, 'Ĩndĩ andũ masya, Ndũkathi: nũndũ ethĩwa tũkakĩa, matikatũsũanĩa; o na ethĩwa nyunzu yaitũ ĩkakw’a, matikatũsũanĩa: ĩndĩ we wĩ vata ta ngili ĩkũmi maitũ; kwondũ wa ũu nĩ kavaa wĩthĩwe wĩyũmbanĩtye kũtũtethasya wĩ ndũanĩ.'),
('kam', '2SA', 18, 4, 'Na mũsumbĩ amea, O ũndũ mwĩona wĩ ũseo mbee now’o nĩĩka. Na mũsumbĩ aũngama ũtee wa mbingĩlo, na andũ onthe maumaala maana na maana na ngili na ngili.'),
('kam', '2SA', 18, 5, 'Na mũsumbĩ eeaĩa Yoavu na Avisai na Itai, akĩmea, Mũsũvĩei ũ mwanake, o Avisalomu, kwondũ wakwa. Na andũ onthe meew’a yĩla mũsumbĩ weaĩe makavuteni onthe ũndũ wa Avisalomu.'),
('kam', '2SA', 18, 6, 'Na ĩndĩ andũ maumaala maenda kĩthekanĩ mokite na Isilaeli: na kaũ waĩ mũtitũnĩ wa Evalaimu.'),
('kam', '2SA', 18, 7, 'Na andũ ma Isilaeli makũnĩwa kw’o nĩ athũkũmi ma Ndaviti, na kwaĩ ũai mũnene kw’o mũthenya ũsu wa andũ ngili mĩongo ĩlĩ.'),
('kam', '2SA', 18, 8, 'Nũndũ kaũ nĩwanyaĩĩkĩe ku ĩũlũ wa nthĩ yonthe; na mũtitũ wamina andũ aingĩ kwĩ ala maminiwe na ũvyũ.'),
('kam', '2SA', 18, 9, 'Na Avisalomu esa kũkomana na athũkũmi ma Ndaviti. Na Avisalomu aendete akuĩtwe nĩ nyũmbũ yake, na nyũmbũ yavĩtĩla ungu wa mbonge nthungu sya mũtĩ wa mwaloni mũnene, na mũtwe wake wakwatwa nĩ mwaloni, na ookĩlw’a ĩũlũ wa nthĩ; na nyũmbũ ĩla yaĩ ungu wake yathi.'),
('kam', '2SA', 18, 10, 'Na mũndũ ũmwe oona ũu, na atavya Yoavu, na amwĩa, Sisya, nĩnonie Avisalomu aniinĩte mwaloninĩ.'),
('kam', '2SA', 18, 11, 'Na Yoavu atavya mũndũ ũla wamũtavisye, Na, sisya, nĩwonie ũu, na nĩkĩ ũtanamũkũnĩa vau akavalũka nthĩ? Nakwa nĩthĩwa nakũnenga ilungu ĩkũmĩ sya vetha, na mũsivi.'),
('kam', '2SA', 18, 12, 'Na ũ mũndũ amwĩa Yoavu, O na ethĩwa ngoona ĩlungu ngili sya vetha kw’okonĩ, ndyĩtĩkĩla kũmũtambũũkĩa mwana wa mũsumbĩ kw’oko kwakwa: nũndũ mũsumbĩ eaĩe we na Avisai na Itai tũkĩw’a, akĩmwĩa, Ĩsũvĩei mũndũ o na wĩva ndakakiite ũ mwanake Avisalomu.'),
('kam', '2SA', 18, 13, 'Keka ũu, kethĩwa nĩkie ũndũ ũte wa w’o ĩũlũ wa thayũ wake (na vati ũvoo ũvithĩtwe mũsumbĩ), we mwene wĩthĩwa ũngalyũkĩle.'),
('kam', '2SA', 18, 14, 'Nĩvo ĩndĩ Yoavu waisye, Nditonya kwĩkalanga naku ta ũu. Nake oosa tũtumo tũtatũ na kw’oko kwake, na atũtonyethya ngoonĩ ya Avisalomu mũkuthũ, e o thayũ vu mwaloninĩ.'),
('kam', '2SA', 18, 15, 'Na anake ĩkũmi ala makuaa mĩio ya kaũ ya Yoavu mamwĩlingĩla na mamũkũna Avisalomu, mamũaa.'),
('kam', '2SA', 18, 16, 'Na Yoavu avuva soo, na andũ masyoka maeka kũatĩĩa Isilaeli; nũndũ Yoavu nĩwasiĩĩe andũ.'),
('kam', '2SA', 18, 17, 'Na moosa Avisalomu na mamwĩkya yĩla ĩimanĩ ĩnene yaĩ mũtitũnĩ, na mamũmbĩĩa kĩvumbu kĩnene kya mavia: na Isilaeli onthe makĩĩa kĩla ũmwe ĩeemanĩ yake.'),
('kam', '2SA', 18, 18, 'Na Avisalomu yĩla waĩ thayũ aĩ anosa na kwĩũngamĩsya kĩtuĩ, kĩla kĩ mwandanĩ wa mũsumbĩ; nũndũ aisye, Ndi na mwana wa kwĩkalya syĩtwa yakwa yĩlilikenwe: na eeta kĩtuĩ na syĩtwa yake mwene; na nĩkĩtawa ũlilikan’yo wa Avisalomu, kũvika ũmũnthĩ.'),
('kam', '2SA', 18, 19, 'Na ĩndĩ Aimaasi mwana wa Nzatoki asya, Eka nzembe yu, na kũmũtwaĩa mũsumbĩ ũvoo, ũndũ Yeova ũmũĩvanĩsye kwa amaitha make.'),
('kam', '2SA', 18, 20, 'Na Yoavu amwĩa, Ndwĩĩthĩwa mũtwai wa ũvoo ũmũnthĩ, ĩndĩ ũkatwaa ũvoo mũthenya ũngĩ; ĩndĩ ũmũnthĩ ndwĩtwaa ũvoo, nĩkwĩthĩwa mwana wa mũsumbĩ nĩ mũkw’ũ.'),
('kam', '2SA', 18, 21, 'Na ĩndĩ Yoavu amwĩa ũla Mũkusi, Enda, ũmũtavye mũsumbĩ ũndũ wonie. Na Mũkusi eekunamĩsya Yoavu, na asemba.'),
('kam', '2SA', 18, 22, 'Nĩvo ĩndĩ Aimaasi mwana wa Nzatoki wamwĩie Yoavu ĩngĩ, Ĩndĩ nĩkwĩkĩke o ũndũ kwĩĩkĩka, nĩngũkwĩsũva, o nakwa ndeka nzembe ĩtina wa Mũkusi. Na Yoavu akũlya, Nũndũ wa kĩ ũkwenda kũsemba, mwana wakwa, nũndũ ndũkethĩwa na ĩtuvi kwondũ wa ũvoo?'),
('kam', '2SA', 18, 23, 'Ĩndĩ nĩkwĩkĩke o ũndũ kwĩĩkĩka, ngasemba, asya ũu. Na amwĩa, Semba. Na ĩndĩ Aimaasi asemba na nzĩa ya Ũiĩnĩ, na amũkĩlya ũla Mũkusi maũũ.'),
('kam', '2SA', 18, 24, 'Na Ndaviti ekalĩte katĩ wa mbingĩlo ilĩ: na mũsyaĩĩsya ambata kyalanĩ kĩ mbingĩlonĩ kũvika ũvainĩ, na aũngalalya metho make, na aketeea, na, sisya, mũndũ asembete e weka.'),
('kam', '2SA', 18, 25, 'Na ũla mũsyaĩĩsya ookĩlya wasya, na atavya mũsumbĩ. Na mũsumbĩ asya, Ethĩwa e weka, ve ũvoo kanyw’anĩ wake. Na ooka asembete mũno, na athengeea.'),
('kam', '2SA', 18, 26, 'Na ũ mũsyaĩĩsya oona mũndũ ũngĩ asembete; na ũ mũsyaĩĩsya anĩĩsya mũsũvĩi wa mũomo, na amwĩa, Sisya, mũndũ ũngĩ asembete e weka. Na mũsumbĩ asya, O nake mũetete ũvoo.'),
('kam', '2SA', 18, 27, 'Na mũsyaĩĩsya asya, Nĩngwasya kũsemba kwa ũla wĩ mbee kũilyĩ kũsemba kwa Aimaasi mwana wa Nzatoki. Na mũsumbĩ asya, Nĩ mũndũ mũseo na nĩwũkĩte na ũvoo mũseo.'),
('kam', '2SA', 18, 28, 'Na Aimaasi anĩĩsya, na atavya mũsumbĩ, Nĩ mũuo. Na eekunamya mbee wa mũsumbĩ ũthyũ wake welekele nthĩ, na asya, Nataĩwe Yeova Ngai waku ũla ũnenganĩte andũ ala mamũkĩlĩlye mwĩaĩi wakwa mũsumbĩ moko moo.'),
('kam', '2SA', 18, 29, 'Na mũsumbĩ akũlya, Mwanake Avisalomu no mũseo? Na Aimaasi asũngĩa, Yila Yoavu watũmie mũthũkũmi wa mũsumbĩ, o nyie mũthũkũmi waku, nonie kĩtuu kĩnene, ĩndĩ ndinamanya nĩ kya kĩ.'),
('kam', '2SA', 18, 30, 'Na mũsumbĩ amwĩa, Vĩta, noiũngama vaa. Na avĩta, na aũngama.'),
('kam', '2SA', 18, 31, 'Na, sisya, ũla Mũkusi ooka; na Mũkusi asya, Nĩ na ũvoo kwondũ wa mwĩaĩi wakwa mũsumbĩ; nũndũ Yeova nũkũĩvanĩsye ũmũnthĩ kwa onthe ala makũkĩlĩle.'),
('kam', '2SA', 18, 32, 'Na mũsumbĩ akũlya Mũkusi, Mwanake Avisalomu no mũseo? Na Mũkusi asũngĩa, Amaitha ma mwĩaĩĩ wakwa, na onthe ala makũkĩlĩlaa makwĩke naĩ, nĩmethĩwe ta mwanake ũsu.'),
('kam', '2SA', 18, 33, 'Na mũsumbĩ atelema mũno, na ambata kasũmbanĩ ke mbingĩlonĩ ĩũlũ, na aĩa: na aendete, aasya atĩĩ, We mwana wakwa Avisalomu, mwana wakwa, mwana wakwa Avisalomu! Nenda kethĩwa ninyie ngwie vandũ vaku, we Avisalomu, mwana wakwa, mwana wakwa!'),
('kam', '2SA', 19, 1, 'Na Yoavu atavw’a, sisya, mũsumbĩ nũnũkũĩa na kũmũmetea Avisalomu.'),
('kam', '2SA', 19, 2, 'Na ũkĩlyo mũthenya ũsu nĩwaalyũlilwe wĩthĩwe kũmeta kwa andũ onthe: nũndũ andũ meewie kũkyaw’a mũthenya ũsu, Mũsumbĩ nũnũkwĩw’a woo ũndũ wa mwana wake.'),
('kam', '2SA', 19, 3, 'Na andũ maenda ndũanĩ na kĩmbithĩ mũthenya ũsu, o tondũ andũ ala masonokaa maendaa na kĩmbithĩ yĩla makĩa kuma kaũnĩ.'),
('kam', '2SA', 19, 4, 'Na mũsumbĩ avw’ĩka ũthyũ wake, na mũsumbĩ aĩa na wasya mũnene, We mwana wakwa Avisalomu, we Avisalomu, mwana wakwa, mwana wakwa!'),
('kam', '2SA', 19, 5, 'Na Yoavu alika nyũmbanĩ vala ve mũsumbĩ, na amwĩa, Ũmũnthĩ nũsonokethetye mothyũ ma athũkũmi maku onthe, ala ũmũnthĩ matangĩĩe thayũ waku, na mathayũ ma ana maku na eĩtu maku, na mathayũ ma iveti syaku, na mathayũ ma aka maku ngombo;'),
('kam', '2SA', 19, 6, 'ũndũ ũmendaa ala makũmenaa, na kũmenaa ala makwendaa. Nũndũ ũmũnthĩ nĩwonanĩtye, kana anene me mbee ũsumbĩnĩ na athũkũmi ti kĩndũ kwaku: nũndũ ũmũnthĩ nĩngwona, kethĩwa Avisalomu ekalile thayũ, na ithyonthe tũkĩkw’a ũmũnthĩ, ũu wĩthĩwa ũkwendeesye mũno ĩndĩ.'),
('kam', '2SA', 19, 7, 'Yu kwondũ wa ũu ũkĩla umaale, noineena na athũkũmi maku na ndeto sya ũkiakisyo nũndũ nĩngwĩvĩta na Yeova, ethĩwa ndwĩumaala, kũtikekala mũndũ naku ũtukũ ũũ: na ũu ũkeethĩwa ũthũku kwaku kwĩ ũthũku w’onthe ũla wakũkwatie kuma wana waku kũvika yu.'),
('kam', '2SA', 19, 8, 'Na ĩndĩ mũsumbĩ ookĩla, na ekala nthĩ mbingĩlonĩ. Na matavya andũ onthe, makĩmea, Sisya, mũsumbĩ nĩwĩkalĩte nthĩ mbingĩlonĩ: na andũ onthe mooka vala ve mũsumbĩ. Na ĩndĩ Isilaeli maĩ manakĩĩa kĩla mũndũ ĩeemanĩ yake.'),
('kam', '2SA', 19, 9, 'Na andũ onthe nĩmatetanasya mbaĩnĩ syonthe sya Isilaeli, makyasya, Mũsumbĩ nĩwatũvonokisye kuma mokonĩ ma amaitha maitũ, na atũtangĩĩa kuma mokonĩ ma Avilisiti; na yu nũkĩĩte Avisalomu akauma ĩ nthĩ.'),
('kam', '2SA', 19, 10, 'Na Avisalomu ũla twamwĩtĩkĩsye mauta atũsumbĩke, nũkw’ĩĩe kaũnĩ. Kwondũ wa ũu ĩndĩ nĩkĩ mũtiũneena ndeto o na ĩmwe ũndũ wa kũtũnga mũsumbĩ?'),
('kam', '2SA', 19, 11, 'Na mũsumbĩ Ndaviti atũmana kwa athembi Nzatoki na Aviathali, akĩmea, Neenai na atumĩa ma Yuta, mũkĩmea, Inyw’ĩ mwĩ ma ĩtina ma kũtũnga mũsumbĩ nyũmbanĩ yake nĩkĩ? Nũndũ kũneena kwa Isilaeli onthe nĩkũvikĩte kwa mũsumbĩ, kũmũete nyũmbanĩ kwake.'),
('kam', '2SA', 19, 12, 'Inyw’ĩ mwĩ ana‐a‐asa makwa, mwĩ ĩvĩndĩ yakwa na mwĩĩ wakwa: nũndũ wa kĩ ĩndĩ inyw’ĩ mwĩ ma ĩtina ma kũtũnga mũsumbĩ?'),
('kam', '2SA', 19, 13, 'Na mũkũlyei Amasa, Ndwĩ ĩvĩndĩ yakwa na mwĩĩ wakwa? Ngai nambĩke ũu, o na mbee, ethĩwa ndwĩĩthĩwa kavuteni wa nguthu mbee wakwa mavinda onthe vandũ va Yoavu.'),
('kam', '2SA', 19, 14, 'Na athyũũa ngoo sya andũ onthe ma Yuta, o ta ngoo ya mũndũ ũmwe; na ĩndĩ matũmana kwa mũsumbĩ, makĩmwĩa, Syoka we, na athũkũmi maku onthe.'),
('kam', '2SA', 19, 15, 'Na ĩndĩ mũsumbĩ asyoka, na avika Yolotani. Na Yuta mooka Ngilikali, nĩ kana maende kũmũthaũa mũsumbĩ, maingye mũsumbĩ Yolotani.'),
('kam', '2SA', 19, 16, 'Na Simei mwana wa Ngela, Mũmbenyamini, ũla waĩ wa ndũa ya Mbaulimu, eekalaata na atheea na andũ ma Yuta amũthaũe mũsumbĩ Ndaviti.'),
('kam', '2SA', 19, 17, 'Na kwaĩ andũ ngili ma Mbenyamini vamwe nake, na Nziva mũthũkũmi wa nyũmba ya Saulo, na ana make ĩkũmi na atano, na athũkũmi make mĩongo ĩlĩ vamwe nake; na mainga Yolotani mũsumbĩ ene.'),
('kam', '2SA', 19, 18, 'Na kwainga ĩtalũ ĩlatye andũ ma nyũmba ya mũsumbĩ, na kwĩka o ũndũ wonaa wĩ ũseo. Na Simei mwana wa Ngela avalũka nthĩ mbee wa mũsumbĩ, yĩla waingaa Yolotani.'),
('kam', '2SA', 19, 19, 'Na amwĩa mũsumbĩ, Mwĩaĩi wakwa ndakandalĩle ũthũku, o na ndũkalilikane ũndũ mũthũkũmi waku wekie na ngũlũ mũthenya ũla mwĩaĩi wakwa mũsumbĩ waumie Yelusaleme, atĩ mũsumbĩ aie ũndũ ũsu ngoonĩ yake.'),
('kam', '2SA', 19, 20, 'Nũndũ mũthũkũmi waku nĩwĩsĩ nĩnĩvĩtĩtye: kwondũ wa ũu, sisya, nĩnooka ũmũnthĩ na nĩ wa mbee wa nyũmba yonthe ya Yosevu wa kũtheea kũkomana na mwĩaĩi wakwa mũsumbĩ.'),
('kam', '2SA', 19, 21, 'Ĩndĩ Avisai mwana wa Nzeluia asũngĩa na akũlya, Simei ndeũawa ũndũ wa ũndũ ũsu, nĩkwĩthĩwa nĩwaumangie mwĩtĩkĩw’a mauta wa Yeova?'),
('kam', '2SA', 19, 22, 'Na Ndaviti akũlya, Nyie nĩ ũndũ mwaũ nenyu, inyw’ĩ ana ma Nzeluia, nĩ kana mwĩthĩwe nthũ syakwa ũmũnthĩ? Mũndũ o na wĩva akoawa ũmũnthĩ nthĩnĩ wa Isilaeli? Nũndũ ndyĩsĩ nĩ mũsumbĩ wa Isilaeli ũmũnthĩ?'),
('kam', '2SA', 19, 23, 'Na mũsumbĩ amwĩa Simei, Ndũkakw’a. Na mũsumbĩ amwĩavĩa.'),
('kam', '2SA', 19, 24, 'Na Mevivosethi mwana wa Saulo atheea kũkomana na mũsumbĩ; na ndaathambya maũũ make, kana kũtila kĩng’ew’a kyake, kana kũthambya ngũa syake, kuma mũthenya ũla mũsumbĩ waendie kũvika mũthenya ũla wenũkie na mũuo.'),
('kam', '2SA', 19, 25, 'Na kweethĩwa, yĩla wavikie Yelusaleme akomane na mũsumbĩ, mũsumbĩ amũkũlya, Nũndũ wa kĩ ndwaaenda nakwa, Mevivosethi?'),
('kam', '2SA', 19, 26, 'Na asũngĩa, Mwĩaĩi wakwa, we mũsumbĩ, mũthũkũmĩ wakwa nĩwangengie: nũndũ mũthũkũmi waku aisye, Ngeetandĩkĩthĩsya ĩng’oi, nĩ kana nĩkuwe nĩyo, na kũthi na mũsumbĩ; nĩkwĩthĩwa mũthũkũmi waku nĩwaie maũũ.'),
('kam', '2SA', 19, 27, 'Nake nũsukĩte mũthũkũmi waku kwa mwĩaĩi wakwa mũsumbĩ; ĩndĩ mwĩaĩi wakwa mũsumbĩ ailyĩ ta mũlaĩka wa Ngai: kwondũ wa ũu ĩka ũndũ wĩona wĩ ũseo.'),
('kam', '2SA', 19, 28, 'Nũndũ nyũmba yonthe ya ĩthe wakwa yaĩ o ta andũ akw’ũ kwa mwĩaĩi wakwa mũsumbĩ; ĩndĩ nĩwaiie mũthũkũmi waku katĩ wa ala maĩsaa mesanĩ yaku mwene. Kwondũ wa ũu yu nĩ na waĩlo mwaũ wa kũmwĩkaĩla mũsumbĩ ĩngĩ?'),
('kam', '2SA', 19, 29, 'Na mũsumbĩ amũkũlya, Nĩkĩ ũendeee na kũneena maũndũ maku? Nĩngwasya, We na Nziva atũanai nthĩ.'),
('kam', '2SA', 19, 30, 'Na Mevivosethi amwĩa mũsumbĩ, Ĩĩ, nĩose yonthe, nũndũ mwĩaĩi wakwa mũsumbĩ nĩ mũku na mũuo nyũmbanĩ yake mwene.'),
('kam', '2SA', 19, 31, 'Na Mbalisilai Mũngileati atheea kuma Lokelimu; na ainga Yolotani vamwe na mũsumbĩ, amũtongoesye ainge Yolotani.'),
('kam', '2SA', 19, 32, 'Na Mbalisilai aĩ mũndũ mũtumĩu mũno, o wa myaka mĩongo nyanya: na nĩwanengae mũsumbĩ kya ũya yĩla waĩ Maanaimu; nũndũ aĩ mũndũ wĩ nguma mũno.'),
('kam', '2SA', 19, 33, 'Na mũsumbĩ amwĩa Mbalisilai, Ingan’ya nakwa, na ngakũnengae lĩu wĩ nakwa Yelusaleme.'),
('kam', '2SA', 19, 34, 'Na Mbalisilai amũkũlya mũsumbĩ, Mĩthenya ya myaka ya thayũ wakwa nĩ yĩana, nĩ kana nambate na mũsumbĩ Yelusaleme?'),
('kam', '2SA', 19, 35, 'Ũmũnthĩ nĩ wa myaka mĩongo nyanya: nĩndonya kũvathũkan’ya katĩ wa ũseo na ũthũku? Mũthũkũmi waku nũtonya kũsama kĩla nĩĩsaa kana kĩla nĩnyusaa? Nĩndonya kwĩw’a yu wasya wa aũme makina na aka makina? Nũndũ wa kĩ ĩndĩ mũthũkũmi waku waĩle kwĩthĩwa mũio kwa mwĩaĩi wakwa mũsumbĩ?'),
('kam', '2SA', 19, 36, 'Mũthũkũmi waku endaa o kũinga Yolotani vamwe na mũsumbĩ: na nũndũ wa kĩ mũsumbĩ wĩenda kũndĩva na ũĩvo wĩana ũu?'),
('kam', '2SA', 19, 37, 'Nĩngũkwĩsũva, mũthũkũmi waku naalũke, nĩ kana ngakw’ĩe ndũanĩ yaitũ ene, vakuvĩ na mbũa ya nau na mwaitũ. Ĩndĩ sisya, mũthũkũmi waku Kimiamu; nainge na mwĩaĩi wakwa mũsumbĩ; na ũmwĩke o ũndũ wĩona wĩ ũseo.'),
('kam', '2SA', 19, 38, 'Na mũsumbĩ asũngĩa, Kimiamu akainga vamwe nakwa, na ngamwĩka ũndũ wĩona wĩ ũseo: na o ũla wĩenda kwakwa, now’o ngakwĩka.'),
('kam', '2SA', 19, 39, 'Na andũ onthe mainga Yolotani, na mũsumbĩ ainga: na mũsumbĩ amũmumunya Mbalisilai, na amũathima; na asyoka kwake mwene.'),
('kam', '2SA', 19, 40, 'Na ĩndĩ mũsumbĩ ainganĩsya Ngilikali, na Kimiamu aingan’ya nake: na andũ onthe ma Yuta, o na nyunzu ya andũ ma Isilaeli, mamũingya mũsumbĩ.'),
('kam', '2SA', 19, 41, 'Na, sisya, andũ onthe ma Isilaeli mamũkĩa mũsumbĩ, na mamwĩa mũsumbĩ, Nĩkĩ ana‐a‐ĩthe maitũ andũ ma Yuta makũyie na kũingya mũsumbĩ na andũ ma nyũmba yake, o na andũ onthe ma Ndaviti vamwe nake Yolotani?'),
('kam', '2SA', 19, 42, 'Na andũ onthe ma Yuta masũngĩa andũ ma Isilaeli, Nĩkwĩthĩwa mũsumbĩ nĩ wa mũvĩa witũ ũla wa vakuvĩ: mũthatĩtwe nĩ ũndũ ũũ nĩkĩ? Nongĩ nĩtũĩte kya kĩla mũsumbĩ ũthooete? Kana nũtũnengete mũthĩnzĩo o na wĩva?'),
('kam', '2SA', 19, 43, 'Na andũ ma Isilaeli masũngĩa andũ ma Yuta, na masya, Twĩ na ianda ĩkũmi nthĩnĩ wa mũsumbĩ, o na twĩ na kĩanda nthĩnĩ wa Ndaviti kwĩ inyw’ĩ: nũndũ wa kĩ ĩndĩ mũnatũvũthisye, ũndũ mũtaneamba kũtũkũlya ũtao witũ ũndũ wa kũtũnga mũsumbĩ waitũ? Na ndeto sya andũ ma Yuta syaĩ mbai kwĩ ndeto sya andũ ma Isilaeli.'),
('kam', '2SA', 20, 1, 'Na kweethĩwa kwaĩ mũndũ mwathe kw’o, ũla wetawa syĩtwa yake Sieva, mwana wa Mbikili, Mũmbenyamini: na avuva soo, na asya, Tũti na kĩanda nthĩnĩ wa Ndaviti, o na tũti na ũtiĩwa mwananĩ wa Yese: kĩla mũndũ aende maeemanĩ make, inyw’ĩ Isilaeli.'),
('kam', '2SA', 20, 2, 'Kwondũ wa ũu andũ onthe ma Isilaeli mambata maeka kũatĩĩa Ndaviti, na maatĩĩa Sieva mwana wa Mbikili, ĩndĩ andũ ma Yuta malũman’ya na mũsumbĩ woo, kuma Yolotani kũvika Yelusaleme.'),
('kam', '2SA', 20, 3, 'Na Ndaviti avika nyũmbanĩ yake Yelusaleme; na mũsumbĩ oosa ala aka make ĩkũmi ngombo, ala watiie masũvĩae nyũmba, na amekĩa ũsũvĩonĩ na amanenga lĩu ũmeanĩe, ĩndĩ ndaalika kwoo. Na ĩndĩ mavingĩwa kũvika mũthenya wa kũkw’a kwoo, makĩkala ta aka ndiwa.'),
('kam', '2SA', 20, 4, 'Nĩvo ĩndĩ mũsumbĩ wamwĩie Amasa, Mbũmbanĩsya andũ ma Yuta mĩthenya ĩtatũ ĩtanathela, naku wĩĩthĩwa vaa.'),
('kam', '2SA', 20, 5, 'Na ĩndĩ Amasa athi amomban’ye andũ ma Yuta vamwe; ĩndĩ ekalanga avĩtũkĩthya ĩvinda yĩla watw’ĩwe.'),
('kam', '2SA', 20, 6, 'Na Ndaviti amwĩa Avisai, Yu Sieva mwana wa Mbikili akatwĩka ũthũku kwĩ ũla Avisalomu ũneekĩte: osa athũkũmi ma mwĩaĩi waku, noimũatĩĩa, ndakese kwĩseũvĩsya ndũa mbiie, na kwĩvonokesya vala tũtatonya kũmwona.'),
('kam', '2SA', 20, 7, 'Na andũ ma Yoavu, na Akelethi, na Avelethi, na ngũmbaũ syonthe maumaala mamũatĩĩe; na mauma Yelusaleme, maatĩĩe Sieva mwana wa Mbikili.'),
('kam', '2SA', 20, 8, 'Na yĩla maĩ ĩvianĩ ĩnene yĩ Ngiveoni, Amasa ooka amathaũe. Na Yoavu eevotoete ngũa yake ya kaũ ĩla wekĩĩte, na yaĩ na mũsivi wĩ ũvyũ ũlũmĩtw’e kĩnyunyunĩ kyake wĩ ndoonĩ yaw’o; na akyumaala wasomoka wavalũka.'),
('kam', '2SA', 20, 9, 'Na Yoavu akũlya Amasa, Wĩ mũseo, mwana‐a‐ia? Na Yoavu akwata Amasa kĩng’ew’a na kw’oko kwake kwa aũme amũmumunye.'),
('kam', '2SA', 20, 10, 'Ĩndĩ Amasa ndaasũva ũvyũ ũla waĩ kw’okonĩ kwa Yoavu: na ĩndĩ amũtonya naw’o ĩvu, na maa make metĩka nthĩ, na ndaamũtonya ĩngĩ; na akw’a. Na Yoavu na Avisai mwana‐a‐inyia mamũatĩĩa Sieva mwana wa Mbikili.'),
('kam', '2SA', 20, 11, 'Na kwaũngama vakuvĩ nake mwanake ũmwe wa Yoavu, na asya, Ũla ũmwendaa Yoavu, na ũla wĩ ngalĩ ya Ndaviti, namũatĩĩe Yoavu.'),
('kam', '2SA', 20, 12, 'Na Amasa ailitaa nthakamenĩ yake lelũnĩ katĩ. Na yĩla ũ mũndũ wonie andũ onthe nĩmaũngama, amũveta Amasa lelũnĩ amũtwaa kĩthekanĩ, na amũvw’ĩka ngũa, yĩla wonie kĩla mũndũ ũla wavĩtaa akĩũngama.'),
('kam', '2SA', 20, 13, 'Yĩla waumiw’e lelũnĩ, andũ onthe maendeea makĩmũatĩĩa Yoavu, maatĩĩe Sieva mwana wa Mbikili.'),
('kam', '2SA', 20, 14, 'Na avĩtĩla mbaĩnĩ syonthe sya Isilaeli kũvika Aveli, na Mbethi‐maaka, na Ambeli onthe: na moombanw’a vamwe, o nao mamũatĩĩa.'),
('kam', '2SA', 20, 15, 'Na mavika na mamũthyũlũlũka mamũtw’ĩkanĩsya ku Aveli ya Mbethi‐maaka, na mamyũmbĩĩa ĩ ndũa kĩvumbu, na kyaaĩĩa ũvai mũlũmu; na andũ onthe ala maĩ na Yoavu makũnanga ũvai, mavalũkye.'),
('kam', '2SA', 20, 16, 'Nĩvo ĩndĩ mũndũ mũka wĩ kĩlĩko waĩ ndũanĩ anĩĩsya, Ĩw’ai, ĩw’ai; nĩngũmwĩsũva, tavyai Yoavu, ũka vaa vakuvĩ, nĩneene naku.'),
('kam', '2SA', 20, 17, 'Na athengeea vala ũĩ; na ũla mũndũ mũka amũkũlya, Nue Yoavu? Na asũngĩa, Ninyie. Na ĩndĩ amwĩa, Ĩw’a ndeto sya mũthũkũmi waku, mwĩĩtu. Nake asũngĩa, Nĩngwĩw’a.'),
('kam', '2SA', 20, 18, 'Na ĩndĩ aneena, akyasya, Tene makothaa kũneena, makyasya, Maikatĩe kũkũlya ũtao ku Aveli: na ĩndĩ ũvoo ũithela.'),
('kam', '2SA', 20, 19, 'Nyie nĩ wa ala ma Isilaeli ma mũuo na kĩthito: we nũkũmantha kwananga ndũa na nyinyia nthĩnĩ wa Isilaeli: wĩenda kũmina ũtiĩwa wa Yeova nĩkĩ?'),
('kam', '2SA', 20, 20, 'Na Yoavu asũngĩa asya, Nĩkwĩthĩwe kũasa, nĩkwĩthĩwe kũasa nakwa, nĩmine kana kwananga.'),
('kam', '2SA', 20, 21, 'Ũvoo ndũilyĩ ũu: ĩndĩ mũndũ wa nthĩ yĩ iĩma ya Evalaimu, syĩtwa yake eetawa Sieva mwana wa Mbikili, nũmũkĩlĩlye mũsumbĩ kw’oko kwake, o Ndaviti; mũnengane e weka, nakwa nĩngũkĩla na kũtia ndũa. Na ũla mũndũ mũka amwĩa Yoavu, Sisya, mũtwe wake nũkwĩkĩlw’a ũvainĩ kũla ũĩ.'),
('kam', '2SA', 20, 22, 'Na ĩndĩ mũndũ mũka aenda kwa andũ onthe na ũĩ wake. Na matila mũtwe wa Sieva mwana wa Mbikili, na mamwĩkĩsya Yoavu. Na avuva soo, na manyaĩĩka mauma ndũanĩ, mathi kĩla mũndũ ĩeemanĩ yake. Na Yoavu asyoka Yelusaleme kwa mũsumbĩ.'),
('kam', '2SA', 20, 23, 'Na ĩndĩ Yoavu aĩ mũnene wa ngũthu yonthe ya Isilaeli; na Mbenaia mwana wa Yeoiata aĩ mũnene wa Akelethi na Avelethi;'),
('kam', '2SA', 20, 24, 'na Atolamu aĩ mũnene wa andũ ala matethethaw’a wĩa wa vinya; na Yeosavati mwana wa Ailuti aĩ mũandĩki wa maũndũ;'),
('kam', '2SA', 20, 25, 'na Sieva aĩ mũandĩki; na Nzatoki na Aviathali maĩ athembi;'),
('kam', '2SA', 20, 26, 'na Ila Mũyaili nake aĩ mũnene mbee ũsumbĩnĩ kwa Ndaviti.'),
('kam', '2SA', 21, 1, 'Na mĩthenya ya Ndaviti kwaĩ yũa mwaka na mwaka, myaka ĩtatũ; na Ndaviti amantha ũthyũ wa Yeova. Na Yeova asya, Nĩ ũndũ wa Saulo, na ũndũ wa nyũmba yake yĩ nthakame, nĩkwĩthĩwa nĩwoaie Angiveoni.'),
('kam', '2SA', 21, 2, 'Na mũsumbĩ ameta Angiveoni, na amea (Angiveoni ĩndĩ matyaĩ ma ana ma Isilaeli, ĩndĩ maĩ ma ũtialo wa Aamoli; na ana ma Isilaeli maĩ mameavie; na Saulo amantha kũmoaa nũndũ wa kĩwĩu kyake kwondũ wa ana ma Isilaeli na Yuta);'),
('kam', '2SA', 21, 3, 'na Ndaviti akũlya Angiveoni, Nĩmwĩka ata? Na ngeew’anĩthya na kyaũ, nĩ kana mũathime ũtiĩwa wa Yeova?'),
('kam', '2SA', 21, 4, 'Na Angiveoni mamwĩa, Ti ũvoo wa vetha na thaavu katĩ waitũ na Saulo, kana nyũmba yake; o na ti ũndũ witũ kũaa mũndũ o na wĩva nthĩnĩ wa Isilaeli. Nake asya, O ũndũ mwĩneena now’o ngamwĩka.'),
('kam', '2SA', 21, 5, 'Na mamwĩa mũsumbĩ, Mũndũ ũla watũminaa, na ũla watũsamĩaa, twanangwe tũtikekale mĩvakanĩ o na yĩva ya Isilaeli,'),
('kam', '2SA', 21, 6, 'aũme mũonza ananĩ make nĩmanenganwe kwitũ, na tũkamũsũĩsya Yeova ku Ngivea ya Saulo, mũnyuve wa Yeova. Na mũsumbĩ asya, Ngamanengane.'),
('kam', '2SA', 21, 7, 'Ĩndĩ mũsumbĩ atĩa Mevivosethi, mwana wa Yonathani mwana wa Saulo, nũndũ wa wĩvĩto wa Yeova ũla waĩ katĩ woo, katĩ wa Ndaviti na Yonathani mwana wa Saulo.'),
('kam', '2SA', 21, 8, 'Ĩndĩ mũsumbĩ oosa ana elĩ ma Lisiva mwĩĩtu wa Aia, ala wamũsyaĩe Saulo, nao nĩ Alimoni na Mevivosethi; na ana atano ma Mikali mwĩĩtu wa Saulo, ala wamũsyaĩe Atilieli mwana wa Mbalisilai Mũmeolathi:'),
('kam', '2SA', 21, 9, 'na amanengane mokonĩ ma Angiveoni, na mamasũsya kĩĩmanĩ Yeova ene, na asu onthe mũonza mavalũka vamwe. Na mooawa mĩthenya ya ngetha, o mĩthenyanĩ ya mbee, wambĩlĩlyonĩ wa kũketha mbaale.'),
('kam', '2SA', 21, 10, 'Na Livisa mwĩĩtu wa Aia oosa ngũa sya makunia, na eeyalanĩlya ĩũlũ wa ĩvia, kuma wambĩlĩlyo wa ngetha kũvika yĩla mbua yasyuĩe kuma ĩtunĩ; na ndaaeka nyũnyi sya yayaya sivuĩle mũthenya, kana nyamũ sya kĩtheka ũtukũ.'),
('kam', '2SA', 21, 11, 'Na Ndaviti atavw’a ũndũ Lisiva mwĩĩtu wa Aia, mũka ngombo wa Saulo, wĩkĩte.'),
('kam', '2SA', 21, 12, 'Na Ndaviti athi na oosa mavĩndĩ ma Saulo na mavĩndĩ ma Yonathani mwana wake kuma kwa andũ ma Yavesi‐ngileati ala mamoyĩe nzĩanĩ nene ya Mbethi‐sani, vala Avilisiti maisũisye mũthenya ũla Avilisiti mamũaĩe Saulo ku Ngilivoa;'),
('kam', '2SA', 21, 13, 'na aete kuma kw’o mavindĩ ma Saulo na mavĩndĩ ma Yonathani mwana wake: na moomban’ya mavĩndĩ ma ala masũiw’e.'),
('kam', '2SA', 21, 14, 'Na mathika mavĩndĩ ma Saulo na Yonathani mwana wake nthĩ ya Mbenyamini ku Nzeela, ngunganĩ ya Kisu ĩthe wake vala vathikawa akw’ũ: na meeka w’onthe ũla mũsumbĩ weaie. Na ĩtina wa ũu Ngai nĩwesũvĩkie ũndũ wa ĩ nthĩ.'),
('kam', '2SA', 21, 15, 'Na Avilisiti maĩ na kaũ ĩngĩ na Isilaeli; na Ndaviti atheea, e na athũkũmi make, na okita na Avilisiti. Na Ndaviti anyala;'),
('kam', '2SA', 21, 16, 'na Isivi‐mbenovu ũla waĩ wa ana ma yĩla ĩmũndũ, yĩla ũito wa ĩtumo yayo waĩ sekeli maana atatũ sya ũthuku kwa kũthima, eevotoete ũvyũ mweũ, asũanĩa kũaa Ndaviti.'),
('kam', '2SA', 21, 17, 'Ĩndĩ Avisai mwana wa Nzeluia amũtethya, na amũkũna Mũvilisiti, na amũaa. Nĩvo ĩndĩ andũ ma Ndaviti mamwĩavĩe, makyasya, Ndũkaambĩla kumaala ũende naitũ kaũnĩ, ndũkese kũvosya taa wa Isilaeli.'),
('kam', '2SA', 21, 18, 'Na kweethĩwa ĩtina wa ũu, kwaĩ kaũ ĩngĩ na Avilisiti ku Ngovu: na ĩndĩ Sivekai Mũusathi amũaa Savu, ũla waĩ wa ana ma yĩla ĩmũndũ.'),
('kam', '2SA', 21, 19, 'Na kwaĩ kaũ ĩngĩ na Avilisiti Ngovu; na Elianani mwana wa Yaale‐olekimu Mũmbethileemu amũaa Ngoliathu Mũngiti ũla mũti wa ĩtumo yake wailyĩ ta mũamba wa mũtumi wa ngũa.'),
('kam', '2SA', 21, 20, 'Na kwaĩ kaũ ĩngĩ Ngathi, vala vaĩ mũndũ mũasa mũno, ũla waĩ na syaa thanthatũ kĩla, kw’oko, na syaa thanthatũ kĩla kũũ, ũtalo waĩ mĩongo ĩlĩ na inya; nake asyaiwe nĩ yĩla ĩmũndũ.'),
('kam', '2SA', 21, 21, 'Na yĩla wavũthisye Isilaeli, Yonathani mwana wa Simei, mwana‐a‐inyia wa Ndaviti, amũaa.'),
('kam', '2SA', 21, 22, 'Asu me ana masyaĩwe nĩ yĩla ĩmũndũ ku Ngathi; na mavalũkw’a nĩ kw’oko kwa Ndaviti na moko ma athũkũmi make.'),
('kam', '2SA', 22, 1, 'Na Ndaviti aneena na Yeova ndeto sya wathi ũũ mũthenya ũla Yeova wamũvonokisye kuma mokonĩ ma amaitha make onthe, na kw’okonĩ kwa Saulo:'),
('kam', '2SA', 22, 2, 'na asya, Yeova nĩ ĩvia yakwa, na ngome yakwa, na mũvonokya wakwa, o wakwa;'),
('kam', '2SA', 22, 3, 'Ngaĩ, nĩ ĩvia yakwa, ngeevitha nthĩnĩ wake; Ngao yakwa, na ũvya wa ũtangĩĩo wakwa, mwako wakwa mũtũlu mũno wa mũnyoolo, na wĩvitho wakwa; Mũtangĩĩi wakwa, nũndangĩĩaa vala ve ũng’endu.'),
('kam', '2SA', 22, 4, 'Ngeekaĩla Yeova, ũla waĩle kũtaĩwa: Na ĩndĩ ngatangĩĩwa kuma kwa amaitha makwa.'),
('kam', '2SA', 22, 5, 'Nũndũ itulumo sya kĩw’ũ nĩsyanthyũlũlũkile; Wingĩ wa maũndũ mate kĩkĩo kya Ngai nĩwambĩkĩie w’ĩa.'),
('kam', '2SA', 22, 6, 'Ndii sya Seoli nĩsyeendingĩlile; Itei sya kĩkw’ũ nĩsyangwatie.'),
('kam', '2SA', 22, 7, 'Thĩnanĩ wakwa nĩnamwĩkaĩlile Yeova; Ĩĩ, nĩnamwĩkaĩlile Ngai wakwa: Na eew’a wasya wakwa e ĩkalũnĩ yake, Na kĩĩo kyakwa kyalika matũnĩ make.'),
('kam', '2SA', 22, 8, 'Nĩvo ĩndĩ nthĩ yathingithangie na kũtetema, Myambĩlĩlyo ya ĩtu yatetema Na yathingithangw’a, nĩkwĩthĩwa aĩ mũthilĩku.'),
('kam', '2SA', 22, 9, 'Syũki yambata kuma manyiũũnĩ make, Na mwaki kuma kanyw’anĩ wake nĩwaminaa: Makaa makanw’a nĩw’o.'),
('kam', '2SA', 22, 10, 'O na akonza matu, na atheea; Na kĩvindu kya ngokomi kyaĩ ungu wa nyaĩĩ syake.'),
('kam', '2SA', 22, 11, 'Na aenda akuĩtwe nĩ mũkeluvi, na aũlũka; Ĩĩ, nĩwonekie nthwaunĩ sya kĩseve.'),
('kam', '2SA', 22, 12, 'Na atw’ĩkĩthya kĩvindu malwanda mamũthyũlũlũkĩte, Kũmbana kwa iw’ũ, mathweo makamu matunĩ.'),
('kam', '2SA', 22, 13, 'Nũndũ wa ũtisu mbee wake Makaa ma mwaki makanw’a.'),
('kam', '2SA', 22, 14, 'Yeova atunduma e ĩtunĩ, Na Ũla Wĩ Ĩũlũ wa Onthe aumya wasya wake.'),
('kam', '2SA', 22, 15, 'Na ekya mĩsyĩ, na amanyaĩĩkya; Atisya ũtisi, na amathokoan’ya.'),
('kam', '2SA', 22, 16, 'Na ĩndĩ mokinyĩlo ma ũkanga moneka, Myambĩlĩlyo ya nthĩ vavuũwa, Nĩ ũkan’yo wa Yeova, Aiveveea mĩthũmũ ya manyiũũ make.'),
('kam', '2SA', 22, 17, 'Atũmana kuma ĩũlũ, ambosa; Anumya iw’ũnĩ nyingĩ;'),
('kam', '2SA', 22, 18, 'Ambonokya kuma kwa mũmaitha wakwa wĩ vinya, Kuma kwa ala mamenaa; nũndũ maĩ na vinya kwĩ nyie.'),
('kam', '2SA', 22, 19, 'Mambithũkĩa mũthenya wa wanangĩko wakwa mũnene; Ĩndĩ Yeova nĩwe wanũnũmĩlye.'),
('kam', '2SA', 22, 20, 'O na anumaalya vandũ vaamu; Ambonokya, nũndũ nĩwatanĩthaw’a ninyie.'),
('kam', '2SA', 22, 21, 'Yeova anduva kwĩanana na ũlũngalu wakwa; Nũndĩvĩte kwĩanana na ũtheu wa moko makwa.'),
('kam', '2SA', 22, 22, 'Nũndũ nĩnĩkwatĩte nzĩa sya Yeova, Na ndyaatia Ngaĩ wakwa ngeka ũthũku.'),
('kam', '2SA', 22, 23, 'Nũndũ motw’ĩo make onthe maĩ mbee wakwa; O na myamũlo yake, ndyaamĩtia.'),
('kam', '2SA', 22, 24, 'O na naĩ mwĩanĩu kwake; Na neesiĩĩa ũthũku wakwa.'),
('kam', '2SA', 22, 25, 'Kwondũ wa ũu Yeova nĩwandĩvie kwĩanana na ũlũngalu wakwa, Kwĩanana na ũtheu wakwa ũla wonaa na metho make.'),
('kam', '2SA', 22, 26, 'Kwa ũla wĩ tei ũkeeyonan’ya wĩ tei; Kwa mũndũ mwĩanĩu ũkeeyon’ya wĩ mwĩanĩu;'),
('kam', '2SA', 22, 27, 'Kwa ũla mũtheu ũkeeyonan’ya wĩ mũtheu; Na kwa ũla mũng’endu ũkonan’ya wĩ na wai.'),
('kam', '2SA', 22, 28, 'Na andũ ala mathĩnaw’a ũkaatangĩĩa; Ĩndĩ metho maku me ĩũlũ wa ala me na mĩng’athĩlĩlyo, nĩ kana ũmatheesye.'),
('kam', '2SA', 22, 29, 'Nũndũ nue taa wakwa, ame Yeova; Na Yeova akamulĩka kĩvindu kyakwa.'),
('kam', '2SA', 22, 30, 'Nũndũ kwondũ waku nĩngũvũthũa nguthu, Kwondũ wa Ngai wakwa nĩngũthaanyũka ũvai.'),
('kam', '2SA', 22, 31, 'Ũndũ wa Ngai, nzĩa yake nĩ mbĩanĩu: Ndeto ya Yeova nĩtatĩtwe; Nake nĩ ngao ya onthe ala mevithaa nthĩnĩ wake.'),
('kam', '2SA', 22, 32, 'Nũndũ Ngai nũũ, ate o Yeova? Na nũũ ũvai, ate o Ngai waitũ?'),
('kam', '2SA', 22, 33, 'Ngai nĩ ngome yakwa yĩ vinya; Na nũtongoesya ala eanĩu nzĩanĩ yake.'),
('kam', '2SA', 22, 34, 'Nũtw’ĩkĩthasya maũũ make ta maũũ ma ndaatai nga, Na nũnũngamasya ĩũlũ wa kũndũ kwakwa kũtũlu.'),
('kam', '2SA', 22, 35, 'Nũmanyĩasya moko makwa kũkita, Kwondũ wa ũu moko makwa makootaa ũta wa ũthuku.'),
('kam', '2SA', 22, 36, 'O na nũnengete ngao ya ũtangĩĩo waku; Na ũuu waku nũnenevetye.'),
('kam', '2SA', 22, 37, 'Nũnenevetye matambya makwa ungu wakwa; Na maũũ makwa matyaatendelũka.'),
('kam', '2SA', 22, 38, 'Nĩnĩkũĩte amaitha makwa, na kũmananga; O na ndyaaĩthyũũa kũvika maminwa.'),
('kam', '2SA', 22, 39, 'Na nĩnĩmaminĩte, na kũmatonya mũkuthũ, na ĩndĩ matitonya kũkĩla: Ĩĩ, nĩmavalũkĩte ungu wa nyaĩĩ syakwa.'),
('kam', '2SA', 22, 40, 'Nũndũ nũmbotoete vinya nũkite kaũ; Nũmekĩtye ĩtheo wakwa ala mambũkĩlĩle.'),
('kam', '2SA', 22, 41, 'O na nũtumĩte amaitha makwa mambon’ya mĩongo, Nĩ kana nĩvete ala mamenaa.'),
('kam', '2SA', 22, 42, 'Masisya, ĩndĩ vatyaĩ wa kũmatangĩĩa; Masisya o Yeova, ĩndĩ ndaamasũngĩa.'),
('kam', '2SA', 22, 43, 'Nĩvo ĩndĩ namakimangie mavinya mũno ta kĩtoo kya nthĩ, Nĩnamakanyangie ta ndaka nzĩanĩ nene, na namanyaĩĩkya kũasa.'),
('kam', '2SA', 22, 44, 'O na nũmbonoketye kuma motetan’yonĩ ma andũ makwa; Nũnzũvĩĩte nĩthĩwe mũtongoi wa i mbaĩ: Ũko wa andũ ũla ndaamanya ũkanthũkũma.'),
('kam', '2SA', 22, 45, 'Andũ ma nthĩ ĩngĩ makeenyivya kwakwa: O yĩla meĩw’a ũvoo wakwa, makambĩw’a.'),
('kam', '2SA', 22, 46, 'Andũ ma nthĩ ĩngĩ makathelekelya, Na makauma mawĩvithonĩ moo makĩtetema.'),
('kam', '2SA', 22, 47, 'Yeova e thayũ; na ĩvia yakwa yĩtaĩwe: Na nanenevw’e Ngai, ĩvia ya ũtangĩĩo wakwa,'),
('kam', '2SA', 22, 48, 'O Ngai ũla ũndĩvanĩsyaa, Na kũtheeasya ngo sya andũ syĩthĩwe ĩtheo wakwa,'),
('kam', '2SA', 22, 49, 'Na ũla ũnumasya kuma kwa amaitha makwa: Ĩĩ, nũmbũkĩlasya ĩũlũ wa ala mambũkĩlĩĩlaa; Nũmbonokasya kwa mũndũ mũng’endu.'),
('kam', '2SA', 22, 50, 'Kwondũ wa ũu ngakũtũngĩa mũvea, ame Yeova, katĩ wa i mbaĩ, Na ngakumya syĩtwa yaku.'),
('kam', '2SA', 22, 51, 'Nũnengae mũsumbĩ wake ũvonokyo mũnene, Na kwonanasya ũseo wĩ wendo kwa mwĩtĩkĩw’a mauta wake, Kwa Ndaviti na ũsyao wake tene na tene.'),
('kam', '2SA', 23, 1, 'Na ĩndĩ ii nĩsyo ndeto sya mũminũkĩlyo sya Ndaviti. Ndaviti mwana wa Yese easya, Na ũ mũndũ ũla wokĩlilw’e ĩũlũ easya, Ũla mwĩtĩkĩw’a mauta wa Ngai wa Yakovo, Na mũtili wa mbathi mũseo wa Isilaeli:'),
('kam', '2SA', 23, 2, 'Veva wa Yeova nĩwaneenie nthĩnĩ wakwa, Na ndeto yake yaĩ ũĩmĩnĩ wakwa.'),
('kam', '2SA', 23, 3, 'Ngai wa Isilaeli aisye, Ũla Ĩvia wa Isilaeli aneenie nakwa atĩĩ: Ũla ũsumbĩkaa andũ na ũlũngalu, Ũla ũsumbĩkaa aimũkĩa Ngai,'),
('kam', '2SA', 23, 4, 'Akeethĩwa ta kyeni kya kĩoko, yĩla syũa yumĩlaa, Kĩoko kũikya, Yĩla nyeki ya vuvĩ yamea nthĩ, Kwondũ wa syũa kwaa mbua yaua.'),
('kam', '2SA', 23, 5, 'Nĩ w’o, nyũmba yakwa ndĩilyĩ ũu na Ngai; Ĩndĩ nũtianĩĩte ũtianĩo nakwa wa tene na tene, Ũseũvĩtw’e maũndũnĩ onthe, na mũlũmu: Nũndũ nĩw’o ũtangĩĩo wakwa w’onthe, na kwenda kwakwa kw’onthe, O na ethĩwa ndeũwĩan’ya mũno.'),
('kam', '2SA', 23, 6, 'Ĩndĩ onthe ala matakĩaa Ngai makeethĩwa ta mĩw’a ya kũlutĩlĩĩlwa kũasa, Nĩkwĩthĩwa matikwatĩka na kwoko;'),
('kam', '2SA', 23, 7, 'Ĩndĩ mũndũ ũla ũmakiitaa Mũvaka eyũmbĩĩe mĩio ya kaũ ya iaa na mũtĩ wa ĩtumo: Na makavĩvw’a vyũ na mwaki me vandũ voo.'),
('kam', '2SA', 23, 8, 'Aa nĩo masyĩtwa ma ngũmbaũ ila Ndaviti waĩ nasyo: Yosevi‐mbasevethi Mũtakemoni, mũnene wa makavuteni; ũsu nĩwe Atino Mwesini, ũla wokitie na maana nyanya ala mooaiwe ĩvinda yĩmwe.'),
('kam', '2SA', 23, 9, 'Na ĩtĩna wake kwaĩ Eleasali mwana wa Ndotai mwana wa Mũaoi, ũmwe wa ila ngũmbaũ itatũ syĩ na Ndaviti, yĩla syamavũthisye Avilisiti ala moombanĩw’e kw’o mokite, na andũ ma Isilaeli maĩ manaenda.'),
('kam', '2SA', 23, 10, 'Ookĩla na akũna Avilisiti mũvaka kw’oko kwake kwanoa, na kw’oko kwake kwalũmana na ũvyũ; na Yeova akĩlya ũkĩlyo mũnene mũthenya ũsu; na andũ masyoka ĩtina wake o mose mũtavo.'),
('kam', '2SA', 23, 11, 'Na ĩtina wake kwaĩ Samama mwana wa Akee Mũalali. Na Avilisiti moombana nguthu, vala vaĩ mũũnda wusũĩte ndengũ; na andũ makũka makĩa Avilisti.'),
('kam', '2SA', 23, 12, 'Ĩndĩ aũngama mũũndanĩ katĩ, na oosesea, na amoaa Avilisiti: na Yeova akĩlya ũkĩlyo mũnene.'),
('kam', '2SA', 23, 13, 'Na atatũ ma ala andũ anene mĩongo ĩtatũ matheea, mavika vala ve Ndaviti ngunganĩ ya Atulamu ĩvinda ya ngetha; na nguthu ya Avilisiti yaĩ ĩnamba maeema mwandanĩ wa Alevai.'),
('kam', '2SA', 23, 14, 'Na ĩvinda yĩu Ndaviti aĩ ngomenĩ yĩ vinya; na asikalĩ ma Avilisiti ĩvinda yĩu maĩ Mbethi‐leemu.'),
('kam', '2SA', 23, 15, 'Na Ndaviti akwatwa nĩ mũng’atũko, na asya, Ame! Kethĩwa mũndũ ũmwe akanenga manzĩ ma ũnyw’a ma kĩthima kya Mbethi‐leemu, kĩla kĩ vakuvĩ na mbingĩlo!'),
('kam', '2SA', 23, 16, 'Na ngũmbaũ isu itatũ syavithũkĩa syavũthũĩla nguthunĩ ya Avilisiti, na syatava manzĩ kĩthimanĩ kya Mbethi‐leemu, kĩla kyaĩ vakuvĩ na mbingĩlo, na syakua, na syamũtwaĩa Ndaviti: ĩndĩ ndaaĩtĩkĩla kũmanyw’a, ĩndĩ etĩa Yeova nthĩ.'),
('kam', '2SA', 23, 17, 'Na asya, Nĩkwĩthĩwe kũasa nakwa, ame Yeova, nĩke ũndũ ũilyĩ ũu: nĩnyw’a nthakame ya andũ ala malekilye mathayũ moo mũisyonĩ? Kwondũ wa ũu ndaaĩthĩkĩla kũmanyw’a. Maũndũ asu nĩmeekiwe nĩ ila ngũmbaũ ĩtatũ.'),
('kam', '2SA', 23, 18, 'Na Avisai, mwana‐a‐inyia wa Yoavu, mwana wa Nzeluia, nĩwe waĩ mũnene katĩ wa asu atatũ. Na nĩwokĩlĩlye andũ maana atatũ ĩtumo na amoaa, na aĩ na syĩtwa katĩ wa asu atatũ.'),
('kam', '2SA', 23, 19, 'Tiwe wataĩawa mũno wa asu atatũ? Kwondũ wa ũu atw’ĩkĩthw’a kavuteni woo: ĩndĩ ala atatũ ma mbee ndaaĩanana nao.'),
('kam', '2SA', 23, 20, 'Na Mbenaia mwana wa Yeoiata, mwana wa mũndũ wĩ ũkũmbaũ wa Kaviseeli, ũla wekĩte meko manene, ooaa ana elĩ ma Alieli wa Moavi: o na atheea na ooaa mũnyambũ wĩ nthĩnĩ wa ĩima ĩvinda kwĩ ĩa.'),
('kam', '2SA', 23, 21, 'Na ooaa Mũmisili, mũndũ mũmbe nesa: na ũ Mũmisili aĩ na ĩtumo kw’okonĩ kwake; ĩndĩ amũtheeea na ndata, na amũvena Mũmisili ĩtumo kw’okonĩ kwake, na amũaa na ĩtumo yake mwene.'),
('kam', '2SA', 23, 22, 'Mbenaia mwana wa Yeoiata nĩwekie maũndũ, asu, na aĩ na syĩtwa katĩ wa ngũmbaũ isu itatũ.'),
('kam', '2SA', 23, 23, 'Ataĩawa mũno kwĩ ala mĩongo ĩtatũ, ĩndĩ ndaaĩanana na ala atatũ ma mbee. Na Ndaviti amwia ethĩwe mũnene wa nguthu ya asũvĩi make.'),
('kam', '2SA', 23, 24, 'Asaeli mwana‐a‐inyia wa Yoavu aĩ ũmwe wa ala mĩongo ĩtatũ; Elianani mwana wa Ndoto wa Mbethi‐leemu,'),
('kam', '2SA', 23, 25, 'na Samama Mũalote, na Elika Mũalote,'),
('kam', '2SA', 23, 26, 'na Elesu Mũvaliti, na Ila mwana wa Ikesi Mũtekoa,'),
('kam', '2SA', 23, 27, 'na Avieseli Mũanathothi, na Mevunai Mũusathi,'),
('kam', '2SA', 23, 28, 'na Nzalimoni Mũaoi, na na Maalai Mũnetovathi,'),
('kam', '2SA', 23, 29, 'na Eelevu mwana wa Mbaana Mũnetovathi, na Itai mwana wa Livae wa ku Ngivea wa ana ma Mbenyamini,'),
('kam', '2SA', 23, 30, 'na Mbenaia Mũvilathoni, na Ititai wa tũlũsĩ twa Ngaasi,'),
('kam', '2SA', 23, 31, 'na Avi‐alivoni Mũalivathi, na Asimavethi Mũmbalumi,'),
('kam', '2SA', 23, 32, 'na Eliava Mũsaalivoni, na ana ma Yaseni, Yonathani,'),
('kam', '2SA', 23, 33, 'na Samama Mũalali, na Aiamu mwana wa Salali Mũalali,'),
('kam', '2SA', 23, 34, 'na Eliveleti mwana wa Aasivai, mwana wa Mũmaaka, na Eliamu mwana wa Aithoveli Mũngilo,'),
('kam', '2SA', 23, 35, 'na Esolo Mũkalimeli, na Vaalai Mũalivi,'),
('kam', '2SA', 23, 36, 'na Ikali mwana wa Nathani wa Sova, na Mbani Mũngati,'),
('kam', '2SA', 23, 37, 'na Nzeleki Mũamimoni, na Naalai Mũmbeelothi, ala makuĩaa Yoavu mwana wa Nzeluia mĩio ya kaũ,'),
('kam', '2SA', 23, 38, 'na Ila Mũithili, na Ngalevu Mũithili,'),
('kam', '2SA', 23, 39, 'na Ulia Mũititi: onthe nĩ mĩongo ĩtatũ na mũonza.'),
('kam', '2SA', 24, 1, 'Na ĩngĩ ũthatu wa Ngai wakanĩa Isilaeli, na atuma Ndaviti ameka naĩ, akyasya, Enda, ũtale Isilaeli na Yuta.'),
('kam', '2SA', 24, 2, 'Na mũsumbĩ amwĩa Yoavu kavuteni wa nguthu, ũla waĩ nake, Enda yu kũũ na kũũ mbaĩnĩ syonthe sya Isilaeli, kuma Ndani kũvika Mbeeli‐sieva, ũtale andũ, nĩ kana nĩmanye ũtalo wa andũ.'),
('kam', '2SA', 24, 3, 'Na Yoavu amwĩa mũsumbĩ, Yu Yeova Ngai waku namongeleele andũ, o ũndũ methĩwa meana, kũndũ ĩana; na metho ma mwĩaĩi wakwa nĩmone ũu: ĩndĩ mwĩaĩi wakwa mũsumbĩ etanĩa ũndũ ũũ nĩkĩ?'),
('kam', '2SA', 24, 4, 'Ĩndĩ o na ũu w’onthe ndeto ya mũsumbĩ yamũkĩlya Yoavu vinya, o na makavuteni ma nguthu. Na Yoavu na makavuteni ma nguthu mauma vala ve mũsumbĩ, matale andũ ma Isilaeli.'),
('kam', '2SA', 24, 5, 'Na mainga Yolotani, na mamba maeema moo Aloeli, ngalĩ ya kw’oko kwa aũme ya ndũa ĩla yĩ mwandanĩ wa Ngati katĩ, na kũvika Yaseli:'),
('kam', '2SA', 24, 6, 'na ĩndĩ mavika Ngileati, na nthĩ ya Tatimu‐otisi; na mavika Ndani‐yaani, na mathyũlũlũka kũvika Sitoni,'),
('kam', '2SA', 24, 7, 'na mavika ngome yĩ vinya ya Tile, na ndũa syonthe sya Aivi, na sya Akanaani; na maumaala maenda ngalĩ ya ĩtheo ya Yuta kũvika Mbeeli‐sieva.'),
('kam', '2SA', 24, 8, 'Na ĩndĩ yĩla maminie kũthi kũũ na kũũ nthĩ yonthe, masyoka Yelusaleme maminĩte myei kenda na mĩthenya mĩongo ĩlĩ.'),
('kam', '2SA', 24, 9, 'Na Yoavu amũnenga mũsumbĩ ũtalo w’onthe wa andũ: na nthĩnĩ wa Isilaeli kwaĩ andũ me ũkũmbaũ ala makũaa ũvyũ ngili maana nyanya; na andũ ma Yuta maĩ ngili maana atano.'),
('kam', '2SA', 24, 10, 'Na ngoo ya Ndaviti yamũthĩn’ya ĩtina wa kũtala andũ. Na Ndaviti amwĩa Yeova, Nĩnĩvĩtĩtye mũno ũndũnĩ ũũ ũla nĩkĩte: ĩndĩ yu, ame Yeova, nĩngũkwĩsũva, veta ũthũku wa mũthũkũmi waku; nũndũ nĩnĩkĩte ũtumanu mũno.'),
('kam', '2SA', 24, 11, 'Na yĩla Ndaviti wokĩlile kĩoko, ndeto ya Yeova yamũkĩa mwathani Ngati, mwoni wa kwa Ndaviti, ĩkĩmwĩa,'),
('kam', '2SA', 24, 12, 'Enda ũneene na Ndaviti, Ũũ nĩw’o Yeova ũnũkwasya, Nĩngũũnenga maũndũ atatũ: nyuva ũmwe wamo, nĩ kana nĩkwĩke w’o.'),
('kam', '2SA', 24, 13, 'Na ĩndĩ Ngati aenda vala ve Ndaviti, na amũtavya, na amũkũlya, Myaka mũonza ya yũa ĩkakũkĩa nthĩ yaku? Kana ũkenda kũkĩa amaitha maku myei ĩtatũ makũatĩĩĩte? Kana kũkeethĩwa mũimũ mĩthenya ĩtatũ nthĩ yaku? Yu kwavindĩĩsya ũsũanĩe ũsũngĩo ũla ngũmũtũngĩa ũla ũndũmie.'),
('kam', '2SA', 24, 14, 'Na Ndaviti amwĩa Ngati, Nĩ mũvivinye mũno: tũvalũke yu kw’okonĩ kwa Yeova; nũndũ matei make nĩ manene; na ndikavalũke kw’okonĩ kwa mũndũ.'),
('kam', '2SA', 24, 15, 'Kwondũ wa ũu Yeova atũma mũimũ ĩũlũ wa Isilaeli kuma kĩoko o kũvika ĩvinda yĩla yatw’ĩtwe; na kwakwie ma andũ kuma Ndani kũvika Mbeeli‐sieva andũ ngili mĩongo mũonza.'),
('kam', '2SA', 24, 16, 'Na yĩla mũlaĩka watambũũkisye kw’oko kwake kwelekela Yelusaleme amyanange, Yeova eealyũla ũndũ wa ũthũku ũsu, na eea mũlaĩka ũla wanangaa andũ, Nũũ; yu siĩĩa kw’oko kwaku. Na mũlaĩka wa Yeova aĩ vakuvĩ na kĩvũĩo kya Alauna Mũyevusi.'),
('kam', '2SA', 24, 17, 'Na Ndaviti aneena na Yeova yĩla wonie mũlaĩka ũla wakũnaa andũ, na asya, Sisya, nĩnĩvĩtĩtye, na nĩnĩkĩte na ngũlũ; ĩndĩ malondu aa, mekĩte ata? Nĩngũkũvoya, kw’oko kwaku nĩkwĩthĩwe ĩũlũ wakwa, na ĩũlũ wa nyũmba ya asa wakwa.'),
('kam', '2SA', 24, 18, 'Na Ngati amũkĩa Ndaviti mũthenya ũsu, na amwĩa, Ambata, ũmwakĩe Yeova kĩthembeo kĩvũĩonĩ kya Alauna Mũyevusi.'),
('kam', '2SA', 24, 19, 'Na Ndaviti ambata kwĩanana na ndeto sya Ngati, o tondũ Yeova weaie.'),
('kam', '2SA', 24, 20, 'Na Alauna asisya, na oona mũsumbĩ na athũkũmi make mokĩte mamwelekele: na Alauna aumaala, na amwĩkunamĩsya mũsumbĩ ũthyũ wake welekele nthĩ.'),
('kam', '2SA', 24, 21, 'Na Alauna amũkũlya, Nũndũ wa kĩ mwĩaĩi wakwa mũsumbĩ woka kwa mũthũkũmi wake? Na Ndaviti asya, Nĩkũthooee kĩvũĩo, nĩmwakĩe Yeova kĩthembeo, nĩ kana ũthĩn’yo ũũ ũsiĩĩwe wumwe andũnĩ.'),
('kam', '2SA', 24, 22, 'Na Alauna amwĩa Ndaviti, Mwĩaĩi wakwa mũsumbĩ nĩose na kũthemba kĩla wĩona kĩ kĩseo: sisya, ng’ombe sya nthembo ya kũvĩvw’a, na ivũi na masoki ma ng’ombe methĩwe ngũ:'),
('kam', '2SA', 24, 23, 'ii syonthe, ame mũsumbĩ, Alauna nũnũũnenga mũsumbĩ. Na Alauna amwĩa mũsumbĩ, Yeova Ngai waku nakwĩtĩkĩle.'),
('kam', '2SA', 24, 24, 'Na mũsumbĩ amwĩa Alauna, Aiee; ĩndĩ nditĩa kũkĩthooa na thooa; o na ndikamũthembea Yeova Ngai wakwa nthembo sya kũvĩvw’a ila ndathooete. Na ĩndĩ Ndaviti athooa kĩvũĩo o na ng’ombe na sekeli mĩongo ĩtano sya vetha.'),
('kam', '2SA', 24, 25, 'Na Ndaviti amwakĩa Yeova kĩthembeo vau, na athemba nthembo sya kũvĩvw’a na nthembo sya mũuo. Na ĩndĩ Yeova eesũvĩka kwondũ wa ĩ nthĩ, na ũthĩn’yo wasiĩĩwa nthĩnĩ wa Isilaeli.'),
('kam', '1KI', 1, 1, 'Na ĩndĩ mũsumbĩ Ndaviti aĩ mũkũu na wa myaka mingĩ; na mamũvw’ĩka ngũa, ĩndĩ ndaaĩw’a muutĩa.'),
('kam', '1KI', 1, 2, 'Kwondũ wa ũu athũkũmi make mamwĩa, Nĩkũmanthwe mwĩĩtu mũtheu kwondũ wa mwĩaĩi wakwa mũsumbĩ: nake aũngamae mbee wa mũsumbĩ na kũmũsũvĩaa; na nakomae kũthũinĩ kyaku, nĩ kana mwĩaĩi wakwa mũsumbĩ eew’ae muutĩa.'),
('kam', '1KI', 1, 3, 'Kwondũ wa ũu mamantha mwĩĩtu mwanake mĩvakanĩ yonthe ya Isilaeli, na moona Avisaki Mũsunami, na mamũetee mũsumbĩ.'),
('kam', '1KI', 1, 4, 'Na mwĩĩtu aĩ mwanake mũno; na amũsũvĩaa mũsumbĩ, na kũmũtethasya; ĩndĩ mũsumbĩ ndaamũmanya.'),
('kam', '1KI', 1, 5, 'Nĩvo ĩndĩ Atoniya mwana wa Akithi wenenevisye, akyasya, Ngeethĩwa mũsumbĩ: na eeyũmbanĩsya makasya na andũ ma ũtũlaa mbalasi, na andũ mĩongo ĩtano ma kũsembaa mbee wake.'),
('kam', '1KI', 1, 6, 'Na ĩthe wake ndaamwĩw’ĩthya woo ĩvinda o na yĩva, akamũkũlya, Wĩkie ũu nĩkĩ? O na ĩngĩ aĩ mũndũ mũmbe nesa; na asyaiwe ĩtina wa Avisalomu.'),
('kam', '1KI', 1, 7, 'Na aneena na Yoavu mwana wa Nzeluia, na mũthembi Aviathali: nao makĩatĩanĩa na Atoniya mamũtetheesye.'),
('kam', '1KI', 1, 8, 'Ĩndĩ mũthembi Nzatoki, na Mbenaia mwana wa Yeoiata, na mwathani Nathani, na Simei, na Lei, o na ngũmbaũ sya Ndaviti, matyaĩ vamwe na Atoniya.'),
('kam', '1KI', 1, 9, 'Na Atoniya ooaĩa malondu na ng’ombe na ila nou vakuvĩ na ĩvia ya Nzoelethi, yĩla yĩ ũtee wa Eni‐lokeli; na ameta ana‐a‐ĩthe make onthe, ana ma mũsumbĩ, na andũ onthe ma Yuta, athũkũmi ma mũsumbĩ:'),
('kam', '1KI', 1, 10, 'ĩndĩ ndaaĩta mwathani Nathani, na Mbenaia, na ila ngũmbaũ, na Solomoni mwana‐a‐ĩthe.'),
('kam', '1KI', 1, 11, 'Nĩvo ĩndĩ Nathani waneenie na Mbathi‐sieva inyia wa Solomoni, akĩmũkũlya, Ndwaaĩw’a kana Atoniya mwana wa Akithi nũnũũsumbĩka, na Ndaviti mwĩaĩi waitũ ndesĩ?'),
('kam', '1KI', 1, 12, 'Na yu kwondũ wa ũu, nĩngũkwĩsũva, eka ngũtae, nĩ kana ũtangĩĩe thayũ waku mwene, na thayũ wa mwana waku Solomoni.'),
('kam', '1KI', 1, 13, 'Enda ũlike vala ve mũsumbĩ Ndaviti, noimwĩa, Mwĩaĩi wakwa, ame mũsumbĩ, ndwaamwĩavĩa mũthũkũmi waku mwĩĩtu, ũkĩmwĩa, Vate ndĩi Solomoni mwana waku akasumbĩka ĩtina wakwa, nake akekala kĩvĩlanĩ kyakwa kya ũsumbĩ? Nũndũ wa kĩ ĩndĩ Atoniya ũnũũsumbĩka?'),
('kam', '1KI', 1, 14, 'Sisya, o yĩla wĩĩthĩwa ũineenea vo na mũsumbĩ, nakwa ngalika ĩtina waku, na kũlũlũmĩlya ndeto syaku.'),
('kam', '1KI', 1, 15, 'Na Mbathi‐sieva alika vala ve mũsumbĩ kasũmbanĩ: na mũsumbĩ aĩ mũkũu mũno; na Avisaki Mũsunami no watetheeasya mũsumbĩ.'),
('kam', '1KI', 1, 16, 'Na Mbathi‐sieva akunama, na eekunamĩsya mũsumbĩ vyũ. Na mũsumbĩ akũlya, Wĩenda kĩ?'),
('kam', '1KI', 1, 17, 'Nake amwĩa, Mwĩaĩi wakwa, nĩwamwĩavĩe mũthũkũmi waku mwĩĩtu na Yeova Ngai waku, ũkyasya, Vate ndĩi Solomoni mwana waku akasumbĩka ĩtina wakwa, na akekala kĩvĩlanĩ kyakwa kya ũsumbĩ.'),
('kam', '1KI', 1, 18, 'Na yu, sisya, Atoniya nũnũũsũmbĩka; naku, mwĩaĩi wakwa mũsumbĩ, ndwĩsĩ:'),
('kam', '1KI', 1, 19, 'na nĩwũaĩte ng’ombe na ila nou na malondu nyingĩ mũno, na nĩwĩtĩte ana onthe ma mũsumbĩ, na mũthembi Aviathali, na Yoavu kavuteni wa nguthu; ĩndĩ ndaamwĩta Solomoni mũthũkũmi waku.'),
('kam', '1KI', 1, 20, 'Naku, mwĩaĩi wakwa mũsumbĩ, metho ma Isilaeli onthe nĩmaũloelelye, nĩ kana ũmatavye ũla ũkekala kĩvĩlanĩ kya ũsumbĩ kya mwĩaĩi wakwa mũsumbĩ ĩtina wake.'),
('kam', '1KI', 1, 21, 'Ethĩwa ti ũu, kũkeethĩwa, yĩla mwĩaĩi wakwa mũsumbĩ ũkakoma na aaĩthe make, nyie na mwana wakwa Solomoni tũkatalwa avĩtan’ya.'),
('kam', '1KI', 1, 22, 'Na, sisya, o akĩneena na mũsumbĩ, mwathani Nathani atonyelela.'),
('kam', '1KI', 1, 23, 'Na matavya mũsumbĩ, makĩmwĩa, Sisya, mwathani Nathani. Na yĩla walikile mbee wa mũsumbĩ, amwĩkunamĩsya mũsumbĩ ũthyũ wake welekele nthĩ.'),
('kam', '1KI', 1, 24, 'Na Nathani amũkũlya, Mwĩaĩi wakwa, ame mũsumbĩ, nũneenete, Atoniya akasumbĩka ĩtina wakwa, na akekala kĩvĩlanĩ kyakwa kya ũsumbĩ?'),
('kam', '1KI', 1, 25, 'Nũndũ nũtheeie ũmũnthĩ, na nĩwũaĩte ng’ombe na ila nou na malondu nyingĩ mũno, na nĩwĩtĩte ana onthe ma mũsumbĩ, na makavuteni ma nguthu, na mũthembi Aviathali; na, sisya, nĩmekũya na kũnyw’a me mbee wake, na kwasya, Mũsumbĩ Atoniya nĩethĩwe thayũ ĩvinda ĩasa.'),
('kam', '1KI', 1, 26, 'Ĩndĩ nyie, o nakwa mũthũkũmi waku, na mũthembi Nzatoki, na Mbenaia mwana wa Yeoiata, na mũthũkũmi waku Solomoni, ndaatwĩta.'),
('kam', '1KI', 1, 27, 'Ũndũ ũsu nĩwĩkĩtwe nĩ mwĩaĩi wakwa mũsumbĩ, na ndwaaon’ya athũkũmi maku ũla waĩle kwĩkala kĩvĩlanĩ kya mwĩaĩi wakwa mũsumbĩ ĩtina wake?'),
('kam', '1KI', 1, 28, 'Nĩvo ĩndĩ mũsumbĩ Ndaviti wasũngĩie na asya, Mwĩte Mbathi‐sieva oke vaa nĩĩ. Na ooka vala ve mũsumbĩ, na aũngama mbee wa mũsumbĩ.'),
('kam', '1KI', 1, 29, 'Na mũsumbĩ eevĩta, na asya, O tondũ Yeova wĩ thayũ, ũla wovoisye thayũ wakwa kuma mathĩnanĩ onthe,'),
('kam', '1KI', 1, 30, 'nĩ w’o, o tondũ nakwĩavĩe na Yeova, Ngai wa Isilaeli, ngĩkwĩa, Vate ndĩi Solomoni mwana waku akasumbĩka ĩtina wakwa, na akekala kĩvĩlanĩ kyakwa kya ũsumbĩ vandũ vakwa; now’o ngwĩka ũmũnthĩ.'),
('kam', '1KI', 1, 31, 'Nĩvo ĩndĩ Mbathi‐sieva wekunamisye ũthyũ wake welekele nthĩ, na amwĩkunamĩsya mũsumbĩ vyũ, na asya, Mwĩaĩi wakwa mũsumbĩ Ndaviti nĩekale thayũ tene na tene.'),
('kam', '1KI', 1, 32, 'Na mũsumbĩ Ndaviti asya, Mete mũthembi Nzatoki, na mwathani Nathani, na Mbenaia mwana wa Yeoiata, moke vaa nĩĩ. Na mooka mbee wa mũsumbĩ.'),
('kam', '1KI', 1, 33, 'Na mũsumbĩ amea, Endai na athũkũmi ma mwĩaĩi wenyu, na mũituma Solomoni mwana wakwa atũla nyũmbũnĩ yakwa mwene, na mũimũtheesya ku Ngioni:'),
('kam', '1KI', 1, 34, 'na mũthembi Nzatoki na mwathanĩ Nathani nĩmamwĩtĩkĩĩsye mauta vo ethĩwe mũsumbĩ wa Isilaeli; na vuvai soo, na mũkyasya, Mũsumbĩ Solomoni ekale thayũ ĩvinda ĩasa.'),
('kam', '1KI', 1, 35, 'Na ĩndĩ mũkambate mũmũatĩĩe, nake akooka na kwĩkala kĩvĩlanĩ kyakwa kya ũsumbĩ; nũndũ akeethĩwa mũsumbĩ vandũ vakwa; na nĩnĩmũtw’ĩte ethĩwe mũnene wĩ mbee ũsumbĩnĩ wa Isilaeli na wa Yuta.'),
('kam', '1KI', 1, 36, 'Na Mbenaia mwana wa Yeoiata amũsũngĩa mũsumbĩ, na asya, Ameni: Yeova, Ngai wa mwĩaĩi wakwa mũsumbĩ, naneene o ũu.'),
('kam', '1KI', 1, 37, 'O tondũ Yeova waĩ na mwĩaĩi wakwa mũsumbĩ, o ta ũu nĩeĩthĩawa na Solomoni, na nakĩtw’ĩkĩthye kĩvĩla kyake kya ũsumbĩ kĩthĩwe kĩnene kwĩ kĩvĩla kya ũsumbĩ kya mwĩaĩi wakwa mũsumbĩ Ndaviti.'),
('kam', '1KI', 1, 38, 'Na ĩndĩ mũthembi Nzatoki, na mwathani Nathani, na Mbenaia mwana wa Yeoiata, na Akelethi, na Avelethi matheea, na matuma Solomoni atũla nyũmbũnĩ ya mũsumbĩ Ndaviti, na mamũete Ngioni.'),
('kam', '1KI', 1, 39, 'Na mũthembi Nzatoki aumya ũvya wa mauta Ĩeemanĩ, na amwĩtĩkĩsya Solomoni mauta. Na mavuva soo; na andũ onthe masya, Mũsumbĩ Solomoni nĩethĩwe thayũ ĩvinda ĩasa.'),
('kam', '1KI', 1, 40, 'Na andũ onthe mambata mamũatĩĩe, na andũ mavuva mĩtũlilũ, na matana na ũtanu mwingĩ, na nthĩ yaalĩlĩkw’a nĩ wasya woo.'),
('kam', '1KI', 1, 41, 'Na Atoniya na aeni onthe ala maĩ nake meew’a ũu o mamina kũya. Na yĩla Yoavu wewie wasya wa soo, akũlya, Kĩlitũko kĩĩ kĩũlitũkan’ya ndũanĩ nĩ kya kĩ?'),
('kam', '1KI', 1, 42, 'Na yĩla waneenaa, sisya, Yonathani mwana wa mũthembi Aviathali ooka: na Atoniya asya, Lika; nĩkwĩthĩwa we wĩ mũndũ mwaĩlu, na nũetete ũvoo mũseo.'),
('kam', '1KI', 1, 43, 'Na Yonathani asũngĩa na amwĩa Atoniya, Nĩ w’o, mwĩaĩi waitũ mũsumbĩ Ndaviti nũmũtw’ĩkĩthisye Solomoni mũsumbĩ:'),
('kam', '1KI', 1, 44, 'na mũsumbĩ nũtũmanĩsye vamwe nake mũthembi Nzatoki, na mwathani Nathani, na Mbenaia mwana wa Yeoiata, na Akelethi, na Avelethi; na nĩmatuma atũla nyũmbũnĩ ya mũsumbĩ;'),
('kam', '1KI', 1, 45, 'na mũthembi Nzatoki na mwathani Nathani nĩmamwĩtĩkĩsye mauta ethĩwe mũsumbĩ ku Ngioni; na nĩmambatie kuma vo makĩtana, mũvaka ndũa yeetĩkĩanĩsya ĩngĩ. Kyu nĩkyo kĩlitũko kĩla mweew’a.'),
('kam', '1KI', 1, 46, 'Na ĩngĩ Solomoni nĩwĩkalĩle kĩvĩla kya ũsumbĩ.'),
('kam', '1KI', 1, 47, 'O na ĩngĩ athũkũmi ma mũsumbĩ mooka mamũathime mwĩaĩi waitũ mũsumbĩ Ndaviti, makyasya, Ngai waku natw’ĩkĩthye syĩtwa ya Solomoni ĩseo kwĩ syĩtwa yaku, na natume kĩvĩla kyake kya ũsumbĩ kĩthĩwa kĩnene kwĩ kĩvĩla kyaku kya ũsumbĩ: na mũsumbĩ eekunamya ũkomonĩ.'),
('kam', '1KI', 1, 48, 'Na ĩngĩ mũsumbĩ asya atĩĩ, Nataĩwe Yeova, Ngai wa Isilaeli, ũla ũnenganĩte mũndũ wa kwĩkala kĩvĩlanĩ kyakwa kya ũsumbĩ ũmũnthĩ, o na metho makwa makyona ũu.'),
('kam', '1KI', 1, 49, 'Na aeni onthe ma Atoniya meew’a w’ĩa, na mookĩla, na mathi kĩla mũndũ na nzĩa yake.'),
('kam', '1KI', 1, 50, 'Na Atoniya eew’a w’ĩa nũndũ wa Solomoni; na ookĩla, na athi, na akwata mbya sya kĩthembeo.'),
('kam', '1KI', 1, 51, 'Na Solomoni eewa, kũkyaw’a, Sisya, Atoniya nũnũũkĩa mũsumbĩ Solomoni; nũndũ, sisya, nũkwete mbya sya kĩthembeo, akyasya, Mũsumbĩ Solomoni nĩambe kũmbĩavĩa kana ndakoaa mũthũkũmi wake na ũvyũ.'),
('kam', '1KI', 1, 52, 'Na Solomoni asya, Ethĩwa akeeyonan’ya kana nĩ mũndũ mwaĩlu, kũtikavalũka ũsw’ĩĩ ũmwe wake nthĩ; ĩndĩ ethĩwa ũthũku ũkooneka nthĩnĩ wake, no wĩkw’a.'),
('kam', '1KI', 1, 53, 'Na ĩndĩ mũsumbĩ Solomoni atũmana, na mamũtheesya kuma kĩthembeonĩ. Na ooka na amwĩkunamĩsya mũsumbĩ Solomoni vyũ; na Solomoni amwĩa, Ĩnũka nyũmba kwaku.'),
('kam', '1KI', 2, 1, 'Na ĩndĩ mĩthenya ya kũkw’a ya Ndaviti yathengeea; nake amwĩaĩa Solomoni mwana wake, akĩmwĩa,'),
('kam', '1KI', 2, 2, 'Nyie nĩngũthi na nzĩa ya nthĩ yonthe: kwondũ wa ũu ĩthĩwa na vinya, nokĩyonan’ya wĩ mũndũ mũũme ki;'),
('kam', '1KI', 2, 3, 'na sũvĩaa wĩaĩo wa Yeova Ngai waku, ũendae nzĩanĩ syake, na kũsũvĩaa myamũlo yake, na mĩao yake, na motw’ĩo make, na mokũsĩ make, kwĩanana na ũla ũandĩkĩtwe mĩaonĩ ya Mose, nĩ kana ũathimĩke maũndũnĩ onthe ala wĩkaa, na o vala ũkelekela;'),
('kam', '1KI', 2, 4, 'nĩ kana Yeova alũlũmĩlye ndeto yake ĩla waneenie ũndũ wakwa, akĩmbĩa, Ethĩwa syana syaku ikasũvĩa mĩendele yasyo, ikinyae mbee wakwa na w’o na ngoo yasyo syonthe na thayũ wasyo w’onthe, ndũkaĩwa nĩ mũndũ kĩvĩlanĩ kya ũsumbĩ kya Isilaeli (aisye ũu).'),
('kam', '1KI', 2, 5, 'Vamwe na ũu nĩwĩsĩ ũndũ Yoavu mwana wa Nzeluia wambĩkie, o ũndũ wamekie makavuteni elĩ ma nguthu sya Isilaeli, o Avineli mwana wa Neli, na Amasa mwana wa Yetheli, ala wamoaie, na etĩkya nthakame ta kwĩ kaũ ĩvinda yĩ mũuo, na eetalĩkangĩlya nthakame ta kwĩ kaũ mũsivinĩ wake ũla weyovete kĩnyunyunĩ kyake, na iatũnĩ syake ila syaĩ maũũnĩ make.'),
('kam', '1KI', 2, 6, 'Kwondũ wa ũu ĩka kwĩanana na ũĩ waku, na ndũkaaeke mũtwe wake wĩ mbũĩ ũtheee Seoli na mũuo.'),
('kam', '1KI', 2, 7, 'Ĩndĩ meke ana ma Mbalisilai Mũngileati nesa, nao methĩawe vamwe na ala maĩsaa mesanĩ yaku; nũndũ o ta ũu nĩmambũkĩe yĩla nakĩĩte Avisalomu mwana‐a‐au.'),
('kam', '1KI', 2, 8, 'Na, sisya, Simei mwana wa Ngela, Mũmbenyamini, wa mũsyĩ wa Mbaulimu e o vamwe naku, ũla wanumanĩe na kĩumo kĩnene mũthenya ũla naendie Maanaimu; ĩndĩ nĩwokie anthaũĩe ũsĩnĩ wa Yolotani, na namwĩavĩa na Yeova, ngĩmwĩa, Ndĩkakũaa na ũvyũ.'),
('kam', '1KI', 2, 9, 'Na yu kwondũ wa ũu ndũkasye nde ĩvĩtyo, nũndũ wĩ mũndũ mũĩ; na ũkamanya ũndũ waĩle kũmwĩka, na ũkatheesya mũtwe wake wĩ mbũĩ wĩ nthakame Seoli.'),
('kam', '1KI', 2, 10, 'Na Ndaviti akoma na aaĩthe make, na athikwa ndũanĩ ya Ndaviti.'),
('kam', '1KI', 2, 11, 'Na mĩthenya ĩla Ndaviti wasumbĩkie Isilaeli nĩ myaka mĩongo ĩna: asumbĩka myaka mũonza Eviloni, na asumbĩka myaka mĩongo ĩtatũ na ĩtatũ Yelusaleme.'),
('kam', '1KI', 2, 12, 'Na Solomoni ekala kĩvĩlanĩ kya ũsumbĩ kya Ndaviti ĩthe wake; na ũsumbĩ wake walũlũmĩla mũno.'),
('kam', '1KI', 2, 13, 'Na ĩndĩ Atoniya mwana wa Akithi athi kwa Mbathi‐sieva inyia wa Solomoni. Na amũkũlya, Waetwe nĩ mũuo? Nake asũngĩa, Nĩ mũuo.'),
('kam', '1KI', 2, 14, 'Na ĩngĩ asya, Nĩ na ũndũ wa kũneena naku. Nake asya, Neena.'),
('kam', '1KI', 2, 15, 'Na asya, Nĩwĩsĩ ũsumbĩ waĩ wakwa, na Isilaeli onthe nĩmambelekelye mothyũ moo, nĩsumbĩke: ĩndĩ ũsumbĩ nũalyũlĩtwe, na nũtw’ĩkĩte wa mwana‐a‐asa wakwa; nũndũ waĩ wake kuma kwa Yeova.'),
('kam', '1KI', 2, 16, 'Na yu nĩngũkwĩtya ũndũ ũmwe; ndũkandeele. Na amwĩa Neena.'),
('kam', '1KI', 2, 17, 'Na asya, Nĩngũkwĩsũva, neena na mũsumbĩ Solomoni (nũndũ ndakakũleela), anenge Avisaki Mũsunami ethĩwe mũka wakwa.'),
('kam', '1KI', 2, 18, 'Na Mbathi‐sieva asya, Nĩ ũseo; nganeena na mũsumbĩ kwondũ waku.'),
('kam', '1KI', 2, 19, 'Kwondũ wa ũu Mbathi‐sieva amũendea mũsumbĩ Solomoni aneene nake kwondũ wa Atoniya. Na mũsumbĩ aũngama akomane nake, na amwĩkunamĩsya, na ekalĩla kĩvĩla kyake kya ũsumbĩ, na atuma kĩvĩla kya ũsumbĩ kiwa kwondũ wa inyia wa mũsumbĩ; nake ekala ngalĩ ya kw’oko kwake kwa aũme.'),
('kam', '1KI', 2, 20, 'Na ĩndĩ asya, Nĩngũkwĩtya ũndũ ũmwe ũnini; ndũkandeele. Na mũsumbĩ amwĩa, Ĩtya, mwaitũ; nũndũ ndikũvata.'),
('kam', '1KI', 2, 21, 'Na asya, Avisaki Mũsunami nanengwe Atoniya mwana‐a‐au ethĩwe mũka wake.'),
('kam', '1KI', 2, 22, 'Na mũsumbĩ Solomoni asũngĩa na amwĩa inyia wake, Na nũndũ wa kĩ ũkwĩtĩsya Atoniya Mũsunami Avisaki? Mwĩtĩsye ũsumbĩ naw’o; nũndũ nĩ mwana‐a‐asa mũkũũ; ĩtya o kwondũ wake, na kwondũ wa mũthembi Aviathali, na kwondũ wa Yoavu mwana wa Nzeluia.'),
('kam', '1KI', 2, 23, 'Nĩvo ĩndĩ mũsumbĩ Solomoni wevĩtie na Yeova, akyasya, Ngai nambĩke ũu, o na mbee, ethĩwa Atoniya ndaneeneete thayũ wake mwene ndeto ĩno.'),
('kam', '1KI', 2, 24, 'Kwondũ wa ũu yu o tondũ Yeova wĩ thayũ, ũla ũnũnũmĩlye, na ũmbĩkalĩtye kĩvĩlanĩ kya ũsumbĩ kya ĩthe wakwa Ndaviti, na ũla ũndw’ĩkĩthĩtye nyũmba, o tondũ wathie, vate ndĩi Atoniya nũkũawa ũmũnthĩ.'),
('kam', '1KI', 2, 25, 'Na mũsũmbĩ Solomoni atũma Mbenaia mwana wa Yeoiata; na amũthũũmũkĩa amũkũna, na akw’a.'),
('kam', '1KI', 2, 26, 'Na mũsumbĩ amwĩa mũthembi Aviathali, Enda Anathothi, mĩũndanĩ yaku mwene; nũndũ nĩwaĩle kũawa: ĩndĩ ĩvinda yĩĩ ndikũaa, nũndũ nĩwakuaa ĩsandũkũ ya Mwĩaĩi Yeova Ndaviti ĩthe wakwa e vo, na nĩkwĩthĩwa nĩwathĩnaw’a ũndũnĩ w’onthe ũla nau wathĩnaw’a naw’o.'),
('kam', '1KI', 2, 27, 'Na ĩndĩ Solomoni amũlũngya Aviathali ndakethĩwe mũthembi wa Yeova, nĩ kana eanĩsye ndeto ya Yeova, ĩla waneenie ũndũ wa nyũmba ya Eli ku Silo.'),
('kam', '1KI', 2, 28, 'Na ũvoo wamũvikĩa Yoavu; nũndũ Yoavu nĩwathũkĩte akaatĩĩa Atoniya, ĩndĩ ndaaathũka aatĩĩe Avisalomu. Na Yoavu akĩĩa Ĩeemanĩ ya Yeova, na akwata mbya sya kĩthembeo.'),
('kam', '1KI', 2, 29, 'Na mũsumbĩ Solomoni atavw’a, Yoavu nũkĩĩe Ĩeemanĩ ya Yeova, na sisya, e vakuvĩ na kĩthembeo. Na ĩndĩ Solomoni atũma Mbenaia mwana wa Yeoiata, akĩmwĩa, Enda ũmũthũũmũkĩe ũmũkũne.'),
('kam', '1KI', 2, 30, 'Na Mbenaia avika Ĩeemanĩ ya Yeova, na amwĩa, Ũũ nĩw’o mũsumbĩ ũnũkwasya, Umaala. Na asya, Aiee; ĩndĩ nĩngw’ĩa vaa. Na Mbenaia amũetee mũsumbĩ ũvoo ĩngĩ, akyasya, Yoavu aneena ũu, na anzũngĩa ũu.'),
('kam', '1KI', 2, 31, 'Na mũsumbĩ amwĩa, Ĩka ũndũ wasya, na ũimũthũũmũkĩa ũmũkũne, noimwĩnzĩa nthĩ; nĩ kana ũvete nthakame kwakwa na nyũmbanĩ ya ĩthe wakwa, ĩla Yoavu wetĩkisye vate kĩtumi.'),
('kam', '1KI', 2, 32, 'Na Yeova akatũnga nthakame yake mũtwenĩ wake mwene, nĩkwĩthĩwa amathũũmũkĩe andũ elĩ maĩ alũngalu na aseo kwĩ we, na amoaa na ũvyũ, na ĩthe wakwa Ndaviti ndaamanya ũu, nao nĩ Avineli mwana wa Neli, kavuteni wa nguthu ya Isilaeli, na Amasa mwana wa Yetheli, kavuteni wa nguthu ya Yuta.'),
('kam', '1KI', 2, 33, 'O ta ũu nthakame yoo ĩkasyoka mũtwenĩ wa Yoavu, na mĩtwenĩ ya ũsyao wake tene na tene: ĩndĩ kwa Ndaviti, na ũsyao wake, na nyũmba yake, na kĩvĩla kyake kya ũsumbĩ, kũkeethĩwa mũuo kuma kwa Yeova tene na tene.'),
('kam', '1KI', 2, 34, 'Na ĩndĩ Mbenaia mwana wa Yeoiata ambata, na amũthũũmũkĩa, na amũaa: na athikwa nyũmbanĩ yake mwene weũnĩ.'),
('kam', '1KI', 2, 35, 'Na mũsumbĩ amwia Mbenaia mwana wa Yeoiata vandũ vake ĩũlũ wa nguthu; na mũsumbĩ aia mũthembi Nzatoki vandũ va Aviathali.'),
('kam', '1KI', 2, 36, 'Na mũsumbĩ atũmana amwĩta Simei, na amwĩa, Ĩyakĩe nyũmba Yelusaleme, noitũa vo, na ndũkaaume vo ũthi o na va.'),
('kam', '1KI', 2, 37, 'Nũndũ mũthenya ũla ũkaumaala, na kũinga ũsĩ wa Kitiloni, manya vyũ nũkakw’a vate ndĩi: nthakame yaku ĩkeethĩwa mũtwenĩ waku mwene.'),
('kam', '1KI', 2, 38, 'Na Simei amwĩa mũsumbĩ, Ndeto ii nĩ nzeo: o ũndũ mwĩaĩi wakwa mũsumbĩ waneena, now’o mũthũkũmi waku wĩĩka. Na Simei atũa Yelũsaleme mĩthenya mingĩ.'),
('kam', '1KI', 2, 39, 'Na kweethĩwa myaka ĩtatũ yathela, athũkũmi elĩ ma Simei meevitha mathi kwa Akisi, mwana wa Maaka, mũsumbĩ wa Ngathi. Na mamũtavya Simei, makĩmwĩa, Sisya, athũkũmi maku me Ngathi.'),
('kam', '1KI', 2, 40, 'Na Simei ookĩla, na atandĩka ĩng’oi yake, na athi Ngathi kwa Akisi, amanthe athũkũmi make; na Simei athi, na aete athũkũmi make kuma Ngathi.'),
('kam', '1KI', 2, 41, 'Na Solomoni atavw’a kana Simei nũnaendie kuma Yelusaleme kũvika Ngathi, na nũnasyokie.'),
('kam', '1KI', 2, 42, 'Na mũsumbĩ atũmana eetya Simei, na amũkũlya, Ndinakwĩavĩthya na Yeova, na ũkũkũsĩĩa, ngĩkwĩa, Manya vyũ, mũthenya ũla ũkaumaala, na kũtambũka o na va, ndũkatĩa kũkw’a? Na wambĩa, Ndeto ii neew’a nĩ nzeo.'),
('kam', '1KI', 2, 43, 'Nũndũ wa kĩ ĩndĩ ndwaasũvĩa wĩvĩto wa Yeova, na mwĩao ũla nakwĩaĩe?'),
('kam', '1KI', 2, 44, 'O na mũsumbĩ amwĩa Simei, Nĩwĩsĩ ũthũku w’onthe ũla ngoo yaku yĩsĩ, ũla wamwĩkie Ndaviti ĩthe wakwa: kwondũ wa ũu Yeova akatũnga ũthũku waku mũtwenĩ waku mwene.'),
('kam', '1KI', 2, 45, 'Ĩndĩ mũsumbĩ Solomoni akaathimwa, na kĩvĩla kya ũsumbĩ kya Ndaviti kĩkalũlũmĩla mbee wa Yeova tene na tene.'),
('kam', '1KI', 2, 46, 'Na ĩndĩ mũsumbĩ amwĩaĩa Mbenaia mwana wa Yeoiata; aumaala, na amũthũũmũkĩa amũkũna, na akw’a. Na ũsumbĩ walũlũmĩla kw’okonĩ kwa Solomoni.'),
('kam', '1KI', 3, 1, 'Na Solomoni atuma ndũũ na Valao mũsumbĩ wa Misili, na atwaa mwĩĩtu wa Valao, na amũete ndũanĩ ya Ndaviti, kũvika amina kwaka nyũmba yake mwene, na nyũmba ya Yeova, na ũvai wa Yelusaleme kũthyũlũlũkya ngalĩ syonthe.'),
('kam', '1KI', 3, 2, 'Ĩndĩ andũ no mathembaa me kũla kũndũ kũtũlu, nĩkwĩthĩwa kũtyaĩ nyũmba mbake kwondũ wa syĩtwa ya Yeova kũvika mĩthenya ĩsu.'),
('kam', '1KI', 3, 3, 'Na Solomoni nĩwamwendete Yeova, o akĩendelaa myamũlonĩ ya Ndaviti ĩthe wake: ate o nĩwathembaa na kũtoeeasya ũvani e kũla kũndũ kũtũlu.'),
('kam', '1KI', 3, 4, 'Na mũsumbĩ aenda Ngiveoni athembee kw’o; nũndũ vo vaĩ vandũ vatũlu vanene: Solomoni nĩwathembee nthembo ngili sya kũvĩvw’a kĩthembeonĩ kyu.'),
('kam', '1KI', 3, 5, 'Ku Ngiveoni Yeova amumĩlĩla Solomoni ndotoni ũtukũ; na Ngai amwĩa, Mbĩtya kĩla ũkwenda ngũnenge.'),
('kam', '1KI', 3, 6, 'Na Solomoni amwĩa, Nũmwonetye mũthũkũmi waku Ndaviti ĩthe wakwa ũseo mwingĩ wĩ wendo, kwĩanana na ũndũ wakinyie mbee waku nthĩnĩ wa w’o, na ũlũngalu, na wĩanĩu wa ngoo e naku; na nĩwamwiĩe ũseo ũũ mũnene wĩ wendo, atĩ nũmũnengete mwana wa kwĩkala kĩvĩlanĩ kyake kya ũsumbĩ, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', '1KI', 3, 7, 'Na yu, ame Yeova Ngai wakwa, nũtw’ĩkĩthĩtye mũthũkũmi waku mũsumbĩ vandũ va Ndaviti ĩthe wakwa: nakwa nĩ o kana kanini; ndyĩsĩ ũndũ numaala kana kũsyoka.'),
('kam', '1KI', 3, 8, 'Na mũthũkũmi waku e katĩ wa andũ maku ala ũnyuvĩte, andũ aingĩ, ala matatalĩka kana kũmanyĩka ũndũ meana nũndũ wa kwingĩva.'),
('kam', '1KI', 3, 9, 'Kwondũ wa ũu nenga mũthũkũmi waku ngoo yĩ ũmanyi wa kũsilan’ya andũ maku, nĩ kana nĩvathũkanasye ũseo na ũthũku; nũndũ nũũ ũtonya kũsilan’ya andũ aa maku maingĩvĩte ũu?'),
('kam', '1KI', 3, 10, 'Na ndeto isu syamwendeesya Mwĩaĩi, nũndũ Solomoni nĩwetya ũndũ ũsu.'),
('kam', '1KI', 3, 11, 'Na Ngai amwĩa, Nĩkwĩthĩwa nĩweetya ũndũ ũsu, na ndũneyĩtĩsya kwĩkala matukũ maingĩ, o na ndũneyĩtĩsya ũthwii, o na ndũnetya mathayũ ma amaitha maku, ĩndĩ nĩweeyĩtĩsya ũmanyi wa kũmanya ũsili wa katĩ;'),
('kam', '1KI', 3, 12, 'sisya, nĩneeka kwĩanana na ndeto yaku: sisya, nĩnakũnenga ngoo yĩ na ũĩ na ũmanyi; o ũndũ kũtaĩ ũngĩ taku mbee waku, o na ĩtina waku kũtikethĩwa ũngĩ taku.'),
('kam', '1KI', 3, 13, 'O na nĩnakũnenga kĩla ũtanetya, ũthwii o na ndaĩa, o ũndũ kũtakethĩwa ũmwe katĩ wa asumbĩ ũilyĩ taku, mĩthenya yaku yonthe.'),
('kam', '1KI', 3, 14, 'Na ethĩwa ũkakinyaa nzĩanĩ syakwa, ũsũvĩae myamũlo yakwa na mĩao yakwa, o tondũ ĩthe waku Ndaviti waendaa, nĩvo ĩndĩ ngaingĩvya mĩthenya yaku.'),
('kam', '1KI', 3, 15, 'Na Solomoni aamũka; na kaĩ, yĩĩ ndoto: na ooka Yelusaleme, na aũngama mbee wa ĩsandũkũ ya ũtianĩo ya Yeova, na athemba nthembo sya kũvĩvw’a, na athemba nthembo sya mũuo, na amavokea athũkũmi make onthe mboka.'),
('kam', '1KI', 3, 16, 'Na ĩndĩ aka elĩ malwaya mamũkĩa mũsumbĩ, na maũngama mbee wake.'),
('kam', '1KI', 3, 17, 'Na mũndũ mũka ũmwe amwĩa, Ame, mwĩaĩi wakwa, nyie na mũndũ mũka ũũ nĩtwĩkalaa nyũmbanĩ ĩmwe; na nasyaa kana nĩ o vamwe nake nyũmbanĩ.'),
('kam', '1KI', 3, 18, 'Na kweethĩwa mĩthenya ĩtatũ ĩtina wa nasyaa, mũndũ mũka ũũ nake asyaa; na twaĩ vamwe; vatyaĩ mũeni vamwe naitũ nyũmbanĩ, ate o ithyĩ elĩ nyũmbanĩ.'),
('kam', '1KI', 3, 19, 'Na kana ka mũndũ mũka ũũ kakw’a ũtukũ, nũndũ nĩwakakomee.'),
('kam', '1KI', 3, 20, 'Na ookĩla ũtukũ katĩ, na oosa kana kakwa ke ũtee wakwa, yĩla mũthũkũmi waku mwĩĩtu eĩkomete, na akaia kĩthũinĩ kyake, na aia kana kake kala kakw’ũ kĩthũinĩ kyakwa.'),
('kam', '1KI', 3, 21, 'Na yĩla nũkĩlile kĩoko nongye kana kakwa, sisya, nĩ kakw’ũ; ĩndĩ yĩla nĩkekuũie kwakya, kaĩ, ti kana kakwa, kala nasyaie.'),
('kam', '1KI', 3, 22, 'Na mũndũ mũka ũla ũngĩ asya, Aiee; ĩndĩ kala ke thayũ nĩ kana kakwa, na kala kakw’ũ nĩ kana kaku. Na ũsu asya Aiee; ĩndĩ kala kakw’ũ nĩ kana kaku, na kala ke thayũ nĩ kana kakwa. Ũu nĩw’o maneenanĩsye mbee wa mũsumbĩ.'),
('kam', '1KI', 3, 23, 'Nĩvo ĩndĩ mũsumbĩ waisye, Ũmwe nũnũkwasya, Kaa nĩ kana kakwa kala ke thayũ, na kana kaku nĩ kala kakw’ũ: na ũla ũngĩ nũnũkwasya, Aiee; ĩndĩ kana kaku nĩ kala kakw’ũ, na kana kakwa nĩ kala ke thayũ.'),
('kam', '1KI', 3, 24, 'Na mũsumbĩ asya, Ndeteei ũvyũ. Na maete ũvyũ vala ve mũsumbĩ.'),
('kam', '1KI', 3, 25, 'Na mũsumbĩ asya, Atũanĩlyai katĩ kana kala ke thayũ, na nengai ũmwe nyunzu, na ũla ũngĩ nyunzu.'),
('kam', '1KI', 3, 26, 'Na ĩndĩ mũndũ mũka ũla kana kake ke thayũ aneena na mũsumbĩ, nũndũ ngoo yake yeew’ĩe kana kake ĩnee, na asya, Ame, mwĩaĩi wakwa, mũnenge kana kala ke thayũ, na ndũkakoae nongi. Ĩndĩ ũla ũngĩ asya, Katikethĩwa kakwa kana kaku; katũanw’e.'),
('kam', '1KI', 3, 27, 'Na ĩndĩ mũsumbĩ asũngĩa asya, Mũnengei kana kala ke thayũ, na mũtikakoae nongi: nĩwe inyia wako.'),
('kam', '1KI', 3, 28, 'Na Isilaeli onthe meew’a sila ũla mũsumbĩ wasilile; na mamũkĩa mũsumbĩ: nũndũ nĩmoonie ũĩ wa Ngai waĩ nthĩnĩ wake, asilae katĩ.'),
('kam', '1KI', 4, 1, 'Na mũsumbĩ Solomoni aĩ mũsumbĩ wa Isilaeli onthe.'),
('kam', '1KI', 4, 2, 'Na aa nĩmo anene me mbee ũsumbĩnĩ ala waĩ nao: Asalia mwana wa mũthembi Nzatoki;'),
('kam', '1KI', 4, 3, 'Eliolevu na Aiya, ana ma Sisa, aandĩki; Yeosavati mwana wa Ailuti, mũandĩki wa maũndũ;'),
('kam', '1KI', 4, 4, 'na Mbenaia mwana wa Yeoiata aĩ mũnene wa nguthu; na Nzatoki na Aviathali maĩ athembi;'),
('kam', '1KI', 4, 5, 'na Asalia mwana wa Nathani aĩ ĩũlũ wa anene; na Nzavuti mwana wa Nathani aĩ mũnene ũsumbĩkinĩ, na mũnyanyae wa mũsumbĩ;'),
('kam', '1KI', 4, 6, 'na Aisali aĩ mũnene wa andũ ma nyũmba; na Atonilamu mwana wa Avata aĩ mũnene wa andũ ala matethethaw’a wĩa wa vinya.'),
('kam', '1KI', 4, 7, 'Na Solomoni aĩ na anene ĩkũmi na elĩ ĩũlũ wa Isilaeli onthe, ala maetae lĩu wa mũsumbĩ na andũ ma nyũmba yake: kĩla mũndũ aetae lĩu wa mwei ũmwe katĩ wa mwaka.'),
('kam', '1KI', 4, 8, 'Na aa nĩmo masyĩtwa moo: Mbeni‐uulu wa nthĩ yĩ iĩma ya Evalaimu;'),
('kam', '1KI', 4, 9, 'na Mbeni‐ndekeli wa ku Makasi, na Saalivimu, na Mbethi‐semesi, na Elonimbethi‐aanani;'),
('kam', '1KI', 4, 10, 'na Mbeni‐eseti, ku Aluvothi (Soko yaĩ yake na nthĩ yonthe ya Eeveili);'),
('kam', '1KI', 4, 11, 'na Mbeni‐avinatavu ku ũtũlunĩ w’onthe wa Ndoli (nake atwaĩte Tavathi mwĩĩtu wa Solomoni);'),
('kam', '1KI', 4, 12, 'na Mbaana mwana wa Ailuti, ku Taanaki na Mekito, na Mbethi‐seani yonthe ĩla yĩ ũtee wa Nzalethani, ĩtheo wa Yesileeli, kuma Mbethi‐seani kũvika Aveli‐meola, o kũvĩtĩla Yokimeamu;'),
('kam', '1KI', 4, 13, 'na Mbeningeveli, ku Lamothi‐ngileati (tũtũla twa Yaili mwana wa Manase, tũla twĩ Ngileati twaĩ twake; o na nthĩ ya Alikovu yaĩ yake, ĩla yĩ Mbasani, yĩ ndũa nene mĩongo thanthatũ syĩ na maũvai na ivingi sya ũthuku);'),
('kam', '1KI', 4, 14, 'na Ainatavu mwana wa Ito, ku Maanaimu;'),
('kam', '1KI', 4, 15, 'na Aimaasi, ku Navitali (nake nĩwatwaie Mbasemathi mwĩĩtu wa Solomoni);'),
('kam', '1KI', 4, 16, 'na Mbaana mwana wa Usiai, ku Aseli na Mbealothi;'),
('kam', '1KI', 4, 17, 'na Yeosavati mwana wa Valua, ku Isakali;'),
('kam', '1KI', 4, 18, 'na Simei mwana wa Ela, ku Mbenyamini;'),
('kam', '1KI', 4, 19, 'na Ngeveli mwana wa Uli, ku nthĩ ya Ngileati, o nthĩ ya Sioni mũsumbĩ wa Aamoli na ya Oku mũsumbĩ wa Mbasani; nake aĩ mũnene e weka ũla waĩ nthĩ ĩsu.'),
('kam', '1KI', 4, 20, 'Yuta na Isilaeli maĩ aingĩ o ta kĩthangathĩ kĩla kĩ ũtee wa ũkanga kwingĩva, makĩĩsaa na kũnyusaa na kũtanaa.'),
('kam', '1KI', 4, 21, 'Na Solomoni asumbĩkĩte mosumbĩ onthe kuma ũla Ũsĩ kũvika nthĩ ya Avilisiti, na kũvika mũvakanĩ wa Misili: maetae mũvothi na mamũthũkũmaa Solomoni mĩthenya yonthe ya thayũ wake.'),
('kam', '1KI', 4, 22, 'Na lĩu wa Solomoni wa mũthenya ũmwe waĩ ithimi mĩongo ĩtatũ sya mũtu mũvinyu, na ithimi mĩongo thanthatũ sya mũtu ũte mũvinyu,'),
('kam', '1KI', 4, 23, 'na ng’ombe nou ĩkũmi, na ng’ombe mĩongo ĩlĩ kuma isesinĩ, na malondu ĩana, vamwe na ndaatai nzamba, na ilong’a, na nthwaia nga, na ngũkũ nou.'),
('kam', '1KI', 4, 24, 'Nũndũ nĩwasumbĩkĩte nthĩ yonthe yĩ mũingo ũũ wa ũla Ũsĩ, kuma Tivisa o na kũvika Ngasa, o na asumbĩ onthe ala maĩ mũingo ũũ wa ũla Ũsĩ: na aĩ na mũuo ngalĩ syonthe ila syamũthyũlũlũkĩte.'),
('kam', '1KI', 4, 25, 'Na Yuta na Isilaeli mekalaa vate mũisyo, kĩla mũndũ ĩtina wa mũsavivũ wake na ĩtina wa mũkũyũ wake, kuma Ndani kũvika Mbeeli‐sieva, mĩthenya yonthe ya Solomoni.'),
('kam', '1KI', 4, 26, 'Na Solomoni aĩ na itũũ ngili mĩongo ĩna sya mbalasi kwondũ wa makasya make, na andũ ngili ĩkũmi na ilĩ ala matũlaa mbalasi.'),
('kam', '1KI', 4, 27, 'Na anene asu maetae, kĩla mũndũ mwei wake, lĩu wa mũsumbĩ Solomoni, na wa onthe ala maĩsaa mesanĩ ya mũsũmbĩ Solomoni; matyaaeka kĩndũ kĩoleke.'),
('kam', '1KI', 4, 28, 'Maetae mbaale nayo na ũa vu vala vaĩ anene kwondũ wa mbalasi na mbalasi syĩ maũũ, kĩla mũndũ kwĩanana na wĩaĩo wake.'),
('kam', '1KI', 4, 29, 'Na Ngai amũnenga Solomoni ũĩ na ũmanyi mwingĩ mũno, na ngoo mbaamu, o ta kĩthangathĩ kĩ ũtee wa ũkanga.'),
('kam', '1KI', 4, 30, 'Na ũĩ wa Solomoni wavĩtũkĩte ũĩ wa ana onthe ma wumilonĩ wa syũa, na ũĩ w’onthe wa Misili.'),
('kam', '1KI', 4, 31, 'Nũndũ aĩ mũĩ kwĩ andũ onthe; kwĩ Ethani Mũesalai, na Emani, na Kalikoli, na Ndalita, ana ma Maoli: na nguma yake yavikĩa mbaĩ syonthe ila syaĩ ngalĩ syonthe.'),
('kam', '1KI', 4, 32, 'Na aneena nthimo ngili itatũ; na mbathi syake syaĩ ngili na itano.'),
('kam', '1KI', 4, 33, 'Na aneena ũvoo wa mĩtĩ, kuma mũkũũ ũla wĩ Levanoni kũvika ĩsovo yĩla yĩmeaa ũvainĩ: o na aneena ũvoo wa nyamũ, na nyũnyi, na tũsamũ tũla tũtambũkaa, na makũyũ.'),
('kam', '1KI', 4, 34, 'Na andũ ma mbaĩ syonthe mooka mew’e ũĩ wa Solomoni, kuma kwa asumbĩ onthe ma nthĩ, ala meew’ĩte ũvoo wa ũĩ wake.'),
('kam', '1KI', 5, 1, 'Na Ilamu mũsumbĩ wa Tile atũma athũkũmi make kwa Solomoni; nũndũ nĩwew’ĩte kana nĩmamwĩtĩkĩsye mauta ethĩwe mũsumbĩ vandũ va ĩthe wake: nũndũ Ilamu nĩwamwendete Ndaviti kuma tene.'),
('kam', '1KI', 5, 2, 'Na Solomoni atũmana kwa Ilamu, akĩmwĩa,'),
('kam', '1KI', 5, 3, 'Nĩwĩsĩ Ndaviti ĩthe wakwa ndaatonya kwaka nyũmba kwondũ wa syĩtwa ya Yeova Ngai wake nũndũ wa makaũ ala mamũthyũlũlũkĩte ngalĩ syonthe, kũvika Yeova amaia ungu wa nyaĩĩ syake.'),
('kam', '1KI', 5, 4, 'Ĩndĩ yu Yeova Ngai wakwa nũnthũmũĩtye ngalĩ syonthe; vati nthũ, kana ũndũ ũthũku wĩkĩkaa.'),
('kam', '1KI', 5, 5, 'Na, sisya, nĩngũsũanĩa kwaka nyũmba kwondũ wa syĩtwa ya Yeova Ngai wakwa, o tondũ Yeova waneenie na Ndaviti ĩthe wakwa, akĩmwĩa, Mwana waku ũla ngekalya kĩvĩlanĩ kyaku kya ũsumbĩ vandũ vaku, nĩwe ũkaka ĩ nyũmba kwondũ wa syĩtwa yakwa.'),
('kam', '1KI', 5, 6, 'Yu ĩndĩ umya mwĩao mandemee mĩtĩ ya mĩkũũ ku Levanoni; na athũkũmi makwa makeethĩwa vamwe na athũkũmi maku; na ngakũĩva kwondũ wa athũkũmi maku kwĩanana na w’onthe ũla ũkaneena: nũndũ nĩwĩsĩ vati ũmwe katĩ waitũ ũla wĩsĩ kũtema mĩtĩ ta Asitoni.'),
('kam', '1KI', 5, 7, 'Na kweethĩwa, yĩla Ilamu wewie ndeto sya Solomoni, atana mũno, na asya, Yeova nataĩwe ũmũnthĩ, ũla ũmũnengete Ndaviti mwana mũĩ asumbĩke andũ aa aingĩ.'),
('kam', '1KI', 5, 8, 'Na Ilamu atũmana kwa Solomoni, akĩmwĩa, Nĩnĩw’ĩte ũvoo ũla wandũmĩe: ngeeka kwenda kwaku kw’onthe kwondũ wa mĩtĩ ya mĩkũũ, na kwondũ wa mĩtĩ ya mĩsonovali.'),
('kam', '1KI', 5, 9, 'Athũkũmi makwa makamĩete kuma Levanoni kũvika ũkanganĩ; na ngamyovan’ya vamwe ĩthambĩĩle ũkanganĩ vandũ vala wĩmbatha, na ngamĩthaĩsya vo, naku ũkamyosa; na wĩĩanĩsya kwenda kwakwa, ũkĩnengane lĩu wa andũ ma nyũmba yakwa.'),
('kam', '1KI', 5, 10, 'Na ĩndĩ Ilamu amũnenga Solomoni mĩtĩ ya mĩkũũ na mĩtĩ ya mĩsonovali o kwĩanana na kwenda kwake kw’onthe.'),
('kam', '1KI', 5, 11, 'Na Solomoni anenga Ilamu ithimi ngili mĩongo ĩlĩ sya nganũ kwondũ wa lĩu wa andũ ma nyũmba yake, na ithimi mĩongo ĩlĩ sya mauta matheu: ũu nĩw’o Solomoni wanengae Ilamu kĩla mwaka.'),
('kam', '1KI', 5, 12, 'Na Yeova anenga Solomoni ũĩ, o tondũ wamwathie; na kwaĩ mũuo katĩ wa Ilamu na Solomoni; na asu elĩ nĩmaseũvĩtye wĩw’ano vamwe.'),
('kam', '1KI', 5, 13, 'Na mũsumbĩ Solomoni aumya kwa Isilaeli onthe andũ ma kũtethethw’a wĩa; na ala maumĩthiw’e maĩ andũ ngili mĩongo ĩtatũ.'),
('kam', '1KI', 5, 14, 'Na amatũmaa Levanoni, ngili ĩkũmi kĩla mwei nguthu; mekalaa Levanoni mwei ũmwe, na myei ĩlĩ mũsyĩ; na Atonilamu aĩ mũnene wa andũ ala matethethaw’a wĩa na vinya.'),
('kam', '1KI', 5, 15, 'Na Solomoni aĩ na ngili mĩongo mũonza ala makuaa mĩio, na ngili mĩongo nyanya ala masũvĩasya iĩmanĩ;'),
('kam', '1KI', 5, 16, 'eka anene ma kwa Solomoni ala maĩ aũngamĩi ma wĩa, ngili itatũ na maana atatũ, ala masumbĩkie andũ ala matethasya wĩa.'),
('kam', '1KI', 5, 17, 'Na mũsumbĩ eeaa, na maalya mavia manene, mavia ma thooa mũnene, makwatye wambĩlĩlyo wa nyũmba na mavia masũvye.'),
('kam', '1KI', 5, 18, 'Na aki ma Solomoni na aki ma Ilamu na Angevali mamasũvya, na maseũvya mĩtĩ na mavia nĩ kana make ĩ nyũmba.'),
('kam', '1KI', 6, 1, 'Na kweethĩwa mwaka wa maana ana na mĩongo nyanya ĩtina wa ana ma Isilaeli mauma nthĩ ya Misili, mwaka wa kana wa Solomoni kũsumbĩka Isilaeli, mwei wa Nzivi, naw’o nĩ mwei wa kelĩ, ambĩlĩlya kwaka nyũmba ya Yeova.'),
('kam', '1KI', 6, 2, 'Na nyũmba ĩla mũsumbĩ Solomoni wamwakĩe Yeova, ũasa wayo waĩ mĩkono mĩongo thanthatũ, na ũthanthau wayo mĩkono mĩongo ĩlĩ, na ũtũlu wayo mĩkono mĩongo ĩtatũ.'),
('kam', '1KI', 6, 3, 'Na valasya wa ĩkalũ ya nyũmba, ũasa waw’o waĩ mĩkono mĩongo ĩlĩ kwĩanana na ũthanthau wa nyũmba; na ũthanthau waw’o kuma ĩ nyũmba waĩ mĩkono ĩkũmi.'),
('kam', '1KI', 6, 4, 'Na eekĩa ĩ nyũmba mbũthi sya kũete kyeni syĩ tũmĩtĩ tũkelangan’ye.'),
('kam', '1KI', 6, 5, 'Na kũkwatan’ya na wako wa nyũmba aakĩĩa tũsũmba twilĩanĩlw’e tũthyũlũlũkĩte, tũkwatene na mawako ma nyũmba ngalĩ syonthe, o ma ĩkalũ na ma vandũ va Ngai va ũneenea; na aaka tũsũmba tũkwatanĩlw’e ũtee tũthyũlũlũkĩte.'),
('kam', '1KI', 6, 6, 'Ũthanthau wa kasũmba kala ke ĩtheo waĩ mĩkono ĩtano, na kala ka katĩ ũthanthau wako waĩ mĩkono thanthatũ, na kala ka katatũ ũthanthau wako waĩ mĩkono mũonza; nũndũ ngalĩ ya ũtee nĩwakie maũwengo ma wako wa nyũmba ngalĩ syonthe, nĩ kana mĩamba ndĩkakwatanw’e na mawako ma nyũmba.'),
('kam', '1KI', 6, 7, 'Na ĩ nyũmba, ĩkyakwa, yaakwa na mavia ala masũvĩw’e vala menzawa; na kũtyaaĩw’ĩka kĩiva kana ĩthoka kana kĩndũ kya kĩaa o na kĩva ĩ nyũmba ĩkyakwa.'),
('kam', '1KI', 6, 8, 'Mũomo wa tũsũmba tũkwatanĩlw’e ũtee twa katĩ waĩ ngalĩ ya kw’oko kwa aũme kwa nyũmba: na mambataa tũsũmbanĩ twa katĩ na mbasya yĩmilĩĩle, na kuma tũla twa katĩ kũvika tũla twa katatũ.'),
('kam', '1KI', 6, 9, 'Ũu nĩw’o wakie nyũmba, na amĩmina; na aĩĩa nyũmba na mĩamba na mbwaũ sya mĩkũũ.'),
('kam', '1KI', 6, 10, 'Na aaka tũla tũsũmba twilĩanĩlw’e tũkwatene na nyũmba yonthe, kĩla kamwe ka ũtũlu wa mĩkono ĩtano: na tũtinĩanĩw’e na nyũmba na mĩtĩ ya mĩkũũ.'),
('kam', '1KI', 6, 11, 'Na ndeto ya Yeova yamũkĩa Solomoni, ĩkĩmwĩa,'),
('kam', '1KI', 6, 12, 'Ũndũ wa nyũmba ĩno ĩla ũkwaka, ethĩwa ũkaendaa myamũlonĩ yakwa, na kwĩkaa motw’ĩo makwa, na kwataa mĩao yakwa yonthe ũendae nthĩnĩ wayo; nĩvo ĩndĩ nĩlũlũmĩlya ndeto yakwa kwaku, ĩla namũtavisye Ndaviti ĩthe waku.'),
('kam', '1KI', 6, 13, 'Na ngekalaa katĩ wa ana ma Isilaeli, na ndikatia andũ makwa Isilaeli.'),
('kam', '1KI', 6, 14, 'Na ĩndĩ Solomoni aaka nyũmba na amĩmina.'),
('kam', '1KI', 6, 15, 'Na aaka mawako ma nyũmba ngalĩ ya nthĩnĩ na mbwaũ sya mĩkũũ: kuma nyũmba nthĩ kũvika mawakonĩ ũvengeelonĩ, aĩĩa ngalĩ ya nthĩnĩ mbwaũ; na aĩĩa nthĩ nyũmbanĩ nthĩnĩ mbwaũ sya mĩtĩ ya mĩsonovalĩ.'),
('kam', '1KI', 6, 16, 'Na aakĩĩa kasũmba nyũmbanĩ ngalĩ ya ĩtina kuma nthĩ kũvika mawakonĩ ũvengeelonĩ, ũasa wako mĩkono mĩongo ĩlĩ, ka mbwaũ sya mĩkũũ: amyakĩĩa nthĩnĩ, vethĩwe vandũ va Ngai va kũneenea, o vala vandũ vatheu mbee.'),
('kam', '1KI', 6, 17, 'Na ĩ nyũmba, o ĩkalũ yĩla yakwatene na vala vandũ va kũneenea, yaĩ mĩkono mĩongo ĩna ũasa wayo.'),
('kam', '1KI', 6, 18, 'Na nyũmbanĩ nthĩnĩ kwaĩ mbwaũ sya mĩkũũ, mbasũvye mĩkauti na malaa malaũkye: kw’onthe kwaĩ mbwaũ sya mĩkũũ; mavia matyaĩ moneka.'),
('kam', '1KI', 6, 19, 'Na aseũvya vala vandũ va ũneenea katĩ wa nyũmba nthĩnĩ, nĩ kana aie vo ĩsandũkũ ya ũtianĩo ya Yeova.'),
('kam', '1KI', 6, 20, 'Na nthĩnĩ wa vandũ vau va ũneenea vaĩ ũthei ũasa wa vo mĩkono mĩongo ĩlĩ, na ũthanthau mĩkono mĩongo ĩlĩ, na ũtũlu mĩkono mĩongo ĩlĩ; na avavw’ĩka thaavu mũtheu: na avw’ĩka kĩthembeo na mbwaũ sya mĩkũũ.'),
('kam', '1KI', 6, 21, 'Ũu nĩw’o Solomoni wavw’ĩkie nyũmba nthĩnĩ thaavu mũtheu: na atila vandũ vau va ũneenea na mĩnyololo ya thaavu; na avavw’ĩka thaavu.'),
('kam', '1KI', 6, 22, 'Na nyũmba yonthe avw’ĩka thaavu, mũvaka nyũmba yonthe yathela: o na kĩthembeo kyonthe kya vala vandũ va ũneenea akĩvw’ĩka thaavu.'),
('kam', '1KI', 6, 23, 'Na nthĩnĩ wa vala vandũ va ũneenea aseũvya akeluvi elĩ ma mbwaũ sya mĩthata, kĩla ũmwe waĩ na ũasa wa mĩkono ĩkũmi.'),
('kam', '1KI', 6, 24, 'Na ũthwau ũmwe wa mũkeluvi waĩ mĩkono ĩtano, na ũthwau ũngĩ waĩ mĩkono ĩtano: kuma mũthya wa ũthwau ũmwe kũvika mũthya wa ũla ũngĩ kwaĩ mĩkono ĩkũmi.'),
('kam', '1KI', 6, 25, 'Na mũkeluvi ũngĩ waĩ mĩkono ĩkũmi: akeluvi me elĩ maĩ ma kĩthimo kĩmwe na mũmbĩlwe ũmwe.'),
('kam', '1KI', 6, 26, 'Ũtũlu wa mũkeluvi ũmwe waĩ mĩkono ĩkũmi, na now’o wa ũla ũngĩ.'),
('kam', '1KI', 6, 27, 'Na aia ala akeluvi nthĩnĩ wa kasũmba ka nthĩnĩ; na nthwau sya akeluvi syaĩ ndambũũku, ũndũ ũthwau wa ũmwe watinĩte wakonĩ ũmwe, na ũthwau wa mũkeluvi ũla ũngĩ watinĩte wakonĩ ũla ũngĩ; na nthwau syoo syatinanĩe nyũmbanĩ katĩ.'),
('kam', '1KI', 6, 28, 'Na avw’ĩka akeluvi thaavu.'),
('kam', '1KI', 6, 29, 'Na avana mawako onthe ma nyũmba ngalĩ syonthe na ngelekan’yo mbasũvye sya akeluvi, na mĩtende, na malaa malaũkye, nthĩnĩ na nza.'),
('kam', '1KI', 6, 30, 'Na nyũmba nthĩ avw’ĩka thaavu, nthĩnĩ na nza.'),
('kam', '1KI', 6, 31, 'Na vandũ va ũlikĩla vala vandũ va ũneenea aseũvya mĩomo ya mbwaũ sya mĩthata: kĩthaku na mĩtĩ ĩla yĩ ndee sya mĩomo yaminĩte kĩlungu kya katano kya wako.'),
('kam', '1KI', 6, 32, 'Na ĩndĩ atuma mĩomo ĩlĩ ya mbwaũ sya mĩthata; na amĩvanĩa ngelekan’yo mbasũvye sya akeluvi, na mĩtende, na malaa malaũkye, na aivw’ĩka thaavu; na atendesya thaavu ĩũlũ wa akeluvi, na ĩũlũ wa mĩtende.'),
('kam', '1KI', 6, 33, 'Na o ta ũu aseũvĩsya vandũ va ũlikĩla ĩkalũnĩ mĩtĩ yĩ ndee sya mĩomo ya mĩthata, yamina kĩlungu kya kana kya wako;'),
('kam', '1KI', 6, 34, 'na mĩomo ĩlĩ ya mbwaũ sya mĩtĩ ya mĩsonovali: mbwaũ ilĩ sya mũomo ũmwe syaĩ sya kũkũnzwa, na mbwaũ ilĩ sya mũomo ũla ũngĩ syaĩ sya kũkũnzwa.'),
('kam', '1KI', 6, 35, 'Na avana ĩũlũ wayo akeluvi, na mĩtende, na malaa malaũkye; na amĩvw’ĩka thaavu wũmbĩĩwe wĩanene na movano.'),
('kam', '1KI', 6, 36, 'Na aaka nza ya nthĩnĩ na mĩsoa ĩtatũ ya mavia masũvye, na mũsoa wa mĩamba ya mĩkũũ.'),
('kam', '1KI', 6, 37, 'Mwaka wa kana wambĩlĩlyo wa nyũmba ya Yeova wakwatw’a, mwei wa Nzivi.'),
('kam', '1KI', 6, 38, 'Na mwaka wa ĩkũmi na ũmwe, mwei wa Mbuli, naw’o nĩ mwei wa nyanya, nyũmba yathela kũndũ kw’onthe kwayo, na kwĩanana na mwakĩle w’onthe wayo. Na ĩndĩ amyakie myaka mũonza.'),
('kam', '1KI', 7, 1, 'Na Solomoni aakie nyũmba ĩ yake myaka ĩkũmi na ĩtatũ, na amina nyũmba yake yonthe.'),
('kam', '1KI', 7, 2, 'Nũndũ aakie nyũmba ya mũtitũ wa Levanoni; ũasa wayo waĩ mĩkono ĩana, na ũthanthau wayo mĩkono mĩongo ĩtano, na ũtũlu wayo mĩkono mĩongo ĩtatũ, yĩ ĩũlũ wa mĩsoa ĩna ya ituĩ sya mĩkũũ, na mĩamba ya mĩkũũ ĩũlũ wa ituĩ.'),
('kam', '1KI', 7, 3, 'Na ĩũlũ yaĩĩwa mbwaũ sya mĩkũũ ĩũlũ wa ĩ mĩamba mĩongo ĩna na itano, ĩla yaĩ ĩũlũ wa ituĩ; ĩkũmi na itano mũsoanĩ ũmwe.'),
('kam', '1KI', 7, 4, 'Na kwaĩ mĩsoa ĩtatũ ya mĩamba, na mbũthi na mbũthi syelekanĩle mĩsoa ĩtatũ.'),
('kam', '1KI', 7, 5, 'Na mĩomo yonthe na mĩtĩ yĩ ndee syayo yaseũvĩtw’e yĩananĩtw’e na mĩamba: na mbũthi na mbũthi syelekanĩle mĩsoa ĩtatũ.'),
('kam', '1KI', 7, 6, 'Na aseũvya valasya na ituĩ; ũasa waw’o waĩ mĩkono mĩongo ĩtano, na ũthanthau waw’o waĩ mĩkono mĩongo ĩtatũ; na valasya mbee wasyo; na ituĩ na mwalyo wa mũomo mbee wasyo.'),
('kam', '1KI', 7, 7, 'Na aseũvya valasya wa kĩvĩla kya ũsumbĩ vala wĩsilĩlaa, o valasya wa sila: na waĩĩwa mbwaũ sya mĩkũũ kuma nthĩ kũvika ũvengeelonĩ.'),
('kam', '1KI', 7, 8, 'Na nyũmba yake vala wĩĩkala, o nza ĩla ĩngĩ yĩ nthĩnĩ wa valasya, yaseũvĩw’e o wĩa ta ũsu. O na aaka nyũmba ya mwĩĩtu wa Valao (ũla Solomoni watwaĩte ethĩwe mũka wake), yailyĩ valasya o ũsu.'),
('kam', '1KI', 7, 9, 'Isu syonthe syaĩ sya mavia ma thooa mũnene, o mavia masũvye, kwĩanana na kĩthimo, matile na mang’weli, ngalĩ ya nthĩnĩ na ya nza, o kuma wambĩlĩlyo kũvika mavia ala maumĩlangĩte ma ũminĩa, na o ta ũu ngalĩ ya ũtee kũvika nza ĩla nene.'),
('kam', '1KI', 7, 10, 'Na wambĩlĩlyo waĩ wa mavia ma thooa mũnene, o mavia manene mũno, mavia ma mĩkono ĩkũmi, na mavia ma mĩkono nyanya.'),
('kam', '1KI', 7, 11, 'Na ĩũlũ kwaĩ mavia ma thooa mũnene, o mavia masũvye, kwĩanana na kĩthimo, o na mbwaũ sya mĩkũũ.'),
('kam', '1KI', 7, 12, 'Na ĩla nza nene ĩla yathyũlũlũkĩte ngalĩ syonthe yaĩ na mĩsoa ĩtatũ ya mavia masũvye, na mũsoa wa mĩamba ya mĩkũũ; o ta nza ya nthĩnĩ ya nyũmba ya Yeova, na valasya wa ĩ nyũmba.'),
('kam', '1KI', 7, 13, 'Na mũsumbĩ Solomoni atũmana Ilamu aetwe kuma Tile.'),
('kam', '1KI', 7, 14, 'Aĩ mwana wa kĩveti ndiwa kya mbaĩ ya Navitali, na ĩthe wake aĩ mũndũ wa Tile, mũtwii wa ũthuku; na ausũĩtwe nĩ ũĩ na ũmanyi na ũtũĩka, atethasye mawĩa onthe na ũthuku. Na ooka kwa mũsumbĩ Solomoni, na amũtetheesya wĩa wake w’onthe.'),
('kam', '1KI', 7, 15, 'Nũndũ aseũvisye ituĩ ilĩ sya ũthuku, kĩla kĩmwe ũasa wakyo mĩkono ĩkũmi na nyanya: na ũthima na ũlii nĩ mĩkono ĩkũmi na ĩlĩ kũthyũlũlũka kĩla kĩmwe.'),
('kam', '1KI', 7, 16, 'Na aseũvya ngovia ilĩ sya ũthuku ũla matwekethetye, sya kwia mĩthyanĩ ya ituĩ: ũtũlu wa ngovia ĩmwe waĩ mĩkono ĩtano, na ũtũlu wa ngovia ĩla ĩngĩ waĩ mĩkono ĩtano.'),
('kam', '1KI', 7, 17, 'Kwaĩ seng’eng’e waseũvĩtw’e ũvĩlanganĩtw’e, na tũkanda tũvĩnde mũvĩndĩle wa mũnyoo, kwondũ wa ngovia isu ila syaĩ mĩthyanĩ ya ituĩ; mũonza ũndũ wa ngovia ĩmwe, na mũonza ũndũ wa ngovia ĩla ĩngĩ.'),
('kam', '1KI', 7, 18, 'Aseũvisye ituĩ ũu; na kwaĩ mĩsoa ĩlĩ ĩthyũlũlũkĩte ĩũlũ wa seng’eng’e ũmwe, ya kũvw’ĩka ngovia isu ila syaĩ mĩthyanĩ ya ituĩ: na now’o wekie ũndũ wa ngovia ĩla ĩngĩ.'),
('kam', '1KI', 7, 19, 'Na ngovia o isu ila syaĩ mĩthyanĩ ya ituĩ sya valasya syaseũvĩtw’e ta ĩlaa ya lili, sya mĩkono ĩna.'),
('kam', '1KI', 7, 20, 'O na kwaĩ ngovia ĩũlũ wa ila ituĩ ilĩ, vakuvĩ na ũkulumbenĩ ũla wĩ vakuvĩ na seng’eng’e: na makũngũmanga maĩ maana elĩ, me mĩsoa mathyũlũlũkĩte ngovia ĩla ĩngi.'),
('kam', '1KI', 7, 21, 'Na aũngamya ituĩ valasyanĩ wa ĩkalũ: na aũngamya kĩtuĩ kya ngalĩ ya kw’oko kwa aũme, na akĩta syĩtwa yakyo Yakini; na aũngamya kĩtuĩ kya ngalĩ ya kw’oko kwa aka, na akĩta syĩtwa yakyo Mboasi.'),
('kam', '1KI', 7, 22, 'Na mĩthyanĩ ya ituĩ kwaĩ mũseũvĩlye ta wa ĩlaa ya lili: na ĩndĩ wĩa wa ituĩ wathela.'),
('kam', '1KI', 7, 23, 'Na aseũvya ũkanga na syĩndũ ila matwekethetye wa mĩkono ĩkũmi kuma ũengo kũvika ũengonĩ ũla ũngĩ, wa kĩlingĩlĩ ngalĩ syonthe, na ũtũlu waw’o waĩ mĩkono ĩtano; na kũthima na ũlii nĩ mĩkono mĩongo ĩtatũ kũthyũlũlũka ngalĩ syonthe.'),
('kam', '1KI', 7, 24, 'Na ĩtheo wa ũengo waw’o ngalĩ syonthe kwaĩ mĩkauti ĩla yawĩlingĩle, ĩkũmi kwa kĩla mũkono, ĩthyũlũlũkĩte ũkanga ngalĩ syonthe; mĩkauti yaĩ mĩsoa ĩlĩ, yatuanĩw’e naw’o.'),
('kam', '1KI', 7, 25, 'Watũlĩtw’e ĩũlũ wa nzaũ ĩkũmi na ilĩ, itatũ isyaĩtye ngalĩ ya ĩũlũ, na itatũ isyaĩtye ũthũĩlonĩ wa syũa, na itatũ isyaĩtye ngalĩ ya ĩtheo, na itatũ isyaĩtye wumĩlonĩ wa syũa; na ũkanga wailĩĩlwe ĩũlũ wasyo, na itimba syasyo syonthe syeelekele ngalĩ ya nthĩnĩ.'),
('kam', '1KI', 7, 26, 'Na kĩemo kyaw’o kyaĩ ta kĩtaa kya kw’oko; na ũengo waw’o watuĩtwe ta ũengo wa kĩkombe, o ta ĩlaa ya lili: waĩ ũtonya kwĩanĩa ithimi sya vetha ngili ilĩ,'),
('kam', '1KI', 7, 27, 'Na aseũvya matina ĩkũmi ma ũthuku; ũasa wa ĩtina yĩmwe waĩ mĩkono ĩna, na ũthanthau waĩ mĩkono ĩna, na ũtũlu waĩ mĩkono ĩtatũ.'),
('kam', '1KI', 7, 28, 'Na mũseũvĩlye wa matina wailyĩ ũũ: maĩ na mavava; na kwaĩ mavava katĩ wa monyitĩku;'),
('kam', '1KI', 7, 29, 'na mavavanĩ ala maĩ katĩ wa monyitĩku kwaĩ mĩnyambũ, na nzaũ, na akeluvi; na monyitĩkunĩ kwaĩ katulĩ ngalĩ ya ĩũlũ; na ĩtheo wa mĩnyambũ na nzaũ kwaĩ mũseũvĩlye wa tũkanda tũvĩnde tũsũnzũlĩte.'),
('kam', '1KI', 7, 30, 'Na kĩla ĩtina yaĩ na ndĩa inya sya ũthuku, na tũmĩlamba twa ũkwatan’ya ndĩa twa ũthuku; na maũũ ana mayo maĩ na syĩndũ sya ũtw’ĩĩka; ungu wa kĩndũ kya kũthambĩa kwaĩ syĩndũ isu sya kũtw’ĩĩka syaseũviw’e na syĩndũ matwekethetye, syĩ na mũseũvĩlye wa tũmakanda tũvĩnde ũtee wa kĩla kĩmwe.'),
('kam', '1KI', 7, 31, 'Na kanyw’a wakyo nthĩnĩ na ĩũlũ wa ĩla ngovia waĩ mũkono ũmwe: na kanyw’a wakyo waĩ kĩlingĩlĩ ta mũseũvĩlye wa katulĩ, mũkono na nyunzu; o na kanyw’anĩ wakyo kwaĩ movane, na mavava masyo nĩmeanene ngalĩ inya, tĩ kĩlingĩlĩ.'),
('kam', '1KI', 7, 32, 'Na ila ndĩa inya syaĩ ungu wa mavava; na tũmĩlamba twa ndĩa twaĩ ĩtinanĩ: na ũtũlu wa ndĩa waĩ mũkono na nyunzu.'),
('kam', '1KI', 7, 33, 'Na mũseũvĩlye wa ndĩa isu wailyĩ mũseũvĩlye wa ndĩa ya ĩkasya ya kaũ: tũmĩlamba twasyo, na ndĩa, na mĩtĩ ya ndĩa, na matilinge ma ũkwatan’ya mĩtĩ ya ndĩa, syonthe syaseũvĩtw’e na syĩndũ ila matwekethetye.'),
('kam', '1KI', 7, 34, 'Na kwaĩ syĩndũ inya sya ũtw’ĩĩka ikotonĩ inya sya kĩla ĩtina: na syĩndũ isu syatuanĩw’e na ĩtina.'),
('kam', '1KI', 7, 35, 'Na ngalĩ ya ĩũlũ ya ĩtina kwaĩ kĩndũ kya kĩlingĩlĩ ũtũlu wakyo nyunzu ya mũkono; na ngalĩ ya ĩũlũ ya ĩtina ikwatũ syayo na mavava mayo syakwatene nayo.'),
('kam', '1KI', 7, 36, 'Na tũsengeanĩ twa ikwatũ syayo, na mavavanĩ mayo, avana akeluvi, na mĩnyambũ, na mĩtende, kwĩanana na ũthei wa kĩla kĩmwe, vamwe na mũseũvĩlye wa tũmakanda tũvĩnde tũthyũlũlũkĩte.'),
('kam', '1KI', 7, 37, 'Ũũ nĩw’o waseũvisye ala matina ĩkũmi: onthe maĩ ma mũtuĩle ũmwe, na kĩthimi kĩmwe, na wũmbĩle ũmwe.'),
('kam', '1KI', 7, 38, 'Na aseũvya syĩndũ ĩkũmi sya kũthambĩa sya ũthuku: kĩndũ kĩmwe kya kũthambĩa kyaĩ kĩtonya kwĩanĩa ithimi sya vathi mĩongo ĩna; na kĩla kĩndũ kya kũthambĩa kyaĩ kya mĩkono ĩna; na ĩũlũ wa kĩla ĩtina kwaĩ kĩndũ kĩmwe kya ũthambĩa.'),
('kam', '1KI', 7, 39, 'Na aia matina, atano ngalĩ ya kw’oko kwa aũme kwa nyũmba, na atano ngalĩ ya kw’oko kwa aka kwa nyũmba: na aia ũkanga ngalĩ ya kw’oko kwa aũme kwa nyũmba ngalĩ ya wumĩlonĩ wa syũa, kwelekela ngalĩ ya ĩtheo.'),
('kam', '1KI', 7, 40, 'Na Ilamu aseũvya syĩndũ sya ũthambĩa, na mĩko, o na masaani manene. Ũu nĩw’o Ilamu waminie wĩa w’onthe ũla wamũtetheesye mũsumbĩ Solomoni kwondũ wa nyũmba ya Yeova:'),
('kam', '1KI', 7, 41, 'ila ituĩ ilĩ, na ngulumbe ilĩ sya ngovia ila syaĩ mĩthyanĩ ya ituĩ; na ila seng’eng’e ilĩ sya kũvw’ĩka ila ngulumbe ilĩ sya i ngovia ila syaĩ mĩthyanĩ ya ituĩ;'),
('kam', '1KI', 7, 42, 'na makũngũmanga maana ana ũndũ wa ila seng’eng’e ilĩ; mĩsoa ĩlĩ ya makũngũmanga ũndũ wa kĩla seng’eng’e wa kũvw’ĩka ila ngulumbe ilĩ sya i ngovia ila syaĩ ĩũlũ wa ila ituĩ;'),
('kam', '1KI', 7, 43, 'na ala matina ĩkũmi, na ila syĩndũ ĩkũmi sya ũthambĩa syĩ matinanĩ;'),
('kam', '1KI', 7, 44, 'na ũkanga o ũsu ũmwe, na ila nzaĩĩ ĩkũmi na ilĩ syĩ ungu wa ũkanga;'),
('kam', '1KI', 7, 45, 'na mbisũ, na mĩko, na masaani manene: o mĩio ĩsu yonthe ya nyũmba ya Yeova, ĩla Ilamu wamũseũvĩsye mũsumbĩ Solomoni, yai ya ũthuku mũkute.'),
('kam', '1KI', 7, 46, 'Mũsumbĩ amĩtuĩe ũiĩnĩ wa Yolotani, nthĩ yĩ yũmba katĩ wa Sukothi na Nzalethani.'),
('kam', '1KI', 7, 47, 'Na Solomoni atia mĩio yonthe ĩte mĩthime, nĩkwĩthĩwa yaĩ mingĩ mũno: ũito wa ũthuku ndwaĩ ũtonya kũmanyĩka.'),
('kam', '1KI', 7, 48, 'Na Solomoni aseũvya mĩio yonthe ĩla yaĩ nyũmbanĩ ya Yeova: kĩthembeo kya thaavu, na mesa ĩla yaĩ na imũtũ ila syaiĩawa Yeova, ya thaavu;'),
('kam', '1KI', 7, 49, 'na syĩndũ ila syeekĩawa mataa, itano ngalĩ ya kw’oko kwa aũme, na itano ngalĩ ya kw’oko kwa aka, mbee wa vala vandũ va Ngai va ũneenea, sya thaavu mũtheu; na ala malaa, na mataa, na mĩveto, sya thaavu;'),
('kam', '1KI', 7, 50, 'na ikombe, na mĩkasi, na masaani manene, na syĩko, na tũvũngũlyũ twa ũkua makaa, sya thaavu mũtheu; na ikwati, sya mĩomo ya nyũmba ya nthĩnĩ, vala vandũ vatheu mbee, o na sya mĩomo ya nyũmba, ũu nĩ kwasya sya ĩkalũ, sya thaavu.'),
('kam', '1KI', 7, 51, 'Wĩa w’onthe ũla mũsumbĩ Solomoni watethisye wa nyũmba ya Yeova wathelile ũu. Na Solomoni alikya nthĩnĩ syĩndũ ila ĩthe wake Ndaviti wavathĩte syĩthĩwe ntheu, o vetha, na thaavu, na mĩio, na asia kũla kwiawa ũthwii wa nyũmba ya Yeova.'),
('kam', '1KI', 8, 1, 'Nĩvo ĩndĩ Solomoni wombanisye atumĩa ma Isilaeli, na atongoi onthe ma i mbaĩ, anene ma nyũmba sya aaĩthe ma ana ma Isilaeli, vala ve mũsumbĩ Solomoni Yelusaleme, mambatye ĩsandũkũ ya ũtianĩo ya Yeova kumya ndũanĩ ya Ndaviti, nayo nĩ Saioni.'),
('kam', '1KI', 8, 2, 'Na andũ onthe ma Isilaeli moombana kwa mũsumbĩ Solomoni vu mbokanĩ, mwei wa Ethanimu, naw’o nĩ mwei wa mũonza.'),
('kam', '1KI', 8, 3, 'Na atumĩa onthe ma Isilaeli mooka, na athembi moosa ĩsandũkũ.'),
('kam', '1KI', 8, 4, 'Na mambatya ĩsandũkũ ya Yeova, na ĩeema ya kũmbanĩa, na mĩio yonthe mĩtheu ĩla yaĩ Ĩeemanĩ; o ĩsu athembi na Alivai mamyambatya.'),
('kam', '1KI', 8, 5, 'Na mũsumbĩ Solomoni na ũmbano w’onthe wa Isilaeli, ũla woombanĩte kwake, waĩ vamwe nake mbee wa ĩsandũkũ, ũkĩthemba malondu na ng’ombe, ila itaĩ italĩka kana kũtalwa nũndũ wa kwingĩva.'),
('kam', '1KI', 8, 6, 'Na athembi malikya ĩsandũkũ ya ũtianĩo ya Yeova nthĩnĩ vandũ vayo, nthĩnĩ wa vala vandũ va ũneenea va nyũmba, kũvika vala vandũ vatheu mbee, o ungu wa nthwau sya akeluvi.'),
('kam', '1KI', 8, 7, 'Nũndũ akeluvi matambũũkĩtye nthwau syoo ĩũlũ wa vala vandũ va ĩsandũkũ, na akeluvi mayĩvw’ĩkĩte ĩsandũkũ ĩũlũ na mĩtĩ yayo.'),
('kam', '1KI', 8, 8, 'Na ĩ mĩtĩ yaĩ mĩasa ũndũ mĩthya yayo nĩyenekee vala vandũ vatheu vu mbee wa vala vandũ va ũneenea; ĩndĩ ndĩaaoneka ũtee; na nĩvo ĩĩ kũvika ũmũnthĩ.'),
('kam', '1KI', 8, 9, 'Kũtyaĩ kĩndũ ĩsandũkũnĩ ate o ala masengea elĩ ma mavia ala Mose wamekĩĩe ku Olevu, yĩla Yeova watianĩe ũtianĩo na ana ma Isilaeli, yĩla maumie nthĩ ya Misili.'),
('kam', '1KI', 8, 10, 'Na kweethĩwa, yĩla athembi maĩ manauma vala vandũ vatheu, mũumbĩ wausũa nyũmba ya Yeova,'),
('kam', '1KI', 8, 11, 'mũvaka athembi matyaatonya kũũngama mathũkũme nũndũ wa mũumbĩ; nũndũ ũtheu mũtisu wa Yeova wausũĩte nyũmba ya Yeova.'),
('kam', '1KI', 8, 12, 'Nĩvo ĩndĩ Solomoni waneenie, Yeova aĩtye atĩ akekala kĩvindunĩ kya ngokomi.'),
('kam', '1KI', 8, 13, 'Nĩ w’o, nĩngwakĩĩte nyũmba ya kwĩkala, vandũ vaku va kwĩkalaa tene na tene.'),
('kam', '1KI', 8, 14, 'Na mũsumbĩ athyũũa ũthyũ wake, na aathima ũmbano w’onthe wa Isilaeli: na ũmbano w’onthe wa Isilaeli waũngama.'),
('kam', '1KI', 8, 15, 'Na asya, Nataĩwe Yeova, Ngai wa Isilaeli, ũla waneenie na kanyw’a wake na Ndaviti ĩthe wakwa, na nĩwĩanĩĩtye na kw’oko kwake, akyasya,'),
('kam', '1KI', 8, 16, 'Kuma mũthenya ũla naumisye andũ makwa Isilaeli nthĩ ya Misili, ndyaanyuva ndũa o na yĩva mbaĩnĩ syonthe sya Isilaeli nake nyũmba vo, nĩ kana syĩtwa yakwa yĩthĩwe vo; ĩndĩ nĩnĩnyuvĩte Ndaviti ethĩwe mũnene wa andũ makwa Isilaeli.'),
('kam', '1KI', 8, 17, 'Na ĩndĩ kwaĩ ngoonĩ ya ĩthe wakwa Ndaviti kwaka nyũmba kwondũ wa syĩtwa ya Yeova, Ngai wa Isilaeli.'),
('kam', '1KI', 8, 18, 'Ĩndĩ Yeova amwĩa Ndaviti ĩthe wakwa, Nĩkwĩthĩwa kwaĩ ngoonĩ yaku kwaka nyũmba kwondũ wa syĩtwa yakwa, nĩweekie nesa nũndũ kwaĩ ngoonĩ yaku:'),
('kam', '1KI', 8, 19, 'ĩndĩ ndũkaka nyũmba ĩsu; ĩndĩ mwana waku ũla ũkauma kĩnyunyunĩ kyaku, nĩwe ũkaka ĩ nyũmba kwondũ wa syĩtwa yakwa.'),
('kam', '1KI', 8, 20, 'Na Yeova nũlũlũmĩlye ndeto yake ĩla waneenie; nũndũ nyie nĩũngamĩte vandũ va Ndaviti ĩthe wakwa, na nĩnĩkalĩte kĩvĩlanĩ kya ũsumbĩ kya Isilaeli, o tondũ Yeova wathie, na nĩnakĩte nyũmba kwondũ wa syĩtwa ya Yeova, Ngai wa Isilaeli.'),
('kam', '1KI', 8, 21, 'Na nĩvo niĩte vandũ kwondũ wa yĩla ĩsandũkũ, yĩla nthĩnĩ wayo ve ũtianĩo wa Yeova, ũla watianĩe na aaĩthe maitũ, yĩla wamaumisye nthĩ ya Misili.'),
('kam', '1KI', 8, 22, 'Na Solomoni aũngama mbee wa kĩthembeo kya Yeova ũmbano w’onthe wa Isilaeli wene, na atambũũkya moko make melekele ĩtunĩ;'),
('kam', '1KI', 8, 23, 'na asya, Ame Yeova, Ngai wa Isilaeli, vati Ngai taku, ĩũlũ ĩtunĩ, kana ĩtheo nthĩ; ũla wĩanĩasya ũtianĩo na ũseo wĩ wendo kwa athũkũmi maku, ala maendaa mbee waku na ngoo syoo syonthe;'),
('kam', '1KI', 8, 24, 'ũla wĩanĩĩtye kwa mũthũkũmi waku Ndaviti ĩthe wakwa ũndũ wamwathie: ĩĩ, nĩwaneenie na kanyw’a waku, na nĩwĩanĩĩtye na kw’oko kwaku, o tondũ kũilyĩ ũmũnthĩ.'),
('kam', '1KI', 8, 25, 'Yu kwondũ wa ũu, ame Yeova, Ngai wa Isilaeli, ĩanĩsya kwa mũthũkũmi waku Ndaviti ĩthe wakwa ũndũ wamwathie, ũkĩmwĩa, Ndũkaĩwa nĩ mũndũ wa kwĩkalaa kĩvĩlanĩ kya ũsumbĩ kya Isilaeli mbee wakwa, ethĩwa syana syaku no ikasũvĩaa mũendele wasyo, ikinyae mbee wakwa o tondũ we wakinyaa mbee wakwa.'),
('kam', '1KI', 8, 26, 'Yu ĩndĩ, ame Ngai wa Isilaeli, nĩngũkũvoya, ndeto yaku nĩyĩanĩe w’o, ĩla waneenie na mũthũkũmi waku Ndaviti ĩthe wakwa.'),
('kam', '1KI', 8, 27, 'Ĩndĩ nĩ w’o, Ngai akekala kũũ nthĩ? Sisya, ĩtu na ĩtu yĩla yĩ ĩũlũ wa matu yĩtitonya ũkwĩanĩa; nyũmba ĩno ĩla nakĩte ĩtonya ata!'),
('kam', '1KI', 8, 28, 'Ĩndĩ elekela kũvoya kwa mũthũkũmi waku, na kwĩsũvana kwake, ame Yeova Ngai wakwa, wĩthukĩĩsye kĩĩo na kũvoya kũla mũthũkũmi waku ũnũũvoya e mbee waku ũmũnthĩ;'),
('kam', '1KI', 8, 29, 'nĩ kana metho maku methĩwe masalukĩtye melekele nyũmba ĩno ũtukũ na mũthenya, o kwelekela vandũ vala wawetie atĩĩ, Syĩtwa yakwa yĩkeethĩwa vo; wĩthukĩĩsye kũvoya kũla mũthũkũmi waku wĩvoya elekele vandũ vaa.'),
('kam', '1KI', 8, 30, 'Na ĩthukĩĩsye wĩsũvano wa mũthũkũmi waku, na wa andũ maku Isilaeli, yĩla mevoya melekele vandũ vaa: ĩĩ, wĩĩw’a wĩ ĩtunĩ ũtũonĩ waku; na weew’a, wĩekea.'),
('kam', '1KI', 8, 31, 'Ethĩwa mũndũ akavĩtanĩsya mũtũi wake, na akiĩwa kĩavo nĩ kana aavĩthw’e, nake akyũka na kwĩavĩa mbee wa kĩthembeo kyaku nyũmbanĩ ĩno;'),
('kam', '1KI', 8, 32, 'nĩvo ĩndĩ wĩĩthukĩĩsya wĩ ĩtunĩ, wĩke, noisilan’ya athũkũmi maku, ũkĩsilĩla ũla mũthũku, ũete mũendele wake ĩũlũ wa mũtwe wake mwene, na ũimũtalĩla ũlũngalu ũla mũlũngalu, ũmũnenge kwĩanana na ũlũngalu wake.'),
('kam', '1KI', 8, 33, 'Yĩla andũ maku Isilaeli makakũnwa mavalũkw’e nĩ mũmaitha, nĩkwĩthĩwa nĩmakũvĩtanĩsye; ethĩwa makakwĩthyũũĩa ĩngĩ, na kumbũla syĩtwa yaku, na kũvoya na ũkwĩsũvĩa nyũmbanĩ ĩno:'),
('kam', '1KI', 8, 34, 'nĩvo ĩndĩ wĩĩthukĩĩsya wĩ ĩtunĩ, noiekea naĩ ya andũ maku Isilaeli, na kũmatũnga ĩngĩ nthĩ ĩla wanengie aaĩthe moo.'),
('kam', '1KI', 8, 35, 'Yĩla ĩtu ĩvinge, na kũte mbua, nĩkwĩthĩwa nĩmakũvĩtanĩsye; ethĩwa makavoya melekele vandũ vaa, na kumbũla syĩtwa yaku, na kwĩthyũũa kũtia naĩ syoo, yĩla ũkamathĩn’ya:'),
('kam', '1KI', 8, 36, 'nĩvo ĩndĩ wĩĩthukĩĩsya wĩ ĩtunĩ, noiekea naĩ ya athũkũmi maku, na ya andũ maku Isilaeli, yĩla wĩmamanyĩasya nzĩa nzeo ĩla maĩle kũthi nayo; na wĩusya mbua nthĩ yaku, ĩla wamanengie andũ maku yĩthĩwe ũtiĩwa.'),
('kam', '1KI', 8, 37, 'Ethĩwa kũkeethĩwa yũa ĩ nthĩ, ethĩwa kũkeethĩwa mũimũ, ethĩwa kũkeethĩwa wũmanĩlu kana mbuka, ngie kana kĩthesa; ethĩwa mũmaitha woo akamathyũlũlũka amatw’ĩkanĩsye me nthĩ yĩ ndũa syoo; ũthĩn’yo o na wĩva, ũwau o na wĩva ũla ũkethĩwa;'),
('kam', '1KI', 8, 38, 'kũvoya na kwĩsũvana o na kwĩva kũla kũkavoywa nĩ mũndũ o na wĩva, kana nĩ andũ maku onthe Isilaeli, kĩla mũndũ o ũla ũkamanya ũthĩn’yo wa ngoo yake mwene, na akĩtambũũkya moko make melekele nyũmba ĩno:'),
('kam', '1KI', 8, 39, 'nĩvo ĩndĩ wĩĩthukĩĩsya wĩ ĩtunĩ ũtũonĩ waku, noiekea, na kwĩka, na kũmũnenga kĩla mũndũ kwĩanana na mĩendele yake yonthe, ũla wĩsĩ ngoo yake; (nũndũ we, o we wĩ weka, nĩwĩsĩ ngoo sya mbaa‐andũ onthe;)'),
('kam', '1KI', 8, 40, 'nĩ kana maũkĩe mĩthenya yonthe ĩla makekala nthĩ ĩla wamanengie aaĩthe maitũ.'),
('kam', '1KI', 8, 41, 'O na ĩngĩ ũvoo wa mũndũ wa nthĩ ĩngĩ, ũla ũte wa andũ maku Isilaeli, yĩla ũkoka kuma nthĩ yĩ kũasa kwondũ wa syĩtwa yaku'),
('kam', '1KI', 8, 42, '(nũndũ makeew’a ũvoo wa syĩtwa yaku ĩnene, na wa kw’oko kwaku kwĩ vinya, na kw’oko kwaku kũtambũũku); yĩla ũkoka na kũvoya elekele nyũmba ĩno;'),
('kam', '1KI', 8, 43, 'wĩĩthukĩĩsya wĩ ĩtunĩ ũtũonĩ waku, nokĩka kwĩanana na w’onthe ũla mũndũ ũsu wa nthĩ ĩngĩ ũkakwĩtya; nĩ kana ngo syonthe sya andũ ma nthĩ matonye kũmanya syĩtwa yaku, maũkĩe, o tondũ andũ maku Isilaeli mekaa, na nĩ kana matonye kũmanya atĩ nyũmba ĩno ĩla nakĩte nĩyĩtanĩaw’a na syĩtwa yaku.'),
('kam', '1KI', 8, 44, 'Ethĩwa andũ maku makaumaala maende kũkita na mũmaitha woo, na nzĩa o na yĩva ĩla wĩmatũma maende nayo, na makavoya Ngai melekele ĩ ndũa ĩla ũnyuvĩte, na melekele nyũmba ĩno nakĩte kwondũ wa syĩtwa yaku;'),
('kam', '1KI', 8, 45, 'nĩvo ĩndĩ wĩĩthukĩĩsya wĩ ĩtunĩ kũvoya kwoo na kwĩsũvana kwoo, noimaseũvĩasya ũvoo woo.'),
('kam', '1KI', 8, 46, 'Ethĩwa makakũvĩtanĩsya (nũndũ vati mũndũ ũtavĩtasya), na ũkamathatĩa, na kũmanengane kwa mũmaitha, nao makamatwaa me atave nthĩ ya amaitha, yĩ kũasa kana vakuvĩ;'),
('kam', '1KI', 8, 47, 'ethĩwa ĩndĩ me nthĩ ĩsu vala matwaiwe me atave makalilikana, na kwĩthyũũa, na ũkwĩsũva me nthĩ ya asu ala mamatavie makyasya, Nĩtũvĩtĩtye, na nĩtwĩkĩte na ngũlũ nĩtwĩ kĩte ũthũku;'),
('kam', '1KI', 8, 48, 'ethĩwa makakũsyokea na ngoo syoo syonthe na thayũ woo w’onthe me nthĩ ya amaitha moo, ala mamatavie, na makakũvoya melekele nthĩ yoo, ĩla wanengie aaĩthe moo, na ndũa ĩla wanyuvie, na nyũmba ĩla nakĩte kwondũ wa syĩtwa yaku:'),
('kam', '1KI', 8, 49, 'nĩvo ĩndĩ wĩĩthukĩĩsya kũvoya kwoo na kwĩsũvana kwoo wĩ ĩtunĩ ũtũonĩ waku, noimaseũvĩsya ũvoo woo;'),
('kam', '1KI', 8, 50, 'noimaekea andũ maku ala makũvĩtanĩsye, na mavĩtyo moo onthe ala makũvĩtanĩsye; noĩmonea ĩnee kwa ala mamatwaie me atave, nĩ kana nao mamew’ĩe ĩnee'),
('kam', '1KI', 8, 51, '(nũndũ nĩ andũ maku, na ũtiĩwa waku, ala wamaumisye nthĩ ya Misili, kuma ikonĩ ĩnene ya iaa);'),
('kam', '1KI', 8, 52, 'nĩ kana metho maku methĩwe masalukĩlye wĩsũvano wa mũthũkũmi waku, na wĩsũvano wa andũ maku Isilaeli, ũmethukĩĩsye o yĩla makakwĩkaĩla.'),
('kam', '1KI', 8, 53, 'Nũndũ nĩwamavathie kũmaumya ngonĩ syonthe sya andũ ma nthĩ, methĩwe ũtiĩwa waku, o tondũ waneenie na kanyw’a wa Mose mũthũkũmi waku, yĩla wamaumisye aaĩthe maitũ Misili, ame Mwĩaĩi Yeova.'),
('kam', '1KI', 8, 54, 'Na kweethĩwa yĩla Solomoni waminie kũmũvoya Yeova mboya ĩsu yonthe na wĩsũvano, ookĩla kuma mbee wa kĩthembeo kya Yeova, kuma kũtulya ndũnĩ kwake na moko make matambũũkĩte melekele ĩtunĩ.'),
('kam', '1KI', 8, 55, 'Na aũngama na ooathima ũmbano w’onthe wa Isilaeli na wasya mũnene, akyasya,'),
('kam', '1KI', 8, 56, 'Nataĩwe Yeova, ũla ũmathũmũĩtye andũ make Isilaeli, kwĩanana na w’onthe ũla wathie: kũtyaalea kwĩanĩw’a ndeto o na ĩmwe ya watho wake w’onthe mũseo, ũla wathie na kanyw’a wa Mose mũthũkũmi wake.'),
('kam', '1KI', 8, 57, 'Yeova Ngai waitũ nĩethĩwe vamwe naitũ, o tondũ waĩ vamwe na aaĩthe maitũ: ndakaatũeke, kana kũtũtia;'),
('kam', '1KI', 8, 58, 'nĩ kana elekelye ngoo sitũ vala ũĩ, tũendae nzĩanĩ syake syonthe na kũkwataa mĩao yake, na myamũlo yake, na motw’ĩo make, ala wameaĩe aaithe maitũ.'),
('kam', '1KI', 8, 59, 'Na ndeto iĩ syakwa ila namwĩsũva Yeova nasyo, nĩsyĩthĩwe vakuvĩ na Yeova Ngai waitũ mũthenya na ũtukũ, nĩ kana aseũvye ũvoo wa mũthũkũmi wake, na ũvoo wa andũ make Isilaeli, o tondũ kĩla mũthenya wĩan’ya vata;'),
('kam', '1KI', 8, 60, 'nĩ kana ngo syonthe sya andũ ma nthĩ imanye Yeova, kana nĩwe Ngai; vati ũngĩ.'),
('kam', '1KI', 8, 61, 'Kwondũ wa ũu ngoo syenyu nĩsyĩthĩwe mbĩanĩu kwa Yeova Ngai waitũ, mũendae myamũlonĩ yake na kũkwataa mĩao yake, o tondu kũilyĩ ũmũnthĩ.'),
('kam', '1KI', 8, 62, 'Na mũsumbĩ, na Isilaeli onthe vamwe nake, mathemba nthembo vu mbee wa Yeova.'),
('kam', '1KI', 8, 63, 'Na Solomoni athemba nthembo ya nthembo sya mũuo, ila wamũthembee Yeova, ng’ombe ngili mĩongo ĩlĩ na ilĩ, na malondu ngili ĩana na mĩongo ĩlĩ. Ũu nĩw’o mũsumbĩ na ana onthe ma Isilaeli mamĩvathanisye nyũmba ya Yeova yĩthĩwe ntheu.'),
('kam', '1KI', 8, 64, 'Mũthenya o ũsu mũsumbĩ avathan’ya vethĩwe vatheu vu nza katĩ ĩla yaĩ mbee wa nyũmba ya Yeova; nũndũ nĩwathembee vo nthembo ya kũvĩvw’a, na nthembo ya mũtu, na mathunya ma nthembo sya mũuo, nũndũ kĩthembeo kya ũthuku kĩla kyaĩ mbee wa Yeova kyaĩ kĩnini ũndũ kĩtatonya kwĩanĩa nthembo ya kũvĩvw’a, na nthembo ya mũtu, na mathunya ma nthembo sya mũuo.'),
('kam', '1KI', 8, 65, 'Ũu nĩw’o Solomoni wavokie mboka ĩvinda yĩu, na Isilaeli onthe vamwe nake, ũmbano mũnene, kuma ũlikĩlonĩ wa Amathi kũvika kalũsĩ ka Misili, me mbee wa Yeova Ngai waitũ, mĩthenya mũonza na mĩthenya mũonza, o mĩthenya ĩkũmi na ĩna.'),
('kam', '1KI', 8, 66, 'Mũthenya wa nyanya oombũũkya andũ; na mamũtaĩa mũsumbĩ, na mathi maeemanĩ moo me na ũtanu na mũyo ngoonĩ nũndũ wa ũseo w’onthe ũla Yeova ũmwonetye Ndaviti mũthũkũmi wake, na Isilaeli andũ make.'),
('kam', '1KI', 9, 1, 'Na kweethĩwa, yĩla Solomoni waminĩte kwaka nyũmba ya Yeova na nyũmba ya mũsumbĩ, na kwenda kw’onthe kwa Solomoni kũla wendeew’e nĩ kwĩka,'),
('kam', '1KI', 9, 2, 'Yeova amumĩlĩla Solomoni ĩvinda ya kelĩ, o tondũ wamumĩlĩle Ngiveoni.'),
('kam', '1KI', 9, 3, 'Na Yeova amwĩa, Nĩnĩw’ĩte kũvoya kwaku na kwĩsũvana kwaku, kũla wĩsũvanĩte mbee wakwa: nĩnĩvathĩte nyũmba ĩno yĩthĩwe ntheu, ĩla wakĩte, nĩkalye syĩtwa yakwa vo tene na tene; na metho makwa na ngoo yakwa ikeethĩwa vo ĩndĩ yonthe.'),
('kam', '1KI', 9, 4, 'Na ngalĩ ĩ yaku, ethĩwa ũkakinyaa mbee wakwa, o tondũ Ndaviti ĩthe waku wakinyaa, wĩanĩunĩ wa ngoo, na ũlũngalunĩ, wĩke kwĩanana na w’onthe ũla nĩkwĩaĩĩte, na ũkĩsũvĩa myamũlo yakwa na motw’ĩo makwa;'),
('kam', '1KI', 9, 5, 'nĩvo ĩndĩ nĩlũlũmĩlya kĩvĩla kya ũsumbĩ kya ũsumbĩko waku ĩũlũ wa Isilaeli tene na tene, kwĩanana na ũndũ namwathie Ndaviti ĩthe waku, ngĩmwĩa, Ndũkaĩwa nĩ mũndũ kĩvĩlanĩ kya ũsumbĩ kya Isilaeli.'),
('kam', '1KI', 9, 6, 'Ĩndĩ ethĩwa mũkeethyũũa na kũeka kũngatĩĩa, inyw’ĩ kana syana syenyu, na kũeka kũkwata mĩao yakwa na myamũlo yakwa ĩla niĩte mbee wenyu, ĩndĩ mũkĩthi na kũthũkũma ngai ingĩ, na kwithaitha;'),
('kam', '1KI', 9, 7, 'nĩvo ĩndĩ nĩveta Isilaeli nthĩ ĩla nĩmanengete; na nyũmba ĩno ĩla nĩvathĩte yĩthĩwe ntheu kwondũ wa syĩtwa yakwa, ngamĩkya vala ndatonya kũmyona; na Isilaeli makeethĩwa nthimo na ma kũvũthĩĩw’a mbaĩnĩ syonthe.'),
('kam', '1KI', 9, 8, 'O na kau nyũmba ĩno nĩ ndũlu ũu, ĩndĩ kĩla mũndũ wĩvavĩtĩlaa akaseng’a, na akamĩtimba; na makasya, Nĩkĩ Yeova wĩkĩte nthĩ ĩno, na nyũmba ĩno ũu?'),
('kam', '1KI', 9, 9, 'Na makasũngĩa, Nĩkwĩthĩwa nĩmamũtiie Yeova Ngai woo, ũla waumisye aaĩthe moo nthĩ ya Misili, na makwatana na ngai ingĩ, na kwithaitha, na kwithũkũma: kwondũ wa ũu Yeova nũmaetee ũthũku ũũ w’onthe.'),
('kam', '1KI', 9, 10, 'Na kweethĩwa, myaka mĩongo ĩlĩ yathela, ĩla Solomoni wakĩte nyũmba isu syelĩ, nyũmba ya Yeova na nyũmba ya mũsumbĩ'),
('kam', '1KI', 9, 11, '(na ĩndĩ Ilamu mũsumbĩ wa Tile nĩwamũnengete Solomoni mĩtĩ ya mĩkũũ na mĩtĩ ya mĩsonovali, vamwe na thaavu, kwĩanana na kwenda kwake kw’onthe), nĩvo mũsumbĩ Solomoni wamũnengie Ilamu ndũa mĩongo ĩlĩ nthĩ ya Ngalilii.'),
('kam', '1KI', 9, 12, 'Na Ilamu auma Tile asisye ndũa ila Solomoni wamũnengie; na ityaamwendeesya.'),
('kam', '1KI', 9, 13, 'Na asya, Nĩ ndũa myaũ ii ila ũnengete, mwana‐a‐asa? Na asyĩta nthĩ ya Kavuli kũvika ũmũnthĩ.'),
('kam', '1KI', 9, 14, 'Na Ilamu amũtwaĩa mũsumbĩ talendi ĩana na mĩongo ĩlĩ sya thaavu.'),
('kam', '1KI', 9, 15, 'Na ũũ nĩw’o ũvoo wa andũ ma kũtethethw’a wĩa ala mũsumbĩ Solomoni waumisye, ma kwaka nyũmba ya Yeova, na nyũmba yake mwene, o na Milo, na ũvai wa Yelusaleme, na Asoli, na Mekito, na Ngeseli.'),
('kam', '1KI', 9, 16, 'Valao mũsumbĩ wa Misili aĩ anambata, na kũkwata ndũa ya Ngeseli, na akamĩvĩvya na mwaki, na akoaa Akanaani ala matwĩe ndũanĩ ĩsu, na akamĩnenga mwĩĩtu wake, kĩveti kya Solomoni, yĩthĩwe kĩanda kyake.'),
('kam', '1KI', 9, 17, 'Na Solomoni aaka Ngeseli, na Mbethi‐oloni ĩla yĩ ngalĩ ya ĩtheo,'),
('kam', '1KI', 9, 18, 'na Mbaalathi, na Tamali ku weũnĩ, nthĩ ĩsu,'),
('kam', '1KI', 9, 19, 'na ndũa syonthe sya kwia mĩio ila Solomoni waĩ nasyo, na ndũa kwondũ wa makasya make ma kaũ, na ndũa sya andũ make ala matũlaa mbalasi, na kĩla Solomoni wendie kwaka kwondũ wa kwĩtanĩthya kwake Yelusaleme, na Levanoni, na nthĩ yonthe ya ũsumbĩko wake.'),
('kam', '1KI', 9, 20, 'Na ũndũ wa andũ onthe ala matialile ma Aamoli, na Aititi, na Avelisi, na Aivi, na Ayevusi, ala mataĩ ma ana ma Isilaeli;'),
('kam', '1KI', 9, 21, 'syana syoo ila syatialile ĩtina woo nthĩ ĩsu, ila ana ma Isilaeli mataatonya kwimina vyũ, imwe sya isu Solomoni asyumisye sya kũtethethaw’a wĩa wa ũkombo kũvika ũmũnthĩ.'),
('kam', '1KI', 9, 22, 'Ĩndĩ ma ana ma Isilaeli Solomoni ndaamatw’ĩkĩthya ngombo: ĩndĩ asu maĩ andũ ma kaũ, na athũkũmi make, na anene me mbee ũsumbĩnĩ wake, na makavuteni make, na anene ma makasya make ma kaũ na ma andũ make ala matũlaa mbalasi.'),
('kam', '1KI', 9, 23, 'Asu maĩ anene mbee ĩũlũ wa wĩa wa Solomoni, maana atano na mĩongo ĩtano, ala masumbĩkaa andũ ala matethasya wĩa.'),
('kam', '1KI', 9, 24, 'Ĩndĩ mwĩĩtu wa Valao ambata kuma ndũanĩ ya Ndaviti aende nyũmbanĩ yake ĩla Solomoni wamwakĩe: na ĩndĩ aaka Milo.'),
('kam', '1KI', 9, 25, 'Na Solomoni nĩwathembaa nthembo sya kũvĩvw’a na nthembo sya mũuo kĩthembeonĩ kĩla wamwakĩe Yeova katatũ kĩla mwaka, aitoeanĩsya ũvani vamwe nasyo, kĩthembeonĩ kĩla kyaĩ mbee wa Yeova. Aminie ĩla nyũmba ũu.'),
('kam', '1KI', 9, 26, 'Na mũsumbĩ Solomoni aseũvĩsya kĩkundi kya ngalawa ku Esioni‐ngeveli, ĩla yĩ vakuvĩ na Elothi, ngũkanĩ ya Ũkanga Mũtune, nthĩ ya Etomu.'),
('kam', '1KI', 9, 27, 'Na i ngalawanĩ Ilamu atũma athũkũmi make, andũ ma ngalawa ala maĩ na ũmanyi wa ũkanga, vamwe na athũkũmi ma Solomoni.'),
('kam', '1KI', 9, 28, 'Na mavika Ovilu, na maumya kw’o thaavu, talendi maana ana na mĩongo ĩlĩ, na mooete kwa mũsumbĩ Solomoni.'),
('kam', '1KI', 10, 1, 'Na yĩla mũsumbĩ mũndũ mũka wa ku Sieva wewie nguma ya Solomoni ũndũ wa syĩtwa ya Yeova, ooka kũmũtata na mokũlyo me vinya.'),
('kam', '1KI', 10, 2, 'Na ooka Yelusaleme e na ũkondo mũnene mũno, e na ngamĩle ila ikuĩte mĩtĩ ĩla ĩnyungaa nesa, na thaavu mwingĩ mũno, na tũvila twĩ thooa mũnene; na yĩla wavikie kwa Solomoni, aneena nake ũvoo w’onthe ũla waĩ ngoonĩ yake.'),
('kam', '1KI', 10, 3, 'Na Solomoni amũsũngĩa mokũlyo make onthe: vati ũndũ waamwaĩa mũsumbĩ ũla ũtaamũtavya.'),
('kam', '1KI', 10, 4, 'Na yĩla mũsumbĩ mũndũ mũka wa ku Sieva wonie ũĩ w’onthe wa Solomoni, na nyũmba ĩla wakie,'),
('kam', '1KI', 10, 5, 'na lĩu ũla waĩsawa mesanĩ yake, na mwaĩkalo ma athũkũmi make, na ũngamĩi wa athũkũmi make, na ngũa syoo, na anengani make ma mbinyu, na wambatĩlo wake ũla wambataa naw’o nyũmbanĩ ya Yeova; veva wake waaa vinya.'),
('kam', '1KI', 10, 6, 'Na amwĩa mũsumbĩ, Ũvoo ũla neewie nĩ nthĩ yakwa mwene, ũndũ wa meko maku na ũndũ wa ũĩ waku, waĩ wa w’o.'),
('kam', '1KI', 10, 7, 'Ĩndĩ ndyaaĩtĩkila i ndeto, kũvika nĩnooka, na metho makwa nĩmawonete: na, sisya, ndyaatavw’a nyunzu; ũĩ waku na kũathimĩka kwaku nĩkũvĩtũkĩte nguma ĩla neewie.'),
('kam', '1KI', 10, 8, 'Andũ maku nĩ atanu, na athũkũmi aa maku nĩ atanu, ala maũngamaa ĩvinda yonthe mbee waku, na mew’aa ũĩ waku.'),
('kam', '1KI', 10, 9, 'Yeova Ngai waku nataĩwe, ũla wendeew’e nue, akwĩkalye kĩvĩlanĩ kya ũsumbĩ kya Isilaeli: nĩkwĩthĩwa Yeova nĩwendie Isilaeli tene na tene, kwondũ wa ũu akũtw’ĩkĩthya mũsumbĩ, wĩkae ũsili wa katĩ na ũlũngalu.'),
('kam', '1KI', 10, 10, 'Na amũnenga mũsumbĩ talendi ĩana na mĩongo ĩlĩ sya thaavu, na mĩtĩ ĩla ĩnyungaa nesa mingĩ mũno, na tũvila twĩ thooa mũnene: kũtyaaetwe ĩngĩ mĩtĩ ĩla ĩnyungaa nesa yingĩvĩte ta ĩsu ĩla mũsumbĩ mũndũ mũka wa ku Sieva wanengie mũsumbĩ Solomoni.'),
('kam', '1KI', 10, 11, 'O na kĩkundi kya ngalawa sya Ilamu, ila syaetie thaavu kumya nthĩ ya Ovilu, nĩkyaetie kuma Ovilu mĩtĩ ya mĩsandali mingĩ mũno na tũvila twĩ thooa mũnene.'),
('kam', '1KI', 10, 12, 'Na mũsumbĩ aseũvĩthya ituĩ na mĩsandali ĩsu kwondũ wa nyũmba ya Yeova, na kwondũ wa nyũmba ya mũsumbĩ, o na mbeve na inanda sya aini: kũtyaaetwe mĩsandali ĩilyĩ ta ĩsu, o na kũtyaaoneka kũvika ũmũnthĩ.'),
('kam', '1KI', 10, 13, 'Na mũsumbĩ Solomoni anenga mũsumbĩ mũndũ mũka wa ku Sieva kyonthe kĩla wendie, o kĩla wetisye, eka ila Solomoni wamũnengie kuma ũlaunĩ wake wa kĩũsumbĩ. Na ĩndĩ eetulũla na asyoka nthĩ yake mwene, we na athũkũmi make.'),
('kam', '1KI', 10, 14, 'Na ĩndĩ ũito wa thaavu ũla waeteawe Solomoni mwaka ũmwe waĩ talendi maana thanthatũ na mĩongo thanthatũ na thanthatũ sya thaavu,'),
('kam', '1KI', 10, 15, 'eka ũla waeteawe nĩ atandĩthya, na ũtandĩthyo wa athoosya, na wa asumbĩ onthe ma nthĩ ya Alavu, na wa makavana ma ĩ nthĩ.'),
('kam', '1KI', 10, 16, 'Na mũsumbĩ Solomoni aseũvĩthya ngao maana elĩ sya thaavu mũtue; sekeli maana thanthatũ sya thaavu syaĩ sya ngao ĩmwe.'),
('kam', '1KI', 10, 17, 'Na aseũvĩthya tũkalo maana atatũ twa thaavu mũtue; latili itatũ sya thaavu syaĩ sya kakalo kamwe: na mũsumbĩ asia nyũmbanĩ ya mũtitũ wa Levanoni.'),
('kam', '1KI', 10, 18, 'O na ĩngĩ mũsumbĩ aseũvĩthya na maeo ma nzou kĩvĩla kĩnene kya ũsumbĩ, na akĩvw’ĩka thaavu mũtheu mũno mbee.'),
('kam', '1KI', 10, 19, 'Kwaĩ matambya thanthatũ ma kwambata kĩvĩlanĩ kyu kya ũsumbĩ, na mũthya wa ĩũlũ wa kĩvĩla kyu waĩ mũkumbe ngalĩ ya mũongonĩ; na kwaĩ kw’oko ngalĩ ĩno na ngalĩ ĩno vakuvĩ na vandũ va kwĩkalĩla, na mĩnyambũ ĩlĩ ĩũngamĩte ũtee wa moko asu.'),
('kam', '1KI', 10, 20, 'Na mĩnyambũ ĩkũmi na ĩlĩ yaũngeme vo ngalĩ ĩno na ngalĩ ĩla ĩngĩ matambyanĩ asu thanthatũ: kũtyaĩ kĩndũ kyaseũvĩtw’e ũu ũsumbĩnĩ o na wĩva.'),
('kam', '1KI', 10, 21, 'Na mĩio yonthe ya mũsumbĩ Solomoni ya kũnyw’a nayo yaĩ ya thaavu, na mĩio yonthe ya nyũmba ya mũtitũ wa Levanoni yaĩ ya thaavu mũtheu: vatyaĩ ũmwe wa vetha; na ũu ndwaatalwa ta ũndũ mĩthenyanĩ ya Solomoni.'),
('kam', '1KI', 10, 22, 'Nũndũ mũsumbĩ aĩ na kĩkundi kya ngalawa sya Talisisi ũkanganĩ vamwe na kĩkundi kya ngalawa sya Ilamu: kĩla myaka ĩtatũ kĩkundi kya ngalawa sya Talisisi kĩisyoka ĩmwe, ikĩete thaavu, na vetha, na maeo ma nzou, na sokwe, na tausi.'),
('kam', '1KI', 10, 23, 'Na ĩndĩ mũsumbĩ Solomoni amakĩla asumbĩ onthe ma nthĩ na ũthwii na ũĩ.'),
('kam', '1KI', 10, 24, 'Na nthĩ yonthe yenda kũvika kwa Solomoni, yĩw’e ũĩ wake, ũla Ngai wekĩie ngoonĩ yake.'),
('kam', '1KI', 10, 25, 'Na maete kĩla mũndũ mũvothi wake, mĩio ya vetha, na mĩio ya thaavu, na ngũa, na mĩio ya kaũ, na mĩtĩ ĩla ĩnyungaa nesa, na mbalasi, na nyũmbũ, syĩanĩe kĩla mwaka.'),
('kam', '1KI', 10, 26, 'Na Solomoni oomban’ya makasya ma kaũ na andũ ma kũtũlaa mbalasi: na aĩ na makasya ngili na maana ana, na andũ ma ũtũlaa mbalasi ngili ĩkũmi na ilĩ, ala wamaiĩte ndũanĩ sya makasya, na vala ve mũsumbĩ Yelusaleme.'),
('kam', '1KI', 10, 27, 'Na mũsumbĩ atw’ĩkĩthya vetha weethĩwa ta mavia ku Yelusaleme ũndũ wa kwingĩva, o na mĩkũũ yeethĩwa ta mĩkũyũ ĩla yĩ nthĩ ndindimalu.'),
('kam', '1KI', 10, 28, 'Na mbalasi ila Solomoni waĩ nasyo syaetawe kuma Misili; na atandĩthya ma mũsumbĩ manengawe ndĩthya, ndĩthya, kĩla ndĩthya kwa thooa wayo.'),
('kam', '1KI', 10, 29, 'Na ĩkasya yambatw’a kuma Misili ya thooa wa sekeli maana thanthatũ sya vetha, na mbalasi ya sekeli ĩana na mĩongo ĩtano; na o ta ũu mamaumĩasya asumbĩ onthe ma Aititi, na asumbĩ ma Silia, na moko moo.'),
('kam', '1KI', 11, 1, 'Na ĩndĩ mũsumbĩ Solomoni nĩwendete aka aingĩ ma nthĩ ingĩ vamwe na mwĩĩtu wa Valao, o aka ma Amoavi, na Aamimoni, na Aetomu, na Asitoni, na Aititi;'),
('kam', '1KI', 11, 2, 'ma mbaĩ ila Yeova watavisye ana ma Isilaeli ũndũ wasyo atĩĩ, Mũtikalike katĩ wasyo, o nasyo itikalike katĩ wenyu; nũndũ vate ndĩi ikathyũũa ngoo syenyu iatĩĩe ngai syasyo: Solomoni alũman’ya na aka asu wendonĩ.'),
('kam', '1KI', 11, 3, 'Na aĩ na iveti maana mũonza, eĩtu ma anene me mbee mosumbĩnĩ, na aka ngombo maana atatũ; na iveti syake syathyũũa ngoo yake.'),
('kam', '1KI', 11, 4, 'Nũndũ kweethĩiwe yĩla Solomoni watw’ĩkie mũkũũ, iveti syake syathyũũa ngoo yake, ĩatĩĩe ngai ingĩ; na ngoo yake ndĩaĩ mbĩanĩu kwa Yeova Ngai wake, o tondũ ngoo ya Ndaviti ĩthe wake yailyĩ.'),
('kam', '1KI', 11, 5, 'Nũndũ Solomoni aatĩĩaa Asetolethi ngai nga ya Asitoni, na Milikomu ngai ya Aamimoni ya ũthatyo.'),
('kam', '1KI', 11, 6, 'Na Solomoni eekaa ũla Yeova wonaa wĩ ũthũku, na ndaamũatĩĩa Yeova ki, o tondũ Ndaviti ĩthe wake wekaa.'),
('kam', '1KI', 11, 7, 'Na ĩndĩ Solomoni aaka vandũ vatũlu kwondũ wa Kemosi ngai ya Moavi ya ũthatyo, kĩĩmanĩ kĩla kĩ mbee wa Yelusaleme, o na kwondũ wa Moleki ngai ya ana ma Amimoni ya ũthatyo.'),
('kam', '1KI', 11, 8, 'Na eekaa o ta ũu kwondũ wa iveti syake syonthe sya nthĩ ingĩ, ila syatoeeasya ũvani na syathembeaa ngai syasyo.'),
('kam', '1KI', 11, 9, 'Na Yeova amũthatĩa Solomoni, nũndũ ngoo yake nĩyathyũũiwe ĩmũeke Yeova, Ngai wa Isilaeli, ũla wamumĩlĩle kelĩ,'),
('kam', '1KI', 11, 10, 'na wamwĩaĩĩte ũndũnĩ ũsu, ndakaatĩĩe ngai ingĩ: ĩndĩ ndaasũvĩa ũla Yeova weaie.'),
('kam', '1KI', 11, 11, 'Kwondũ wa ũu Yeova amwĩa Solomoni, Nĩkwĩthĩwa ũu nĩwĩkĩtwe nue, na ndwaalũmya ũtianĩo wakwa na myamũlo yakwa, ĩla nakwĩaĩe, vate ndĩi ngakũvena ũsumbĩ, na ngoonenga mũthũkũmi waku.'),
('kam', '1KI', 11, 12, 'Ĩndĩ mĩthenyanĩ yaku ndikeka ũu, kwondũ wa Ndaviti ĩthe waku: ĩndĩ ngoovenana kw’okonĩ kwa mwana waku.'),
('kam', '1KI', 11, 13, 'Ĩndĩ ndikovenana ũsumbĩ w’onthe; ĩndĩ nganenga mwana waku mbaĩ ĩmwe, kwondũ wa Ndaviti mũthũkũmi wakwa, na kwondũ wa Yelusaleme ĩla nĩnyuvĩte.'),
('kam', '1KI', 11, 14, 'Na Yeova amũkĩlĩlya Solomoni nthũ, Aatati Mũetomu: aĩ wa ũsyao wa mũsumbĩ wa nthĩ ya Etomu.'),
('kam', '1KI', 11, 15, 'Nũndũ kweethĩiwe, yĩla Ndaviti waĩ Etomu, na Yoavu kavuteni wa nguthu waĩ anambata kwĩnzĩa ala mooaiwe nthĩ, na waĩ anakũna kĩla mũndũ mũũme ku Etomu'),
('kam', '1KI', 11, 16, '(nũndũ Yoavu na Isilaeli onthe nĩmekalaa kw’o myei thanthatũ, mũvaka aveta kĩla mũndũ mũũme ku Etomu);'),
('kam', '1KI', 11, 17, 'Aatati akĩa, we na Aetomu amwe ma athũkũmi ma ĩthe wake vamwe nake, maende Misili, Aatati e kana kanini.'),
('kam', '1KI', 11, 18, 'Na mookĩla kuma Mitiani na mavika Valani; na moosa andũ kuma Valani na maenda nao, na mavika Misili, kwa Valao mũsumbĩ wa Misili, ũla wamũnengie nyũmba, na kũmũthimĩa lĩu, na amũnenga o nthĩ.'),
('kam', '1KI', 11, 19, 'Na Aatati oona ũseo mũno methonĩ ma Valao, kũvika amũnenga mũamũe, o mwĩĩtu‐a‐inyia wa Tavenesi kĩveti kyake, ethĩwe mũka.'),
('kam', '1KI', 11, 20, 'Na mwĩĩtu‐a‐inyia wa Tavenesi asyaa Ngenuvathi mwana wake, ũla Tavenesi wamũaĩĩsye nyũmbanĩ ya Valao; na Ngenuvathi aĩ nyũmbanĩ ya Valao e na ana ma Valao.'),
('kam', '1KI', 11, 21, 'Na yĩla Aatati wewie e Misili atĩ Ndaviti nũkomete na aaĩthe make, na Yoavu kavuteni wa nguthu nĩ mũkw’ũ, Aatati amwĩa Valao, Ndeka nĩthi, nĩende nthĩ yakwa mwene.'),
('kam', '1KI', 11, 22, 'Na ĩndĩ Valao amwĩa, Ĩndĩ ũnyivĩwe nĩ kyaũ wĩ kũũ kwakwa, atĩ, sisya, nũkwenda ũsyoka nthĩ yaku mwene? Na asũngĩa, Ti kĩndũ; ĩndĩ ndeka nĩthi.'),
('kam', '1KI', 11, 23, 'Na Ngai amũkĩlĩlya nthũ ĩngĩ, Lesoni mwana wa Eliata, ũla wakĩĩte kuma kwa mwĩaĩi wake Atateseli mũsumbĩ wa Sova.'),
('kam', '1KI', 11, 24, 'Na eeyũmbanĩsya andũ, na atw’ĩka kavuteni wa nguthu, yĩla Ndaviti woaie ala ma Sova: na mathi Ndamasiku, na matũa kw’o, na masumbĩka ku Ndamasiku.'),
('kam', '1KI', 11, 25, 'Na aĩ nthũ ya Isilaeli mĩthenya yonthe ya Solomoni, eka ũthũku ũla Aatati wekie: na athĩtha Isilaeli mũno, na asumbĩka Silia.'),
('kam', '1KI', 11, 26, 'Na Yelovoamu mwana wa Nevati, ũsu Mũevalaimu wa Nzeleta, mũthũkũmi wa Solomoni, ũla syĩtwa ya inyia wake eetawa Nzelua, mũndũ mũka ndiwa, o nake amũkĩlĩlya mũsumbĩ kw’oko kwake.'),
('kam', '1KI', 11, 27, 'Na kĩĩ nĩkyo kĩtumi kya kũmũkĩlĩlya mũsumbĩ kw’oko kwake: Solomoni aaka Milo, na atũngĩĩa vandũ vala vavũthũiwe ndũanĩ ya Ndaviti ĩthe wake.'),
('kam', '1KI', 11, 28, 'Na mũndũ ũsu Yelovoamu aĩ ngũmbaũ nene; na Solomoni oona mwanake ũsu atĩ nĩ mũthangaau, na amwia ĩũlũ wa wĩa w’onthe wa nyũmba ya Yosevu.'),
('kam', '1KI', 11, 29, 'Na kweethĩwa ĩvinda yĩu, yĩla Yelovoamu waumie Yelusaleme, mwathani Aiya Mũsilo amwĩthĩa nzĩanĩ; na ĩndĩ Aiya eevw’ĩkĩte ngũa nzaũ; na asu elĩ maĩ kĩsesinĩ me oka.'),
('kam', '1KI', 11, 30, 'Na Aiya akwata ĩla ngũa nzaũ ĩla wĩvw’ĩkĩte, na amĩtembũanga ilungu ĩkũmi na ilĩ.'),
('kam', '1KI', 11, 31, 'Na amwĩa Yelovoamu, Ĩyosee ilungu ĩkũmi; nũndũ ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Sisya, ngavenana ũsumbĩ kw’okonĩ kwa Solomoni, na ngakũnenga mbaĩ ĩkũmi'),
('kam', '1KI', 11, 32, '(ĩndĩ akeethĩwa na mbaĩ ĩmwe, kwondũ wa mũthũkũmi wakwa Ndaviti na kwondũ wa Yelusaleme, ndũa ĩla nĩnyuvĩte kuma mbaĩnĩ syonthe sya Isilaeli);'),
('kam', '1KI', 11, 33, 'nũndũ nindiĩte, na nĩsyathaithĩte Asetolethi ngai nga ya Asitoni, na Kemosi ngai ya Moavi, na Milikomu ngai ya ana ma Amimoni; na ityaaenda nzĩanĩ syakwa, syĩkae ũla nonaa wĩ ũseo, na kũsũvĩaa myamũlo yakwa na motw’ĩo makwa, o tondũ Ndaviti ĩthe wake wekaa.'),
('kam', '1KI', 11, 34, 'Ĩndĩ ndikaumya ũsumbĩ w’onthe kw’okonĩ kwake; ĩndĩ ngamũtw’ĩkĩthya mũnene wĩ mbee ũsumbĩnĩ mĩthenya yonthe ya thayũ wake, kwondũ wa Ndaviti mũthũkũmi wakwa ũla namũnyuvie, ũla wakwataa mĩao yakwa na myamũlo yakwa;'),
('kam', '1KI', 11, 35, 'ĩndĩ ngaumya ũsumbĩ kw’okonĩ kwa mwana wake, na ngakũnenga, o mbaĩ ĩkũmi.'),
('kam', '1KI', 11, 36, 'Na nganenga mwana wake mbaĩ ĩmwe, nĩ kana Ndaviti mũthũkũmi wakwa ethĩwe na taa mbee wakwa mavinda onthe Yelusaleme, ndũa ĩla nĩnyuvĩte kwondũ wakwa nĩkalye syĩtwa yakwa vo.'),
('kam', '1KI', 11, 37, 'Na ngakwosa na ũkasumbĩka kwĩanana na w’onthe ũla ngoo yaku yendete, na ũkeethĩwa mũsumbĩ wa Isilaeli.'),
('kam', '1KI', 11, 38, 'Na kũkeethĩwa, ethĩwa ũkeethukĩĩasya w’onthe ũla nĩkwĩaa, na ũkakinyaa nzĩanĩ syakwa, na kwĩkaa ũla nonaa wĩ ũseo, ũsũvĩae myamũlo yakwa na mĩao yakwa, o tondũ Ndaviti mũthũkũmi wakwa wekaa; ngeethĩawa vamwe naku, na ngakwakĩa nyũmba nũmu, o tondũ namwakĩe Ndaviti, na ngakũnenga Isilaeli.'),
('kam', '1KI', 11, 39, 'Na ngathĩn’ya ũsyao wa Ndaviti kwondũ wa ũndũ ũsu, ĩndĩ ti tene na tene.'),
('kam', '1KI', 11, 40, 'Kwondũ wa ũu Solomoni amantha kũmũaa Yelovoamu; ĩndĩ Yelovoamu ookĩla, na akĩa athĩ Misili, kwa Sisaki mũsumbĩ wa Misili, na ekala Misili kũvika yĩla Solomoni wakwie.'),
('kam', '1KI', 11, 41, 'Na ĩndĩ meko ala angĩ ma Solomoni, na w’onthe ũla wekaa, na ũĩ wake, ti maandĩke ĩvukunĩ ya meko ma Solomoni?'),
('kam', '1KI', 11, 42, 'Na ĩvinda yĩla Solomoni wasumbĩkie Isilaeli onthe ku Yelusaleme yaĩ myaka mĩongo ĩna.'),
('kam', '1KI', 11, 43, 'Na Solomoni akoma na aaĩthe make na athikwa ndũanĩ ya Ndaviti ĩthe wake; na Leovoamu mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 12, 1, 'Na Leovoamu aenda Sekemu: nũndũ Isilaeli onthe maĩ aendu Sekemu makamũtw’ĩkĩthye mũsumbĩ.'),
('kam', '1KI', 12, 2, 'Na kweethĩwa, yĩla Yelovoamu mwana wa Nevati wewie ũu (nũndũ aĩ o Misili ĩvinda yĩu, vala wakĩĩe aume vala ve mũsumbĩ Solomoni, na Yelovoamu atwĩe Misili,'),
('kam', '1KI', 12, 3, 'na matũmana aketwe), Yelovoamu na ũmbano w’onthe wa Isilaeli mooka, na maneena na Leovoamu, maimwĩa,'),
('kam', '1KI', 12, 4, 'Ĩthe waku nĩwatw’ĩkĩthĩtye ĩsoki yitũ ĩito: yu kwondũ wa ũu vũthangya ũthũkũmi ũsu mũito wa ĩthe waku, na ĩsoki yake ĩito yĩla watwĩkĩie, na tũkakũthũkũma.'),
('kam', '1KI', 12, 5, 'Na amea, Endai mwĩkale o mĩthenya ĩtatũ, na ĩndĩ mũimbũkĩa ĩngĩ. Na andũ asu mathi.'),
('kam', '1KI', 12, 6, 'Na mũsumbĩ Leovoamu eethĩwa nzama na atumĩa, ala manaũngamaa mbee wa ĩthe wake Solomoni yĩla ũnaĩ o thayũ, akĩmakũlya, Mwĩnenga ũtao wĩva nĩmasũngĩa andũ asu?'),
('kam', '1KI', 12, 7, 'Na maneena nake, makĩmwĩa, Ethĩwa ũkeethĩwa mũthũkũmi wa andũ asu ũmũnthĩ, na ũkamathũkũma, na kũmasũngĩa, na kũmaneen’ya ndeto nzeo, mo makeethĩwa athũkũmi maku tene na tene.'),
('kam', '1KI', 12, 8, 'Ĩndĩ atia ũtao wa atumĩa ũla mamũtaie naw’o, na eethĩwa nzama na anake ala ma mũika wake, ala maũngamaa mbee wake.'),
('kam', '1KI', 12, 9, 'Na amakũlya, Mwĩnenga ũtao wĩva, nĩ kana twĩmasũngĩa andũ asu, ala maneenete nakwa, makĩmbĩa, Tũvũthangĩsye ĩsoki yĩla ĩthe waku watwĩkĩie?'),
('kam', '1KI', 12, 10, 'Na anake ala ma mũika wake maneena nake, makĩmwĩa, Ũũ nĩw’o wĩmatavya andũ asu ala maneenie naku, makĩkwĩa, Ĩthe waku nĩwatw’ĩkĩthisye ĩsoki yitũ ĩito, ĩndĩ we tũvũthangĩsye; ũũ nĩw’o wĩmatavya, Kyaa kyakwa kya mwela nĩ kĩnene kwĩ kĩnyunyu kya ĩthe wakwa.'),
('kam', '1KI', 12, 11, 'Na yu o ũndũ ĩthe wakwa wamwaĩkĩtye ĩsoki ĩito, nakwa ngongeleela ĩsoki yenyu: ĩthe wakwa amũsilĩlaa na mĩsalisa, ĩndĩ nyie ngamũsilĩlaa na ing’auũ.'),
('kam', '1KI', 12, 12, 'Na ĩndĩ Yelovoamu na andũ onthe mooka vala ve Leovoamu mũthenya wa katatũ, o tondũ mũsumbĩ weaĩte, akĩmea, Mbũkĩai ĩngĩ mũthenya wa katatũ.'),
('kam', '1KI', 12, 13, 'Na mũsumbĩ amasũngĩa andũ na vinya, na atia ũtao wa atumĩa ũla mamũtaie naw’o,'),
('kam', '1KI', 12, 14, 'na aneena nao kwĩanana na ũtao wa anake, akĩmea, Ĩthe wakwa nĩwatw’ĩkĩthisye ĩsoki yenyu ĩito, ĩndĩ nyie ngayongeleela ĩsoki yenyu: ĩthe wakwa amũsilĩlaa na mĩsalisa, ĩndĩ nyie ngamũsilĩlaa na ing’auũ.'),
('kam', '1KI', 12, 15, 'Na ĩndĩ mũsumbĩ ndaaĩthukĩĩsya andũ; nũndũ ũu waĩ ũndũ waetetwe nĩ Yeova, nĩ kana alũlũmĩlye ndeto yake, ĩla Yeova wamũtavisye Yelovoamu mwana wa Nevati na kanyw’a wa Aiya Mũsilo.'),
('kam', '1KI', 12, 16, 'Na yĩla Isilaeli onthe moonie kana mũsumbĩ ndaamethukĩĩsya, andũ mamũsũngĩa mũsumbĩ, makĩmwĩa, Twĩ na kĩanda kyaũ nthĩnĩ wa Ndaviti? O na tũti na ũtiĩwa nthĩnĩ wa mwana wa Yese: endai maeemanĩ menyu, inyw’ĩ Isilaeli: na yu ĩsyaĩĩsye nyũmba yaku mwene Ndaviti. Na ĩndĩ Isilaeli maenda maeemanĩ moo.'),
('kam', '1KI', 12, 17, 'Ĩndĩ ũndũ wa ana ma Isilaeli ala matwĩe ndũanĩ sya Yuta, Leovoamu amasumbĩka.'),
('kam', '1KI', 12, 18, 'Na ĩndĩ mũsumbĩ Leovoamu atũma Atolamu, ũla waĩ mũnene wa andũ ala matethethaw’a wĩa na vinya; na Isilaeli onthe mamũkimanga na mavia akw’a. Na mũsumbĩ Leovoamu eekalaata ambate vala ve ĩkasya yake, akĩe avike Yelusaleme.'),
('kam', '1KI', 12, 19, 'Ũu nĩw’o Isilaeli mang’endee nyũmba ya Ndaviti kũvika ũmũnthĩ.'),
('kam', '1KI', 12, 20, 'Na kweethĩwa, yĩla Isilaeli onthe meewie Yelovoamu nũsyokete, matũmana mamwĩte oke ũmbanonĩ, na mamũtw’ĩkĩthya mũsumbĩ wa Isilaeli onthe: vati ĩmwe yaaatĩanĩa na nyũmba ya Ndaviti, ate o mbaĩ ya Yuta yĩ yoka.'),
('kam', '1KI', 12, 21, 'Na yĩla Leovoamu wavikie Yelusaleme, oomban’ya nyũmba yonthe ya Yuta, na mbaĩ ya Mbenyamini, andũ ngili ĩana na mĩongo nyanya ala anyuve, ala maĩ ma kaũ, mokite na nyũmba ya Isilaeli, mamũtũngĩe Leovoamu mwana wa Solomoni ũsumbĩ.'),
('kam', '1KI', 12, 22, 'Ĩndĩ ndeto ya Ngai yamũkĩa Semaia mũndũ wa Ngai, ĩkĩmwĩa,'),
('kam', '1KI', 12, 23, 'Neena na Leovoamu mwana wa Solomoni, mũsumbĩ wa Yuta, na nyũmba yonthe ya Yuta na Mbenyamini, na andũ ala angĩ, ũkĩmea,'),
('kam', '1KI', 12, 24, 'Ũũ nĩw’o Yeova ũnũkwasya, Mũtikambate, o na mũtikokite na ana‐a‐ĩthe menyu ana ma Isilaeli: syokai kĩla mũndũ nyũmbanĩ yake; nũndũ ũndũ ũũ wumĩte kwakwa. Na ĩndĩ meethukĩĩsya ndeto ya Yeova, na masyoka na meeendea, kwĩanana na ndeto ya Yeova.'),
('kam', '1KI', 12, 25, 'Na ĩndĩ Yelovoamu aaka Sekemu nthĩ yĩ iĩma ya Evalaimu, na atũa kw’o; na auma kw’o, na aaka Venueli.'),
('kam', '1KI', 12, 26, 'Na Yelovoamu asya ngoonĩ yake, Yu ũsumbĩ ũkasyoka nyũmbanĩ ya Ndaviti:'),
('kam', '1KI', 12, 27, 'ethĩwa andũ aa makambata mathembe nthembo nyũmbanĩ ya Yeova Yelusaleme, nĩvo ĩndĩ ngoo sya andũ aa syĩmwĩthyũũĩa mwĩaĩi woo, o Leovoamu mũsumbĩ wa Yuta; na makambũaa, na kũmũsyokea Leovoamu mũsumbĩ wa Yuta.'),
('kam', '1KI', 12, 28, 'Nĩvo ĩndĩ mũsumbĩ wasũanĩie, na atusya tũsaũ twĩlĩ twa thaavu; na amea, Nĩ vinya kwenyu kwambata Yelusaleme: sisyai ngai syenyu, inyw’ĩ Isilaeli, ila syamwambatisye kuma nthĩ ya Misili.'),
('kam', '1KI', 12, 29, 'Na aũngamya kamwe Mbethi‐eli, na kala kangĩ aũngamya Ndani.'),
('kam', '1KI', 12, 30, 'Na ũndũ ũsu watw’ĩka naĩ; nũndũ andũ maendaa kũthaitha vala ve kamwe, o kũvika Ndani.'),
('kam', '1KI', 12, 31, 'Na aaka nyũmba sya kũla kũndũ kũtũlu, na amatw’a athembi kuma andũnĩ onthe, ala mataĩ ma ana ma Livai.'),
('kam', '1KI', 12, 32, 'Na Yelovoamu atw’a mboka mwei wa nyanya, mũthenya wa ĩkũmi na ĩtano wa mwei, ĩilyĩ mboka ĩla yĩ Yuta, na ambata vala ve kĩthembeo; na ũu now’o wekie Mbethi‐eli, akĩthembea tũsaũ tũla watuĩtye: na aia ku Mbethi‐eli athembi ma kũndũ kũtũlu kũla waseũvĩtye.'),
('kam', '1KI', 12, 33, 'Na ambata vala vaĩ kĩthembeo kĩla waseũvĩtye ku Mbethi‐eli mũthenya wa ĩkũmi na ĩtano wa mwei wa nyanya, o mwei ũla wasũanĩie na ngoo yake mwene: na atw’a mboka kwondũ wa ana ma Isilaeli, na ambata vala vaĩ kĩthembeo, atoeesye ũvani.'),
('kam', '1KI', 13, 1, 'Na, sisya, kwooka mũndũ wa Ngai kuma Yuta avike Mbethi‐eli kwondũ wa ndeto ya Yeova: na Yelovoamu aũngyĩ vakuvĩ na kĩthembeo atoeesye ũvani.'),
('kam', '1KI', 13, 2, 'Na atavya kĩthembeo na wasya mũnene kwondũ wa ndeto ya Yeova, na asya, We, kĩthembeo, kĩthembeo, ũũ nĩw’o Yeova ũnũkwasya: Sisya, kavĩsĩ kakasyawa nyũmbanĩ ya Ndaviti, syĩtwa yako kakeetwa Yosia; na ĩũlũ waku kakathemba athembi ma kũla kũndũ kũtũlu ala matoeeasya ũvani ĩũlũ waku, na makavĩvĩsya mavĩndĩ ma andũ ĩũlũ waku.'),
('kam', '1KI', 13, 3, 'Na anengane wonan’yo mũthenya o ũsu, akyasya, Ũũ nĩw’o wonan’yo ũla Yeova ũneenete: Sisyai, kĩthembeo kĩkaatũkana, na mũu ũla wĩ ĩũlũ wakyo ũketĩka.'),
('kam', '1KI', 13, 4, 'Na kweethĩwa, yĩla mũsumbĩ wewie ndeto sya ũ mũndũ wa Ngai, ila wakĩtavĩsye kĩthembeo ku Mbethi‐eli, Yelovoamu atambũũkya kw’oko kwake e kĩthembeonĩ, akyasya, Mũkwatei. Na kw’oko kwake, kũla wamũtambũũkĩsye, kwooma, ũndũ ũtatonya kũkũtũnga ĩngĩ.'),
('kam', '1KI', 13, 5, 'O na kĩthembeo kyaatũkana, na mũu wetĩka kuma kĩthembeonĩ, kwĩanana na wonan’yo ũla mũndũ wa Ngai wanengane kwondũ wa ndeto ya Yeova.'),
('kam', '1KI', 13, 6, 'Na mũsumbĩ asũngĩa na amwĩa mũndũ wa Ngai, Ĩsũvane yu ũseo wa Yeova Ngai waku, noĩmboyea, kw’oko kwakwa kũnzyokee ĩngĩ. Na ũla mũndũ wa Ngai amwĩsũva Yeova, na kw’oko kwa mũsumbĩ kwamũsyokea, na kwekala ũndũ kwĩĩilyĩ mbee.'),
('kam', '1KI', 13, 7, 'Na mũsumbĩ amwĩa mũndũ wa Ngai, Ũka twĩnũkan’ye, ũkevuũkye, na ngakũnenga mũthĩnzĩo.'),
('kam', '1KI', 13, 8, 'Na ũla mũndũ wa Ngai amwĩa mũsumbĩ, O na ũkanenga nyunzu ya nyũmba yaku, ndilika naku, o na ndiya lĩu kana kũnyw’a manzĩ vandũ vaa;'),
('kam', '1KI', 13, 9, 'nũndũ now’o nĩaĩĩtwe nĩ ndeto ya Yeova, ĩkĩmbĩa, Ndũkaye lĩu, kana kũnyw’a manzĩ, o na ndũkasyoke na nzĩa ĩla ũendie nayo.'),
('kam', '1KI', 13, 10, 'Kwondũ wa ũu athi na nzĩa ĩngĩ, na ndaasyoka na nzĩa ĩla wũkie Mbethi‐eli nayo.'),
('kam', '1KI', 13, 11, 'Na ĩndĩ ku Mbethi‐eli kwatwĩe mwathani mũkũũ; na ũmwe wa ana make athi na amũtavya mawĩa onthe ala mũndũ wa Ngai wĩkie mũthenya ũsu Mbethi‐eli: ndeto ila ũneenie na mũsumbĩ, o na isu mamũtavya ĩthe woo.'),
('kam', '1KI', 13, 12, 'Na ĩthe woo amakũlya, Aendie na nzĩa yĩva? Na ĩndĩ ana make nĩmoonete nzĩa ĩla mũndũ wa Ngai ũla ũnaumĩte Yuta ũendie nayo.'),
('kam', '1KI', 13, 13, 'Na amea ana make, Ndandĩkĩai ĩng’oi. Na ĩndĩ mamũtandĩkĩa ĩng’oi; na ayĩtũla.'),
('kam', '1KI', 13, 14, 'Na amũatĩĩa ũla mũndũ wa Ngai, na amwĩthĩa ekalĩte nthĩ ĩtina wa mũtĩ wa mwaloni; na amũkũlya, Nue mũndũ wa Ngai ũla ũnaumĩte Yuta? Nake asya, Ninyie.'),
('kam', '1KI', 13, 15, 'Nĩvo ĩndĩ wamwĩie, Ũka tũende kwakwa, ũye lĩu.'),
('kam', '1KI', 13, 16, 'Nake asya, Ndi na ũthei wa kũsyokan’ya naku, kana kũlika kwaku; o na ndiya lĩu kana kũnyusanĩa manzĩ naku vandũ vaa:'),
('kam', '1KI', 13, 17, 'nũndũ nataviw’e nĩ ndeto ya Yeova, Ndũkaye lĩu kana kũnyw’a manzĩ kw’o, kana kwĩthyũũa ũsyoke na nzĩa ĩla ũendie nayo.'),
('kam', '1KI', 13, 18, 'Na amwĩa, Nyie o nakwa nĩ mwathani o taku; na mũlaĩka aneenie nakwa na ndeto ya Yeova, akĩmbĩa, Mũtũngĩthye mũsyokan’ye wĩ nake nyũmbanĩ yaku, nĩ kana aye lĩu na kũnyw’a manzĩ. Ĩndĩ amũtavisye ũvũngũ.'),
('kam', '1KI', 13, 19, 'Na ĩndĩ asyokan’ya nake, na aya lĩu nyũmbanĩ yake, na anyw’a manzĩ.'),
('kam', '1KI', 13, 20, 'Na kweethĩwa, yĩla mailyĩ mesanĩ, ndeto ya Yeova yamũkĩa mwathani ũla wamũtũngĩthisye;'),
('kam', '1KI', 13, 21, 'na aneena na wasya mũnene na mũndũ wa Ngai ũla ũnaumĩte Yuta, akĩmwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩkwĩthĩwa ũleile kwĩw’a kanyw’a wa Yeova, na ndũnasũvĩa mwĩao ũla Yeova Ngai waku ũnakwĩaĩe,'),
('kam', '1KI', 13, 22, 'ĩndĩ wasyoka, na waya lĩu na wanyw’a manzĩ vandũ vala ũnakũtavisye ũndũ wa vo, Ndũkaye lĩu, na ndũkanyw’e manzĩ; kimba kyaku kĩtikathikwa ngunganĩ ya aaĩthe maku vala vathikawa akw’ũ.'),
('kam', '1KI', 13, 23, 'Na kweethĩwa ĩtina wa maya lĩu, na manyw’a, atandĩka ĩng’oi kwondũ wa mwathani, o mwathani ũla ũmũtũngĩthisye.'),
('kam', '1KI', 13, 24, 'Na yĩla waminie kũthi, mũnyambũ wakomana nake nzĩanĩ, na wamũaa: na kimba kyake kyavalũkw’a nzĩanĩ, na ĩng’oi yaũngama vakuvĩ nakyo; na mũnyambũ naw’o waũngama vakuvĩ na kimba.'),
('kam', '1KI', 13, 25, 'Na, sisya, andũ mavĩtĩla vo, na moona kimba kĩvalũkĩtw’e nzĩanĩ, na mũnyambũ ũũngamĩte ũtee wa kimba; na mooka na matavan’ya ũũ ndũanĩ vala watwĩe ũla mwathani mũkũũ.'),
('kam', '1KI', 13, 26, 'Na yĩla mwathani ũla ũmũtũngithisye nzĩanĩ wewie ũu, asya, Nĩ ũla mũndũ wa Ngai, ũla ũleile kwĩw’a kanyw’a wa Yeova: kwondũ wa ũu Yeova nũmũnenganie kwa mũnyambũ, ũla ũmũvũnyangie, na wamũaa, kwĩanana na ndeto ya Yeova, ĩla ũnaneenie nake.'),
('kam', '1KI', 13, 27, 'Na aneena na ana make, akĩmea, Ndandĩkĩai ĩng’oi. Na mayĩtandĩka.'),
('kam', '1KI', 13, 28, 'Na athi na eethĩa kimba kyake kĩvalũkĩtw’e nzĩanĩ, na yĩla ĩng’oi na mũnyambũ iũngamĩte ũtee wa kimba: mũnyambũ ndwĩĩ ũnaya kimba, kana kũvũnyanga ĩng’oi.'),
('kam', '1KI', 13, 29, 'Na ũla mwathani oosa kimba kya ũ mũndũ wa Ngai, na akĩtũlya ĩng’oinĩ, na akĩtũnga; na mwathani mũkũũ avika ndũanĩ yake, amũmetee, na kũmũthika.'),
('kam', '1KI', 13, 30, 'Na aia kimba kyake ngunganĩ yake mwene vala vathikawa akw’ũ; na mamũmetea, makyasya, Ĩiaa, mwana‐a‐asa!'),
('kam', '1KI', 13, 31, 'Na kweethĩwa, ĩtina wa kũmũthika, aneena na ana make, akĩmea, Nakw’a, mwĩnthika nyie ngunganĩ vala vathikawa akw’ũ vala mũndũ wa Ngai ũthikĩtwe; mwĩia mavĩndĩ makwa ũtee wa mavĩndĩ make.'),
('kam', '1KI', 13, 32, 'Nũndũ ndeto ila ũkĩneeneie kĩthembeo ku Mbethi‐eli kwondũ wa ndeto ya Yeova, o na nyũmba syonthe sya kũndũ kũtũlu kũla kwĩ ndũanĩ sya Samalia, ikeanĩw’a vate ndĩi.'),
('kam', '1KI', 13, 33, 'Ĩtina wa ũndũ ũsu Yelovoamu ndaaĩthyũũa kuma mũendelenĩ wake mũthũku, ĩndĩ o ĩngĩ kuma andũnĩ onthe amatw’a athembi ma kũla kũndũ kũtũlu: o ũla wendaa amũvathan’ya, nĩ kana vethĩwe athembi ma kũla kũndũ kũtũlu.'),
('kam', '1KI', 13, 34, 'Na ũndũ ũsu watw’ĩkie naĩ kwa nyũmba ya Yelovoamu, o ya kũmĩveta, na kũmyananga yume ĩũlũ wa nthĩ.'),
('kam', '1KI', 14, 1, 'Ĩvinda yĩu Aviya mwana wa Yelovoamu awaa.'),
('kam', '1KI', 14, 2, 'Na Yelovoamu amwĩa mũka wake, Nĩngũkwĩsũva, ũkĩla noyĩyũlan’ya, nĩ kana ndũkamanyĩke wĩ kĩveti kya Yelovoamu; na enda Silo: sisya, mwathani Aiya e ku, ũla waneenie ũndũ wakwa kana ngeethĩwa mũsumbĩ wa andũ aa.'),
('kam', '1KI', 14, 3, 'Na kua imũtũ ĩkũmi, na tũmũtũ, na sũva wa ũkĩ wa nzũkĩ, noimũendea: akakũtavya ũndũ kwĩĩkĩka kwa mwana.'),
('kam', '1KI', 14, 4, 'Na kĩveti kya Yelovoamu kyeeka ũu, na kyookĩla, na kyathi Silo, na kyavika nyũmba kwa Aiya. Na ĩndĩ Aiya ndaĩ atonya kwona; nũndũ metho make nĩmaĩte mbindu nũndũ wa kũkũa.'),
('kam', '1KI', 14, 5, 'Na Yeova amwĩa Aiya, Sisya, kĩveti kya Yelovoamu nĩkyũkĩte ũkũkũlya ũndũ wa mwana wakyo; nũndũ nĩ mũwau: kĩtavye ũna na ũna; nũndũ kwĩĩthĩwa, yĩla kĩũtonyelela kĩĩyĩkalya ta kĩveti kĩngĩ.'),
('kam', '1KI', 14, 6, 'Na kweethĩwa, yĩla Aiya wewie matuu ma maũũ makyo, kĩkĩtonyelela mũomonĩ, akĩa, Lika, we kĩveti kya Yelovoamu; nũndũ wa kĩ ũkwĩyĩkalya ta ũngĩ? Nũndũ nĩtũmĩtwe kwaku na ũvoo mũito.'),
('kam', '1KI', 14, 7, 'Enda, ũmũtavye Yelovoamu, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya: Nũndũ nĩnakũnenevisye ngĩkumya katĩ wa andũ, na nakũtw’ĩkĩthya mũnene wĩ mbee ũsumbĩnĩ wa andũ makwa Isilaeli,'),
('kam', '1KI', 14, 8, 'na navena nyũmba ya Ndaviti ũsumbĩ, na nakũnenga; ĩndĩ o na ũu ndwaaĩkala ta mũthũkũmi wakwa Ndaviti, ũla wakwataa mĩao yakwa, na wambikĩlile na ngoo yake yonthe, eke ũla nonaa wĩ ũseo w’oka,'),
('kam', '1KI', 14, 9, 'ĩndĩ nĩwĩkĩte ũthũku kũvĩtũka onthe ala maĩ mbee waku, na wathi na kwĩseũvĩsya ngai ingĩ, na mĩvw’anano ya syĩndũ ila ũtwekethetye, ũkĩnthatya, na nũmbĩkĩtye ĩtina waku:'),
('kam', '1KI', 14, 10, 'kwondũ wa ũu, sisya, ngamĩetee nyũmba ya Yelovoamu ũthũku, na ngaveta kwa Yelovoamu kĩla mwana mũũme, ũla wĩĩthĩwa e mwove na ũla wĩĩthĩwa ate mwove nthĩnĩ wa Isilaeli na ngatuta vyũ nyũmba ya Yelovoamu, o tondũ mũndũ ũtutaa vũũ, mũvaka yathela vyũ.'),
('kam', '1KI', 14, 11, 'Ũla wa Yelovoamu ũkakw’ĩa ndũanĩ ngitĩ ikaya; na ũla ũkakw’ĩa kĩthekanĩ nyũnyi sya yayaya ikaya; nũndũ Yeova nũneenete ũu.'),
('kam', '1KI', 14, 12, 'Ũkĩla ĩndĩ ũsyoke nyũmbanĩ kwaku: na yĩla maũũ maku melika ĩ ndũanĩ, mwana ethi ũkw’a.'),
('kam', '1KI', 14, 13, 'Na Isilaeli onthe makamũmetea, na makamũthika; nũndũ no ũsu weka wa Yelovoamu wĩthikwa mbũanĩ, nĩkwĩthĩwa nthĩnĩ wake nĩvekwonekete ũndũ ũseo welekele Yeova, Ngai wa Isilaeli, nyũmbanĩ ya Yelovoamu.'),
('kam', '1KI', 14, 14, 'Na ĩngĩ Yeova akeeyũkĩlĩlya mũsumbĩ wa Isilaeli, ũla ũkaveta nyũmba ya Yelovoamu mũthenya ũsu: ĩndĩ nata? O na yu.'),
('kam', '1KI', 14, 15, 'Nũndũ Yeova akakũna Isilaeli, o tondũ mũangi ũthingithangaw’a wĩ manzĩnĩ; na akakũanĩsya Isilaeli na mĩi kuma nthĩ ĩno nzeo ĩla wamanengie aaĩthe moo, na akamanyaĩĩkya mũingo wa ũla Ũsĩ, nĩkwĩthĩwa nĩmaseũvisye Aselimu syoo, makĩmũthatya Yeova.'),
('kam', '1KI', 14, 16, 'Na akaekana na Isilaeli nũndũ wa naĩ sya Yelovoamu, ila wĩkĩte, na ila wavĩtĩthĩtye Isilaeli nasyo.'),
('kam', '1KI', 14, 17, 'Na kĩveti kya Yelovoamu kyookĩla, na kyathi, na kyavika Tilisa: na kĩkĩvika mwalyonĩ wa nyũmba, mwana akw’a.'),
('kam', '1KI', 14, 18, 'Na Isilaeli onthe mamũthika, na mamũmetea, kwĩanana na ndeto ya Yeova, ĩla waneenie na kanyw’a wa mũthũkũmi wake Aiya.'),
('kam', '1KI', 14, 19, 'Na meko ala angĩ ma Yelovoamu, ũndũ wokitie kaũ, na ũndũ wasumbĩkie, sisya, nĩmaandĩkĩtwe ĩvukunĩ ya maũndũ ma mavinda ma Isilaeli.'),
('kam', '1KI', 14, 20, 'Na mĩthenya ĩla Yelovoamu wasumbĩkie nĩ myaka mĩongo ĩlĩ na ĩlĩ: na akoma na aaĩthe make, na Natavu mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 14, 21, 'Na Leovoamu mwana wa Solomoni asumbĩka Yuta. Leovoamu aĩ wa myaka mĩongo ĩna na ũmwe yĩla wambĩlĩlye kũsumbĩka, na asumbĩka myaka ĩkũmi na mũonza Yelusaleme, ndũa ĩla Yeova wanyuvĩte mbaĩnĩ syonthe sya Isilaeli, ekalye syĩtwa yake vo: na syĩtwa ya inyia wake eetawa Naama Mũamimoni.'),
('kam', '1KI', 14, 22, 'Na Yuta meekaa ũla Yeova wonaa wĩ ũthũku, na mamwĩkĩa kĩwĩu na naĩ syoo ila meekaa, kũvĩtũka syonthe ila aaĩthe moo meekaa.'),
('kam', '1KI', 14, 23, 'Nũndũ nao nĩmeeyakie kũndũ kũtũlu, na ituĩ, na Aselimu, kĩla kĩĩmanĩ kĩtũlu, na ĩtina wa kĩla mũtĩ mwĩũ;'),
('kam', '1KI', 14, 24, 'o na kwaĩ aũme ĩ nthĩ ala meekaa naĩ na aũme angĩ: nĩmeekaa kwĩanana na mothatyo onthe ma mbaĩ ila Yeova wailũngilye mbee wa ana ma Isilaeli.'),
('kam', '1KI', 14, 25, 'Na kweethĩwa mwaka wa katano wa kũsumbĩka kwa mũsumbĩ Leovoamu, Sisaki mũsumbĩ wa Misili ambata okite na Yelusaleme;'),
('kam', '1KI', 14, 26, 'na atwaa mothwii maie ma nyũmba ya Yeova, na mothwii maie ma nyũmba ya mũsumbĩ; o na atwaa onthe vyũ: na atwaa ngao syonthe sya thaavu ila Solomoni waseũvĩtye.'),
('kam', '1KI', 14, 27, 'Na mũsumbĩ Leovoamu aseũvya ngao sya ũthuku mweũ vandũ va isu, na asia mokonĩ ma makavuteni ma nguthu ya asũvĩi, ala masũvĩaa mũomonĩ wa nyũmba ya mũsumbĩ.'),
('kam', '1KI', 14, 28, 'Na kweethĩwa, o yĩla mũsumbĩ walikaa nyũmbanĩ ya Yeova, asũvĩi makikua, na makitũnga kasũmbanĩ ka asũvĩi.'),
('kam', '1KI', 14, 29, 'Na ĩndĩ meko ala angĩ ma Leovoamu, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta?'),
('kam', '1KI', 14, 30, 'Na kwaĩ kaũ katĩ wa Leovoamu na Yelovoamu mavinda onthe.'),
('kam', '1KI', 14, 31, 'Na Leovoamu akoma na aaĩthe make, na athikwa na aaĩthe make ndũanĩ ya Ndaviti: na syĩtwa ya inyia wake eetawa Naama Mũamimoni. Na Aviyamu mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 15, 1, 'Na ĩndĩ mwaka wa ĩkũmi na nyanya wa kũsumbĩka kwa Yelovoamu mwana wa Nevati, Aviyamu ambĩlĩlya kũsumbĩka Yuta.'),
('kam', '1KI', 15, 2, 'Asumbĩka myaka ĩtatũ Yelusaleme: na syĩtwa ya inyia wake eetawa Maaka, mwĩĩtu wa Avisalomu.'),
('kam', '1KI', 15, 3, 'Na nĩwaendaa naĩnĩ syonthe sya ĩthe wake, ila wekĩte mbee wake; na ngoo yake ndĩaĩ mbĩanĩu kwa Yeova Ngai wake, o tondũ ngoo ya Ndaviti ĩthe wake yailyĩ.'),
('kam', '1KI', 15, 4, 'Ĩndĩ kwondũ wa Ndaviti Yeova Ngai wake amũnenga taa ku Yelusaleme, akĩũngamya mwana wake ĩtina wake, na kũlũlũmĩlya Yelusaleme;'),
('kam', '1KI', 15, 5, 'nĩkwĩthĩwa Ndaviti nĩweekaa ũla Yeova wonaa wĩ ũseo, na ndaaĩthyũũa na kũtia ũndũ o na wĩva ũla wamwĩaĩe mĩthenya yonthe ya thayũ wake, ate o ũndũnĩ wa Ulia Mũititi.'),
('kam', '1KI', 15, 6, 'Na kwaĩ kaũ katĩ wa Leovoamu na Yelovoamu mĩthenya yonthe ya thayũ wake.'),
('kam', '1KI', 15, 7, 'Na meko ala angĩ ma Aviyamu, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta? Na kwaĩ kaũ katĩ wa Aviyamu na Yelovoamu.'),
('kam', '1KI', 15, 8, 'Na Aviyamu akoma na aaĩthe make; na mamũthika ndũanĩ ya Ndaviti: na Asa mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 15, 9, 'Na mwaka wa mĩongo ĩlĩ wa kũsumbĩka kwa Yelovoamu mũsumbĩ wa Isilaeli Asa ambĩlĩlya kũsumbĩka Yuta.'),
('kam', '1KI', 15, 10, 'Na asumbĩka Yelusaleme myaka mĩongo ĩna na ũmwe: na syĩtwa ya inyia wake eetawa Maaka mwĩĩtu wa Avisalomu.'),
('kam', '1KI', 15, 11, 'Na Asa eekaa ũla Yeova wonaa wĩ ũseo, o tondũ ĩthe wake Ndaviti wekaa.'),
('kam', '1KI', 15, 12, 'Na alũngya aũme ala meekaa naĩ na aũme angĩ maume ĩ nthĩ, na aveta mĩvw’anano yonthe ĩla ĩthe wake waseũvĩtye.'),
('kam', '1KI', 15, 13, 'O na aumya Maaka inyia wake ndakethĩwe ũnenenĩ wa kĩũsumbĩ, nũndũ nĩwaseũvĩtye mũvw’anano wa kũthatya wĩthĩwe wa Asela; na Asa atemanga mũvw’anano wa inyia wake, na oovĩvĩsya kalũsĩnĩ ketawa Kitiloni.'),
('kam', '1KI', 15, 14, 'Ĩndĩ kũla kũndũ kũtũlu kũtyaavetwa: ĩndĩ ngoo ya Asa yaĩ mbĩanĩu kwa Yeova mĩthenya yake yonthe.'),
('kam', '1KI', 15, 15, 'Na aete nyũmbanĩ ya Yeova syĩndũ ila ĩthe wake wavathĩte syĩthĩwe ntheu, na syĩndũ ila we mwene wavathĩte syĩthĩwe ntheu, vetha, na thaavu, na mĩio.'),
('kam', '1KI', 15, 16, 'Na kwaĩ kaũ katĩ wa Asa na Mbaasa mũsumbĩ wa Isilaeli mĩthenya yoo yonthe.'),
('kam', '1KI', 15, 17, 'Na Mbaasa mũsumbĩ wa Isilaeli ambata okite na Yuta, na aaka Lama, nĩ kana ndakaeke mũndũ o na wĩva kumaala kana kũsyoka vala ve Asa mũsumbĩ wa Yuta.'),
('kam', '1KI', 15, 18, 'Nĩvo ĩndĩ Asa waumaalilye vetha w’onthe na thaavu ũla watialĩtwe wa mothwii maie ma nyũmba ya Yeova, na mothwii maie ma nyũmba ya mũsumbĩ, na oonengane mokonĩ ma athũkũmi make; na mũsumbĩ Asa amũtwaĩa Mbeni‐aatati, mwana wa Tavilimoni, mwana wa Esioni, mũsumbĩ wa Silia, ũla watwie Ndamasiku, akĩmwĩa,'),
('kam', '1KI', 15, 19, 'Kwĩ wĩw’ano katĩ wakwa naku, o ta katĩ wa ĩthe wakwa na ĩthe waku: sisya, nĩnakũetee mũthĩnzĩo wa vetha na thaavu; enda, wanange wĩw’ano waku na Mbaasa mũsumbĩ wa Isilaeli, nĩ kana aume vala nĩĩ.'),
('kam', '1KI', 15, 20, 'Na Mbeni‐aatati amwĩthukĩĩsya mũsumbĩ Asa, na atũma makavuteni ma ita syake mokite na ndũa sya Isilaeli, na makũna Iyoni, na Ndani, na Aveli‐mbethimaaka, na Kinelothi yonthe, vamwe na nthĩ yonthe ya Navitali.'),
('kam', '1KI', 15, 21, 'Na kweethĩwa, yĩla Mbaasa wewie ũu, aeka kwaka Lama, na atũa Tilisa.'),
('kam', '1KI', 15, 22, 'Nĩvo ĩndĩ mũsumbĩ Asa watavanisye Yuta kw’onthe; vati ũmwe ũtaathi wĩanĩ: na makua mavia ma Lama, na mĩtĩ yayo, ĩla Mbaasa wakĩte nayo; na mũsumbĩ Asa aaka nayo Ngeva ya Mbenyamini, na Misiva.'),
('kam', '1KI', 15, 23, 'Na ĩndĩ meko ala angĩ onthe ma Asa, na vinya wake w’onthe mũnene, na w’onthe ũla wekaa, na ndũa ila wakie ti, maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta? Ĩndĩ ĩvinda ya kũtumĩa kwake awaa maũũ.'),
('kam', '1KI', 15, 24, 'Na Asa akoma na aaĩthe make, na athikwa vamwe na aaĩthe make ndũanĩ ya Ndaviti ĩthe wake; na Yeosavati mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 15, 25, 'Na Natavu mwana wa Yelovoamu ambĩlĩlya kũsumbĩka Isilaeli mwaka wa kelĩ wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta; na asumbĩka Isilaeli myaka ĩlĩ.'),
('kam', '1KI', 15, 26, 'Na eekaa ũla Yeova wonaa wĩ ũthũku, na aendaa mũendelenĩ wa ĩthe wake, na naĩnĩ yake ĩla wavĩtĩthisye Isilaeli nayo.'),
('kam', '1KI', 15, 27, 'Na Mbaasa mwana wa Aiya, wa nyũmba ya Isakali amũsamĩa; na Mbaasa amũkũnĩa ku Ngivethoni, ĩla yaĩ ya Avilisiti; nũndũ Natavu na Isilaeli onthe nĩmathyũlũlũkĩte Ngivethoni mamĩtw’ĩkanĩsye.'),
('kam', '1KI', 15, 28, 'O mwaka wa katatũ wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Mbaasa amũaa Natavu, na asumbĩka vandũ vake.'),
('kam', '1KI', 15, 29, 'Na kweethĩwa, o yĩla watw’ĩkie mũsumbĩ, akũnu nyũmba yonthe ya Yelovoamu: ndaamũtiĩa Yelovoamu ũmwe ũla ũnũkũveva, kũvika amũmina vyũ; kwĩanana na ndeto ya Yeova, ĩla waneenie na kanyw’a wa mũthũkũmi wake Aiya Mũsilo;'),
('kam', '1KI', 15, 30, 'nũndũ wa naĩ sya Yelovoamu ila wavĩtisye, na ila wavĩtĩthisye Isilaeli nasyo, nũndũ wa ũthatyo wake ũla wamũthatisye Yeova, Ngai wa Isilaeli, naw’o.'),
('kam', '1KI', 15, 31, 'Na ĩndĩ meko ala angĩ ma Natavu, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 15, 32, 'Na kwaĩ kaũ katĩ wa Asa na Mbaasa mũsumbĩ wa Isilaeli mĩthenya yoo yonthe.'),
('kam', '1KI', 15, 33, 'Mwaka wa katatũ wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Mbaasa mwana wa Aiya ambĩlĩlya kũsumbĩka Isilaeli onthe ku Tilisa, na asumbĩka myaka nĩomgo ĩlĩ na ĩna.'),
('kam', '1KI', 15, 34, 'Na eekaa ũla Yeova wonaa wĩ ũthũku, na aendaa mũendelenĩ wa Yelovoamu, na naĩnĩ yake ĩla wavĩtĩthisye Isilaeli nayo.'),
('kam', '1KI', 16, 1, 'Na ndeto ya Yeova yamũkĩa Yeu mwana wa Aanani ĩkĩmũneenea Mbaasa, ĩkĩmwĩa,'),
('kam', '1KI', 16, 2, 'Nĩkwĩthĩwa nĩnakũkĩlilye kuma kĩtoonĩ, na nakũtw’ĩkĩthya mũnene wĩ mbee ũsumbĩnĩ wa andũ makwa Isilaeli, naku nũendete na mũendele wa Yelovoamu, na wamavĩtĩthya andũ makwa Isilaeli, ũkĩnthatya na naĩ syoo;'),
('kam', '1KI', 16, 3, 'sisya, ngamina vyũ Mbaasa na nyũmba yake; na ngatw’ĩkĩthya nyũmba yaku ta nyũmba ya Yelovoamu mwana wa Nevati.'),
('kam', '1KI', 16, 4, 'Ũla wa Mbaasa ũkakw’ĩa ndũanĩ ngitĩ ikaya; na ũla wake ũkakw’ĩa kĩthekanĩ nyũnyi sya yayaya ikaya.'),
('kam', '1KI', 16, 5, 'Na ĩndĩ meko ala angĩ ma Mbaasa, na ũla wekaa, na vinya wake mũnene, ti maandĩke ĩvukuni ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 16, 6, 'Na Mbaasa akoma na aaĩthe make, na athikwa Tilisa; na Ela mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 16, 7, 'Na ũndũ ũngĩ ndeto ya Yeova yookie na kanyw’a wa mwathani Yeu mwana wa Aanani ĩkĩmũneenea Mbaasa, na nyũmba yake, nũndũ wa ũthũku w’onthe ũla wekaa Yeova ene, akĩmũthatya na wĩa wa moko make, ũndũ wa kwĩthĩwa ta nyũmba ya Yelovoamu, na nũndũ nĩwamũkũnie.'),
('kam', '1KI', 16, 8, 'Mwaka wa mĩongo ĩlĩ na thanthatũ wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Ela mwana wa Mbaasa ambĩlĩlya kũsumbĩka Isilaeli ku Tilisa, na asumbĩka myaka ĩlĩ.'),
('kam', '1KI', 16, 9, 'Na mũthũkũmi wake Nzimili, kavuteni wa nyunzu ya makasya make ma kaũ, amũsamĩa. Na aĩ Tilisa, anyw’ĩte akalooteka e nyũmbanĩ ya Alisa, ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba ku Tilisa:'),
('kam', '1KI', 16, 10, 'na Nzimili alika na amũkũna, na amũaa, mwaka wa mĩongo ĩlĩ na mũonza wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta, na asumbĩka vandũ vake.'),
('kam', '1KI', 16, 11, 'Na kweethĩwa, yĩla wambĩlĩlye kũsumbĩka, o ekala kĩvĩlanĩ kyake kya ũsumbĩ, akũna nyũmba yonthe ya Mbaasa: ndaamũtiĩa mwana mũũme o na ũmwe, wa andũ ma mbaĩ yake, o na wa anyanyae make.'),
('kam', '1KI', 16, 12, 'Nzimili aananga nyũmba yonthe ya Mbaasa o ta ũu, kwĩanana na ndeto ya Yeova, ĩla waneenee Mbaasa na kanyw’a wa mwathani Yeu,'),
('kam', '1KI', 16, 13, 'nũndũ wa naĩ syonthe sya Mbaasa, na naĩ sya Ela mwana wake, ila mavĩtisye, na ila mavĩtĩthisye Isilaeli nasyo, makĩmũthatya Yeova, Ngai wa Isilaeli, na maũndũ moo ma mana.'),
('kam', '1KI', 16, 14, 'Na ĩndĩ meko ala angĩ ma Ela, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 16, 15, 'Mwaka wa mĩongo ĩlĩ na mũonza wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Nzimili asumbĩka mĩthenya mũonza ku Tilisa. Na ĩndĩ andũ maĩ manamba maeema moo mataũĩĩe Ngivethoni, ĩla yaĩ ya Avilisiti.'),
('kam', '1KI', 16, 16, 'Na andũ ala maĩ mwakonĩ wa maeema meew’a kũkyaw’a, Nzimili nũnamũsamĩe, o na nũnamũaie mũsumbĩ: kwondũ wa ũu Isilaeli onthe mũthenya ũsu mamũtw’a Omili, kavuteni wa nguthu, mũsumbĩ wa Isilaeli me ku mwakonĩ wa maeema.'),
('kam', '1KI', 16, 17, 'Na Omili ambata kuma Ngivethoni, na Isilaeli onthe vamwe nake, na mathyũlũlũka Tilisa mamĩtw’ĩkanĩsye.'),
('kam', '1KI', 16, 18, 'Na kweethĩwa, yĩla Nzimili wonie ndũa nĩyakwatwa, alika nthĩnĩ wa nyũmba nene yĩ kĩemo yĩ nyũmbanĩ ya mũsumbĩ, na amĩvĩvĩlya ĩla nyũmba ya mũsumbĩ ĩũlũ wake mwene, na akw’a,'),
('kam', '1KI', 16, 19, 'nũndũ wa naĩ syake ila wavitisye akĩka ũla Yeova wonaa wĩ ũthũku, kwondũ wa kũthi mũendelenĩ wa Yelovoamu, na naĩnĩ yake ĩla wekaa, amavĩtĩthye Isilaeli.'),
('kam', '1KI', 16, 20, 'Na ĩndĩ meko ala angĩ ma Nzimili, na ũvingan’yo wake ũla weekie, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 16, 21, 'Nĩvo ĩndĩ andũ ma Isilaeli meeaanisye nguthu ilĩ: nyunzu ya andũ yamũatĩĩa Tivini mwana wa Nginathi, mamũtw’ĩkĩthye mũsumbĩ; na nyunzu yaatĩĩa Omili.'),
('kam', '1KI', 16, 22, 'Ĩndĩ andũ ala mamũatĩĩe Omili mamakĩlya vinya andũ ala mamũatĩĩe Tivini mwana wa Nginathi: kwondũ wa ũu Tivini akw’a, na Omili asumbĩka.'),
('kam', '1KI', 16, 23, 'Mwaka wa mĩongo ĩtatũ na ũmwe wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Omili ambĩlĩlya kũsumbĩka Isilaeli, na asumbĩka myaka ĩkũmi na ĩlĩ: asumbĩka myaka thanthatũ Tilisa.'),
('kam', '1KI', 16, 24, 'Na athooa kwa Semeli kĩĩma kya Samalia na thooa wa talendi ilĩ sya vetha; na aaka ku kĩĩmanĩ, na eeta syĩtwa ya ndũa ĩla wakie Samalia, kwĩtanĩsya na syĩtwa ya Semeli, mwene wa kĩĩma.'),
('kam', '1KI', 16, 25, 'Na Omili eekaa ũla Yeova wonaa wĩ ũthũku, na eekaa ũthũku kũvĩtũka onthe ala maĩ mbee wake.'),
('kam', '1KI', 16, 26, 'Nũndũ aendaa mũendelenĩ w’onthe wa Yelovoamu mwana wa Nevati, na naĩnĩ syake ila wamavĩtĩthisye Isilaeli nasyo, akĩthatya Yeova, Ngai wa Isilaeli, na maũndũ moo ma mana.'),
('kam', '1KI', 16, 27, 'Na ĩndĩ meko ala angĩ ma Omili ala wekaa, na vinya wake mũnene ũla wonanisye, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 16, 28, 'Na ĩndĩ Omili akoma na aaĩthe make, na athikwa Samalia; na Aavu mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 16, 29, 'Na mwaka wa mĩongo ĩtatũ na nyanya wa kũsumbĩka kwa Asa mũsumbĩ wa Yuta Aavu mwana wa Omili ambĩlĩlya kũsumbĩka Isilaeli: na Aavu mwana wa Omili asumbĩka Isilaeli ku Samalia myaka mĩongo ĩlĩ na ĩlĩ.'),
('kam', '1KI', 16, 30, 'Na Aavu mwana wa Omili eekaa ũla Yeova wonaa wĩ ũthũku kũvĩtũka onthe ala maĩ mbee wake.'),
('kam', '1KI', 16, 31, 'Na kweethĩwa, o ta kaĩ waĩ ũndũ ũnini kwake kũendaa naĩnĩ sya Yelovoamu mwana wa Nevati, atĩ atwaa Yeseveli mwĩĩtu wa Ethimbaali mũsumbĩ wa Asitoni, na athi athũkũma Mbaali, na amĩthaitha.'),
('kam', '1KI', 16, 32, 'Na amyakĩa Mbaali kĩthembeo nyũmbanĩ ya Mbaali, ĩla wakĩte Samalia.'),
('kam', '1KI', 16, 33, 'Na Aavu aseũvya Asela; na Aavu ongeleela mũni mbee kũmũthatya Yeova, Ngai wa Isilaeli, kũvĩtũka asumbĩ onthe ma Isilaeli ala maĩ mbee wake.'),
('kam', '1KI', 16, 34, 'Mĩthenyanĩ yake Ieli Mũmbethi‐eli aaka Yeliko: akwatya wambĩlĩyo wayo na kũkw’ĩĩwa nĩ ĩkithathi yake, Avilamu, na aũngamya mbingĩlo syayo na kũkw’ĩĩwa nĩ ĩlumaita yake ya mũndũ mũũme, Sekuvu, kwĩanana na ndeto ya Yeova, ĩla waneenie na kanyw’a wa Yosua mwana wa Nuni.'),
('kam', '1KI', 17, 1, 'Na Eliya Mũtisivi, ũla waĩ wa ekali ma ũeninĩ ma Ngileati, amwĩa Aavu, O tondũ Yeova, Ngai wa Isilaeli, wĩ thayũ, ũla nĩũngamaa mbee wake, kũtikethĩwa ĩmwe kana mbua myaka ĩno, ate o kwĩanana na ndeto yakwa.'),
('kam', '1KI', 17, 2, 'Na ndeto ya Yeova yamũkĩa, ĩkĩmwĩa,'),
('kam', '1KI', 17, 3, 'Uma vaa, ĩthyũũe ũende ngalĩ ya wumĩlonĩ wa syũa, ũkevithe ũtee wa kalũsĩ ketawa Kelithi, kala ke mbee wa Yolotani.'),
('kam', '1KI', 17, 4, 'Na ũkeethĩawa ũkĩnyusaa ma kala kalũsĩ; na nĩnĩaĩĩte ngũngũũ ikũathĩĩasye vo.'),
('kam', '1KI', 17, 5, 'Na ĩndĩ athi na eeka kwĩanana na ndeto ya Yeova; nũndũ nĩwaendie na ekala ũtee wa kalũsĩ ka Kelithi, kala ke mbee wa Yolotani.'),
('kam', '1KI', 17, 6, 'Na ngũngũũ syamũeteae imũtũ na nyama kĩoko, na imũtũ na nyama wĩoo; na anyusaa ma kalũsĩ.'),
('kam', '1KI', 17, 7, 'Na kweethĩwa ĩtinanga, kala kalũsĩ kang’ala, nũndũ kũtyaĩ mbua nthĩ ĩsu.'),
('kam', '1KI', 17, 8, 'Na ndeto ya Yeova yamũkĩa, ĩkĩmwĩa,'),
('kam', '1KI', 17, 9, 'Ũkĩla, ũende Nzalevathi, yĩ ku Sitoni, nokĩkala kw’o: sisya, nĩnĩaĩĩte mũndũ mũka ndiwa wĩ kw’o eĩanĩasya mavata maku.'),
('kam', '1KI', 17, 10, 'Na ĩndĩ ookĩla athi Nzalevathi; na yĩla wavikie mbingĩlonĩ ya ndũa, sisya, mũndũ mũka ndiwa aĩ vo aikolan’ya ngũ: na amwĩta, na amwĩa, Nĩngũkwĩsũva, ndetee manzĩ manini me kavũngũlyũnĩ, nĩnyw’e.'),
('kam', '1KI', 17, 11, 'Na aendete kũmalatya, amwĩta, na amwĩa, Nĩngũkwĩsũva, ndetee kalungu ka kĩmũtũ ke kw’okonĩ kwaku.'),
('kam', '1KI', 17, 12, 'Na amũsũngĩa, O tondũ Yeova Ngai waku wĩ thayũ, ndi na kamũtũ, ĩndĩ no kamũtu ka ũvĩ ke mũtũnginĩ, na mauta manini me sũvanĩ: na sisya, nĩkolanasya tũlũkũ twĩlĩ, nĩ kana nĩsyoke nĩseũvye kwondũ wakwa na mwana wakwa, tũye, na tũikw’a.'),
('kam', '1KI', 17, 13, 'Na Eliya amwĩa, Ndũkakĩe; enda wĩke o tondũ wasya; ĩndĩ amba ũnzeũvĩsya kamũtũ kanini, noĩmbumaalĩlya na ĩtina ũiseũvya kwondũ waku na mwana waku.'),
('kam', '1KI', 17, 14, 'Nũndũ ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Mũtũngi wa mũtu ndũkathela, o na sũva wa maũta maikanyiva, kũvika mũthenya ũla Yeova ũkausya mbua ĩũlũ wa nthĩ.'),
('kam', '1KI', 17, 15, 'Na athi na eeka kwĩanana na ndeto ya Eliya: na we, na Eliya, na nyũmba yake, maie mĩthenya mingĩ.'),
('kam', '1KI', 17, 16, 'Mũtũngi wa mũtu ndwaathela, o na sũva wa mauta matyaanyiva, kwĩanana na ndeto ya Yeova, ĩla waneenie na kanyw’a wa Eliya.'),
('kam', '1KI', 17, 17, 'Na kweethĩwa ĩtina wa maũndũ asu, mwana wa mũndũ mũka ũsu, mwene wa nyũmba, awaa; na ũwau wake waĩ mũnene, kũvika veva wamũthela.'),
('kam', '1KI', 17, 18, 'Na amwĩa Eliya, Nĩ ũndũ naku wa kĩ, we mũndũ wa Ngai? Nĩwookie kwakwa ũndilikan’ye naĩ yakwa, na kũaa mwana wakwa!'),
('kam', '1KI', 17, 19, 'Nake amwĩa, Nenga mwana waku. Na amwosa kuma kĩthũinĩ kyake, na amũtwaa kasũmbanĩ ka ĩũlũ, kala wekalaa, na amwia ũkomonĩ wake mwene.'),
('kam', '1KI', 17, 20, 'Na amwĩkaĩla Yeova, na amwĩa, Ame Yeova Ngai wakwa, o na nũmũetee ũthũku mũndũ mũka ndiwa ũla nĩkalaa ũeni kwake, ũkyũaa mwana wake?'),
('kam', '1KI', 17, 21, 'Na eekomya etambũũkĩtye ĩũlũ wa mwana mavinda atatũ, na amwĩkaĩla Yeova, na amwĩa, Ame Yeova Ngai wakwa, nĩngũkwĩsũva, thayũ wa mwana ũũ ũsyoke nthĩnĩ wake ĩngĩ.'),
('kam', '1KI', 17, 22, 'Na Yeova eethukĩĩsya wasya wa Eliya; na thayũ wa mwana wasyoka nthĩnĩ wake ĩngĩ, nake athayũũka.'),
('kam', '1KI', 17, 23, 'Na Eliya oosa mwana, na atheea nake kuma kasũmbanĩ kũlika nyũmbanĩ, na amũnenga inyia wake; na Eliya amwĩa, Sisya, mwana waku e thayũ.'),
('kam', '1KI', 17, 24, 'Na mũndũ mũka amwĩa Eliya, Yu nĩngũmanya wĩ mũndũ wa Ngai, na ndeto ya Yeova kanyw’anĩ waku nĩ w’o.'),
('kam', '1KI', 18, 1, 'Na kweethĩwa ĩtina wa mĩthenya mingĩ, ndeto ya Yeova yamũkĩa Eliya, mwaka wa katatũ, ĩkĩmwĩa, Enda, ũkeyumbũe kwa Aavu; na ngausya mbua ĩũlũ wa nthĩ.'),
('kam', '1KI', 18, 2, 'Na Eliya athi eeyumbũa kwa Aavu. Na yũa yaĩ ĩnene Samalia.'),
('kam', '1KI', 18, 3, 'Na Aavu amwĩta Ovatia, ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba yake. (Na Ovatia amũkĩĩte Yeova mũno:'),
('kam', '1KI', 18, 4, 'nũndũ kweethĩiwe, yĩla Yeseveli wavetie athani ma Yeova, Ovatia oosa athani ĩana, na amavitha mĩongo ĩtano, mĩongo ĩtano, ngunganĩ, na amathĩasya imũtũ na manzĩ.)'),
('kam', '1KI', 18, 5, 'Na Aavu amwĩa Ovatia, Anganga ĩ nthĩ kw’onthe, ũvike nthongonĩ syonthe sya manzĩ, na tũlũsĩnĩ tw’onthe: nokwĩthĩwa tũkona nyeki na kũvĩtya mbalasi na nyũmbũ, tũtikasye nyamũ syonthe.'),
('kam', '1KI', 18, 6, 'Kwondũ wa ũu meeaan’ya nthĩ mamyangange kw’onthe: Aavu athi na nzĩa ĩmwe e weka, na Ovatia athi na nzĩa ĩngĩ e weka.'),
('kam', '1KI', 18, 7, 'Na yĩla Ovatia waĩ nzĩanĩ, sisya, Eliya akomana nake: na amũmanya, na avalũka na ũthyũ wake, na amũkũlya, Nue mwĩaĩi wakwa Eliya?'),
('kam', '1KI', 18, 8, 'Na amũsungĩa, Ninyie: enda, ũmwĩe mwĩaĩi waku, Sisya, Eliya e vaa.'),
('kam', '1KI', 18, 9, 'Na amwĩa, Nĩvĩtĩtye ũndũnĩ mwaũ, kana wende kũnengane mũthũkũmi waku kw’okonĩ kwa Aavu, ambũae?'),
('kam', '1KI', 18, 10, 'O tondũ Yeova Ngai waku wĩ thayũ, vati mbaĩ kana ũsumbĩ, vala mwĩaĩi wakwa ũtatũmanĩte ũmanthwe: na yĩla masya, Nde vaa, aiavĩthya ũsumbĩ na mbaĩ kĩavo kana matyaakwona.'),
('kam', '1KI', 18, 11, 'Na yu wĩasya, Enda, ũmũtavye mwĩaĩi waku, Sisya, Eliya e vaa.'),
('kam', '1KI', 18, 12, 'Na kwĩĩthĩwa, o nauma vala ũĩ, Veva wa Yeova akakũtwaa vala ndesĩ; na ĩndĩ yĩla nĩvĩka na kũmũtavya Aavu, nake ndakatonya ũkwona, akambũaa: ĩndĩ nyie mũthũkũmi waku nĩnĩmũkĩaa Yeova kuma wana wakwa.'),
('kam', '1KI', 18, 13, 'Mwĩaĩi wakwa ndaatavw’a ũndũ neekie yĩla Yeseveli woaie athani ma Yeova, ũndũ navithie andũ ĩana athani ma Yeova mĩongo ĩtano, mĩongo ĩtano, ngunganĩ, na namathĩasya imũtũ na manzĩ?'),
('kam', '1KI', 18, 14, 'Na yu wĩasya, Enda, ũmwĩe mwĩaĩi waku, Sisya, Eliya e vaa; na akambũaa.'),
('kam', '1KI', 18, 15, 'Na Eliya asya, O tondũ Yeova wa nguthu wĩ thayũ, ũla nĩũngamaa mbee wake, vate ndĩi ngeeyumbũa kwake ũmũnthĩ.'),
('kam', '1KI', 18, 16, 'Na ĩndĩ Ovatia athi akomane na Aavu, na amũtavya; na Aavu aenda akomane na Eliya.'),
('kam', '1KI', 18, 17, 'Na kweethĩwa, yĩla Aavu wonie Eliya, Aavu amũkũlya, Nue, we mũthĩn’ya wa Isilaeli?'),
('kam', '1KI', 18, 18, 'Na asũngĩa, Ndyaathĩn’ya Isilaeli, ĩndĩ nue, na nyũmba ya au, nũndũ nũtiĩte mĩao ya Yeova, na nũatĩĩe Mbaalimu.'),
('kam', '1KI', 18, 19, 'Kwondũ wa ũu yu tũmana, noimbũmbanĩsya Isilaeli onthe kĩĩmanĩ kya Kalimeli, na athani ma Mbaali maana ana na mĩongo ĩtano, na athani ma Asela maana ana, ala maĩsaa mesanĩ ya Yeseveli.'),
('kam', '1KI', 18, 20, 'Kwondũ wa ũu Aavu atũmana ana onthe ma Isilaeli, na oomban’ya athani kĩĩmanĩ kya Kalimeli.'),
('kam', '1KI', 18, 21, 'Na Eliya athengeea andũ onthe, na akũlya, Mũkaendaa mũkĩthua katĩ wa ngalĩ ilĩ ĩvinda yĩana ata? Ethĩwa Yeova nĩwe Ngai, mũatĩĩei; ĩndĩ ethĩwa nĩ Mbaali, mũatĩĩei ĩndĩ. Na andũ matyaamũsũngĩa ndeto.'),
('kam', '1KI', 18, 22, 'Nĩvo ĩndĩ Eliya wameie andũ, Nyie, o nyie nĩ nyioka, nĩtialĩte mwathani wa Yeova; ĩndĩ athani ma Mbaali nĩ andũ maana ana na mĩongo ĩtano.'),
('kam', '1KI', 18, 23, 'Kwondũ wa ũu nĩmatũnenge tũsalũ twĩlĩ twa mũew’a; na manyuve kasalũ kamwe kwondũ woo ene, na makatilange ilungu, na kwilĩĩla ĩũlũ wa ngũ, na matikekĩe mwaki ungu; nakwa ngathĩnza kasalũ kala kangĩ, na ngakailĩĩla ĩũlũ wa ngũ, na ndikekĩa mwaki ungu.'),
('kam', '1KI', 18, 24, 'Nenyu ĩkaĩlei syĩtwa ya ngai yenyu, nakwa ngeekaĩla syĩtwa ya Yeova: na Ngai ũla wĩsũngĩa na mwaki, nĩethĩwe Ngai. Na andũ onthe masũngĩa na masya, Nĩkwaw’a nesa.'),
('kam', '1KI', 18, 25, 'Na Eliya amea athani ma Mbaali, Ĩnyuvĩei kasalũ kamwe, na mũkyamba kũkathĩnza; nũndũ inyw’ĩ mwĩ aingĩ; na ĩkaĩlei syĩtwa ya ngai yenyu, ĩndĩ mũtikekĩe mwaki ungu.'),
('kam', '1KI', 18, 26, 'Na moosa kasalũ kala manengiwe, na makathĩnza na meekaĩla syĩtwa ya Mbaali kuma kĩoko o kũvika katambanga, makyasya, We, Mbaali, twĩw’e. Ĩndĩ vatyaĩ wasya, kana ũmwe waasũngĩa. Na matũlĩla makĩthyũlũlũka kĩthembeo kĩla kyaseũviw’e.'),
('kam', '1KI', 18, 27, 'Na kweethĩwa katambanga, Eliya amathekeea na kĩvũthya, na asya, Ũkĩlyai wasya mũnene; nũndũ nake nĩ ngai: no ũnũkũsũanĩa, kana nĩwathũkĩte vandũ, kana nũendete kyalo, kana nokwĩthĩwa akomete na mũvaka aamũkw’e.'),
('kam', '1KI', 18, 28, 'Na mookĩlya wasya mũnene, na meetemanga na tũvyũ na tũwenzi o tondũ mekaa, mũvaka nthakame yamanyũlũlũkĩla mũno.'),
('kam', '1KI', 18, 29, 'Na kweethĩwa, kwathonoka katambanga, mathana kũvika ĩvinda ya kũthemba nthembo ya wĩoo; ĩndĩ vatyaĩ wasya, kana wa kũsungĩa o na wĩva, kana ũla waaona ta ũndũ.'),
('kam', '1KI', 18, 30, 'Na Eliya amea andũ onthe, Nthengeeai; na andũ onthe mamũthengeea. Na atũngĩĩa kĩthembeo kya Yeova kĩla kyaĩ kĩomboe.'),
('kam', '1KI', 18, 31, 'Na Eliya oosa mavia ĩkũmi na elĩ, kwĩanana na ũtalo wa mbaĩ sya ana ma Yakovo, ũla ndeto ya Ngai yamũkĩe, ĩkĩmwĩa, Syĩtwa yaku yĩkeethĩwa Isilaeli.'),
('kam', '1KI', 18, 32, 'Na aaka kĩthembeo na mavia asu syĩtwanĩ ya Yeova; na enza mũtaũ kũthyũlũlũka kĩthembeo, mũnene ũndũ ũtonya kwĩanĩa ithimi ilĩ sya mbeũ.'),
('kam', '1KI', 18, 33, 'Na aĩĩa ngũ, na atilanga kala kasalũ ilungu, na ailĩĩla ĩũlũ wa i ngũ. Na asya, Usũsyai mĩtũngi ĩna manzĩ, na mũkĩtulũla ĩũlũ wa nthembo ya kũvĩvw’a, na ĩũlũ wa ngũ.'),
('kam', '1KI', 18, 34, 'Na amea, Ĩkai ũu ĩvinda ya kelĩ; na meeka ũu ĩvinda ya kelĩ. Na amea, Ĩkai ũu ĩvinda ya katatũ; na meeka ũu ĩvinda ya katatũ.'),
('kam', '1KI', 18, 35, 'Na manzĩ meeyangalya ũtee wa kĩthembeo; na ausũsya mũtaũ naw’o manzĩ.'),
('kam', '1KI', 18, 36, 'Na kweethĩwa ĩvinda ya kũthemba nthembo ya wĩoo, mwathani Eliya athengeea, na asya, Ame Yeova, Ngai wa Avalaamu, na wa Isaka, na wa Isilaeli, nĩkũmanyĩke ũmũnthĩ kana wĩ Ngai nthĩnĩ wa Isilaeli, na kana nyie nĩ mũthũkũmi waku, na nĩneeka maũndũ aa onthe kwondũ wa ndeto yaku.'),
('kam', '1KI', 18, 37, 'Mbĩthukĩĩsya, ame Yeova, mbĩthukĩĩsya, nĩ kana andũ aa mamanye kana we, Yeova, nue Ngai, na nũalyũlĩte ngoo syoo ĩngĩ.'),
('kam', '1KI', 18, 38, 'Nĩvo ĩndĩ mwaki wa Yeova watheeie, na wavĩvya nthembo ya kũvĩvw’a, na ngũ, na mavia, na kĩtoo, na wanyenya manzĩ ala maĩ mũtaũnĩ.'),
('kam', '1KI', 18, 39, 'Na yĩla andũ onthe moonie ũu, mavalũka na mothyũ moo: na masya, Yeova, nĩwe Ngai; Yeova, nĩwe Ngai.'),
('kam', '1KI', 18, 40, 'Na Eliya amea, Makwatei athani ma Mbaali; mũtikaeke ũmwe avonoke. Na mamakwata; na Eliya amatheesya kalũsĩnĩ ka Kisoni, na amoaĩa vo.'),
('kam', '1KI', 18, 41, 'Na Eliya amwĩa Aavu, Ambata, ũye na kũnyw’a; nũndũ we kĩuumo kya mbua mbingĩ.'),
('kam', '1KI', 18, 42, 'Kwondũ wa ũu Aavu ambata aye na kũnyw’a. Na Eliya ambata mũtumbĩnĩ wa Kalimeli; na eekunamya nthĩ, na eekĩa ũthyũ wake katĩ wa mau make.'),
('kam', '1KI', 18, 43, 'Na amwĩa mũthũkũmi wake, Ambata yu, ũsisye kwelekela ũkanganĩ. Na ambata, na asisya, na asya, Vati kĩndũ. Na amwĩa, Enda ĩngĩ mavinda mũonza.'),
('kam', '1KI', 18, 44, 'Na kweethĩwa ĩvinda ya mũonza, asya, Sisya, nĩkũũkĩla kathweo kuma ũkanganĩ, kanini ta kĩtaa kya mũndũ. Na asya, Ambata, ũmwĩe Aavu, Ova ĩkasya yaku, noitheea, nĩ kana mbua ndĩkakũsiĩĩe.'),
('kam', '1KI', 18, 45, 'Na kweethĩwa o kavinda kanini, matu maia kwondũ wa mathweo na kĩseve, na kwaĩ mbua nene. Na Aavu aenda akuĩtwe, na avika ku Yesileeli;'),
('kam', '1KI', 18, 46, 'na kw’oko kwa Yeova kwaĩ ĩũlũ wa Eliya; na eevotoa kĩnyunyu kyake, na asemba mbee wa Aavu ũlikĩlonĩ wa Yesileeli.'),
('kam', '1KI', 19, 1, 'Na Aavu amũtavya Yeseveli w’onthe ũla Eliya wĩkie, o na ũndũ wũaie athani onthe na ũvyũ.'),
('kam', '1KI', 19, 2, 'Nĩvo ĩndĩ Yeseveli watũmie mũtũmwa vala ve Eliya, akĩmwĩa, Ngai nimbĩke ũu, o na mbee, ethĩwa nditw’ĩkĩthya thayũ waku ta thayũ wa ũmwe wa asu ũnĩ ta yu.'),
('kam', '1KI', 19, 3, 'Na yĩla wonie ũu, ookĩla, na aenda atangĩĩe thayũ wake, na avika Mbeeli‐sieva, ĩla ya Yuta, na amũtia mũthũkũmi wake kw’o.'),
('kam', '1KI', 19, 4, 'Ĩndĩ we mwene athi kyalo kya mũthenya ũmwe weũnĩ, na avika na ekala nthĩ ĩtina wa mũtĩ wa mũlutemu: na eevoyea akw’e, na asya, Nũu; yu, ame Yeova, osa thayu wakwa; nũndũ ndi mũseo kwĩ aaĩthe makwa.'),
('kam', '1KI', 19, 5, 'Na akoma too ĩtina wa mũtĩ wa mũlutemu; na, sisya, mũlaĩka amũkiita, na amwĩa, Ũkĩla ũye.'),
('kam', '1KI', 19, 6, 'Na asisya, na, kaĩ, kwaĩ kamũtũ kakaangĩwe makaanĩ, o na sũva wa manzĩ mũtwenĩ wake. Na aya na anyw’a, na akoma ĩngĩ.'),
('kam', '1KI', 19, 7, 'Na mũlaĩka wa Yeova ooka ĩngĩ ya kelĩ, na amũkiita, na amwĩa, Ũkĩla ũye, nũndũ kyalo nĩ kĩvĩtũku vinya waku.'),
('kam', '1KI', 19, 8, 'Na ookĩla, na aya na anyw’a, na aenda na vĩnya wa lĩu ũsu mĩthenya mĩongo ĩna na matukũ mĩongo ĩna kũvika Olevu kĩĩma kya Ngai.'),
('kam', '1KI', 19, 9, 'Na avika vau ngunganĩ, na akoma vo; na, sisya, ndeto ya Yeova yamũkĩa, na amũkũlya, Wĩĩka ata vaa, Eliya?'),
('kam', '1KI', 19, 10, 'Na asũngĩa, Nĩnaĩ na kĩwĩu kingĩ kwondũ wa Yeova, Ngai wa nguthu; nũndũ ana ma Isilaeli nĩmatiĩte ũtianĩo waku, na maomboangĩte ithembeo syaku, na moaĩte athani maku na ũvyũ: na nyie, o nyie nĩ nyioka, nĩtialĩte; na nĩmeũmantha thayũ wakwa, movete.'),
('kam', '1KI', 19, 11, 'Na asya, Umaala, noiũngama kĩĩmanĩ mbee wa Yeova. Na, sisya, Yeova avĩta, na kĩseve kĩnene na kĩ vinya kyaatũa iĩma, na kyaatũanga mavia ilungu mbee wa Yeova; ĩndĩ Yeova ndaĩ kĩsevenĩ: na ĩtina wa kĩseve kwaĩ kĩtetemo kya nthĩ; ĩndĩ Yeova ndaĩ kĩtetemonĩ kya nthĩ:'),
('kam', '1KI', 19, 12, 'na ĩtina wa kĩtetemo kya nthĩ kwaĩ mwaki; ĩndĩ Yeova ndaĩ mwakinĩ: na ĩtina wa mwaki kwaĩ wasya mũnini mũuu.'),
('kam', '1KI', 19, 13, 'Na kweethĩwa, yĩla Eliya wawĩwie, alingĩla ũthyũ wake suka wake, na aumaala, na aũngama ũlikĩlonĩ wa ngunga. Na sisya, ookĩwa nĩ wasya, naw’o wasya, Wĩĩka ata vaa, Eliya?'),
('kam', '1KI', 19, 14, 'Nake asũngĩa, Nĩnaĩ na kĩwĩu kingĩ kwondũ wa Yeova, Ngai wa nguthu; nũndũ ana ma Isilaeli nĩmatiĩte ũtianĩo waku, na maomboangĩte ithembeo syaku, na moaĩte athani maku na ũvyũ; na nyie, o nyie nĩ nyioka, nĩtialĩte; na nĩmeũmantha thayũ wakwa, movete.'),
('kam', '1KI', 19, 15, 'Na Yeova amwĩa, Enda, syoka na nzĩa yaku ya weũnĩ wa Ndamasiku: na yĩla wĩvika kw’o, ũkamwĩtĩkĩsye Aasaeli mauta ethĩwe mũsumbĩ wa Silia;'),
('kam', '1KI', 19, 16, 'na ũkamwĩtĩkĩsye Yeu mwana wa Nimisi mauta ethĩwe mũsumbĩ wa Isilaeli; na ũkamwĩtĩkĩsye Elisa mwana wa Savati wa Avelimeola mauta ethĩwe mwathani vandũ vaku.'),
('kam', '1KI', 19, 17, 'Na kũkeethĩwa, ũla wĩvonoka ũvyũnĩ wa Aasaeli Yeu akamũaa; na ũla wĩvonoka ũvyũnĩ wa Yeu Elisa akamũaa.'),
('kam', '1KI', 19, 18, 'Ĩndĩ ngeetialĩlya ngili mũonza nthĩnĩ wa Isilaeli, ala ndu syoo syonthe itaatulĩlya Mbaali, na kĩla kanyw’a ũtaamĩmumunya.'),
('kam', '1KI', 19, 19, 'Na ĩndĩ auma vo, na oona Elisa mwana wa Savati, ũla wenzaa, e na syove ĩkũmi na ilĩ sya ng’ombe syĩ mbee wake, nake e o na kĩla kya ĩkũmi na ilĩ: na Eliya avĩtĩla vala ũĩ, na amwĩkĩsya suka wake.'),
('kam', '1KI', 19, 20, 'Na atia ng’ombe, na amũatĩĩa Eliya asembete, na asya, Nĩngũkwĩsũva, ndeka nĩende kũmamumunya nau na mwaitũ, na ĩndĩ ngakũatĩĩa. Na amwĩa, Syoka ĩngĩ; nũndũ nakwĩka ata?'),
('kam', '1KI', 19, 21, 'Na asyoka aeka ũmũatĩĩa, na oosa kyove kya ng’ombe, na asyũaa, na aua nyama syasyo na mĩio ya ila ng’ombe, na anenga andũ, na maya. Na ĩndĩ ookĩla, na amũvikĩla Eliya, na amũthũkũma.'),
('kam', '1KI', 20, 1, 'Na Mbeni‐aatati mũsumbĩ wa Silia oomban’ya nguthu yake onthe vamwe; na vamwe nake kwaĩ asumbĩ mĩongo ĩtatũ na elĩ, na mbalasi na makasya ma kaũ: na ambata na athyũlũlũka Samalia amĩtw’ĩkanĩsye, na okita nayo.'),
('kam', '1KI', 20, 2, 'Na atũma atũmwa kwa Aavu mũsumbĩ wa Isilaeli, ndũanĩ nthĩnĩ, na amwĩa, Ũũ nĩw’o Mbeni‐aatati ũnũkwasya,'),
('kam', '1KI', 20, 3, 'Vetha waku na thaavu waku nĩ wakwa; o na iveti syaku na syana syaku, o ila nzeo mbee, nĩ syakwa.'),
('kam', '1KI', 20, 4, 'Na mũsumbĩ wa Isilaeli asũngĩa na asya, No kwĩanana na ndeto yaku, mwĩaĩi wakwa, ame mũsumbĩ; nyie nĩ waku, na syonthe ila nĩ nasyo.'),
('kam', '1KI', 20, 5, 'Na atũmwa mooka ĩngĩ, na masya, Ũũ nĩw’o Mbeni‐aatati ũnũũneena, aikwĩa, Nĩ w’o, nĩnatũmana kwaku, ngĩkwĩa, Ũnenge vetha waku, na thaavu waku, na iveti syaku, na syana syaku;'),
('kam', '1KI', 20, 6, 'ĩndĩ ngatũma athũkũmi makwa kwaku ũnĩ saa ũũ, na makamantha nyũmbanĩ yaku, na nyũmbanĩ sya athũkũmi maku; na kũkeethĩwa, atĩ kĩndũ o na kĩva kĩla kyendeeasya metho maku, makoosa na moko moo, na maikua.'),
('kam', '1KI', 20, 7, 'Nĩvo ĩndĩ mũsumbĩ wa Isilaeli wetie atumĩa onthe ma nthĩ ĩsu, na amea, Sũanĩai, nĩngũmwĩsũva, nĩmwene ũndũ mũndũ ũũ ũnũũmantha kwĩka ũndũ ũthũku: nũndũ nũnatũmanie kwakwa ose iveti syakwa, na syana syakwa, na vetha wakwa, na thaavu wakwa; na ndyaamũvata.'),
('kam', '1KI', 20, 8, 'Na atũmĩa onthe na andũ onthe mamwĩa, Ndũkethukĩĩsye, kana kwĩtĩkĩla.'),
('kam', '1KI', 20, 9, 'Kwondũ wa ũu amea atũmwa ma Mbeni‐aatati, Mũtavyei mwĩaĩi wakwa mũsumbĩ, Kyonthe kĩla wambie kũtũmana kwa mũthũkũmi waku ngeeka; ĩndĩ ũndũ ũũ nditonya kwĩka. Na atũmwa mathi, na mamũtũngĩa ndeto ĩngĩ.'),
('kam', '1KI', 20, 10, 'Na Mbeni‐aatati atũmana kwake, na asya, Ngai nimbĩke ũu, o na mbee, ethĩwa kĩtoo kya Samalia kĩkeanĩa mbĩ sya andũ onthe ala mangatĩĩe.'),
('kam', '1KI', 20, 11, 'Na mũsumbĩ wa Isilaeli asũngĩa na asya, Mũtavyei, Ũla wĩvotoaa mĩio yake ya kaũ ndakekathũe ta ũla wĩvotookya.'),
('kam', '1KI', 20, 12, 'Na kweethĩwa, yĩla Mbeni‐aatati wewie ũtũmane ũsu, akĩnyw’a, we na asumbĩ malwandanĩ, amea athũkũmi make, Ĩtaũsyei. Na meetaũsya mokite na ĩ ndũa.'),
('kam', '1KI', 20, 13, 'Na, sisya, mwathani amũthengeea Aavu mũsumbĩ wa Isilaeli, na amwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩwene nguthu ĩno yonthe nene? Sisya, nĩmĩnengane kw’okonĩ kwaku ũmũnthĩ; na ũkamanya ninyie Yeova.'),
('kam', '1KI', 20, 14, 'Na Aavu akũlya, Naaũ? Nake asya, Uũ nĩw’o Yeova ũnũkwasya, Na anake ma anene me mbee ũsumbĩnĩ ma mbalo sya ĩ nthĩ. Nĩvo ĩndĩ wakũlilye, Nũũ wĩkwatya kaũ? Nake asũngĩa, Nũe.'),
('kam', '1KI', 20, 15, 'Na ĩndĩ oomban’ya anake ma anene me mbee ũsumbĩnĩ ma mbalo sya ĩ nthĩ, na maĩ maana elĩ na mĩongo ĩtatũ na elĩ: na ĩtina wa asu oomban’ya andũ onthe, o ana onthe ma Isilaeli, nao maĩ ngili mũonza.'),
('kam', '1KI', 20, 16, 'Na maumaala katambanga. Ĩndĩ Mbeni‐aatati anyw’ĩte akalooteka e malwandanĩ, we na asumbĩ, asumbĩ mĩongo ĩtatũ na elĩ ala mamũtetheesye.'),
('kam', '1KI', 20, 17, 'Na anake ma anene me mbee ũsumbĩnĩ ma i mbalo sya nthĩ mamba kumaala; na Mbeni‐aatati atũmana, na mamwĩa, makyasya, Kwĩ andũ maumĩte Samalia.'),
('kam', '1KI', 20, 18, 'Na asya, Ethĩwa nĩmaumĩte kwondũ wa mũuo, makwatei me thayũ; kana ethĩwa nĩmaumĩte mokite, makwatei me thayũ.'),
('kam', '1KI', 20, 19, 'Kwondũ wa ũu mauma ndũanĩ, anake ma anene me mbee ũsumbĩnĩ ma i mbalo sya nthĩ, na ita ila syamaatĩĩe.'),
('kam', '1KI', 20, 20, 'Na mooaa kĩla ũmwe mũndũ wake; na Asilia makũka, na Isilaeli mamakũa: na Mbeni‐aatati mũsumbĩ wa Silia avonoka akuĩtwe nĩ mbalasi e na andũ matũlĩte mbalasi.'),
('kam', '1KI', 20, 21, 'Na mũsumbĩ wa Isilaeli aumaala na akũna mbalasi na makasya ma kaũ, na ooaa Asilia na ũai mũnene.'),
('kam', '1KI', 20, 22, 'Na ũla mwathani amũthengeea mũsumbĩ wa Isilaeli, na amwĩa, Enda, ĩyĩkĩe vinya, na sũanĩa, noisisya ũndũ ũkwĩka; nũndũ mwaka ũkyambĩlĩlya mũsumbĩ wa Silia akooka okite naku.'),
('kam', '1KI', 20, 23, 'Na athũkũmi ma mũsumbĩ wa Silia mamwĩa, Ngai yoo nĩ ngai ya iĩma; kwondũ wa ũu maĩ na vinya kwĩ ithyĩ, ĩndĩ nĩtũkitĩe nao ũiĩnĩ, na vate ndĩi tũkeethĩwa twĩ vinya kwĩ mo.'),
('kam', '1KI', 20, 24, 'Na ĩka ũndũ ũũ: veta asumbĩ vyũ, kĩla ũmwe vandũ vake, nokĩkĩa makavuteni vandũ voo;'),
('kam', '1KI', 20, 25, 'na ĩtalĩle ita, ta ita ila ũnaaisye mbalasi vandũ va mbalasi, na ĩkasya vandũ va ĩkasya; na tũkokitĩa nao ũiĩnĩ, na vate ndĩi tũkeethĩwa na vinya kwĩ mo. Na eethukĩĩsya wasya woo, na eeka ũu.'),
('kam', '1KI', 20, 26, 'Na kweethĩwa mwaka ũkyambĩlĩlya, Mbeni‐aatati oomban’ya Asilia, na ambata Aveki, okite na Isilaeli.'),
('kam', '1KI', 20, 27, 'Na ana ma Isilaeli moombanw’a, na manengwa lĩu, na mamaumaalĩla: na ana ma Isilaeli mamba maeema moo mbee woo mailyĩ ta ndĩthya ilĩ nini sya tũtena twa mbũi; ĩndĩ Asilia mausũa nthĩ.'),
('kam', '1KI', 20, 28, 'Na mũndũ wa Ngai athengeea na aneena na mũsumbĩ wa Isilaeli, na amwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩkwĩthĩwa Asilia nĩmaneenete, Yeova nĩ ngai ya iĩma, ĩndĩ ti ngai ya myanda; kwondũ wa ũu nganengane nguthu ĩno nene yonthe kw’okonĩ kwaku, na mũkamanya kana ninyie Yeova.'),
('kam', '1KI', 20, 29, 'Na mamba maeema moo melekanĩlye mĩthenya mũonza. Na ĩndĩ kweethĩwa, o mũthenya wa mũonza kaũ wakwatw’a; na ana ma Isilaeli mooaa ma Asilia andũ ala maendaa na maũũ ngili ĩana mũthenya ũmwe.'),
('kam', '1KI', 20, 30, 'Ĩndĩ ala angĩ makũka mathi Aveki, ndũanĩ nthĩnĩ; na ũvai wamavalũkĩla andũ ngili mĩongo ĩlĩ na mũonza ala matialĩte. Na Mbeni‐aatati akĩa, na alika ndũanĩ, kasũmbanĩ ka nthĩnĩ.'),
('kam', '1KI', 20, 31, 'Na athũkũmi make mamwĩa, Sisya yu, nĩtwĩw’ĩte atĩ asumbĩ ma nyũmba ya Isilaeli nĩ asumbĩ me tei: nĩtũũkwĩsũva, twĩvotoe makunia inyunyunĩ sitũ, na makanda mĩtwenĩ yaitũ, na kwĩyumĩlya kwa mũsumbĩ wa Isilaeli: nokwĩthĩwa akatangĩĩa thayũ waku.'),
('kam', '1KI', 20, 32, 'Kwondũ wa ũu meevotoa makunia inyunyu syoo, na meekĩa makanda mĩtwenĩ yoo, na mooka vala ve mũsumbĩ wa Isilaeli, na mamwĩa, Mũthũkũmi waku Mbeni‐aatati easya, Nĩngũkwĩsũva, ndeka nĩ thayũ. Na akũlya, E thayũ o na yu? Nĩ mwana‐a‐asa.'),
('kam', '1KI', 20, 33, 'Na ĩndĩ andũ asu malolonza mũno, na meekalaata kũkwata ethĩwa ũu nĩw’o ũsũanĩĩte; na masya, Mwana‐a‐au Mbeni‐aatati. Nĩvo ĩndĩ waisye, Endai mũmũete. Na ĩndĩ Mbeni‐aatati aumaala vala ũĩ: na amũlikya ĩkasyanĩ.'),
('kam', '1KI', 20, 34, 'Na Mbeni‐aatati amwĩa, Ndũa ila ĩthe wakwa wavenie ĩthe waku ngatũnga; na ũkeeseũvĩsya nzĩa Ndamasiku, o tondũ ĩthe wakwa waseũvisye Samalia. Aavu asya, Nakwa ngakũlekya ũende na ũtianĩo ũũ. Na ĩndĩ atianĩa ũtianĩo nake, na amũlekya.'),
('kam', '1KI', 20, 35, 'Na mũndũ ũmwe wa ana ma athani amwĩa mũtindan’ya wake kwondũ wa ndeto ya Yeova, Ngũna, nĩngũkwĩsũva. Na mũndũ ũsu alea kũmũkũna.'),
('kam', '1KI', 20, 36, 'Nĩvo ĩndĩ wamwĩie, Nĩkwĩthĩwa ndũnew’a wasya wa Yeova, sisya, o wauma vaa nĩĩ, mũnyambũ nũkũaa. Na o auma vala waĩ, mũnyambũ wamwona, na wamũaa.'),
('kam', '1KI', 20, 37, 'Nĩvo ĩndĩ wonie mũndũ ũngĩ, na amwĩa, Ngũna, nĩngũkwĩsũva. Na mũndũ ũsu amũkũna, o kũmũkũna na kũmũkita.'),
('kam', '1KI', 20, 38, 'Kwondũ wa ũu mwathani athi, na amweteela mũsumbĩ ũtee wa nzĩa, na eeyũlan’ya kwa kwĩvw’ĩka metho na kĩtambaa kya mũtwe.'),
('kam', '1KI', 20, 39, 'Na mũsumbĩ akĩvĩta, amwĩkaĩla mũsumbĩ; na asya, Mũthũkũmi waku nĩwaumaalile aenda kaũnĩ katĩ; na, sisya, mũndũ aathũkĩla ũtee, na andetee mũndũ, na ambĩa, Sũvĩa mũndũ ũũ: ethĩwa kwondũ wa ũndũ o na wĩva, akaaa, nĩvo ĩndĩ thayũ waku wĩĩthĩwa vandũ va thayũ wake, kana ethĩwa ti ũu ũkaĩva talendi ya vetha.'),
('kam', '1KI', 20, 40, 'Na yĩla mũthũkũmi waku wĩthĩiwe na wĩa kũũ na kũũ, aenda. Na mũsumbĩ wa Isilaeli amwĩa, Ũũ now’o ũsilĩlo waku wĩĩthĩwa; we mwene nũtwie.'),
('kam', '1KI', 20, 41, 'Na akalaata, na aumya kĩtambaa kya mũtwe methoni make; na mũsumbĩ wa Isilaeli amũmanya atĩ nĩ ũmwe wa athani.'),
('kam', '1KI', 20, 42, 'Na amwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩkwĩthĩwa nũleketye mũndũ ũla nĩvathĩte anangwe vyũ auma kw’okonĩ kwaku, kwondũ wa ũu thayũ waku ũkeethĩwa vandũ va thayũ wake, na andũ maku vandũ va andũ make.'),
('kam', '1KI', 20, 43, 'Na mũsumbĩ wa Isilaeli aenda nyũmbanĩ yake atakinyĩkya na e na woo, na avika Samalia.'),
('kam', '1KI', 21, 1, 'Na kweethĩwa ĩtina wa maũndũ asu, Navothi Mũyesileeli aĩ na mũũnda wa mĩsavivũ, ũla waĩ Yesileeli, vakuvĩ mũno na nyũmba nene mbanakavye ya Aavu mũsumbĩ wa Samalia.'),
('kam', '1KI', 21, 2, 'Na Aavu aneena na Navothi, akĩmwĩa, Nenga mũũnda waku wa mĩsavivũ nĩ kana nĩthĩwe naw’o wĩthĩwe mũũnda wa nyũnyi, nĩkwĩthĩwa wĩ vakuvĩ na nyũmba yakwa; na vandũ vaw’o ngakũnenga mũũnda mũseo wa mĩsavivũ kwĩ w’o: kana ethĩwa nũkwona nĩ ũseo, ngakũnenga mbesa sya thooa waw’o.'),
('kam', '1KI', 21, 3, 'Na Navothi amwĩa Aavu, Yeova ndakandeke nĩkũnenge ũtiĩwa ũla natiĩwe nĩ aaĩthe makwa.'),
('kam', '1KI', 21, 4, 'Na Aavu alika nyũmbanĩ yake atakinyĩkya na e na woo nũndũ wa ndeto ila Navothi Mũyesileeli wamũtavya; nũndũ nĩwasya, Ndikũnenga ũtiĩwa ũla natiĩwe nĩ aaĩthe makwa. Na akoma ũkomonĩ wake, na athyũũa ũthyũ wake, na alea kũya lĩu.'),
('kam', '1KI', 21, 5, 'Ĩndĩ Yeseveli kĩveti kyake kyamũkĩa na kyamũkũlya, Nũndũ wa kĩ veva waku wĩ na woo, ũndũ ũũlea kũya lĩu?'),
('kam', '1KI', 21, 6, 'Nake amwĩa, Nũndũ nĩnĩneenie na Navothi Mũyesileeli, na namwĩa, Nenga mũũnda waku wa mĩsavivũ ũndũ wa mbesa; kana ngũnenge mũũnda ũngĩ vandũ vaw’o, ethĩwa ũũ nũkwendeesya: na asũngĩa, Ndikũnenga mũũnda wakwa wa mĩsavivũ.'),
('kam', '1KI', 21, 7, 'Na Yeseveli kĩveti kyake kyamũkũlya, Yu nũkũsumbĩka ũsumbĩ wa Isilaeli? Ũkĩla, ũye lĩu, na tana ngoo yaku: ngakũnenga mũũnda wa mĩsavivũ wa Navothi Mũyesileeli.'),
('kam', '1KI', 21, 8, 'Na ĩndĩ aandĩka mavalũa syĩtwanĩ ya Aavu, na amasiĩla na ũsiĩlo wake, na amatwaĩa atumĩa, na anene me ndaĩa ala maĩ ndũanĩ yake, na ala matwĩe vamwe na Navothi, mavalũa asu.'),
('kam', '1KI', 21, 9, 'Na aandĩka mavalũa asu, akyasya, Tavan’yai kũtĩĩa ũya, na mwiei Navothi okĩlĩtw’e katĩ wa andũ:'),
('kam', '1KI', 21, 10, 'na iai andũ elĩ mbee wake, andũ athe, na nĩmamũkũsĩĩe, makyasya, Nĩwamũuma Ngai na mũsumbĩ. Na ĩndĩ mũmumaalyei nza, na mũimũkima na mavia akw’e.'),
('kam', '1KI', 21, 11, 'Na andũ ma ndũa yake, o atumĩa na anene me ndaĩa ala matwĩe ndũanĩ yake, meeka o tondũ Yeseveli watũmanĩte kwoo, kwĩanana na ũndũ kwaandĩkĩtwe mavalũanĩ ala wamatwaĩĩte.'),
('kam', '1KI', 21, 12, 'Matavan’ya kũtĩĩa ũya, na maia Navothi okĩlĩtw’e katĩ wa andũ.'),
('kam', '1KI', 21, 13, 'Na ala andũ elĩ, ala athe, malika na mekala nthĩ mbee wake: na andũ asu athe makũsĩĩa, o ĩũlũ wa Navothi, andũ mene, makyasya, Navothi nũmũumĩte Ngai na mũsumbĩ. Na ĩndĩ mamumaalya ũtee wa ndũa, na mamũkimanga na mavia akw’a.'),
('kam', '1KI', 21, 14, 'Nĩvo ĩndĩ matũmanie kwa Yeseveli, makĩmwĩa, Navothi nĩwakimangwa na mavia, na nĩ mũkw’ũ.'),
('kam', '1KI', 21, 15, 'Na kweethĩwa, yĩla Yeseveli wewie Navothi nĩwakimangwa na mavia, na akw’a, Yeseveli amwĩa Aavu, Ũkĩla, wose mũũnda wa mĩsavivũ wa Navothi Mũyesileeli wĩthĩwe waku, ũla waleile ũkũnenga kwondũ wa mbesa; nũndũ Navothi nde thayũ, ĩndĩ nĩ mũkw’ũ.'),
('kam', '1KI', 21, 16, 'Na kweethĩwa, yĩla Aavu wewie atĩ Navothi nĩ mũkw’ũ, Aavu ookĩla atheee mũũndanĩ wa mĩsavivũ wa Navothi Mũyesileeli, awose wĩthĩwe wake.'),
('kam', '1KI', 21, 17, 'Na ndeto ya Yeova yamũkĩa Eliya Mũtisivi, ĩkĩmwĩa,'),
('kam', '1KI', 21, 18, 'Ũkĩla, ũtheee ũkomane na Aavu mũsumbĩ wa Isilaeli, ũla ũtwĩe Samalia: sisya, e mũũndanĩ wa mĩsavĩvũ wa Navothi, vala ũtheeete awose wĩthĩwe wake.'),
('kam', '1KI', 21, 19, 'Na ũkaneene nake, ũkĩmwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩwũaĩte, o na kwosa? Na ũkaneene nake, ũkĩmwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Vandũ vala ngitĩ ĩnalambalambĩlye nthakame ya Navothi, vo ngitĩ ikalambalambĩlya nthakame yaku, o yaku.'),
('kam', '1KI', 21, 20, 'Na Aavu amũkũlya Eliya, Nũmbonete, we mũmaitha wakwa? Na asũngĩa, Nĩnĩkwonete, nĩkwĩthĩwa nĩwĩthooetye wĩke ũla Yeova wonaa wĩ ũthũku.'),
('kam', '1KI', 21, 21, 'Sisya, ngakũetee ũthũku, na ngakũtuta vyũ na ngaveta kwa Aavu kĩla mwana mũũme, na ũla wĩĩthĩwa e mwove na ũla wĩĩthĩwa ate mwove nthĩnĩ wa Isilaeli:'),
('kam', '1KI', 21, 22, 'na ngatw’ĩkĩthya nyũmba yaku ta nyũmba ya Yelovoamu mwana wa Nevati, na ta nyũmba ya Mbaasa mwana wa Aiya nũndũ wa ũthatyo ũla wanthatĩtye naw’o, na ũla wamavĩtĩthĩtye Isilaeli naw’o.'),
('kam', '1KI', 21, 23, 'O na Yeova aneena ũndũ wa Yeseveli, akyasya, Ngitĩ ikaĩĩa Yeseveli vakuvĩ na ũvai mũlũmu wa Yesileeli.'),
('kam', '1KI', 21, 24, 'Ũla wa Aavu ũla ũkakw’ĩa ndũanĩ ngitĩ ikaya; na ũla ũkakw’ĩa kĩthekanĩ nyũnyi sya yayaya ikaya.'),
('kam', '1KI', 21, 25, '(Ĩndĩ kũtyaĩ mũndũ o na wĩva wailyĩ Aavu, ũla weethooisye eke ũla Yeova wonaa wĩ ũthũku, ũla Yeseveli kĩveti kyake kyamũthokoanisye.'),
('kam', '1KI', 21, 26, 'Na eeka ũla ũthatasya akĩatĩĩa mĩvw’anano, kwĩanana na w’onthe ũla Aamoli meekaa, ala Yeova wamalũngilye mbee wa ana ma Isilaeli.)'),
('kam', '1KI', 21, 27, 'Na kweethĩwa, yĩla Aavu wewie ndeto isu, atembũanga ngũa syake, na eevw’ĩka makunia mwĩĩ wake, na atĩĩa ũya, na akomea makunia, na aenda eyondetye.'),
('kam', '1KI', 21, 28, 'Na ndeto ya Yeova yamũkĩa Eliya Mũtisivi, ĩkĩmwĩa,'),
('kam', '1KI', 21, 29, 'Nĩwene ũndũ Aavu ũkwĩnyivya mbee wakwa? Nũndũ nũkwĩnyivya mbee wakwa, ndikaete ũthũku ũsu mĩthenyanĩ yake; ĩndĩ mĩthenyanĩ ya mwana wake ngaete ũthũku ũsu nyũmbanĩ yake.'),
('kam', '1KI', 22, 1, 'Na mekalaa myaka ĩtatũ vate kaũ katĩ wa Silia na Isilaeli.'),
('kam', '1KI', 22, 2, 'Na kweethĩwa mwaka wa katatũ, Yeosavati mũsumbĩ wa Yuta amũtheeea mũsumbĩ wa Isilaeli.'),
('kam', '1KI', 22, 3, 'Na mũsumbĩ wa Isilaeli akũlya athũkũmi make, Nĩmwĩsĩ Lamothi‐ngileati nĩ yaitũ, na nĩtũvindĩtye, na tũtiũmyumya kw’okonĩ kwa mũsumbĩ wa Silia?'),
('kam', '1KI', 22, 4, 'Na akũlya Yeosavati, Nũũthi vamwe nakwa kaũnĩ ku Lamothi‐ngileati? Na Yeosavati amwĩa mũsumbĩ wa Isilaeli, Nyie nĩilyĩ o taku, na andũ makwa ta andũ maku, na mbalasi syakwa ta mbalasi syaku.'),
('kam', '1KI', 22, 5, 'Na Yeosavati amwĩa mũsumbĩ wa Isilaeli, Nĩngũkwĩsũva, amba ũkũlya ũndũ ndeto ya Yeova ĩnĩkwasya.'),
('kam', '1KI', 22, 6, 'Nĩvo ĩndĩ mũsumbĩ wa Isilaeli wombanisye athani, vakuvĩ andũ maana ana, na amakũlya, Nĩngũthi Lamothi‐ngileati kũkita, kana nĩeke? Na mamwĩa, Ambata; nũndũ Mwĩaĩi akamĩnengane kw’okonĩ kwa mũsumbĩ.'),
('kam', '1KI', 22, 7, 'Ĩndĩ Yeosavati akũlya, Vati mwathani ũngĩ wa Yeova vaa tũmũkũlye?'),
('kam', '1KI', 22, 8, 'Na mũsumbĩ wa Isilaeli amwĩa Yeosavati, Ve o mũndũ ũngĩ ũla wa kũtũkũlĩlya kwa Yeova, Mikaia mwana wa Imila: ĩndĩ nĩngũmũmena; nũndũ ndambathanĩaa ũseo, ĩndĩ ũthũku. Na Yeosavati asya, mũsumbĩ ndakaneene ũu.'),
('kam', '1KI', 22, 9, 'Nĩvo ĩndĩ mũsumbĩ wa Isilaeli wamwĩtie mũnene wa kwake, na amwĩa, Mũlatye Mĩkaia mwana wa Imila mĩtũkĩ.'),
('kam', '1KI', 22, 10, 'Na ĩndĩ mũsumbĩ wa Isilaeli na Yeosavati mũsumbĩ wa Yuta mekalĩte kĩla ũmwe kĩvĩlanĩ kyake kya ũsumbĩ, mekĩĩte ngũa syoo ndasa, vandũ ũtheinĩ ũlikĩlonĩ mbingĩlonĩ ya Samalia; na athani onthe no mathanĩaa mbee woo.'),
('kam', '1KI', 22, 11, 'Na Nzetekia mwana wa Kenaana eeseũvĩsya mbya sya iaa, na asya, Ũũ nĩw’o Yeova ũnũkwasya, Ũkatindĩka Asilia na ii, mũvaka maminwa.'),
('kam', '1KI', 22, 12, 'Na athani onthe mathana ũu, makyasya, Ambata Lamothi‐ngileati, ũkaathimĩke; nũndũ Yeova akamĩnengane kw’okonĩ kwa mũsumbĩ.'),
('kam', '1KI', 22, 13, 'Na mũtũmwa ũla waendie kũmwĩta Mikaia aneena nake, akĩmwĩa, Sisya yu, ndeto sya athani niũtavan’ya ũseo kwa mũsumbĩ na kanyw’a ũmwe: nĩngũkwĩsũva, ndeto yaku yĩthĩwe ĩilyĩ ta ĩmwe yoo, noineena ũseo.'),
('kam', '1KI', 22, 14, 'Na Mikaia asya, O tondũ Yeova wĩ thayũ, o ũndũ Yeova wĩmbĩa, now’o nĩneena.'),
('kam', '1KI', 22, 15, 'Na yĩla wavikie vala ve mũsumbĩ, mũsumbĩ amũkũlya, Mikaia, nĩtũũthi Lamothi‐ngileati tũkite, kana tũeke? Na amũsũngĩa, Ambatai mũkaathimĩke; na Yeova akamĩnengane kw’okonĩ kwa mũsumbĩ.'),
('kam', '1KI', 22, 16, 'Na mũsumbĩ amwĩa, Nĩtũa ngũavĩthasya mavinda meana ndũkandavye ũndũ ũte wa w’o syĩtwanĩ ya Yeova?'),
('kam', '1KI', 22, 17, 'Nake asya, Nĩnonie Isilaeli onthe manyaĩĩkĩte iĩmanĩ, ta malondu mate mũĩthi: na Yeova asya, Aa mati na vwana; masyoke kĩla mũndũ nyũmbanĩ yake na mũuo.'),
('kam', '1KI', 22, 18, 'Na mũsumbĩ wa Isilaeli amwĩa Yeosavati, Ndinakũtavya ndakambathanĩa ũseo, ĩndĩ ũthũku?'),
('kam', '1KI', 22, 19, 'Na Mikaia asya, Kwondũ wa ũu ĩw’a ndeto ya Yeova: Nĩnonie Yeova ekalĩte kĩvĩlanĩ kyake kya ũsumbĩ, na nguthu yonthe ya ĩtunĩ ĩũngamĩte vakuvĩ nake kw’okonĩ kwake kwa aũme na kw’okonĩ kwake kwa aka.'),
('kam', '1KI', 22, 20, 'Na Yeova akũlya, Nũũ ũla wĩmũkengakenga Aavu, nĩ kana ambate avalũke ku Lamothi‐ngileati? Na ũmwe aneena na nzĩa ĩno, na ũngĩ aneena na nzĩa ĩngĩ.'),
('kam', '1KI', 22, 21, 'Na kwaumĩla veva, na waũngama mbee wa Yeova, na wasya, Ngamũkengakenga.'),
('kam', '1KI', 22, 22, 'Na Yeova ookũlya, Na kyaũ? Naw’o wasya, Ngaumaala nĩthi, na ngeethĩwa veva wa ũvũngũ kanyw’anĩ wa athani make onthe. Nake asya, Ũkamũkengakenga, o na ũkamũkĩlya vinya: enda, wĩke ũu.'),
('kam', '1KI', 22, 23, 'Kwondũ wa ũu ĩndĩ, sisya, Yeova nĩwĩkĩĩte veva wa ũvũngũ kanyw’anĩ wa athani aa onthe maku: na Yeova nũneenete ũthũku ũndũ waku.'),
('kam', '1KI', 22, 24, 'Nĩvo ĩndĩ Nzetekia mwana wa Kenaana wathengeeie, na amũkũna Mikaia ĩkovi ĩtau, na akũlya, Veva wa Yeova aumanga kwakwa ata aneene naku?'),
('kam', '1KI', 22, 25, 'Na Mikaia asya, Sisya, ũkoona mũthenya ũsu, yĩla wĩlika kasũmbanĩ ka nthĩnĩ wĩvithe.'),
('kam', '1KI', 22, 26, 'Na mũsumbĩ wa Isilaeli asya, Mũkwatei Mikaia, na mũimũtũnga kwa Amoni ngavana wa ndũa, na kwa Yoasi mwana wa mũsumbĩ;'),
('kam', '1KI', 22, 27, 'na mũkyasya, Ũũ nĩw’o mũsumbĩ ũnũkwasya, Ĩkĩai mũndũ ũũ kolokolonĩ, na mũimũnenga kĩmũtũ kya thĩna na manzĩ ma thĩna, kũvika yĩla nĩsyoka na mũuo.'),
('kam', '1KI', 22, 28, 'Na Mikaia asya, Ethĩwa nongi ũkasyoka na mũuo, Yeova ndaneenete na kanyw’a wakwa. Na asya, Ĩw’ai, inywĩ andũ, inyw’onthe.'),
('kam', '1KI', 22, 29, 'Na ĩndĩ mũsumbĩ wa Isilaeli na Yeosavati mũsumbĩ wa Yuta mambata Lamothi‐ngileati.'),
('kam', '1KI', 22, 30, 'Na mũsumbĩ wa Isilaeli amwĩa Yeosavati, Nĩngwĩyũlan’ya, na kũlika kaũnĩ; ĩndĩ, we, ĩkĩa ngũa syaku ndasa. Na mũsumbĩ wa Isilaeli eeyũlan’ya, na alika kaũnĩ.'),
('kam', '1KI', 22, 31, 'Na ĩndĩ mũsumbĩ wa Silia aĩ aneaĩa makavuteni mĩongo ĩtatũ na elĩ ma makasya make ma kaũ, akamea, Mũtikokite na ala anini kana ala anene, ate o mũsumbĩ wa Isilaeli.'),
('kam', '1KI', 22, 32, 'Na kweethĩwa, yĩla makavuteni ma makasya moonie Yeosavati, masya, Nĩ w’o, nĩ mũsumbĩ wa Isilaeli; na meelelũka mokite nake: na Yeosavati akaya.'),
('kam', '1KI', 22, 33, 'Na kweethĩwa, yĩla makavuteni ma makasya moonie ti mũsumbĩ wa Isilaeli, masyoka maeka kũmũatĩĩa.'),
('kam', '1KI', 22, 34, 'Na mũndũ ũmwe akoota ũta wake na alũlũngĩlya mũsyĩ, na amũathĩla mũsumbĩ wa Isilaeli katĩ wa mothalan’yo ma mĩio ya kaũ: kwondũ wa ũu amwĩa mũingi wa ĩkasya yake, Thyũũa kw’oko kwaku, ũmbumye nguthunĩ; nũndũ nĩ mũkite mũno.'),
('kam', '1KI', 22, 35, 'Na kaũ waingĩva mũthenya ũsu: na mũsumbĩ atw’ĩĩkĩwa ĩkasyanĩ yake okite na Asilia, na akw’a wĩoo; na nthakame yauma vandũ vala wokitĩlwe yalika ĩkasyanĩ nthĩnĩ.'),
('kam', '1KI', 22, 36, 'Na wasya wauma nguthunĩ yonthe syũa yĩkĩthũa, ũkyasya, Kĩla mũndũ naende ndũanĩ yake, na kĩla mũndũ nthĩ yake.'),
('kam', '1KI', 22, 37, 'Na ĩndĩ mũsumbĩ akw’a, na atwawa Samalia; na mamũthika mũsumbĩ ku Samalia.'),
('kam', '1KI', 22, 38, 'Na mathambĩsya ĩkasya ũtee wa ndia ya Samalia; na ngitĩ syalambalambya nthakame yake (na ĩndĩ malwaya mathambaa vo); kwĩanana na ndeto ya Yeova ĩla waneenie.'),
('kam', '1KI', 22, 39, 'Na ĩndĩ meko ala angĩ ma Aavu, na w’onthe ũla wekaa, na nyũmba ĩla wakie na maeo ma nzou, na ndũa syonthe ila wakie, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '1KI', 22, 40, 'Na ĩndĩ Aavu akoma na aaĩthe make; na Aasia mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 22, 41, 'Na Yeosavati mwana wa Asa ambĩlĩlya kũsumbĩka Yuta mwaka wa kana wa kũsumbĩka kwa Aavu mũsumbĩ wa Isilaeli.'),
('kam', '1KI', 22, 42, 'Yeosavati aĩ wa myaka mĩongo ĩtatũ na ĩtano yĩla wambĩlĩlye kũsumbĩka; na asumbĩka myaka mĩongo ĩlĩ na ĩtano ku Yelusaleme. Na syĩtwa ya inyia wake eetawa Asuva mwĩĩtu wa Silii.'),
('kam', '1KI', 22, 43, 'Na nĩwaendaa mũendelenĩ w’onthe wa Asa ĩthe wake; ndaathũkĩla ũtee, aeke kwĩka ũla Yeova wonaa wĩ ũseo: ĩndĩ kũla kũndũ kũtũlu kũtyaavetwa; andũ nĩmaendeeaa na kũthemba na kũtoeesya ũvani kũla kũndũ kũtũlu.'),
('kam', '1KI', 22, 44, 'Na Yeosavati aseũvya mũuo na mũsumbĩ wa Isilaeli.'),
('kam', '1KI', 22, 45, 'Na ĩndĩ meko ala angĩ ma Yeosavati, na vinya wake mũnene ũla wonanisye, na ũndũ wokitie, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta?'),
('kam', '1KI', 22, 46, 'Na ũtialo wa aũme ala meekaa naĩ na aũme ala angĩ, ala matialile mĩthenyanĩ ya ĩthe wake Asa, amaumya ĩ nthĩ.'),
('kam', '1KI', 22, 47, 'Na kũtyaĩ mũsumbĩ nthĩ ya Etomu: mwamũli nowe mũsumbĩ.'),
('kam', '1KI', 22, 48, 'Yeosavati aseũvya ngalawa sya Talisisi sya kũthi Ovilu ilatye thaavu: ĩndĩ ityaathi; nũndũ ngalawa syaanangĩwe Esioni‐ngeveli.'),
('kam', '1KI', 22, 49, 'Nĩvo ĩndĩ Aasia mwana wa Aavu wamwĩie Yeosavati, Athũkũmi makwa nĩmaende na athũkũmi maku ngalawanĩ. Ĩndĩ Yeosavati ndaaĩtĩkĩla.'),
('kam', '1KI', 22, 50, 'Na Yeosavati akoma na aaĩthe make, na athikwa na aaĩthe make ndũanĩ ya Ndaviti ĩthe wake; na Yeolamu mwana wake asumbĩka vandũ vake.'),
('kam', '1KI', 22, 51, 'Aasia mwana wa Aavu ambĩlĩlya kũsumbĩka Isilaeli ku Samalia mwaka wa ĩkũmi na mũonza wa kũsumbĩka kwa Yeosavati mũsumbĩ wa Yuta, na asumbĩka Isilaeli myaka ĩlĩ.'),
('kam', '1KI', 22, 52, 'Na eekaa ũla Yeova wonaa wĩ ũthũku, na aendaa mũendelenĩ wa ĩthe wake, na mũendelenĩ wa inyia wake, na mũendelenĩ wa Yelovoamu mwana wa Nevati, ũla wamavĩtĩthisye Isilaeli naw’o.'),
('kam', '1KI', 22, 53, 'Na athũkũma Mbaali, na amĩthaitha, na amũthatya Yeova, Ngai wa Isilaeli, kwĩanana na w’onthe ũla ĩthe wake wekaa.'),
('kam', '2KI', 1, 1, 'Na Moavi yang’endea Isilaeli ĩtina wa kũkw’a kwa Aavu.'),
('kam', '2KI', 1, 2, 'Na Aasia avalũkĩla mbũthinĩ kasũmbanĩ kake ke ĩũlũ ke Samalia, na awaa: na atũma atũmwa, na amea, Endai, mũkũlyei Mbaali‐nzevuvu, ngai ya Ekiloni, ethĩwa ngavoa ũwau ũũ.'),
('kam', '2KI', 1, 3, 'Ĩndĩ mũlaĩka wa Yeova amwĩa Eliya Mũtisivi, Ũkĩla, nokyambata ũkomane na ala matũmĩtwe nĩ mũsumbĩ wa Samalia, noimakũlya, Nĩ kwakwĩthĩwa kũti Ngai nthĩnĩ wa Isilaeli, nĩmũkũthi kũkũlya kwa Mbaali‐nzevuvu, ngai ya Ekiloni?'),
('kam', '2KI', 1, 4, 'Yu kwondũ wa ũu Yeova easya atĩĩ, Ndũkauma ũkomonĩ ũla ũlĩsĩte, ĩndĩ ndwĩtĩa ũkw’a. Na Eliya athi.'),
('kam', '2KI', 1, 5, 'Na ala matũmĩtwe mamũsyokea, na amakũlya, Nũndũ wa kĩ mwasyoka?'),
('kam', '2KI', 1, 6, 'Na mamwĩa, Nĩkũkie mũndũ akomana naitũ, na atwĩa, Endai, mũmũsyokee mũsumbĩ ũla ũmũtũmie, na mũimwĩa, Ũũ nĩw’o Yeova ũnũũkũlya, Nĩ kwakwĩthĩwa kũti Ngai nthĩnĩ wa Isilaeli, kana ũtũmane kũkũlya Mbaali‐nzevuvu, ngai ya Ekiloni? Kwondũ wa ũu ndũkauma ũkomonĩ ũla ũlĩsĩte, ĩndĩ ndwĩtĩa ũkw’a.'),
('kam', '2KI', 1, 7, 'Na amakũlya, Mũndũ ũsu ũla wũkie akomana nenyu, na amũtavya ndeto isu, nĩ mũndũ ũilyĩ ata?'),
('kam', '2KI', 1, 8, 'Na mamũsũngĩa, Eĩ mũndũ wĩ maw’ĩa, na eĩvotoete mũsivi wa mũkwa kĩnyunyunĩ kyake. Na asya, Nĩ Eliya Mũtisivi.'),
('kam', '2KI', 1, 9, 'Nĩvo ĩndĩ mũsumbĩ watũmie vala ũĩ kavuteni wa mĩongo ĩtano e na ala make mĩongo ĩtano. Na amwambatĩa: na, sisya, ekalĩte nthĩ mũtumbĩnĩ wa kĩĩma. Na aneena nake, We mũndũ wa Ngai, mũsumbĩ asya, Theea.'),
('kam', '2KI', 1, 10, 'Na Eliya asũngĩa na amwĩa kavuteni wa mĩongo ĩtano, Ethĩwa nyie nĩ mũndũ wa Ngai, mwaki ũtheee kuma ĩtunĩ, ũkũvĩvya we na ala maku mĩongo ĩtano. Na kwatheea mwaki kuma ĩtunĩ, na wamũvĩvya we na ala make mĩongo ĩtano.'),
('kam', '2KI', 1, 11, 'Na ĩngĩ atũma vala ũĩ kavuteni ũngĩ wa mĩongo ĩtano e na ala make mĩongo ĩtano. Na asũngĩa na amwĩa, We mũndũ wa Ngai, ũũ nĩw’o mũsumbĩ waneena, Theea mĩtũkĩ.'),
('kam', '2KI', 1, 12, 'Na Eliya amasũngĩa na amea, Ethĩwa nyie nĩ mũndũ wa Ngai, mwaki ũtheee kuma ĩtunĩ, na ũkũvĩvya we na ala maku mĩongo ĩtano. Na mwaki wa Ngai watheea kuma ĩtunĩ, na wamũvĩvya vamwe na ala make mĩongo ĩtano.'),
('kam', '2KI', 1, 13, 'Na ĩngĩ atũma kavuteni wa katatũ wa mĩongo ĩtano e na ala make mĩongo ĩtano. Na kavuteni wa katatũ wa mĩongo ĩtano ambata, na avika na atulya ndu mbee wa Eliya, na amwĩsũva, na amwĩa, Ame mũndũ wa Ngai, nĩngũkwĩsũva, thayũ wakwa, na thayũ wa aa mĩongo ĩtano athũkũmi maku, wĩthĩwe wĩ vata methonĩ maku.'),
('kam', '2KI', 1, 14, 'Sisya, nĩkwatheeie mwaki kuma ĩtunĩ, na wavĩvya makavuteni elĩ ma mĩongo ĩtano ala mambie kũka vamwe na ala moo mĩongo ĩtano; ĩndĩ yu thayũ wakwa nĩwĩthĩwe wĩ vata methonĩ maku.'),
('kam', '2KI', 1, 15, 'Na mũlaĩka wa Yeova amwĩa Eliya, Theea wĩ nake: ndũkamũkĩe. Na ookĩla, na atheea nake kwa mũsumbĩ.'),
('kam', '2KI', 1, 16, 'Na amwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nũndũ nũtũmĩte atũmwa makũlye Mbaali‐nzevuvu, ngai ya Ekiloni, ũu nĩ kwakwĩthĩwa kũti Ngai nthĩnĩ wa Isilaeli ũkũlye ndeto yake? Kwondũ wa ũu ndũkauma ũkomonĩ ũla ũlĩsĩte, ĩndĩ ndwĩtĩa ũkw’a.'),
('kam', '2KI', 1, 17, 'Na ĩndĩ akw’a kwĩanana na ndeto ya Yeova ĩla Eliya waneenie. Na Yeolamu ambĩlĩlya kũsumbĩka vandũ vake mwaka wa kelĩ wa kũsumbĩka kwa Yeolamu mwana wa Yeosavati mũsumbĩ wa Yuta; nĩkwĩthĩwa ndaĩ mwana.'),
('kam', '2KI', 1, 18, 'Na ĩndĩ meko ala angĩ ma Aasia ala wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '2KI', 2, 1, 'Na kweethĩwa, yĩla Yeova wendie kũmwambatya Eliya ĩtunĩ na kĩlingi, kana Eliya athi na Elisa kuma Ngilikali.'),
('kam', '2KI', 2, 2, 'Na Eliya amwĩa Elisa, Ĩkala vaa, ningũkwĩsũva; nũndũ Yeova nũndũmĩte nĩvike Mbethi‐eli. Na Elisa asya, O tondũ Yeova wĩ thayũ, na o tondũ kyuu kyaku kĩ thayũ, ndikũtia. Na ĩndĩ matheea mavika Mbethi‐eli.'),
('kam', '2KI', 2, 3, 'Na ana ma athani ala maĩ Mbethi‐eli mamumaalĩla Elisa, na mamũkũlya, Nĩwĩsĩ kana Yeova nũkũveta vwana waku ũmũnthĩ ndakethĩwe ĩũlũ waku? Na asya, Ĩĩ, nĩnĩsĩ; vindyai.'),
('kam', '2KI', 2, 4, 'Na Eliya amwĩa, Elisa, ĩkala vaa, nĩngũkwĩsũva; nũndũ Yeova nũndũmĩte Yeliko. Na asya, O tondũ Yeova wĩ thayũ, na o tondũ kyuu kyaku kĩ thayũ, ndikũtia. Na ĩndĩ mavika Yeliko.'),
('kam', '2KI', 2, 5, 'Na ana ma athani ala maĩ Yeliko mamũthengeea Elisa, na mamũkũlya, Nĩwĩsĩ kana Yeova nũkũveta vwana waku ũmũnthĩ ndakethĩwe ĩũlũ waku? Na asũngĩa, Ĩĩ, nĩnĩsĩ; vindyai.'),
('kam', '2KI', 2, 6, 'Na Eliya amwĩa, Ĩkala vaa, nĩngũkwĩsũva; nũndũ Yeova nũndũmĩte Yolotani. Na asya, O tondũ Yeova wĩ thayũ, na o tondũ kyuu kyaku kĩ thayũ, ndikũtia. Namo elĩ maendeea.'),
('kam', '2KI', 2, 7, 'Na andũ mĩongo ĩtano ma ana ma athani maenda, na maũngama me kũasa mamelekele: namo elĩ maũngama ũtee wa Yolotani.'),
('kam', '2KI', 2, 8, 'Na Eliya oosa suka wake, na ookũnza, akũna manzĩ, na maaanĩka ngalĩ ĩno na ĩno, na ĩndĩ me elĩ mainga makinyĩte nthĩ nyũmũ.'),
('kam', '2KI', 2, 9, 'Na kweethĩwa, yĩla maminie kũinga, Eliya amwĩa Elisa, Ngũlya ũla ũkwenda ngwĩke, ndanamba kwoswa kuma vala ũĩ. Na Elisa asya, Nĩngũkwĩsũva, kĩanda kya veva waku kũndũ kwĩlĩ kĩthĩwe ĩũlũ wakwa.'),
('kam', '2KI', 2, 10, 'Na asya, Nĩwakũlya ũndũ wĩ vĩnya: ĩndĩ, ethĩwa ũkambona ngyumw’a vala ũĩ, ũu ũkeethĩwa kwaku; ĩndĩ ethĩwa ti w’o, ũu ndwĩĩthĩwa.'),
('kam', '2KI', 2, 11, 'Na kweethĩwa, yĩla maendangĩĩe, na makĩneenangan’ya, sisya, kwaumĩla ĩkasya ya mwaki na mbalasi sya mwaki, ila syamataanisye elĩ; na Eliya ambatw’a ĩtunĩ nĩ kĩlingi.'),
('kam', '2KI', 2, 12, 'Na Elisa oona ũu, na ookĩlya wasya, Asa wakwa, asa wakwa, makasya ma Isilaeli na ala matũlaa mbalasi syamo! Na ndaamwona ĩngĩ: na akwata ngũa syake mwene, na aitembũan’ya ilungu ilĩ.'),
('kam', '2KI', 2, 13, 'O na oosa suka wa Eliya ũla wavalũkile kuma kwake, na asyoka, na aũngama ngũkanĩ ya Yolotani.'),
('kam', '2KI', 2, 14, 'Na oosa suka wa Eliya ũla wavalũkile kuma kwake, na akũna manzĩ, na asya, Yeova aĩva, Ngai wa Eliya? O na yĩla wakũnie manzĩ, maaanĩka ngalĩ ĩno na ĩno; na Elisa ainga.'),
('kam', '2KI', 2, 15, 'Na yĩla ana ma athani ala maĩ Yeliko mamwelekele mamwonie, masya, Veva wa Eliya nĩwĩkalĩle Elisa. Na mooka makomane nake, na meekunamya nthĩ mbee wake.'),
('kam', '2KI', 2, 16, 'Na mamwĩa, Sisya yu, ve andũ mĩongo ĩtano me vinya vamwe na athũkũmi maku; nĩtũũkwĩsũva, maende mamanthe vwana waku, Veva wa Yeova no ĩthĩwa amwambatisye, na kũmwĩkya kĩĩmanĩ kĩmwe, kana kyandanĩ kĩmwe. Na asya, Mũtikatũmane.'),
('kam', '2KI', 2, 17, 'Na yĩla mamũingĩĩsye mũvaka eew’a nthoni, asya, Tũmanai. Kwondũ wa ũu matũma andũ mĩongo ĩtano; na mamantha mĩthenya ĩtatũ, ĩndĩ matyaamwona.'),
('kam', '2KI', 2, 18, 'Na mamũsyokea, yĩla wekalĩte Yeliko; na amea, Ndineemũtavya, Mũtikathi?'),
('kam', '2KI', 2, 19, 'Na andũ ma ndũa mamwĩa Elisa, Sisya, nĩtũũkwĩsũva, vandũ va ndũa ĩno nĩ va kwendeesya, o tondũ mwĩaĩi wakwa ũnũkwona: ĩndĩ manzĩ nĩ mathũku, na nthĩ nĩnĩkwĩtĩkya ũsyao wayo.'),
('kam', '2KI', 2, 20, 'Na asya, Ndeteei sũva mweũ, na mũkĩkĩa mũnyũ nthĩnĩ waw’o. Na mamũetee.'),
('kam', '2KI', 2, 21, 'Na aumaala aenda mbulutinĩ ya a manzĩ, na eekĩa mũnyũ nthĩnĩ wayo, na asya, Ũũ nĩw’o Yeova ũnũkwasya, Nĩnĩvoetye manzĩ aa; kuma yu kũikethĩwa kĩkw’ũ ĩngĩ kana kwĩtĩkya ũsyao.'),
('kam', '2KI', 2, 22, 'Kwondũ wa ũu manzĩ mavow’a kũvika ũmũnthĩ, kwĩanana na ndeto ya Elisa ĩla waneenie.'),
('kam', '2KI', 2, 23, 'Na ambata kuma vo kũvika Mbethi‐eli; na ambatĩte nzĩanĩ, kwauma imwana ndũanĩ, na syamũthekeea na kĩvũthya, na kũmwĩa, Ambata, we kĩvala; ambata, we kĩvala.'),
('kam', '2KI', 2, 24, 'Na asisya ĩtina wake na asyona, na aiumanĩa syĩtwanĩ ya Yeova. Na kwauma mũtitũnĩ nduva nga ilĩ, na syatembũanga imwana mĩongo ĩna na ilĩ syasyo.'),
('kam', '2KI', 2, 25, 'Na auma vo athi kĩĩmanĩ kya Kalimeli, na kuma kw’o asyoka Samalia.'),
('kam', '2KI', 3, 1, 'Na ĩndĩ Yeolamu mwana wa Aavu ambĩlĩlya kũsumbĩka Isilaeli ku Samalia mwaka wa ĩkũmi na nyanya wa kũsumbĩka kwa Yeosavati mũsumbĩ wa Yuta, na asumbĩka myaka ĩkũmi na ĩlĩ.'),
('kam', '2KI', 3, 2, 'Na eekaa ũla Yeova wonaa wĩ ũthũku, ĩndĩ ti ta ĩthe wake, na ta inyia wake; nũndũ nĩwavetie kĩtuĩ kya Mbaali kĩla ĩthe wake waseũvĩtye.'),
('kam', '2KI', 3, 3, 'Ĩndĩ o na ũu alũman’ya na naĩ sya Yelovoamu mwana wa Nevati, ila wavĩtĩthĩtye Isilaeli nasyo; ndaaitia.'),
('kam', '2KI', 3, 4, 'Na ĩndĩ Mesa mũsumbĩ wa Moavi aĩ mũĩthya wa malondu; na amũnengae mũsumbĩ wa Isilaeli tũtena twa malondu ngili ĩana, na ndũũme ngili ĩana, o na maw’ĩa.'),
('kam', '2KI', 3, 5, 'Ĩndĩ kweethĩwa, yĩla Aavu wakwie, mũsumbĩ wa Moavi amũng’endea mũsumbĩ wa Isilaeli.'),
('kam', '2KI', 3, 6, 'Na mũsumbĩ Yeolamu auma Samalia ĩvinda yĩu, na oomban’ya Isilaeli onthe.'),
('kam', '2KI', 3, 7, 'Na athi atũmana kwa Yeosavati mũsumbĩ wa Yuta, akĩmwĩa, Mũsumbĩ wa Moavi nũng’endeete: ũkathi vamwe nakwa tũkite na Moavi kaũnĩ? Na asya, Ngambata: nyie nĩilyĩ o taku, na andũ makwa ta andũ maku, na mbalasi syakwa ta mbalasi syaku.'),
('kam', '2KI', 3, 8, 'Na amũkũlya, Twĩambata na nzĩa yĩva? Na amũsũngĩa, Nzĩa ya weũ wa Etomu.'),
('kam', '2KI', 3, 9, 'Na ĩndĩ mũsumbĩ wa Isilaeli athi, na mũsumbĩ wa Yuta, na mũsumbĩ wa Etomu; na mathi melingĩlĩte kyalo kya mĩthenya mũonza: na kũtyaĩ manzĩ ma ĩ nguthu, o na ma nyamũ ila syamaatĩĩe.'),
('kam', '2KI', 3, 10, 'Na mũsumbĩ wa Isilaeli asya, Ĩiaa! Nũndũ Yeova nĩwĩtĩte asumbĩ aa atatũ mombane vamwe amanengane kw’okonĩ kwa Moavi.'),
('kam', '2KI', 3, 11, 'Ĩndĩ Yeosavati akũlya, Vati mwathani wa Yeova vaa, nĩ kana tũmũkũlye Yeova na kanyw’a wake? Na ũmwe wa athũkũmi ma mũsumbĩ wa Isilaeli asũngĩa na asya, Elisa mwana wa Savati e vaa, ũla wetĩkĩasya moko ma Eliya manzĩ.'),
('kam', '2KI', 3, 12, 'Na Yeosavati asya, Ndeto ya Yeova yĩ nake. Kwondũ wa ũu mũsumbĩ wa Isilaeli na Yeosavati na mũsumbĩ wa Etomu matheea vala ũĩ.'),
('kam', '2KI', 3, 13, 'Na Elisa amwĩa mũsumbĩ wa Isilaeli, Nĩ ũndũ naku wa kĩ? Enda kwa athani ma ĩthe waku, na athani ma inyia waku. Na mũsumbĩ wa Isilaeli amwĩa, Aiee; nũndũ Yeova nĩwĩtĩte asumbĩ aa atatũ mombane vamwe amanengane kw’okonĩ kwa Moavi.'),
('kam', '2KI', 3, 14, 'Na Elisa asya, O tondũ Yeova wa nguthu wĩ thayũ, ũla nĩũngamaa mbee wake, nĩ w’o, kethĩwa ti atĩ nĩngwona Yeosavati mũsumbĩ wa Yuta ta mũndũ, ndisisya kwelekela ngalũko ĩla ũĩ we, kana ũkwona.'),
('kam', '2KI', 3, 15, 'Ĩndĩ yu ndetee mũndũ wĩsĩ kũinga mbeve. Na kweethĩwa, yĩla mũingi ũsu waingaa, kw’oko kwa Yeova kwooka ĩũlũ wake.'),
('kam', '2KI', 3, 16, 'Na asya, Ũũ nĩw’o Yeova ũnũkwasya, Ĩnzai mĩtaũ mwandanĩ ũũ wusũe.'),
('kam', '2KI', 3, 17, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Mũtikona kĩseve, o na mũtikona mbua; ĩndĩ mwanda ũũ ũkausũa manzĩ, na mũkanyusaa, inyw’ĩ na indo syenyu na nyamũ syenyu.'),
('kam', '2KI', 3, 18, 'Na ũu no ũndũ ũvũthũ methonĩ ma Yeova: nake akanengane Amoavi nao kw’okonĩ kwaku.'),
('kam', '2KI', 3, 19, 'Na mũkakũne kĩla ndũa mbiie, na kĩla ndũa yĩ vata, na mũkateme kĩla mũtĩ mũseo, na kũlinda nthongo syonthe sya manzĩ, na kũthũkya kĩla kĩlungu kĩseo kya nthĩ na mavia.'),
('kam', '2KI', 3, 20, 'Na kweethĩwa kĩoko, ta ĩvinda ya kũthemba nthembo, sisya, kwooka manzĩ na nzĩa ya Etomu, na nthi yausũa manzĩ.'),
('kam', '2KI', 3, 21, 'Na ĩndĩ yĩla Amoavi onthe meewie atĩ asumbĩ mambatĩte mokite nao, meeyũmbanĩsya, onthe ala maĩ matonya kwĩkĩa mĩio ya kaũ, o na ala akũangũ, na maũngama mũvakanĩ.'),
('kam', '2KI', 3, 22, 'Na mookĩla kĩoko tene, na syũa yaatha ĩũlũ wa manzĩ, na Amoavi moona manzĩ me mbee woo me matune ta nthakame:'),
('kam', '2KI', 3, 23, 'na masya, ĩno nĩ nthakame; asumbĩ nĩmanangĩtwe vate ndĩi, na nĩmoaĩte kĩla mũndũ mũtindan’ya wake: yu kwondũ wa ũu, Moavi, endai mũtavonĩ.'),
('kam', '2KI', 3, 24, 'Na yĩla mavikie mwakonĩ wa maeema wa Isilaeli, Aisilaeli mookĩla na makũna Amoavi, mũvaka makũka mbee woo; na maendeea na malika ĩ nthĩ makũnĩte Amoavi.'),
('kam', '2KI', 3, 25, 'Na mavalũkya i ndũa nthĩ; na kĩla kĩlungunĩ kĩseo kya nthĩ mekya kĩla mũndũ ĩvia yake, na makyusũsya; na malinda nthongo syonthe sya manzĩ, na mavalũkya mĩtĩ yonthe mĩseo, mũvaka Kili‐alesethio yoka matialilye mavĩa mayo; ĩndĩ ala mekasya mavia na ikũtha mamĩthyũlũlũka, na mamĩkũna.'),
('kam', '2KI', 3, 26, 'Na yĩla mũsumbĩ wa Moavi wonie kana kaũ nũvyũvie kwake athi na andũ maana mũonza ala makũaa ũvyũ, mavũthũe nzĩa mavike kwa mũsumbĩ wa Etomu; ĩndĩ matyaatonya.'),
('kam', '2KI', 3, 27, 'Na ĩndĩ oosa ĩkithathi yake yĩla yaaĩle kũsumbĩka vandũ vake, na ayĩthemba ũvainĩ yĩthĩwe nthembo ya kũvĩvw’a. Na kwaĩ ũthatu mũnene ĩũlũ wa Isilaeli: na mamũtia, na masyoka nthĩ yoo ene.'),
('kam', '2KI', 4, 1, 'Na ĩndĩ mũndũ mũka ũmwe wa iveti sya ana ma athani amwĩkaĩla Elisa, akĩmwĩa, Mũthũkũmi waku mũemewa nũkw’ĩte; naku nĩwĩsĩ mũthũkũmi waku nĩwakĩaa Yeova: na ũla mũandũi nĩ mũku ose syana syakwa ilĩ syĩthĩwe ngombo.'),
('kam', '2KI', 4, 2, 'Na Elisa amwĩa, Ngakwĩka ata? Ndavya; wĩ na kyaũ nyũmbanĩ? Nake asũngĩa, Mũthũkũmi waku mwĩĩtu nde kĩndũ nyũmbanĩ, ate o kavisũ ka mauta.'),
('kam', '2KI', 4, 3, 'Nĩvo ĩndĩ waisye, Enda ũvoye mĩio ndee kwa atũi maku onthe, o mĩio mĩthei; ndũkavoye mĩvũthũ.'),
('kam', '2KI', 4, 4, 'Na ũkalike nthĩnĩ, na ũkĩvingĩa we na ana maku nyũmba, nokyonosya mĩionĩ ĩsu yonthe; na ũkia ũtee, ũla wausũa.'),
('kam', '2KI', 4, 5, 'Na ĩndĩ auma vala ũĩ, na eevingĩa mũomo we na ana make; nao mamũetee mĩio, nake oonoesya.'),
('kam', '2KI', 4, 6, 'Na kweethĩwa, mĩio yausũa, amwĩa mwana wake, Ndetee o mũio. Nake amwĩa. Kũti mũio ũngĩ. Na mauta maeka.'),
('kam', '2KI', 4, 7, 'Na ĩndĩ ooka na atavya ũ mũndũ wa Ngai. Nake amwĩa, Enda, ũthoosye mauta asu, ũĩve thiĩ waku, na ala meũtiala nĩ maku na ma ana maku.'),
('kam', '2KI', 4, 8, 'Na kweethĩwa mũthenya ũmwe, Elisa aenda Sunemu, vala vaĩ mũndũ mũka wĩ nguma; na amũingĩĩsya aye lĩu. Na kwondũ wa ũu kweethĩawa, o yĩla wavĩtaa, aathũkĩlaa vo aye lĩu.'),
('kam', '2KI', 4, 9, 'Na amwĩa mũũme, Sisya, yu, nĩngwona ũũ nĩ mũndũ mũtheu wa Ngai, ũla ũvĩtĩlaa kwitũ mavinda onthe.'),
('kam', '2KI', 4, 10, 'Nĩngũkwĩsũva, tũseũvye kasũmba kanini wakonĩ; na tũmwiĩe vo ũkomo, na mesa, na kĩvĩla, na kĩndũ kĩla kĩkĩawa taa: na kũkeethĩawa, yĩla wĩũkaa kwitũ, akathũkĩlaa vo.'),
('kam', '2KI', 4, 11, 'Na kweethĩwa mũthenya ũmwe, ooka vau, na aathũkĩla kasũmbanĩ na akoma vo.'),
('kam', '2KI', 4, 12, 'Na amwĩa Ngeasi mũthũkũmi wake, Mwĩte ũla Mũsunami. Na amina ũmwĩta, aũngama mbee wake.'),
('kam', '2KI', 4, 13, 'Na amwĩa, Yu mũtavye, Sisya, nũtũsũvĩĩte na ũsũvĩo ũũ w’onthe; ũla wĩĩkwa nata? Nũkwenda ũvoyewe ũndũ kwa mũsumbĩ, kana kwa kavuteni wa nguthu? Na asũngĩa, Nĩkalaa katĩ wa andũ makwa mwene.'),
('kam', '2KI', 4, 14, 'Nake asya, Ĩndĩ eĩkwa ata? Na Ngeasi asũngĩa, Nĩ w’o, nde mwana, na mũũme wake nĩ mũkũũ.'),
('kam', '2KI', 4, 15, 'Na asya, Mwĩte. Na yĩla wamwĩtie, aũngama mũomonĩ.'),
('kam', '2KI', 4, 16, 'Na asya, Ĩvinda ta yĩĩ, kyathĩ kyavika, ũkeethĩwa ũkwete mwana. Nake asya, Aiee, mwĩaĩi wakwa, we mũndũ wa Ngai, ndũkatavye mũthũkũmi waku mwĩĩtu ũvũngũ.'),
('kam', '2KI', 4, 17, 'Na mũndũ mũka ũsu aitava, na asyaa mwana ĩvinda yĩu, kyathĩ kyavika, o tondũ Elisa wamũtavisye.'),
('kam', '2KI', 4, 18, 'Na yĩla mwana waĩ aneana, kweethĩwa mũthenya ũmwe, aumaala aenda vala ve ĩthe wake vala ve akethi.'),
('kam', '2KI', 4, 19, 'Na amwĩa ĩthe, Mũtwe wakwa, mũtwe wakwa. Na amwĩa mũthũkũmi wake, Mũtwae vala ve inyia wake.'),
('kam', '2KI', 4, 20, 'Na yĩla wamũtwaie, na amũvikya vala ve inyia wake, akĩkwa kũvika katambanga na ĩndĩ akw’a.'),
('kam', '2KI', 4, 21, 'Nake ambata amũkomya ũkomonĩ wa ũ mũndũ wa Ngai, na amũvingĩa na mũomo, na aumaala.'),
('kam', '2KI', 4, 22, 'Na amwanĩĩsya mũũme, na asya, Nĩngũkwĩsũva, ndũmĩa ũmwe wa athũkũmi, na yĩmwe ya mang’oi, nĩ kana nĩsembe vala ve ũla mũndũ wa Ngai, na ngĩsyoka.'),
('kam', '2KI', 4, 23, 'Nake amũkũlya, Nũndũ wa kĩ ũũthi kwake ũmũnthĩ? Ti mũtiso wa mwei kana savato. Na asya, Kũkeethĩwa kũseo.'),
('kam', '2KI', 4, 24, 'Nĩvo ĩndĩ watandĩkie ĩng’oi, na amwĩa mũthũkũmi wake, Tongosya, noiendeea; ndũkandindye nzĩanĩ, ndaũtavĩtye.'),
('kam', '2KI', 4, 25, 'Na ĩndĩ athi, na avika kwa mũndũ wa Ngai kĩĩmanĩ kya Kalimeli. Na kweethĩwa, yĩla mũndũ wa Ngai wamwonie e kũasa, amwĩa mũthũkũmi wake Ngeasi, Sisya, kũya nĩ ũla Mũsunami:'),
('kam', '2KI', 4, 26, 'nĩngũkwĩsũva, semba oyu ũmũthaũe noimũkũlya, Wĩ mũseo? Na mũemeu nĩ mũeso? Na mwana nĩ mũseo? Na asũngĩa, Nĩ kũseo.'),
('kam', '2KI', 4, 27, 'Na yĩla wavikie vala ve mũndũ wa Ngai kĩĩmanĩ, amũkwata maũũ. Na Ngeasi athengeea amũvete; ĩndĩ ũ mũndũ wa Ngai amwĩa, Ekana nake: nũndũ thayũ wake nũkwĩw’a woo nthĩnĩ wake; na Yeova nũmbithĩte, na ndaandavya.'),
('kam', '2KI', 4, 28, 'Nĩvo ĩndĩ waisye, Nyie naamwĩtya mwĩaĩi wakwa mwana? Ndyaaneena, Ndũkangenge?'),
('kam', '2KI', 4, 29, 'Nĩvo ĩndĩ wamwĩie Ngeasi, Ĩvotoe kĩnyunyu kyaku, nokyosa ndata yakwa kw’okonĩ kwaku, noienda: ethĩwa ũkakomana na mũndũ o na wĩva, ndũkamũkethye; na ethĩwa mũndũ o na wĩva akakũkethya, ndũkamũketheke: na ũkaie ndata yakwa ũthyũnĩ wa kala kana.'),
('kam', '2KI', 4, 30, 'Na inyia wa kala kana asya, O tondũ Yeova wĩ thayũ, na tondũ kyuu kyaku kĩ thayũ, ndikũtia. Na ookĩla, na amũvikĩla.'),
('kam', '2KI', 4, 31, 'Na Ngeasi atongosya mbee woo, na aia ndata ũthyũnĩ wa kana; ĩndĩ vatyaĩ wasya, kana kwĩw’a. Kwondũ wa ũu asyoka amũthaũe, na amũtavya, akĩmwĩa, Kana katinaamũka.'),
('kam', '2KI', 4, 32, 'Na yĩla Elisa walikile nyũmbanĩ, sisya, kana kaĩ kakw’ũ, na kaiĩtwe ũkomonĩ wake.'),
('kam', '2KI', 4, 33, 'Kwondũ wa ũu alika, na eevingia mũomo e nako ma elĩ, na amũvoya Yeova.'),
('kam', '2KI', 4, 34, 'Na alĩsa, na eekomya ĩũlũ wa kana, na eekĩa kanyw’a wake ĩũlũ wa kanyw’a wako, na metho make ĩũlũ wa metho mako, na moko make ĩũlũ wa moko mako: na eekomya etambũũkĩtye ĩũlũ wako; na mwĩĩ wa kana wakwata muutĩa.'),
('kam', '2KI', 4, 35, 'Na ĩndĩ asyoka, na atũũanga kũũ na kũũ ĩvinda yĩmwe nyũmbanĩ; na alĩsa, na eekomya etambũũkĩtye ĩũlũ wako: na kana kaathimũa mathimũa mũonza, na kana kasalukya metho mako.'),
('kam', '2KI', 4, 36, 'Na amwĩta Ngeasi, na amwĩa, Mwĩte Mũsunami. Na ĩndĩ amwĩta. Na yĩla walikile vala waĩ, amwĩa, Osa mwana waku.'),
('kam', '2KI', 4, 37, 'Nĩvo ĩndĩ walikile, na eevalũkya nthĩ maũũnĩ make, na eekunamya kũvika nthĩ; na oosa mwana wake, na aumaala.'),
('kam', '2KI', 4, 38, 'Na Elisa ooka ĩngĩ Ngilikali. Na kwaĩ yũa nthĩ ĩsu; na ana ma athani mekalĩte mbee wake; na amwĩa mũthũkũmi wake, Ĩkĩa kĩteve, noiuĩa ana ma athani ũsũũ.'),
('kam', '2KI', 4, 39, 'Na ũmwe aumaala athi kĩsesinĩ ove nyũnyi, na oona ũthaana wa kĩthekanĩ, na atw’a ikuu sya kĩthekanĩ syaw’o ngũa yake yausũa, na ooka na atũangĩa kĩtevenĩ kya ũsũũ; nũndũ matyasyĩsĩ.'),
('kam', '2KI', 4, 40, 'Na ĩndĩ mamevũĩa andũ asu maye. Na kweethĩwa, makĩya ũla ũsũũ, mookĩlya mawasya, na masya, We mũndũ wa Ngai, kwĩ kĩkw’ũ kĩtevenĩ. Na matyaatonya kũya.'),
('kam', '2KI', 4, 41, 'Ĩndĩ nake asya, Ete mũtu ĩndĩ. Na awĩkya kĩtevenĩ; na asya, Mevũĩei andũ, maye. Na kũtyaĩ ũndũ ũthũku kĩtevenĩ.'),
('kam', '2KI', 4, 42, 'Na kwooka mũndũ kuma Mbaalisalisa, na amũetee mũndũ wa Ngai kĩmũtũ kya ũsyao wa mbee, imũtũ mĩongo ĩlĩ sya mbaale, na iia sya nganũ ĩkunianĩ yake. Na asya, Nenga andũ, maye.'),
('kam', '2KI', 4, 43, 'Na mũthũkũmi wake asya, Asi, nĩnaĩle kwia lĩu ũũ mbee wa andũ ĩana? Ĩndĩ asya, Nenga andũ, maye; nũndũ ũũ nĩw’o Yeova ũnũkwasya, Makaya, na makatialya.'),
('kam', '2KI', 4, 44, 'Kwondũ wa ũu awia mbee woo, na maya, na matialya, kwĩanana na ndeto ya Yeova.'),
('kam', '2KI', 5, 1, 'Na ĩndĩ Naamani kavuteni wa nguthu ya mũsumbĩ wa Silia, aĩ mũndũ wĩ nguma kwa vwana wake, na wa kũtaĩwa, nĩkwĩthĩwa Yeova nĩwanengete Silia kũkĩlya vinya ũndũ wake: o na aĩ ngũmbaũ nene, ĩndĩ awaĩte mangũ.'),
('kam', '2KI', 5, 2, 'Na Asilia meethĩiwe maumaalile nguthu, nguthu, na makaete kelĩtu ke katave kuma nthĩ ya Isilaeli; na kathũkũmaa kĩveti kya Naamani.'),
('kam', '2KI', 5, 3, 'Na kamwĩa vivi wako, Nenda kethĩwa mwĩaĩi wakwa e vala ve mwathani ũla wĩ Samalia! Ethĩwa amũvosya ĩndĩ mangũ make.'),
('kam', '2KI', 5, 4, 'Na ũmwe alika, na amũtavya mwĩaĩi wake, akĩmwĩa, Kelĩtu kala ka nthĩ ya Isilaeli kaisye ũna na ũna.'),
('kam', '2KI', 5, 5, 'Na mũsumbĩ wa Silia asya, Enda yu, na ngamũtwaĩa mũsumbĩ wa Isilaeli valũa. Na athi, na akua talendi ĩkũmi sya vetha, na ilungu ngili thanthatũ sya thaavu, na ngũa sya ũkũan’ya makũan’ya ĩkũmi.'),
('kam', '2KI', 5, 6, 'Na amũetee mũsumbĩ wa Isilaeli ũla valũa, akĩmwĩa, Na yu yĩla valũa ũũ wĩkũvikĩa, sisya, nĩnĩtũmĩte Naamani mũthũkũmi wakwa kwaku, nĩ kana ũmũvosye mangũ make.'),
('kam', '2KI', 5, 7, 'Na kweethĩwa, yĩla mũsumbĩ wa Isilaeli wasomie valũa, atembũanga ngũa syake, na asya, Nyie nĩ Ngai, nũae na kũthayũũkya, ũndũ mũndũ ũũ ũnũũtũmana kwakwa nĩvosye mũndũ mangũ make? Ĩndĩ nĩngũmwĩsũva, sũanĩai mwone ũndũ ũnũũnthea.'),
('kam', '2KI', 5, 8, 'Na kweethĩwa, yĩla Elisa mũndũ wa Ngai wewie kana mũsumbĩ wa Isilaeli nũtembũangĩte ngũa syake, atũmana kwa mũsumbĩ, akĩmũkũlya, Nũndũ wa kĩ ũnatembũangie ngũa syaku? Nĩoke yu vala nĩĩ, na akamanya ve mwathani nthĩnĩ wa Isilaeli.'),
('kam', '2KI', 5, 9, 'Kwondũ wa ũu Naamani ooka e na mbalasi syake na makasya make, na aũngama mũomonĩ wa nyũmba ya Elisa.'),
('kam', '2KI', 5, 10, 'Na Elisa atũma mũtũmwa vala ũĩ, akĩmwĩa, Enda ũthambe ũsĩnĩ wa Yolotani mavinda mũonza, na mwĩĩ waku ũkakũsyokea, na ũkeethĩwa mũtheu.'),
('kam', '2KI', 5, 11, 'Ĩndĩ Naamani aĩ mũthatu, na athi, na asya, Sisya, nĩsũanĩaa, nde ndĩi ya kũmbumaalĩla, na kũũngama, na kwĩkaĩla syĩtwa ya Yeova Ngai wake, na kũvĩtĩlya kw’oko kwake ĩũlũ wa vala vandũ, na kũvosya ũla ũwaĩte mangũ.'),
('kam', '2KI', 5, 12, 'Avana na Vaalivali mbũsĩ sya Ndamasiku ti nzeo kwĩ iw’ũ syonthe sya Isilaeli? Nditonya kũthambĩa nthĩnĩ wasyo, na ngeethĩwa mũtheu? Kwondũ wa ũu eethyũũa na athi athatĩte mũno.'),
('kam', '2KI', 5, 13, 'Na athũkũmi make mathengeea, na maneena nake, na masya, Asa wakwa, kethĩwa mwathani akũtavya wĩke ũndũ ũnene, ndwĩthĩwa weeka? Ti kavaa mũno ĩndĩ, akĩkwĩa, Thamba, nokĩthea?'),
('kam', '2KI', 5, 14, 'Nĩvo ĩndĩ watheeie, na eethika mavinda mũonza ũsĩnĩ wa Yolotani, kwĩanana na ndeto ya mũndũ wa Ngai; na mwĩĩ wake wasyoka wekala ĩngĩ ta mwĩĩ wa kana kanini, na aĩ mũtheu.'),
('kam', '2KI', 5, 15, 'Na amũsyokea mũndũ wa Ngai, we na nguthu yake yonthe, na ooka, na aũngama mbee wake; na asya, Sisya yu, nĩnĩsĩ vati Ngai nthĩ yonthe, ate o nthĩnĩ wa Isilaeli: yu kwondũ wa ũu, nĩngũkwĩsũva, osa mũthĩnzĩo wa mũthũkũmi waku.'),
('kam', '2KI', 5, 16, 'Ĩndĩ asya, O tondũ Yeova wĩ thayũ, ũla nĩũngamaa mbee wake, ndikosa o na ũmwe. Na amũthing’ĩĩsya ose; ĩndĩ alea.'),
('kam', '2KI', 5, 17, 'Na Naamani asya, Ethĩwa ti ũu, ĩndĩ, nĩngũkwĩsũva, mũthũkũmi waku nanengwe mũthanga wa mĩio ĩtonya kũkuwa nĩ nyũmbũ ilĩ; nũndũ mũthũkũmi waku kuma yu ndakathembea ngai ingĩ ate o Yeova, nthembo ya kũvĩvw’a kana nthembo ya kũtonywa.'),
('kam', '2KI', 5, 18, 'Yeova naekee mũthũkũmi waku ũndũnĩ ũũ: yĩla vwana wakwa wĩlikaa nyũmbanĩ ya Limoni athaithe vo, na akĩkwatĩla kw’oko kwakwa, na ngĩkunamya nyũmbanĩ ya Limoni, yĩla ngekunamya nyũmbanĩ ya Limoni, Yeova naekee mũthũkũmi waku ũndũnĩ ũsu.'),
('kam', '2KI', 5, 19, 'Na amwĩa, Enda na ũvoo. Kwondũ wa ũu auma vala ũĩ athi vandũ vaasanga.'),
('kam', '2KI', 5, 20, 'Ĩndĩ Ngeasi, mũthũkũmi wa Elisa mũndũ wa Ngai, asya, Sisya, vwana wakwa nĩwamũeka Naamani ũũ Mũsilia, ailea kwosa mokonĩ make kĩla waetie: o tondũ Yeova wĩ thayũ, ngasemba nĩmũvikile, na ngyosa kĩndũ kwake.'),
('kam', '2KI', 5, 21, 'Na ĩndĩ Ngeasi amũvikĩla Naamani. Na yĩla Naamani wonie mũndũ asembete amũvikĩlĩte, auma ĩkasyanĩ amũthaũe, na akũlya, Nĩ kũseo?'),
('kam', '2KI', 5, 22, 'Nake asũngĩa, Nĩ kũseo. Vwana wakwa nĩwandũma, akyasya Sisya, oyu kwooka anake elĩ ma ana ma athani kuma nthĩ yĩ iĩma ya Evalaimu; manenge, nĩngũkwĩsũva, talendi ya vetha, na ngũa sya ũkũan’ya makũan’ya elĩ.'),
('kam', '2KI', 5, 23, 'Na Naamani asya, Endeew’a nĩ kwosa talendi ilĩ. Na amũingĩĩsya, na ova talendi ilĩ sya vetha mĩvukonĩ ĩlĩ, vamwe na ngũa sya ũkũan’ya makũan’ya elĩ, na amaĩkya athũkũmi make elĩ; na mamĩkua me mbee wake.'),
('kam', '2KI', 5, 24, 'Na yĩla wavikie kĩĩmanĩ, amyosa kuma mokonĩ moo, na amia nyũmbanĩ, na aeka andũ asu mathi, na maenda.'),
('kam', '2KI', 5, 25, 'Ĩndĩ alika, na aũngama mbee wa vwana wake. Na Elisa amwĩa, Wauma va, Ngeasi? Na asya, Mũthũkũmi waku ndaathi vandũ.'),
('kam', '2KI', 5, 26, 'Na amũkũlya, Ngoo yakwa ndĩnaendan’ya naku, yĩla mũndũ ũsu wĩtulũlile atia ĩkasya yake akũthaũe? Nĩ ĩvinda ya kwosa mbesa, na kwosa ngũa, na mĩũnda ya mĩthata na mĩũnda ya mĩsavivũ, na malondu na ng’ombe, na athũkũmi aũme na athũkũmi eĩtu?'),
('kam', '2KI', 5, 27, 'Kwondũ wa ũu mangũ ma Naamani makalũman’ya naku, na ũsyao waku tene na tene. Na auma mbee wake eũvĩtw’e nĩ mangũ ta ĩa.'),
('kam', '2KI', 6, 1, 'Na ana ma athani mamwĩa Elisa, Sisya yu, vandũ vala twĩkalaa mbee waku vatiũtwĩanĩa.'),
('kam', '2KI', 6, 2, 'Nĩtũũkwĩsũva, tũende ũsĩnĩ wa Yolotani, na kĩla mũndũ akyumya mũtĩ vo, na tũkĩyakĩa vandũ vo, vala tũtonya kũtũa. Na amasũngĩa, Endai inyw’ĩ.'),
('kam', '2KI', 6, 3, 'Na ũmwe asya, Edeew’a nĩngũkwĩsũva, nĩ kũendan’ya na athũkũmi maku. Na asũngĩa, Nĩngũthĩ.'),
('kam', '2KI', 6, 4, 'Kwondũ wa ũu aendan’ya nao. Na yĩla mavikie Yolotani, matema mĩtĩ.'),
('kam', '2KI', 6, 5, 'Ĩndĩ yĩla ũmwe wavalũkasya mũtĩ, ĩthoka yasingĩla yavota manzĩnĩ; na akaya, na asya, Ĩiaa, vwana wakwa! Nũndũ nĩ ya mboya.'),
('kam', '2KI', 6, 6, 'Na ũ mũndũ wa Ngai akũlya, Yavotela va? Na amwon’ya vala vandũ. Na atema kamũtĩ, na akekya vo, na kũtuma kĩaa kĩthambĩa.'),
('kam', '2KI', 6, 7, 'Na asya, Yose. Na ĩndĩ atambũũkya kw’oko kwake, na akyosa.'),
('kam', '2KI', 6, 8, 'Na ĩndĩ mũsumbĩ wa Silia nĩwakwatĩtye kaũ na Isilaeli; na asũanĩa na athũkũmi make, akyasya, Mwako wakwa wa maeema ũkeethĩwa vana.'),
('kam', '2KI', 6, 9, 'Na ũla mũndũ wa Ngai atũmana kwa mũsumbĩ wa Isilaeli, akĩmwĩa, Ĩsũvĩe ndũkavĩtĩle vandũ vana; nũndũ Asilia nĩmatheeete vo.'),
('kam', '2KI', 6, 10, 'Na mũsumbĩ wa Isilaeli atũmana vandũ vala mũndũ wa Ngai wamũtavisye na wamũtaie ũndũ wa vo; na eetangĩĩa vo, ti ĩmwe kana kelĩ.'),
('kam', '2KI', 6, 11, 'Na ngoo ya mũsumbĩ wa Silia yathĩnw’a mũno nũndũ wa ũndũ ũsu; na ameta athũkũmi make, na amea, Mũtiũmbon’ya nĩ wĩva waitũ ũla wĩ ngalĩ ya mũsumbĩ wa Isilaeli?'),
('kam', '2KI', 6, 12, 'Na ũmwe wa athũkũmi make amwĩa, Aiee, mwĩaĩi wakwa, ame mũsumbĩ; ĩndĩ Elisa, mwathani ũla wĩ nthĩnĩ wa Isilaeli, nũtavasya mũsumbĩ wa Isilaeli ndeto ila ũneeneaa kasũmbanĩ kaku ka ũkoma.'),
('kam', '2KI', 6, 13, 'Na amea, Endai mũsisye vala ũĩ, nĩ kana nĩtũmane na kũmũete. Na atavw’a, kũkyaw’a, Sisya e Ndothani.'),
('kam', '2KI', 6, 14, 'Kwondũ wa ũu atũma mbalasi, na makasya, na nguthu nene kw’o: na mooka ũtukũ, na mathyũlũlũka ndũa.'),
('kam', '2KI', 6, 15, 'Na yĩla mũthũkũmi wa mũndũ wa Ngai wokĩlile kĩoko tene, na aumaala, sisya, nguthu yĩ na mbalasi na makasya yathyũlũlũkĩte ndũa. Na mũthũkũmi wake amwĩa, Ĩiaa, vwana wakwa! Tũkeeka ata?'),
('kam', '2KI', 6, 16, 'Na asũngĩa, Ndũkakĩe; nũndũ ala me vamwe naitũ nĩ aingĩ kwĩ ala me na asu.'),
('kam', '2KI', 6, 17, 'Na Elisa avoya, na asya, Yeova, nĩngũkũvoya, salukya metho make, one. Na Yeova asalukya metho ma mwanake ũsu; na oona: na, sisya, kĩĩma kyusũĩte mbalasi na makasya ma mwaki mathyũlũlũkĩte Elisa.'),
('kam', '2KI', 6, 18, 'Na yĩla matheeie vala ũĩ, Elisa amũvoya Yeova, na asya, Nĩngũkũvoya, kũna andũ aa na mbindu. Na amakũna na mbindu kwĩanana na ndeto ya Elisa.'),
('kam', '2KI', 6, 19, 'Na Elisa amea, Ĩno ti nzĩa, o na ĩno tiyo ndũa: mbikĩlai, na ngamũvikya vala ve mũndũ ũla mũmamthaa. Na amatongoesya mavika Samalia.'),
('kam', '2KI', 6, 20, 'Na kweethĩwa, yĩla malikile Samalia, Elisa asya, Yeova, salukya metho ma andũ aa, mone. Na Yeova asalukya metho moo, na moona; na, sisya, maĩ Samalia katĩ.'),
('kam', '2KI', 6, 21, 'Na mũsumbĩ wa Isilaeli amwĩa Elisa, yĩla wamonie, Asa wakwa, nĩngũmakũna? Nĩngũmakũna?'),
('kam', '2KI', 6, 22, 'Na asũngĩa, Ndũkamakũne: nũkwenda kũkũna ala watavie na ũvyũ waku na ũta waku? Ia lĩu na manzĩ mbee woo, nĩ kana maye na manyw’e, na kũsyoka kwa vwana woo.'),
('kam', '2KI', 6, 23, 'Na aseũvya lĩu mwingĩ kwondũ woo; na yĩla maminie kũya na kũnyw’a, amaeka mathi, na mathi kwa vwana woo. Na nguthu sya Silia ityaaũka ĩngĩ nthĩ ya Isilaeli.'),
('kam', '2KI', 6, 24, 'Na kweethĩwa ĩtina wa ũu, Mbeni‐aatati mũsumbĩ wa Silia oomban’ya ngũthu yake yonthe, na ambata, na athyũlũlũka Samalia amĩtw’ĩkanĩsya.'),
('kam', '2KI', 6, 25, 'Na kwaĩ yũa ĩnene Samalia: na, sisya, mamĩtw’ĩkanĩsya, kũvika mũtwe wa ĩng’oi wathooiw’e ilungu mĩongo nyanya sya vetha, na kĩlungu kya kana kya kavu kya mai ma mavũĩ, ilungu itano sya vetha.'),
('kam', '2KI', 6, 26, 'Na mũsumbĩ wa Isilaeli akĩvĩtĩla ũvainĩ, mũndũ mũka amwĩkaĩla, akĩmwĩa, Ndethya, mwĩaĩi wakwa, ame mũsumbĩ.'),
('kam', '2KI', 6, 27, 'Na asya, Ethĩwa Yeova ndeũkũtethya, nyie ngakũtethya na ũtethyo wumĩte va? Kuma kĩvũĩonĩ, kana kuma kĩangĩonĩ kya nzavivũ?'),
('kam', '2KI', 6, 28, 'Na mũsumbĩ amũkũlya, Wĩ na ũndũ mwaũ. Na asũngĩa, Mũndũ mũka ũũ anambĩie, Umya mwana waku, tũmũye ũmũnthĩ, na tũkaya mwana wakwa ũnĩ.'),
('kam', '2KI', 6, 29, 'Na ĩndĩ tũnaua mwana wakwa, na tũnamũya: na namwĩa ũnĩ ũsu, Umya mwana waku, tũmũye; na nũvithĩte mwana wake.'),
('kam', '2KI', 6, 30, 'Na kweethĩwa, yĩla mũsumbĩ wewie ndeto sya ũ mũndũ mũka, atembũanga ngũa syake (na nĩwavĩtĩle ĩũlũ wa ũvai); na andũ moona, na, sisya, aĩ na ĩkunia nthĩnĩ mwĩĩnĩ wake.'),
('kam', '2KI', 6, 31, 'Nĩvo ĩndĩ waisye, Ngai nambĩke ũu, o na mbee, ethĩwa mũtwe wa Elisa mwana wa Savati ũkekala ĩũlũ wake ũmũnthĩ.'),
('kam', '2KI', 6, 32, 'Ĩndĩ Elisa ekalĩte nyũmbanĩ yake, na atumĩa mekalĩte nake; na mũsumbĩ atũma mũndũ kuma vala ũĩ: ĩndĩ mũtũmwa atanamba ũvika vala ũĩ, atavya atumĩa, Nĩmũkwona ũndũ mwana ũũ wa mũaani ũtũmĩte mũndũ avete mũtwe wakwa? Sisyai, yĩla mũtũmwa ũnũũka, vingai mũomo, na mũilũmya mũomo ndakalike: matuu ma maũũ ma vwana wake matiĩ ĩtina wake?'),
('kam', '2KI', 6, 33, 'Na o akĩneena nao, sisya, mũtũmwa atheea vala ũĩ: na asya, Sisya, ũthũku ũũ wumĩte kwa Yeova; nĩmweteelela Yeova ĩvinda yĩasanga kĩ?'),
('kam', '2KI', 7, 1, 'Na Elisa asya, Ĩw’ai ndeto ya Yeova: ũũ nĩw’o Yeova ũnũkwasya, Ũnĩ ta ĩvinda yĩĩ kĩthimo kya mũtu mũvinyũ kĩkathoow’a na sekeli, na ithimo ilĩ sya mbaale na sekeli, mbingĩlonĩ ya Samalia.'),
('kam', '2KI', 7, 2, 'Nĩvo ĩndĩ kavuteni ũla mũsumbĩ wekwatĩlaa kw’oko kwake wasũngĩie mũndũ wa Ngai, na amwĩa, Sisya, o na kethĩwa Yeova akaseũvya mbũthi ĩtunĩ, ũndũ ũsu nũtonya kwĩthĩwa? Na amũsũngĩa, Sisya, ũkawona na metho maku, ĩndĩ ndũkaya.'),
('kam', '2KI', 7, 3, 'Na ĩndĩ kwaĩ andũ ana mawaĩte mangũ ku ũlikĩlonĩ mbingĩlonĩ: na maneenan’ya ũmwe na ũla ũngĩ, Twĩĩkala vaa mũvaka twĩkw’a nĩkĩ?'),
('kam', '2KI', 7, 4, 'Ethĩwa twĩasya, Nĩtũũlika ndũanĩ, yũa yĩ ndũanĩ, na tũkakw’ĩa vo; na ethĩwa tũkekala vaa tũvindĩtye, no twĩkw’a. Kwondũ wa ũu ĩndĩ ũkai, na tũvalũke mokonĩ ma nguthu ya Asilia: ethĩwa nĩmeũtũeka twĩ thayũ, tũkekala thayũ; na ethĩwa nĩmekũtũaa, no twĩkw’a.'),
('kam', '2KI', 7, 5, 'Na mookĩla kwĩ ũmithi, maende mwakonĩ wa maeema wa Asilia; na yĩla mavikie ũtee wa mwako wa maeema wa Asilia, kaĩ, kũtyaĩ mũndũ vo.'),
('kam', '2KI', 7, 6, 'Nũndũ Mwĩaĩi nĩwatumie nguthu ya Asilia yĩw’a kĩtuu kya makasya, na kĩtuu kya mbalasi, o kĩtuu kya nguthu nene: na maneenan’ya ene kwa ene, Kaĩ, mũsumbĩ wa Isilaeli nũmaandĩkĩte asumbĩ ma Aititi na asumbĩ ma Amisili, matũvithũkĩe.'),
('kam', '2KI', 7, 7, 'Kwondũ wa ũu mookĩla na makĩa kwĩ ũmithi, na matia maeema moo, na mbalasi syoo, na mang’oi moo, o mwako wa maeema ũndũ wailyĩ, na makĩa matangĩĩe thayũ woo.'),
('kam', '2KI', 7, 8, 'Na yĩla asu mawaĩte mangũ mavikie ũtee wa mwako wa maeema, malika ĩeemanĩ yĩmwe, na maya na manyw’a, na makua kumya vo vetha, na thaavu, na ngũa, na mathi na maivitha; na masyoka, na malika ĩeemanĩ yĩngĩ, na makua kumya o na vo, na mathi na maivitha.'),
('kam', '2KI', 7, 9, 'Nĩvo ĩndĩ maneenanisye ene kwa ene, Tũtikwĩka nesa; ũmũnthĩ nĩ mũthenya wa ũvoo mũseo, na ithyĩ nĩtũvindĩtye: ethĩwa twĩĩkala kũvika kĩoko kũikya, ũsilĩlo ũkatũvikĩla; kwondũ wa ũu ĩndĩ ũkai, tũende tũtavye andũ ma nyũmba ya mũsumbĩ:'),
('kam', '2KI', 7, 10, 'Kwondũ wa ũu mooka na meeta mũsũvĩi wa mũomonĩ wa ndũa; na matavan’ya, makyasya, Twavika mwako wa maeema wa Asilia, na, kaĩ, kũtiĩĩ mũndũ vo, o na wasya wa mũndũ, ĩndĩ no mbalasi syovetwe, na mang’oi movetwe, na maeema o ũndũ mailyĩ.'),
('kam', '2KI', 7, 11, 'Na ameta asũvĩi; na matavya andũ ma nyũmba ya mũsumbĩ me nthĩnĩ.'),
('kam', '2KI', 7, 12, 'Na mũsumbĩ ookĩla ũtukũ, na amea athũkũmi make, Nĩngũmwon’ya yu ũndũ Asilia matwĩkĩte. Nĩmesĩ twĩ na nzaa; kwondũ wa ũu nĩmaumĩte mwakonĩ wa maeema mevithe kĩthekanĩ, makyasya, Yĩla meuma ndũanĩ, tũkamakwata me thaũ, na tũilika ndũanĩ.'),
('kam', '2KI', 7, 13, 'Na ũmwe wa athũkũmi make asũngĩa, na asya, Nĩngũkwĩsũva, amwe nĩmose mbalasi itano sya ila itialĩte, ila itialĩtw’e ndũanĩ (sisya, isu no ta ĩkomano yonthe ya Isilaeli yĩla yĩtialĩte nthĩnĩ wayo; sisya, isu no ta ĩkomano yonthe ya Isilaeli yĩla yĩminĩtwe); na tũtũmanei twone.'),
('kam', '2KI', 7, 14, 'Kwondũ wa ũu moosa makasya elĩ me na mbalasi; na mũsumbĩ atũmana maatiĩe nguthu ya Asilia, akyasya, Endai mũsisye.'),
('kam', '2KI', 7, 15, 'Na mamaatĩĩa kũvika Yolotani: na, kaĩ, nzĩa yonthe yausũĩte ngũa na mĩio, ĩla Asilia malekangilye mekalaatĩte. Na atũmwa masyoka, na matavya mũsumbĩ.'),
('kam', '2KI', 7, 16, 'Na andũ maumaala, na matava mwakonĩ wa maeema wa Asilia. Na kwondũ wa ũu kĩthimo kya mũtu mũvinyu wathoow’a sekeli, na ithimo ilĩ sya mbaale sekeli, kwĩanana na ndeto ya Yeova.'),
('kam', '2KI', 7, 17, 'Na mũsumbĩ aia kavuteni ũla wekwatĩlaa kw’oko kwake ethĩwe akĩsũvĩa mbingĩlo: na andũ mamũkinyangĩa mbingĩlonĩ, na akw’a o tondũ mũndũ wa Ngai ũnaisye, ũla ũnaneenie yĩla mũsumbĩ ũnatheeie vala ũĩ.'),
('kam', '2KI', 7, 18, 'Na kweethĩwa o tondũ mũndũ wa Ngai ũnatavĩtye mũsumbĩ, akyasya, Ithimo ilĩ sya mbaale sekeli, na kĩthimo kya mũtu mũvinyu sekeli, kũkeethĩwa ũu ũnĩ ta ĩvinda yĩĩ mbingĩlonĩ ya Samalia;'),
('kam', '2KI', 7, 19, 'na kavuteni ũsu asũngĩa mũndũ wa Ngai, na amwĩa, Yu, sisya, o na kethĩwa Yeova akaseũvya mbũthi ĩtunĩ, ũndũ ta ũsu nũtonya kwĩthĩwa? Na amũsũngĩa, Sisya, ũkawona na metho maku, ĩndĩ ndũkaya;'),
('kam', '2KI', 7, 20, 'kweethĩiwe o w’o kwake; nũndũ andũ nĩmamũkinyangĩe mbingĩlonĩ, na akw’a.'),
('kam', '2KI', 8, 1, 'Na ĩndĩ Elisa nĩwaneenete na mũndũ mũka, ũla wathayũũkĩsye mwana, akĩmwĩa, Ũkĩla, ũende we na andũ ma nyũmba yaku, nokĩkala ũeni o vala ũtonya kwĩkala: nũndũ Yeova nĩwĩtĩte yũa yũke; nayo yĩkooka ĩũlũ wa nthĩ myaka mũonza.'),
('kam', '2KI', 8, 2, 'Na ũla mũndũ mũka ookĩla, na eeka kwĩanana na ndeto ya mũndũ wa Ngai; na athi na andũ ma nyũmba yake, na ekala ũeni nthĩ ya Avilisiti myaka mũonza.'),
('kam', '2KI', 8, 3, 'Na kweethĩwa ĩtina wa myaka mũonza yathela, mũndũ mũka ũsu asyoka kuma nthĩ ya Avilisiti: na aenda amwĩkaĩle mũsumbĩ kwondũ wa nyũmba yake na nthĩ yake.'),
('kam', '2KI', 8, 4, 'Na ĩndĩ mũsumbĩ aĩ akĩneena na Ngeasi mũthũkũmi wa mũndũ wa Ngai, akĩmwĩa, Ndavya, nĩngũkwĩsũva, maũndũ onthe manene ala Elisa wĩkĩte.'),
('kam', '2KI', 8, 5, 'Na kweethĩwa, yĩla waĩ aimũtavya mũsumbĩ ũndũ wamũthayũũkisye ũla waĩ mũkw’ũ, sisya, mũndũ mũka ũsu ũla wathayũũkĩw’e mwana wake, amwĩkaĩla mũsumbĩ kwondũ wa nyũmba yake na nthĩ yake. Na Ngeasi asya, Mwĩaĩi wakwa, ame mũsumbĩ, ũũ nĩwe ũla mũndũ mũka, na ũũ nĩwe mwana wake, ũla Elisa wamũthayũũkisye.'),
('kam', '2KI', 8, 6, 'Na yĩla mũsumbĩ wakũlilye mũndũ mũka, amũtavya. Kwondũ wa ũu mũsumbĩ amumĩsya mũnene ũmwe wa kwake, akĩmwĩa, Tuma atũngĩwa kyonthe kĩla kyaĩ kyake, na mosyao onthe ma mũũnda kuma mũthenya ũla watiie ĩ nthĩ, o na kũvika yu.'),
('kam', '2KI', 8, 7, 'Na Elisa aenda Ndamasiku; na Mbeni‐aatati mũsumbĩ wa Silia aĩ mũwau; na atavw’a, kũkyaw’a, Mũndũ wa Ngai nĩ mũku kũũ.'),
('kam', '2KI', 8, 8, 'Na mũsumbĩ amwĩa Aasaeli, Kua mũthĩnzĩo na kw’oko kwaku, noienda, ũthaũe mũndũ wa Ngai, na kũmũkũlya Yeova kwa kanyw’a wake, ũkyasya, Ngavoa ũwau ũũ?'),
('kam', '2KI', 8, 9, 'Na ĩndĩ Aasaeli aenda kũmũthaũa, akuĩte mũthĩnzĩo, o wa kĩla kĩndũ kĩseo kya Ndamasiku, mĩio ĩkuwa nĩ ngamĩle mĩongo ĩna, na ooka na aũngama mbee wake, na asya, Mwana waku Mbeni‐aatati mũsumbĩ wa Silia nũndũmĩte vala ũĩ, aikũlya, Ngavoa ũwau ũũ?'),
('kam', '2KI', 8, 10, 'Na Elisa amwĩa, Enda, ũmwĩe, Ndwĩtĩa ũvoa; ĩndĩ Yeova nũmbonetye ndakatĩa ũkw’a.'),
('kam', '2KI', 8, 11, 'Na amũketeea mũno, mũvaka asonoka: na mũndũ wa Ngai aĩa.'),
('kam', '2KI', 8, 12, 'Na Aasaeli akũlya, Mwĩaĩi wakwa eĩĩa kĩ? Na asũngĩa, Nũndũ nĩnĩsĩ ũthũku ũla ũkameka ana ma Isilaeli: ngome syoo syĩ vinya ũkavĩvya na mwaki, na anake moo ũkamoaa na ũvyũ, na twana twoo tũũkenge ũkatũng’atan’ya tũtilĩkange, na ũkataũa aka moo ala aito.'),
('kam', '2KI', 8, 13, 'Na Aasaeli asya, Ĩndĩ mũthũkũmi waku nĩ mwaũ, ũla no ta ngitĩ, nĩ kana eke ũndũ ũnenevete ũu? Na Elisa asũngĩa, Yeova nũmbonetye atĩ ũkeethĩwa mũsumbĩ wa Silia.'),
('kam', '2KI', 8, 14, 'Na ĩndĩ auma vala ve Elisa, na ooka vala ve vwana wake; ũla wamũkũlilye, Elisa akwĩa ata? Na asũngĩa, Ambĩa ndwĩtĩa kũvoa.'),
('kam', '2KI', 8, 15, 'Na kweethĩwa ũnĩ ũsu oosa ĩvula, na ayĩinda manzĩnĩ, na amũkunĩkĩlya ũthyũ, na ĩndĩ akw’a: na Aasaeli asumbĩka vandũ vake.'),
('kam', '2KI', 8, 16, 'Na mwaka wa katano wa kũsumbĩka kwa Yolamu mwana wa Aavu mũsumbĩ wa Isilaeli, Yeosavati e o mũsumbĩ wa Yuta ĩvinda yĩu, Yeolamu mwana wa Yeosavati mũsumbĩ wa Yuta ambĩlĩlya kũsumbĩka.'),
('kam', '2KI', 8, 17, 'Aĩ wa myaka mĩongo ĩtatũ na ĩlĩ yĩla wambĩlĩlye kũsumbĩka; na asumbĩka myaka nyanya Yelusaleme.'),
('kam', '2KI', 8, 18, 'Na aendaa mũendelenĩ wa asumbĩ ma Isilaeli, o tondũ nyũmba ya Aavu yekaa: nũndũ nĩwatwaĩte mwĩĩtu wa Aavu ethĩwe kĩveti kyake; na nĩwekaa ũla Yeova wonaa wĩ ũthũku.'),
('kam', '2KI', 8, 19, 'Ĩndĩ Yeova ndaaĩtĩkĩla kwananga Yuta, kwondũ wa Ndaviti mũthũkũmi wake, nũndũ nĩwamwathĩte akamũnenga taa kwondũ wa syana syake ĩvinda yonthe.'),
('kam', '2KI', 8, 20, 'Mĩthenyanĩ yake andũ me Etomu nĩmang’endie meyumye kw’okonĩ kwa Yuta, na meesumbĩkĩsya mũsumbĩ.'),
('kam', '2KI', 8, 21, 'Nĩvo ĩndĩ Yolamu waingie aenda Nzaili, e na makasya make onthe ma kaũ; na ookĩla ũtukũ, na akũna Aetomu ala mamũthyũlũlũkĩte, na makavuteni ma makasya; na andũ makĩa mathi maeemanĩ moo.'),
('kam', '2KI', 8, 22, 'Na ĩndĩ andũ ma Etomu mang’enda meeyumya kw’okonĩ kwa Yuta kũvika ũmũnthĩ. Nĩvo ĩndĩ andũ ma Livina mang’endie ĩvinda yĩu.'),
('kam', '2KI', 8, 23, 'Na meko ala angĩ ma Yolamu, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta?'),
('kam', '2KI', 8, 24, 'Na Yolamu akoma na aaĩthe make, na athikwa na aaĩthe make ndũanĩ ya Ndaviti; na Aasia mwana wake asumbĩka vandũ vake.'),
('kam', '2KI', 8, 25, 'Mwaka wa ĩkũmi na ĩlĩ ya kũsumbĩka kwa Yolamu mwana wa Aavu mũsumbĩ wa Isilaeli, Aasia mwana wa Yeolamu mũsumbĩ wa Yuta ambĩlĩlya kũsumbĩka.'),
('kam', '2KI', 8, 26, 'Aasia aĩ wa myaka mĩongo ĩlĩ an ĩlĩ yĩla wambĩlĩlye kũsumbĩka; na asumbĩka mwaka ũmwe Yelusaleme. Na syĩtwa ya inyia wake eetawa Athalia mwĩĩtu wa Omili mũsumbĩ wa Isilaeli.'),
('kam', '2KI', 8, 27, 'Na nĩwaendaa mũendelenĩ wa nyũmba ya Aavu, na eekaa ũla Yeova wonaa wĩ ũthũku, o tondũ nyũmba ya Aavu yekaa; nũndũ aĩ mũthoni wa nyũmba ya Aavu.'),
('kam', '2KI', 8, 28, 'Na aenda na Yolamu mwana wa Aavu okite na Aasaeli mũsumbĩ wa Silia ku Lamothi‐ngileati: na Asilia mamũkita Yolamu.'),
('kam', '2KI', 8, 29, 'Na mũsumbĩ Yolamu asyoka avoee ku Yesileeli mawũkite ala Asilia mamũkitĩe Lama, yĩla wokitaa na Aasaeli mũsumbĩ wa Silia. Na Aasia mwana wa Yeolamu mũsumbĩ wa Yuta atheea kũsisya Yolamu mwana wa Aavu ku Yesileeli, nũndũ aĩ mũwau.'),
('kam', '2KI', 9, 1, 'Na mwathani Elisa eeta ũmwe wa ana ma athani, na amwĩa, Ĩvotoe kĩnyunyu kyaku, nokyosa sũva ũũ wa mauta kw’okonĩ kwaku, ũende Lamothi‐ngileati.'),
('kam', '2KI', 9, 2, 'Na wavika kw’o, mũmanthe Yeu mwana wa Yeosavati mwana wa Nimisi, noilika, ũmũkĩlye kuma katĩ wa ana‐a‐ĩthe make, noienda nake kasũmbanĩ ke nthĩnĩ.'),
('kam', '2KI', 9, 3, 'Nĩvo ĩndĩ wĩosa sũva wa mauta, noimwĩtĩkĩsya mũtwe, na mwĩe, Ũũ nĩw’o Yeova ũnũkwasya, Nĩnakwĩtĩkĩsya mauta wĩthĩwe mũsumbĩ wa Isilaeli. Na ĩndĩ vingũa mũomo, ũkũke, na ndũkekale.'),
('kam', '2KI', 9, 4, 'Kwondũ wa ũu ũ mwanake, o ũsu mwanake mwathani, aenda Lamothi‐ngileati.'),
('kam', '2KI', 9, 5, 'Na yĩla wavikie, sisya, makavuteni ma nguthu mekalĩte nthĩ; na asya, Nĩ na ũtũmane kwaku, we kavuteni. Na Yeu akũlya, Kwa wĩva wa ithyonthe? Na asũngĩa, Kwaku, we kavuteni.'),
('kam', '2KI', 9, 6, 'Na ookĩla, na alika nyũmbanĩ; na amwĩtĩkĩsya mauta mũtwe, na amwĩa, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Nĩnĩkwĩtĩkĩĩtye mauta wĩthĩwe mũsumbĩ wa andũ ma Yeova, o Isilaeli.'),
('kam', '2KI', 9, 7, 'Na ũkakũne nyũmba ya Aavu vwana waku, nĩ kana nĩĩvanĩsye nthakame ya athũkũmi makwa athani, na nthakame ya athũkũmi onthe ma Yeova, kw’okonĩ kwa Yeseveli.'),
('kam', '2KI', 9, 8, 'Nũndũ nyũmba yonthe ya Aavu ĩkaanangwa; na ngaveta kwa Aavu kĩla mwana mũũme, na ũla wĩĩthĩwa mwove na ũla wĩĩthĩwa ate mwove nthĩnĩ wa Isilaeli.'),
('kam', '2KI', 9, 9, 'Na ngatw’ĩkĩthya nyũmba ya Aavu ta nyũmba ya Yelovoamu mwana wa Nevati, na ta nyũmba ya Mbaasa mwana wa Aiya.'),
('kam', '2KI', 9, 10, 'Na ngitĩ ikamũĩa Yeseveli kĩlungunĩ kya nthĩ kya Yesileeli, na kũtikethĩwa ũmwe wa kũmũthika. Na avingũa mũomo, na akũka.'),
('kam', '2KI', 9, 11, 'Nĩvo ĩndĩ Yeu wamaumaalĩle athũkũmi ma mwĩaĩi wake: na ũmwe amũkũlya, Nĩ kũseo? Mũndũ ũsu wa ndũũka wũkie vala ũĩ nũndũ wa kĩ? Na amea, Nĩmwĩsĩ mũndũ ũsu na ũndũ kũneena kwake kwĩĩilyĩ.'),
('kam', '2KI', 9, 12, 'Na mwĩa, Nĩ ũvũngũ; tũtavye oyu. Na asya, Aneena nakwa ũna na ũna, akĩmbĩa, Ũũ nĩw’o Yeova ũnũkwasya, Nĩnĩkwĩtĩkĩĩtye mauta wĩthĩwe mũsumbĩ wa Isilaeli.'),
('kam', '2KI', 9, 13, 'Nĩvo ĩndĩ meekalaatile, na moosa kĩla mũndũ ngũa yake, na masia ungu wake me mbasyanĩ ĩũlũ, na mavuva soo, makyasya, Yeu nĩ mũsumbĩ.'),
('kam', '2KI', 9, 14, 'Kwondũ wa ũu Yeu mwana wa Yeosavati mwana wa Nĩmisi amũsamĩa Yolamu. (Na ĩndĩ Yolamu nĩwasũvĩĩte Lamothi‐ngileati, we na Isilaeli onthe, nũndũ wa Aasaeli mũsumbĩ wa Silia;'),
('kam', '2KI', 9, 15, 'ĩndĩ mũsumbĩ Yolamu aĩ anasyoka akavoee ku Yesileeli mawũkite ala mamũkitĩte, yĩla wokitaa na Aasaeli mũsumbĩ wa Silia.) Na Yeu asya, Ethĩwa kwenda kwenyu kũilyĩ ũũ, mũtikaeke ĩndĩ ũmwe avonoke kuma ndũanĩ, aende akatavan’ye ũvoo ku Yesileeli.'),
('kam', '2KI', 9, 16, 'Kwondũ wa ũu Yeu akuwa nĩ ĩkasya, na athi Yesileeli; nũndũ Yolamu akomete kw’o. Na Aasia mũsumbĩ wa Yuta aĩ anatheea kũmũsisya Yolamu.'),
('kam', '2KI', 9, 17, 'Na ĩndĩ mũsyaĩĩsya nĩwaũngamĩte mwakonĩ mũtũlu wa mũnyoolo ku Yesileeli, na esa kwona nguthu ya Yeu okanĩtye nayo, na asya, Nĩngwona nguthu. Na Yolamu asya, Osa mũndũ ũtũlaa mbalasi, noimũtũma amĩthaũe, nake nakakũlye, Nĩ mũuo?'),
('kam', '2KI', 9, 18, 'Kwondũ wa ũu ũmwe athi atũlĩte mbalasi amũthaũe, na asya, Ũũ nĩw’o mũsumbĩ ũnũkwasya, Nĩ mũuo? Na Yeu asya, Wĩ ũndũ mwau na mũuo? Syoka ĩtina wakwa. Na ũla mũsyaĩĩsya atavan’ya, akyasya, Mũtũmwa avika vala maĩ, ĩndĩ ndeũsyoka.'),
('kam', '2KI', 9, 19, 'Na ĩndĩ atũma ũngĩ wa kelĩ atũlĩte mbalasi, ũla nake wavikie vala maĩ, na asya, Ũũ nĩwo mũsumbĩ ũnũkwasya, Nĩ mũuo? Na Yeu asũngĩa, Wĩ ũndũ mwaũ na mũuo? Syoka ĩtina wakwa.'),
('kam', '2KI', 9, 20, 'Na mũsyaĩĩsya atavan’ya, akyasya, Avika o vala maĩ, na ndeũsyoka: na mũtwaĩle nĩ ta mũtwaĩle wa Yeu mwana wa Nimisi; nũndũ nũtwĩate ta mũndũ wa ndũũka.'),
('kam', '2KI', 9, 21, 'Na Yolamu asya, Ovai ĩkasya. Na moova ĩkasya yake ya kaũ. Na Yolamu mũsumbĩ wa Isilaeli na Aasia mũsumbĩ wa Yuta maumaala, kĩla ũmwe e ĩkasyanĩ yake, na maumaala mamũthaũe Yeu, na mamwĩthĩa kĩlungunĩ kya nthĩ kya Navothi Mũyesileeli.'),
('kam', '2KI', 9, 22, 'Na kweethĩwa, yĩla Yolamu wonie Yeu, akũlya, Nĩ mũuo, Yeu? Na asũngĩa, Mũuo mwaũ, ĩvinda yĩla ũmalwaya wa inyia waku Yeseveli na mooi make maingĩvĩte ũu?'),
('kam', '2KI', 9, 23, 'Na Yolamu athyũũa moko make, na akĩa, na amwĩa Aasia, Kwĩ ũkengani, we Aasia.'),
('kam', '2KI', 9, 24, 'Na Yeu akoota ũta wake na vinya wake w’onthe, na aathĩla Yolamu katĩ wa ituo syake; na mũsyĩ wakuthũkĩla ngoonĩ yake, na ang’uthũka ĩkasyanĩ yake.'),
('kam', '2KI', 9, 25, 'Nĩvo ĩndĩ Yeu wamũtavisye Mbitikali kavuteni wake, Mũkĩlye, noimwĩkya kĩlungunĩ kya mũũnda wa Navothi Mũyesileeli; nũndũ lilikana yĩla nyie naku twaendanasya vamwe tũkuĩtwe twĩ ĩtina wa Aavu ĩthe wake, ũndũ Yeova waiie mũio ũũ ĩũlũ wake:'),
('kam', '2KI', 9, 26, 'Vate ndĩi nĩnonete ĩoo nthakame ya Navothi, na nthakame ya ana make, easya ũu Yeova; na ngakũĩvĩa kĩlungunĩ kĩĩ kya nthĩ, easya ũu Yeova. Yu kwondũ wa ũu mwose noimwĩkya kĩlungunĩ kĩĩ kya nthĩ, kwĩanana na ndeto ya Yeova.'),
('kam', '2KI', 9, 27, 'Ĩndĩ yĩla Aasia mũsumbĩ wa Yuta wonie ũu, akũka na nzĩa ĩvĩtĩle nyũmba yĩ mũũndanĩ. Na Yeu amũatĩĩa, na asya, Mũkũnei nake e ĩkasyanĩ: na mamũkũnĩa kyambatonĩ kya Nguli, ĩla yĩ vakuvĩ na Ivileamu. Na akĩĩa Mekito, na akw’ĩa kw’o.'),
('kam', '2KI', 9, 28, 'Na athũkũmi make mamũkua e ĩkasyanĩ kũvika Yelusaleme, na mamũthika ngunganĩ yake vala vathikawa akw’ũ vamwe na aaĩthe make ndũanĩ ya Ndaviti.'),
('kam', '2KI', 9, 29, 'Na mwaka wa ĩkũmi na ũmwe wa kũsumbĩka kwa Yolamu mwana wa Aavu, Aasia ambĩlĩlya kũsumbĩka Yuta.'),
('kam', '2KI', 9, 30, 'Na yĩla Yeu wavikie Yesileeli, Yeseveli eew’a ũu; na avaka metho make langi, na eekĩa kĩmanza mũtwe wake, na asyaĩlya mbũthinĩ.'),
('kam', '2KI', 9, 31, 'Na yĩla Yeu walikaa mbingĩlonĩ, asya, Nĩ mũuo, we Nzimili, mũai wa vwana waku?'),
('kam', '2KI', 9, 32, 'Na ang’elelya ũthyũ wake mbũthinĩ, na akũlya, Nũũ ũla wĩ ngalĩ yakwa? Nũũ? Na avakũe elĩ kana atatũ mamũkunĩkĩla.'),
('kam', '2KI', 9, 33, 'Nake asya, Mwĩkyei nthĩ. Na ĩndĩ mamwĩkya nthĩ; na nthakame ĩmwe yake yatalĩkangĩla ũvai, na mbalasi: nake amũangan’ya na maũũ.'),
('kam', '2KI', 9, 34, 'Na yĩla walikile, aya na anyw’a; na asya, Sisyai yu mũndũ mũka ũũ mũumanĩe, na mũimwĩnzĩa nthĩ; nũndũ nĩ mwĩĩtu wa mũsumbĩ.'),
('kam', '2KI', 9, 35, 'Na mathi mamwĩnzĩe nthĩ; ĩndĩ matyaamwĩthĩa ate o kĩng’ala, na nyaĩĩ, na itaa sya moko make.'),
('kam', '2KI', 9, 36, 'Kwondũ wa ũu masyoka, na mamũtavya. Nake asya, Ĩno nĩyo ndeto ya Yeova, ĩla waneenie na kanyw’a wa mũthũkumĩ wake Eliya Mũtisivi, akyasya, Kĩlungunĩ kya nthĩ kya Yesileeli ngiti ikaya nyama sya mwĩĩ wa Yeseveli;'),
('kam', '2KI', 9, 37, 'na kimba kya Yeseveli kĩkeethĩwa ta vũũ ĩũlũ wa mũũnda kĩlungunĩ kya nthĩ kya Yesileeli, nĩ kana matikaaneene, Ũũ nĩwe Yeseveli.'),
('kam', '2KI', 10, 1, 'Na ĩndĩ Aavu aĩ na ana aũme mĩongo mũonza Samalia. Na Yeu aandĩka mavalũa, na amatwaa Samalia, kwa asumbĩki ma ku Yesileeli, o atumĩa, na kwa ala maeie ana ma Aavu, akĩmea,'),
('kam', '2KI', 10, 2, 'Na yu o yĩla valũa ũũ wĩmũvikĩa, nũndũ ana ma vwana wenyu me vamwe nenyu, na mwĩ na makasya ma kaũ na mbalasi, o na ndũa mbiie, na mĩio ya kaũ;'),
('kam', '2KI', 10, 3, 'manthai ũla mũseo mbee na mwaĩlu wa ana ma vwana wenyu, na mwiei kĩvĩlanĩ kya ũsumbĩ kya ĩthe wake, na mũkyũkitĩa nyũmba ya vwana wenyu.'),
('kam', '2KI', 10, 4, 'Ĩndĩ meew’a w’ĩa mũno, na masya, Sisyai, asumbĩ asu elĩ matyaaũngama mbee wake: ithyĩ ĩndĩ tũkaũngama ata?'),
('kam', '2KI', 10, 5, 'Na ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba, na ũla waĩ mũnene wa ndũa, o na atumĩa nao, na ala maeie syana isu, matũmana kwa Yeu, makĩmwĩa, Twĩ athũkũmi maku, na tũkeeka w’onthe ũla wĩtwĩaĩa; tũtikatw’ĩkĩthya mũndũ o na wĩva mũsumbĩ: ĩka ũla wĩona wĩ ũseo.'),
('kam', '2KI', 10, 6, 'Na ĩndĩ amaandĩkĩa valũa ĩvinda ya kelĩ, akĩmea, Ethĩwa mwĩ ngalĩ ĩla yakwa, na ethĩwa mũkeethukĩĩsya wasya wakwa, osai mĩtwe ya andũ, ana ma vwana wenyu, na mũimbũkĩa kũũ Yesileeli ũnĩ ĩvinda ta yĩĩ. Na ĩndĩ ana ma mũsumbĩ, andũ mĩongo mũonza, maĩ vamwe na andũ me nguma ma ndũa, ala mamaeie.'),
('kam', '2KI', 10, 7, 'Na kweethĩwa, yĩla valũa wamavĩkĩe, moosa ana ma mũsumbĩ, na mamoaa, o andũ mĩongo mũonza, na meekĩa mĩtwe yoo ikavũnĩ, na mamĩtwaa Yesileeli.'),
('kam', '2KI', 10, 8, 'Na kwooka mũtũmwa, na amũtavya, akyasya, Nĩmaetete mĩtwe ya ana ma mũsumbĩ. Na asya, Miei ivumbu ilĩ ũlikĩlonĩ mbingĩlonĩ kũvika kĩoko.'),
('kam', '2KI', 10, 9, 'Na kweethĩwa kĩoko, aumaala, na aũngama, na amea andũ onthe, Mwĩ alũngalu inyw’ĩ: sisyai, nĩnĩnamũsamĩe vwana wakwa, na namũaa; ĩndĩ nũũ ũla wũaie aa onthe?'),
('kam', '2KI', 10, 10, 'Manyai yu kũikavalũka nthĩ ndeto o na yĩva ya Yeova, ĩla Yeova waneenie ũndũ wa nyũmba ya Aavu: nũndũ Yeova nĩwĩkĩte ũla waneenie na kanyw’a wa mũthũkũmi wake Eliya.'),
('kam', '2KI', 10, 11, 'Kwondũ wa ũu Yeu akũnĩa onthe ala matialĩte ma nyũmba ya Aavu ku Yesileeli, na andũ make onthe me nguma, na anyanyae make ala wesene nao, na athembi make, kũvika ndaamũtialya mũndũ o na ũmwe.'),
('kam', '2KI', 10, 12, 'Na ookĩla na akũsya, na athi Samalia. Na yĩla waĩ nzĩanĩ vala ve nyũmba ya aĩthi ya kũtilĩla malondu maw’ĩa,'),
('kam', '2KI', 10, 13, 'Yeu akomana na ana‐a‐ĩthe ma Aasia mũsumbĩ wa Yuta, na amakũlya, Mwĩ aaũ inyw’ĩ? Na masũngĩa, Ithyĩ twĩ ana‐a‐ĩthe ma Aasia: na nĩtũũtheea tũkethye ana ma mũsumbĩ na ana ma kĩveti kya mũsumbĩ.'),
('kam', '2KI', 10, 14, 'Nake asya, Makwatei me thayũ. Na mamakwata me thayũ, na mamoaĩa ĩimanĩ ya nyũmba ya kũtilĩla malondu maw’ĩa, o andũ mĩongo ĩna na elĩ; o na ndaatialya ũmwe woo.'),
('kam', '2KI', 10, 15, 'Na yĩla waĩ anauma kw’o, akomana na Yeonatavu mwana wa Lekavi okĩte kũmũthaũa; na amũkethya, na amũkũlya, Ngoo yaku nĩ ndũngalu, o tondũ ngoo yakwa ĩilyĩ na ngoo yaku? Na Yeonatavu asũngĩa, Nĩ ndũngalu. Ethĩwa ĩilyĩ ũu, nenga kw’oko kwaku. Na amũnenga kw’oko kwake; na amwambatya vala ũĩ ĩkasyanĩ.'),
('kam', '2KI', 10, 16, 'Na amwĩa, Ũka tũendan’ye, wone kĩwĩu kyakwa kwondũ wa Yeova. Kwondũ wa ũu mamũkua e ĩkasyanĩ yake.'),
('kam', '2KI', 10, 17, 'Na yĩla wavikie Samalia, akũna onthe ala matialĩlw’e Aavu ku Samalia, kũvika amũmina, kwĩanana na ndeto ya Yeova, ĩla wamũtavisye Eliya.'),
('kam', '2KI', 10, 18, 'Na Yeu oomban’ya andũ onthe vamwe, na amea, Aavu athũkũmie Mbaali kavola; ĩndĩ Yeu akamũthũkũma mũno.'),
('kam', '2KI', 10, 19, 'Yu kwondũ wa ũu metei moke vala nĩĩ athani onthe ma Mbaali, na athaithi make onthe, na athembi make onthe; kũtikethĩwe ũmwe ũte vo: nũndũ nĩ na nthembo nene ya kũmũthembea Mbaali; o ũla ũteĩthĩwa vo, ndakekala thayũ. Ĩndĩ Yeu eekie ũu na ũseleke, nĩ kana anange athaithi ma Mbaali.'),
('kam', '2KI', 10, 20, 'Na Yeu asya, Tw’ai ũmbano ũkilĩtye kwondũ wa Mbaali. Na mootw’a.'),
('kam', '2KI', 10, 21, 'Na Yeu atũmana ku Isilaeli kw’onthe: na athaithi onthe ma Mbaali mooka, na kũtyaĩ mũndũ o na ũmwe waatiala ũla ũtaaũka. Na malika nyũmbanĩ ya Mbaali; na nyũmba ya Mbaali yausũa ki kuma mũthya ũmwe kũvika ũla ũngĩ.'),
('kam', '2KI', 10, 22, 'Na amwĩa mũsyaĩĩsya wa kasũmba kala kaiawa ngũa sya ũthaithi, Ete ngũa sya ũthaithi kwondũ wa athaithi onthe ma Mbaali. Na amaetee ngũa sya ũthaithi.'),
('kam', '2KI', 10, 23, 'Na Yeu, e na Yeonatavu mwana wa Lekavi, malika nyũmbanĩ ya Mbaali; na amea athaithi ma Mbaali, Manthai, na mũisisya nĩ kana vatikethĩwe vaa vamwe nenyu o na ũmwe wa athũkũmi ma Yeova, ate o athaithi ma Mbaali oka.'),
('kam', '2KI', 10, 24, 'Na malika mathembe nthembo sya kũtonywa na nthembo sya kũvĩvw’a. Na ĩndĩ Yeu nĩwaiĩte andũ mĩongo nyanya ũtee, na amea, Ethĩwa mũndũ o na wĩva ũla nĩete mokonĩ menyu akavonoka, ũla wĩmũlekya athi, thayũ wake ũkeethĩwa vandũ va thayũ wa ũsu.'),
('kam', '2KI', 10, 25, 'Na kweethĩwa, o amina kũthemba nthembo sya kũvĩvw’a, Yeu amea nguthu ya asũvĩi na makavuteni, Likai, mũmoae; mũtikaeke ũmwe aumaale. Na mamakũna kwa kũmatemanga na ũvyũ; na asũvĩi na makavuteni mamekya nza, na mathi ndũanĩ yĩ nyũmba ya Mbaali.'),
('kam', '2KI', 10, 26, 'Na maumaalya ituĩ ila syaĩ nyũmbanĩ ya Mbaali, na maivĩvya.'),
('kam', '2KI', 10, 27, 'Na matũlanga kĩtuĩ kya Mbaali, na maomboa nyũmba ya Mbaali, na mamĩtw’ĩkĩthya ũtũnda, kũvika ũmũnthĩ.'),
('kam', '2KI', 10, 28, 'Ũu nĩw’o Yeu waminie Mbaali nthĩnĩ wa Isilaeli.'),
('kam', '2KI', 10, 29, 'Ĩndĩ Yeu ndaaeka kũatĩĩa naĩ sya Yelovoamu mwana wa Nevati, ila wamavĩtĩthisye Isilaeli nasyo, nasyo nĩ ii, tũsaũ twa thaavu tũla twaĩ Mbethi‐eli, na Ndani.'),
('kam', '2KI', 10, 30, 'Na Yeova amwĩa Yeu, Nĩkwĩthĩwa nĩwĩkĩte nesa ũkĩka ũla nonaa wĩ ũseo, na nũmĩkĩte nyũmba ya Aavu kwĩanana na w’onthe ũla waĩ ngoonĩ yakwa, ana maku ma nzyawa ya kana makekala kĩvĩlanĩ kya ũsumbĩ kya Isilaeli.'),
('kam', '2KI', 10, 31, 'Ĩndĩ Yeu ndaaĩsũvĩa aende mĩaonĩ ya Yeova, Ngai wa Isilaeli, na ngoo yake yonthe: ndaatia naĩ sya Yelovoamu, ila wavĩtĩthisye Isilaeli nasyo.'),
('kam', '2KI', 10, 32, 'Mĩthenya ĩsu Yeova nĩwambĩlĩlye kũmaola Isilaeli: na Aasaeli amakũnĩa mĩvakanĩ yonthe ya Isilaeli;'),
('kam', '2KI', 10, 33, 'kuma Yolotani kũthi ngalĩ ya wumĩlonĩ wa syũa, nthĩ yonthe ya Ngileati, Angati, na Aleuveni, na Amanase, kuma Aloeli, ĩla yĩ vakuvĩ na mwanda wa Alinoni, o Ngileati na Mbasani.'),
('kam', '2KI', 10, 34, 'Na ĩndĩ meko ala angĩ ma Yeu, na w’onthe ũla wekaa, na vinya wake w’onthe mũnene, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '2KI', 10, 35, 'Na Yeu akoma na aaĩthe make; na mamũthika Samalia. Na Yeoaasi mwana wake asumbĩka vandũ vake.'),
('kam', '2KI', 10, 36, 'Na ĩvinda yĩla Yeu wasumbĩkie Isilaeli ku Samalia yaĩ myaka mĩongo ĩlĩ na nyanya.'),
('kam', '2KI', 11, 1, 'Na ĩndĩ yĩla Athalia inyia wa Aasia wonie kana mwana wake nĩ mũkw’ũ, ookĩla na amina ũsyao w’onthe wa kĩũsumbĩ.'),
('kam', '2KI', 11, 2, 'Ĩndĩ Yeoseva, mwĩĩtu wa mũsumbĩ Yolamu, mwĩĩtu‐a‐inyia wa Aasia, oosa Yoasi mwana wa Aasia, na amũya kũmumya ananĩ ma mũsumbĩ ala mooaawa, o we na mũei wake, na amekĩa kasũmbanĩ ka ũkoma; na mamũvitha Athalia ndakamwone, na ĩndĩ ndaaũawa;'),
('kam', '2KI', 11, 3, 'na aĩ nake avithĩtwe nyũmbanĩ ya Yeova myaka thanthatũ. Na Athalia asumbĩka ĩ nthĩ.'),
('kam', '2KI', 11, 4, 'Na mwaka wa mũonza Yeoiata atũmana na aete makavuteni ma maana ma Akali na ma nguthu ya asũvĩi, na amaete vala ũĩ nyũmbanĩ ya Yeova; na atianĩa ũtianĩo nao, na ameavĩthĩsya nyũmbanĩ ya Yeova, na amon’ya mwana wa mũsumbĩ.'),
('kam', '2KI', 11, 5, 'Na ameaĩa, akĩmea, Ũũ nĩw’o ũla mwĩĩka: kĩlungu kya katatũ kya inyw’ĩ, ala mũkaa mũthenya wa savato, mũkeethĩwa asyaĩĩsya ma kũsũvĩa nyũmba ya mũsumbĩ;'),
('kam', '2KI', 11, 6, 'na kĩlungu kĩngĩ kĩkeethĩwa mbingĩlonĩ yĩtawa Suli; na kĩlungu kĩngĩ mbingĩlonĩ ĩla yĩ ĩtina wa nguthu ya asũvĩi: ũu nĩw’o mwĩsyaĩĩasya nyũmba, na mũkeethĩwa kĩsiĩĩi.'),
('kam', '2KI', 11, 7, 'Na ila nguthu ilĩ sya inyw’ĩ, o onthe ala maumaalaa mũthenya wa savato, mũkasũvĩa nyũmba ya Yeova mũthyũlũlũkĩte mũsumbĩ.'),
('kam', '2KI', 11, 8, 'Na mũkathyũlũlũka mũsumbĩ ngalĩ syonthe, kĩla mũndũ akwete mĩio yake ya kaũ kw’okonĩ kwake; na ũla wĩvotela nthĩnĩ wa mĩselele, nĩoawe: na mwĩĩthĩwa na mũsumbĩ yĩla wĩumaala, na yĩla wĩsyoka.'),
('kam', '2KI', 11, 9, 'Na makavuteni ma maana meeka kwĩanana na w’onthe ũla mũthembi Yeoiata weaĩte; na moosa kĩla mũndũ andũ make, ala maĩ ma ũlika mũthenya wa savato, na ala maĩ ma kumaala mũthenya wa savato, na mooka vala ve mũthembi Yeoiata.'),
('kam', '2KI', 11, 10, 'Na mũthembi amanenga makavuteni ma maana matumo na ngao ila syaĩ sya mũsumbĩ Ndaviti, ila syaĩ nyũmbanĩ ya Yeova.'),
('kam', '2KI', 11, 11, 'Na asũvĩi maũngama, kĩla mũndũ akwete mĩio yake ya kaũ kw’okonĩ kwake, kuma ngalĩ ya kwo’ko kwa aũme kũvika ngalĩ ya kw’oko kwa aka kwa nyũmba, vakuvĩ na kĩthembeo na nyũmba, mathyũlũlũkĩte mũsumbĩ ngalĩ syonthe.'),
('kam', '2KI', 11, 12, 'Nĩvo ĩndĩ waumaalilye mwana wa mũsumbĩ, na amwĩkĩa ĩla ngovĩa ya ũsumbĩ, na amũnenga ũla ũkũsĩ; na mamũtw’ĩkĩthya mũsumbĩ, na mamwĩtĩkĩsya mauta; na makũnangan’ya mbĩ, na masya, Mũsumbĩ nĩekale thayũ ĩvinda ĩasa.'),
('kam', '2KI', 11, 13, 'Na yĩla Athalia wewie kĩlonzo kya asũvĩi na kya andũ, ooka vala ve andũ nyũmbanĩ ya Yeova:'),
('kam', '2KI', 11, 14, 'na asisya, na, kaĩ, mũsumbĩ aũngyĩ vakuvĩ na kĩtuĩ, o tondũ kweekawa, na makavuteni na masoo vakuvĩ na mũsumbĩ; na andũ onthe ma ĩ nthĩ matana, na mavuva masoo. Nĩvo ĩndĩ Athalia watembũangie ngũa syake, na asya, Nĩ ũvinga! Nĩ ũvinga!'),
('kam', '2KI', 11, 15, 'Na mũthembi Yeoiata ameaĩa makavuteni ma maana ala maiĩtwe ĩũlũ wa nguthu, na amea, Mumaalĩlye katĩ wa mĩselele; na ũla wĩmũatĩĩa mũaei na ũvyũ. Nũndũ mũthembi aisye, Ndakoaĩwe nyũmbanĩ ya Yeova.'),
('kam', '2KI', 11, 16, 'Kwondũ wa ũu mamwathũkĩa; na athi na nzĩa ya ũlikĩlo wa mbalasi wa nyũmba ya mũsumbĩ: na ooaĩwa vo.'),
('kam', '2KI', 11, 17, 'Na Yeoiata atianĩa ũtianĩo katĩ wa Yeova na mũsumbĩ na andũ, atĩ makeethĩwa andũ ma Yeova; o na katĩ wa mũsumbĩ na andũ.'),
('kam', '2KI', 11, 18, 'Na andũ onthe ma ĩ nthĩ mathi nyũmbanĩ ya Mbaali, na mamĩomboanga; ithembeo syayo na mĩvw’anano yayo matũlanga ilungu vyũ, na mooaĩa Matani mũthembi wa Mbaali mbee wa ithembeo. Na mũthembi aia anene ĩũlũ wa nyũmba ya Yeova.'),
('kam', '2KI', 11, 19, 'Na oosa makavuteni ma maana, na Akali, na asũvĩi, na andũ ma ĩ nthĩ; na mamũete mũsumbĩ kuma nyũmbanĩ ya Yeova, na mooka na nzĩa ya mbingĩlo ya asũvĩi asu kũvika nyũmba ya mũsumbĩ. Na ekala kĩvĩlanĩ kya ũsumbĩ kya asumbĩ.'),
('kam', '2KI', 11, 20, 'Na ĩndĩ andũ onthe ma ĩ nthĩ matana, na ndũa yausya. Na maĩ manamũaĩa Athalia na ũvyũ nyũmbanĩ ya mũsumbĩ.'),
('kam', '2KI', 11, 21, 'Yeoasi aĩ wa myaka mũonza yĩla wambĩlĩlye kũsumbĩka.'),
('kam', '2KI', 12, 1, 'Yeoasi ambĩlĩlya kũsumbĩka mwaka wa mũonza wa kũsumbĩka kwa Yeu; na asumbĩka myaka mĩongo ĩna Yelusaleme: na syĩtwa ya inyia wake eetawa Nzivia wa ku Mbeeli‐sieva.'),
('kam', '2KI', 12, 2, 'Na Yeoasi eekaa ũla Yeova wonaa wĩ ũseo mĩthenya yake yonthe ĩla mũthembi Yeoiata wamũmanyĩisye.'),
('kam', '2KI', 12, 3, 'Ĩndĩ kũla kũndũ kũtũlu kũtyaavetwa; andũ nĩmaendeeaa na kũthemba na kũtoeesya ũvani kũla kĩndũ kũtũlu.'),
('kam', '2KI', 12, 4, 'Na Yeoasi amea athembi, Mbesa syonthe sya syĩndũ ila ivathĩtwe syĩthĩwe ntheu ila ietawe nyũmbanĩ ya Yeova, mbesa ila itethasya wĩa, o mbesa sya andũ kwĩanana na kĩla mũndũ ũndũ ũtalĩlwe, na mbesa syonthe ila mũndũ o na wĩva ũsũanĩaa ngoonĩ aete nyũmbanĩ ya Yeova,'),
('kam', '2KI', 12, 5, 'athembi masyose, kĩla mũndũ kuma kwa ũla wĩsene nake; na makatũngĩĩa kũndũ kũvũthũku kwa nyũmba, o vala vakoneka ũomboku.'),
('kam', '2KI', 12, 6, 'Ĩndĩ kweethĩiwe, mwaka wa mĩongo ĩlĩ na ĩtatũ wa kũsumbĩka kwa mũsumbĩ Yeoasi athembi matyaĩ manatũngĩĩa kũndũ kũvũthũku kwa nyũmba.'),
('kam', '2KI', 12, 7, 'Nĩvo ĩndĩ mũsumbĩ Yeoasi wamwĩtie mũthembi Yeoiata, na athembi ala angĩ, na amakũlya, Nũndũ wa kĩ mũtiũtũngĩĩa kũndũ kũvũthũku kwa nyũmba? Yu kwondũ wa ũu mũtikose mbesa ingĩ kwa ala mwĩsene namo, ĩndĩ inenganei kwondũ wa ala moomboku ma nyũmba.'),
('kam', '2KI', 12, 8, 'Na athembi meetĩkĩla matikosa mbesa ingĩ kuma kwa andũ, o na matikatũngĩĩa kũndũ kũvũthũku kwa nyũmba.'),
('kam', '2KI', 12, 9, 'Ĩndĩ mũthembi Yeoiata oosa ĩsandũkũ, na atonya ĩima ngunĩkonĩ yayo, na ayia ũtee wa kĩthembeo, ngalĩ ya kw’oko kwa aũme, vala mũndũ ũlikĩlaa nyũmbanĩ ya Yeova: na athembi ala masũvĩaa me mwalyonĩ meekĩa nthĩnĩ wayo mbesa syonthe ila syaetiwe nyũmbanĩ ya Yeova.'),
('kam', '2KI', 12, 10, 'Na kweethĩwa, yĩla moonie kwaĩ mbesa mbingĩ ĩsandũkũnĩ, mũandĩki wa mũsumbĩ na mũthembi mũnene mambata, na meekĩa mbesa ila syoonekie nyũmbanĩ ya Yeova mũvukonĩ na maitala.'),
('kam', '2KI', 12, 11, 'Na mbesa ila syathimiwe manengane mokonĩ ma ala matethasya wĩa, ala masyaĩĩasya nyũmba ya Yeova: na maĩva aseũvya ma mbwaũ na aki, ala matethasya wĩa nyũmbanĩ ya Yeova,'),
('kam', '2KI', 12, 12, 'o na aki ma mavia na asũvya ma mavia, na kwondũ wa kũthooa mĩtĩ na mavia masũvye ma kũtũngĩĩa kũndũ kũvũthũku kwa nyũmba ya Yeova, na kwondũ wa syonthe ila syaumiwe sya kũtũngĩĩa nyũmba.'),
('kam', '2KI', 12, 13, 'Ĩndĩ kũtyaaseũvw’a kwondũ wa nyũmba ya Yeova ikombe sya vetha, kana mĩkasi, kana masaani manene, kana masoo, kana mĩio o na yĩva ya thaavu, kana mĩio ya vetha, na mbesa ila syaetiwe nyũmbanĩ ya Yeova;'),
('kam', '2KI', 12, 14, 'nũndũ isu syanengiwe ala matethasya wĩa, na matũngĩĩa nyũmba ya Yeova nasyo.'),
('kam', '2KI', 12, 15, 'O na ĩngĩ matyaatalana na andũ, ala mamanengie mbesa isu kw’okonĩ kwoo mamanenge ala matethasya wĩa; nũndũ matethasya na kĩthito.'),
('kam', '2KI', 12, 16, 'Mbesa sya nthembo kwondũ wa mavĩtyo, na mbesa sya nthembo kwondũ wa naĩ, ityaaetwe nyũmbanĩ ya Yeova: syaĩ sya athembi.'),
('kam', '2KI', 12, 17, 'Nĩvo ĩndĩ Aasaeli mũsumbĩ wa Silia wambatie, na okita na Ngathi, na amĩkwata; na Aasaeli eelekelya ũthyũ kũthi Yelusaleme.'),
('kam', '2KI', 12, 18, 'Na Yeoasi mũsumbĩ wa Yuta oosa syĩndũ syonthe ivathĩtwe syĩthĩwe ntheu ila Yeosavati na Yeolamu na Aasia, aaĩthe make, asumbĩ ma Yuta, mavathĩte syĩthĩwe ntheu, na syĩndũ syake mwene ila ivathĩtwe syĩthĩwe ntheu, na thaavu w’onthe ũla woonekie mothwiinĩ maie ma nyũmba ya Yeova, na ma nyũmba ya mũsumbĩ, na amũtwaĩa Aasaeli mũsumbĩ wa Silia: na aeka Yelusaleme.'),
('kam', '2KI', 12, 19, 'Na ĩndĩ meko ala angĩ ma Yoasi, na w’onthe ũla wekaa, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Yuta?'),
('kam', '2KI', 12, 20, 'Na athũkũmi make mookĩla, na mamũsamĩa, na mamũkũnĩa Yoasi nyũmbanĩ yĩtawa Milo, nzĩanĩ ĩla ĩelete Silila.'),
('kam', '2KI', 12, 21, 'Nũndũ Yosakali mwana wa Simeathi, na Yeosavatu mwana wa Someli, athũkũmi make, mamũkũna, na akw’a; na mamũthika vamwe na aaĩthe make ndũanĩ ya Ndaviti: na Amasia mwana wake asumbĩka vandũ vake.'),
('kam', '2KI', 13, 1, 'Mwaka wa mĩongo ĩlĩ na ĩtatũ wa kũsumbĩka kwa Yoasi mwana wa Aasia, mũsumbĩ wa Yuta, Yeoaasi mwana wa Yeu ambĩlĩlya kũsumbĩka Isilaeli ku Samalia, na asumbĩka myaka ĩkũmi na mũonza.'),
('kam', '2KI', 13, 2, 'Na eekaa ũla Yeova wonaa wĩ ũthũku, na aatĩĩa naĩ sya Yelovoamu mwana wa Nevati, ila wavĩtĩthisye Isilaeli nasyo; ndaaitia.'),
('kam', '2KI', 13, 3, 'Na ũthatu wa Yeova wamakanĩa Isilaeli, na amanengane kw’okonĩ kwa Aasaeli mũsumbĩ wa Silia, na kw’okonĩ kwa Mbeni‐aatati mwana wa Aasaeli, mavinda onthe.'),
('kam', '2KI', 13, 4, 'Na Yeoaasi amwĩsũva Yeova, na Yeova amwĩthukĩĩsya; nũndũ nĩwonie thĩna wa Isilaeli, ũndũ mũsumbĩ wa Silia wamathĩnasya.'),
('kam', '2KI', 13, 5, '(Na Yeova anenga Isilaeli mũtangĩĩi, na ĩndĩ mauma kw’okonĩ kwa Asilia; na ana ma Isilaeli mekala maeemanĩ moo o ta tene.'),
('kam', '2KI', 13, 6, 'Ĩndĩ vamwe na ũu matyaatia naĩ sya nyũmba ya Yelovoamu, ila wavĩtĩthisye Isilaeli nasyo, ĩndĩ maendaa nthĩnĩ wasyo: o na kwatialw’a Asela ku Samalia.)'),
('kam', '2KI', 13, 7, 'Nũndũ ndaamũtialĩlya Yeoaasi andũ ate o andũ mĩongo ĩtano ala matũlaa mbalasi, na makasya ma kaũ ĩkũmi, na andũ ngili ĩkũmi ala maendaa na maũũ; nũndũ mũsumbĩ wa Silia nĩwamanangie, na amatw’ĩkĩthya ta kĩtoo yĩla kũũvũwa.'),
('kam', '2KI', 13, 8, 'Na ĩndĩ meko ala angĩ ma Yeoaasi, na w’onthe ũla wekaa, na vinya wake mũnene, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '2KI', 13, 9, 'Na Yeoaasi akoma na aaĩthe make; na mamũthika Samalia: na Yoasi mwana wake asumbĩka vandũ vake.'),
('kam', '2KI', 13, 10, 'Mwaka wa mĩongo ĩtatũ na mũonza wa kũsumbĩka kwa Yoasi mũsumbĩ wa Yuta, Yeoasi mwana wa Yeoaasi ambĩlĩlya kũsumbĩka Isilaeli ku Samalia, na asumbĩka myaka ĩkũmi na thanthatũ.'),
('kam', '2KI', 13, 11, 'Na eekaa ũla Yeova wonaa wĩ ũthũku; ndaatia naĩ syonthe sya Yelovoamu mwana wa Nevati, ila wavĩtĩthisye Isilaeli nasyo; ĩndĩ aendaa nthĩnĩ wasyo.'),
('kam', '2KI', 13, 12, 'Na ĩndĩ meko ala angĩ ma Yoasi, na w’onthe ũla wekaa, na vinya wake mũnene ũla wokitie Amasia mũsumbĩ wa Yuta naw’o, ti maandĩke ĩvukunĩ ya maũndũ ma mavinda ma asumbĩ ma Isilaeli?'),
('kam', '2KI', 13, 13, 'Na Yoasi akoma na aaĩthe make: na Yelovoamu ekalĩla kĩvĩla kyake kya ũsumbĩ: na Yoasi athikwa Samalia vamwe na asumbĩ ma Isilaeli.'),
('kam', '2KI', 13, 14, 'Na ĩndĩ Elisa aĩ mũwau ũwau wake ũla wamũaie: na Yoasi mũsumbĩ wa Isilaeli atheea vala ũĩ, na amũĩĩa, na asya, Asa wakwa, asa wakwa, makasya ma Isilaeli na mbalasi syamo!'),
('kam', '2KI', 13, 15, 'Na Elisa amwĩa, Osa ũta na mĩsyĩ; nake oosa ũta na mĩsyĩ.'),
('kam', '2KI', 13, 16, 'Na amwĩa mũsumbĩ wa Isilaeli, Koota ũta na kw’oko kwaku; na ookoota na kw’oko kwake. Na Elisa ailĩĩla moko make ĩũlũ wa moko ma mũsumbĩ.'),
('kam', '2KI', 13, 17, 'Na asya, Vingũa mbũthi ĩla yelekele wumĩlonĩ wa syũa; na amĩvingũa. Na ĩndĩ Elisa asya, Atha; na aatha. Na asya, Mũsyĩ wa Yeova wa kũkĩlya vinya, o mũsyĩ wa kũkĩlya Silia vinya; nũndũ ũkakũnĩa Asilia ku Aveki, kũvika wamamina vyũ.'),
('kam', '2KI', 13, 18, 'Na asya, Osa mĩsyĩ; na amyosa. Na amwĩa mũsumbĩ wa Isilaeli, Atha nthĩ; na aatha katatũ, na aeka.'),
('kam', '2KI', 13, 19, 'Na ũ mũndũ wa Ngai amũthatĩa, na amwĩa, Nĩwĩaĩlĩte kũatha mavinda atano kana thanthatũ: nĩvo ĩndĩ wĩĩthĩwa ũmĩkũna Silia kũvika wamĩmina vyũ; kwondũ wa ũu yu ũkakũna Silia o katatũ.'),
('kam', '2KI', 13, 20, 'Na Elisa akw’a, na mamũthika. Na nguthu sya Amoavi syalika nthĩ ĩsu, mwaka ũkyambĩlĩlya.'),
('kam', '2KI', 13, 21, 'Na kweethĩwa, yĩla mathikaa mũndũ, sisya, mesa kwona nguthu; na mamwĩkya ũ mũndũ ngunganĩ ya Elisa vala vathikawa akw’ũ: na mũndũ ũsu o akiita mavĩndĩ ma Elisa, athayũũka, na aũngama na maũũ make.'),
('kam', '2KI', 13, 22, 'Na Aasaeli mũsumbĩ wa Silia athĩn’ya Isilaeli mĩthenya yonthe ya Yeoaasi.'),
('kam', '2KI', 13, 23, 'Ĩndĩ Yeova aĩ mũseo kwoo, na amew’ĩa tei, na amelekela, nũndũ wa ũtianĩo wake na Avalaamu, na Isaka, na Yakovo, na ndaaĩtĩkĩla kũmananga, o na ndaamekya maume vala ũĩ kũvika yĩu.'),
('kam', '2KI', 13, 24, 'Na Aasaeli mũsumbĩ wa Silia akw’a; na Mbeni‐aatati mwana wake asumbĩka vandũ vake.'),
